window.__D("text/zohar-chadash/c005",{"p":[[9514013421,"<p>מַעֲרָב מַעֲרָב, אִתְעַר לְגַבֵּי נַאֲקַת חֲלָלִין, וּקְרָבִין תַּקִּיפִין דְּבָנַי. אִיתְעַר לְגַבֵּי רְחִימָתִי יוֹנָתִי תַמָּתִי, הֵיךְ אָזְלִין בְּנָהָא. וְהֵיךְ מִתְבַּדְּרִין בְּכַמָּה סִטְרִין.</p>"],[9514013422,"<p>אֲחֹתִי בְּרַתִּי רַעֲיָיתִי רַעֲיָיא דִּילִי, רְחֵימְתָּא דְנַפְשָׁאי, מַה נֶּעֱבֵיד מִן בְּנָנָא מַה יַּעַבְדוּן אִינוּן. אֲבָל רְחִימָתִי אֲחֹתִי, אֵימָא לָךְ, אִי בִּרְעוּ סַלְקָא עֲלָךְ, אַנְתְּ מְרוּבַּעַת, וְגַדְפִין דִּילָךְ פְּרִישָׂן לְד' סִטְרִין, בְּאוֹמָאָה עֲלָךְ בְּרַתִּי יְחִידָתִי, דְּתֵהַךְ בַּהֲדַיְיהוּ, וְלָא תִשְׁבּוֹק לוֹן, וְתֶחֱפֵי עֲלַיְיהוּ בְּאַרְבַּע סִטְרִין דְּעָלְמָא. וְאִי לָא, יִתְאַבְדוּן מֵעָלְמָא.</p>"],[9514013423,"<p>מָה אֵימָא לָךְ ר', בְּהַהִיא שַׁעֲתָא דִּכְנֶסֶת יִשְׂרָאֵל שָׁמְעַת דָא, אֲרֵימַת קָלָא, וְאִזְדַּעְזְעוּ תְּמַנֵּיסַר אֶלֶף עָלְמִין, וְקוּדְשָׁא בְּרִיךְ הוּא בַּהֲדָהּ. וּכְדֵין (ירמיהו ל״א:ט״ו) קוֹל בְּרָמָה נִשְׁמַע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ. וְקוּדְשָׁא בְּרִיךְ הוּא כְּדֵין, (ישעיהו כ״ב:י״ב) וַיִּקְרָא אֲדֹנָי ה' צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד.</p>"],[9514013424,"<p>מַאן חָמָא עִרְטוּלָא בְּכָלְהוֹ רְקִיעִין. מַאן חָמָא בִּלְבּוּלָא וּמִסְפֵּידָא דְּתַמָּן. עַד דְּכָל חֵיילֵי שְׁמַיָיא חֲשִׁיבוּ, דְּכָל עָלְמִין יִתְהַפְּכוּן.</p>"],[9514013425,"<p>אֲמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא לִכְנֶסֶת יִשְׂרָאֵל, בְּרַתִּי יְחִידָתִי דִילִי, תְּהַךְ לְחַפְיָיא עֲלַיְיהוּ, וּלְדַיְירָא עִם בְּנָנָן. אֲמָרָה לֵיהּ, מָארֵי דְעָלְמָא, לָא אֵיהַךְ. בָּתַר דְּרָבֵית לוֹן, וּתְקֵינִית לוֹן, וּגְדֵילִית לוֹן. אֱהֵי חָמִית לְשַׂנְאֵיהוֹן דְּאָכְלֵי לוֹן, וְתִינְשֵׁי לָנָא תַּמָּן. כְּדֵין אוֹמֵי קוּדְשָׁא בְּרִיךְ הוּא לָהּ, לַאֲקָמָא לָהּ, וּלְמִפְרַק לוֹן לְיִשְׂרָאֵל, וְלַאֲפָקָא לוֹן מִגָּלוּתָא. כְּמָה דְאַתְּ אָמֵר, (ירמיהו ל״א:ט״ז) כֹּה אָמַר ה' מִנְעִי קוֹלֵךְ מִבֶּכִי וְגו', וְיֵשׁ תִּקְוָה לְאַחֲרִיתֵךְ כו', וְשָׁבוּ בָנִים לִגְבוּלָם.</p>"],[9514013426,"<p>וְעַל דָּא נָפְקַת מִקַּמֵּיהּ. כֵּיוָן דְּנָפְקַת מִקַּמֵּיהּ, פְּתַח קוּדְשָׁא בְּרִיךְ הוּא עַל כָּל חֵילֵי שְׁמַיָיא וַאֲמַר אֵיכָה יוּעַם זָהָב, וְכָל הַהוּא קִינָה דְּאַלְפָא בֵיתָא, קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי אֲמַר לָהּ, לְבָתַר קְשַׁר רְחִימִין בְּהַהוּא תִּנְיָינָא וְחָתְמוּ פִּתְקִין.</p>"],[9514013427,"<p>וְהַשְׁתָּא אַהֲדַרְנָא לְפַרְשָׁתָא, דְּוַדַּאי גָּלוּתָא אִתְמְשַׁךְ. (במדבר כ״ד:י״ז) אֶרְאֶנּוּ וְלֹא עַתָּה, לְמַאן קָאָמַר אֶרְאֶנּוּ. לְהַהוּא דְּאִיתְּמָר עֲלוֹי כִּי אֵינֶנּוּ. כַּד יֵיתֵי לְפָקְדָא לַאֲיַילְתָּא. וְלֹא עַתָּה, וְלֹא לִזְּמַן קָרוֹב. אֲשׁוּרֶנּוּ וְלֹא קָרוֹב, אִסְתַּכַּלְנָא בֵּיהּ, אֲבָל לָאו כְּעַן, אֶלָּא לִזְמַן רָחוֹק.</p>"],[9514013428,"<p>דָּרַךָ כּוֹכָב מִיַּעֲקֹב, רַבִּי רַבִּי, כַּמָּה רָזִין סְתִימִין כְּלִילָן הָכָא. פָּתַח וְאָמַר, (בראשית ב׳:כ״א) וַיַּפֵּל ה' אֱלֹהִים תַּרְדֵּמָה עַל הָאָדָם וַיִּישָׁן. כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם קַדְמָאָה, דּוּ פַּרְצוּפִין בְּרָאוֹ, וַהֲווּ מִתְחַבְּרָן כַּחֲדָא בְּלָא פֵּירוּדָא. מַאי טַעְמָא. בְּגִין דִּכְתִיב, (שם ה) זָכָר וּנְקֵבָה בְּרָאָם, בְּלָא פֵּירוּדָא, וְלָא כְתִיב בְּרָאוֹ, אֶלָּא בְּרָאָם.</p>"],[9514013429,"<p>כֵיוָן דְּאִתְבְּרִיאוּ, הֲווֹ כַּחֲדָא דָּא עִם דָּא, בְּשִׁיקוּלָא. מָה עֲבַד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. נְסַר לֵיהּ נְסִירוּ, וּנְטַל לְנוּקְבָא מִנֵּיהּ, וְאַתְקֵין לָהּ בְּכַמָּה תִּיקּוּנִין, וְקִשְׁטָהּ בְּכַמָּה קִישּׁוּטִין, וְאַלְבֵּישׁ לָהּ בְּכַמָּה לְבוּשִׁין.</p>"],[9514013430,"<p>בְּאָן אֲתַר, בְּגִנְתָא דְעֵדֶן אַתְקֵין לָהּ. כַּמָּה קִישּׁוּטִין קְשַׁט לָהּ. שִׁבְעִין. וְאִינוּן שִׁבְעִים פָּנִים דְּאוֹרַיְיתָא. כַּמָּה תִּיקּוּנִין תַּקֵּין לָהּ. תְּלֵיסַר תִּיקּוּנִין. אִינוּן תְּלֵיסַר מְכִילִין, דְּאוֹרַיְיתָא נִדְרֶשֶׁת בְּהוּ. כַּמָּה לְבוּשִׁין אַלְבֵּישׁ לָהּ. שִׁית לְבוּשִׁין. וְאִינוּן שִׁית סִדְּרֵי מִשְׁנָה, בְּשִׁית אַנְפִּין.</p>"],[9514013431,"<p>כָל הַנֵּי תִּיקּוּנִין, וְכָל הַנֵּי קִישּׁוּטִין, וְכָל הַנֵּי לְבוּשִׁין, עֲבַד לָהּ קוּדְשָׁא בְּרִיךְ הוּא תַּמָּן בְּגִנְתָא דְעֵדֶן, וּלְבָתַר וַיְבִיאֶהָ אֶל הָאָדָם. וְאָדָם הֵיכָן הֲוָה. בַּאֲתַר דִּנְקוּדָה דְּצִיּוֹן, דְּבֵי מַקְדְּשָׁא תַּמָּן. וּמִתַּמָּן נְטֵיל לוֹן, וְאָעֵיל לוֹן בְּגִנְתָא דְעֵדֶן, וּבָרֵיךְ לוֹן בִּרְכַּת חֲתָנִים.</p>"],[9514013432,"<p>וְרָזָא דָא, דָּרַךְ כּוֹכָב מִיַּעֲקֹב. דָּרַךְ וְקַשֵּׁיט וְתַקֵּין הַהוּא כּוֹכָב, דְּאִתְנְטֵיל מִיַּעֲקֹב. דִּבְגִין כָּךְ, בְּגִינָהּ יִתְגְּלֵי, מַאן דְּיִתְגְּלֵי. בְּגִין דְּעַל דָּא הֲוָה אָתֵי לְגַבָּהּ, וְאִתְמְשַׁךְ מֵעֵילָא לְתַתָּא. וְקָם שֵׁבֶט מִיִשְּׂרָאֵל, דָּא אִילָנָא דְחַיֵּי. וְקָם: כְּמָא דְאַתְּ אָמֵר, (שם ו) וַהֲקִמֹתִי אֶת בְּרִיתִי.</p>"],[9514013433,"<p>וְכַד יְהֵא דָא, וּמָחַץ פַּאֲתֵי מוֹאָב וְגו'. כָּל אִינוּן סִטְרִין דְּאִתְאַחֲדָן בְּאִילָנָא תַּתָּאָה, יִתְעַבְרוּן וְיִתְעֲדוּן מִנֵּיהּ. כְּדֵין, (שם ב) וַיֹּאמֶר הָאָדָם זֹאת הַפַּעַם. דָּא זִמְנָא דְּעִדּוּנִין וְעִנּוּגִין, לְאִשְׁתַּעְשְׁעָא כַּחֲדָא וְלָא כִשְׁאָר זִמְנִין דְּסִטְרָא בִּישָׁא אִתְאַחֲדַת בֵּינָנָא. אֲבָל הַשְׁתָּא לֵית עִרְבּוּבְיָא דְּסִטְרָא אָחֳרָא עִמָּנָא, אֶלָּא עֶצֶם מֵעֲצָמַי, וְלָא שִׁיתּוּפָא אָחֳרָא דְּבִישׁ.</p>"],[9514013434,"<p>עֶצֶם מֵעֲצָמַי, נְהִירוּ דְּאַסְפַּקְלַרְיָיא דְּנָהֲרָא מַמָּשׁ. וּבָשָׂר מִבְּשָׂרִי, מַלְבּוּשָׁא מֵהַהוּא מַלְבּוּשָׁא דְּאִתְלַבַּשׁ בֵּיהּ נְהוֹרָא עִילָּאָה דִּילִי. לְזֹאת יִקָּרֵא אִשָּׁה, בְּשָׁלְטָנוּתָא עִילָּאָה עַל כָּל עָלְמָא, דְּלָא תַעֲדֵי לְעָלַם. כְּדֵין (דניאל ב) תַּדִּק וְתָסֵף כָּל [אִלֵּין] מַלְכְוָתָא וְהִיא תְּקוּם לְעָלְמַיָּא.</p>"],[9514013435,"<p>אֶרְאֶנּוּ וְלֹא עַתָּה, רְאִיָּיה דָא דַּאֲנָא חָמֵינָא, זְמִינָא לְמֶחֱמֵי לֵיהּ, וּלְאִתְקְרָבָא כַּחֲדָא. וְלֹא עַתָּה, בְּגָלוּתָא דְּבָבֶל, בְּהַהוּא בֵיתָא דִּבְנוֹ עוֹלֵי גוֹלָה. אֲשׁוּרֶנּוּ, אֲנָא זַמֵּינָא לְאִסְתַּכָּלָא בֵּיהּ אַנְפִּין בְּאַנְפִּין. וְלֹא קָרוֹב, אֶלָּא בְּהַהוּא בֵיתָא בַּתְרַיְיתָא. דְּבֵין בְּהַאי וּבֵין בְּהַאי, לָא הֲוָה נַיְיחָא, וְלָא קוּרְבָא וְאַחְדוּתָא כִּדְקָא יָאוֹת.</p>"],[9514013436,"<p>אִי רַבִּי אִי רַבִּי, כַּמָּה קַשְׁיָא מִלָּה, כַּמָּה אָרִיךְ זִימְנָא, כַּמָּה עָאקוּ עַל עָאקוּ, זַמִּינִין לְשַׂנְאֵיהוֹן דְּיִשְׂרָאֵל בְּגָלוּתָא, וְכַמָּה יִשְׁלְטוּן חֵיוָותָא, וְכַמָּה יִשְׁאֲגוּן לְמִיטְרַף טַרְפִין דְּיִשְׂרָאֵל, בְּכָל זִמְנָא וְזִמְנָא עַד סוֹף יוֹמַיָא.</p>"],[9514013437,"<p>כָעֵת לְסוֹף יוֹמַיָא, כְּפוּם שַׁעֲתָא דְּיוֹמָא, בְּעִידָן דִּי זְרַח שִׁמְשָׁא, מִן יוֹמָא שְׁתִיתָאָה, בְּשַׁעֲתָא דְּיִזְדַּמְּנוּן לְפוּם מִנְיַן שְׁנִין, דְּיוֹבֵל וּשְׁמִטָה כַּחֲדָא, דְּאִיהוּ רעַל דָּא מִן יוֹמָא שְׁתִיתָאָה. כָּעֵת זְמִינָא קָלָא חָדָא לְאִתְעָרָא מֵרוֹם רוֹמֵי רְקִיעִין, קָלָא עָצִיב בִּמְרִירוּ, מַה דְּלָא הֲוָה הָכֵי מִן יוֹמָא דְּאִתְבְּרוּן עָלְמִין.</p>"],[9514013438,"<p>וְהַהוּא קָלָא יֶהֱוֵי דַּקִיק, בַּחֲשַׁאי, בִּמְרִירוּ, וַעֲצִיבוּ, נְחֵית וּסְלֵיק, סְלֵיק וּנְחֵית, וְכֵן אֲמַר, אַיֶּילֶת רְחִימִין הֲוַת לִי מִן יוֹמִין קַדְמָאִין, וְאִתְנְשִׂיאַת מִינָאי. רְחוּמִין קַיָּימִין הֲוֵי לִי בַּהֲדָהּ, אַדְכַּרְנָא דְּחוֹתְמָא דִּדְיוֹקְנָה הֲוָה חָתֵים עַל לִבִּי, וַהֲוָה חָתֵים עַל דְּרוֹעָאי, וַהֲוָה תַּקִּיף בְּגַוִּוי רְחִימוּ דִילָהּ, וְרִשְׁפֵּי שַׁלְהוֹבָה מוֹקְדִין בְּגַוִּוי.</p>"],[9514013439,"<p>בְּהַהוּא שַׁעֲתָא גָּעֵי תְּלַת גּוֹעִין, דָּא בָּתַר דָּא, וְיִזְדַּעְזְעוּן רְקִיעִין, וְיִזְדַּעְזְעוּן עָלְמִין כָּלְהוֹ, עַד דְּיִשְׁתַּמְּעוּ קָלִין תְּלַת, לְגוֹ נוּנָא תַּנִּינָא, וְיֵעֲרוֹק אַרְבַּע מְאָה אֶלֶף פַּרְסֵי גּוֹ נוּנָא חַד דְּיַמָּא. וְתַמָּן יוֹשִׁיט מְצוֹדִין וְיַפְרִישׂ רִשְׁתִּין, וְיַמְשִׁיךְ לֵיהּ מִן יַמָּא, וְיָעֵיל לֵיהּ גּוֹ מְתִיבְתָּא דְרָקִיעַ, וְיֶחֱמוּן מִנֵּיהּ כָּל אִינוּן קוֹשִׁין וְכָל אִינוּן פְּלוּגְתִּין דְּאַקְשֵׁי תַּמָּן. וִיהֵא תָּפִיס תַּמָּן מְאָה וְחַמְשִׁין יוֹמִין.</p>"],[9514013440,"<p>וְהַהוּא זִמְנָא, יִכְנוֹשׁ קוּדְשָׁא בְּרִיךְ הוּא כָּל חֵיילֵי שְׁמַיָּיא, וְכָל בְּנֵי מְתִיבְתָּא דִילֵיהּ, וְהוּא לְעֵילָא מִכָּלְהוֹ, וְאַיְיתוּן קַמֵּיהּ הַהוּא תִּנְיָינָא, וְיִקְשׁוֹר תְּלַת קִשְׁרִין בְּקוֹדְלֵיהּ, וְיִטְלוּ אִינוּן תְּלַת רְחִימִין, וִיהַדְּרוּן לֵיהּ לַאֲתַר דַהֲוָה תָּפִיס תַּמָּן. וְאִינוּן רְחִימִין יֵיעֲלוּן בְּהֵיכָלָא חָדָא דְּאִיקְרֵי אַהֲבָה, וִיהוֹן גְּנִיזִין תַּמָּן.</p>"],[9514013441,"<p>וְאוֹמֵי לוֹן קוּדְשָׁא בְּרִיךְ הוּא, לְכָל אִינוּן חַיָּילִין, וְלִתְרֵי מְתִיבְתֵּי, לְמֵהַךְ כָּלְהוֹ, וּלְמִשְׁמַע קָלָא דִּרְחִימוּתָא, דְּאִיהוּ תָּאֵיב לְמִשְׁמַע קָלָה בַּהֲדַיְיהוּ. בְּהַהוּא שַׁעֲתָא יִתְעַר עַל עַמָּא קַדִּישָׁא עָאקִין, אִלֵּין עַל אִלֵּין, בִּדְחִיקוּ סַגֵּי, וְאִינוּן צָוְוחִין צְוָוחָה בָּתַר צְוָוחָה, דִּמְעִין בָּתַר דִּמְעִין, וְיִתְעֲרוּן לָהּ. אִיהִי אַשְׁמָעַת קָלָא עַל בְּנָהָא.</p>"],[9514013442,"<p>וְקוּדְשָׁא בְּרִיךְ הוּא קָארֵי וַאֲמַר, דָּא הִיא אַיָּילָתִי, חֲבֵירָתִי, יוֹנָתִי, שְׁלֵימָתִי הַיּוֹשֶׁבֶת בַּגַּנִּים, דְּלָא הֲוַת יָתְבָא אֶלָּא בְּסֵתֶר הַמַּדְרֵגָה פְּנִימָאָה, כְּמָה דְאַתְּ אָמֵר (תהילים מ״ה:י״ד) כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה, וְהַשְׁתָּא בַּגַּנִּים, בַּחֲצִיפוּ, כְּאִימָּא דְאָזְלָא בָּתַר בְּרָהּ, בַּשְּׁוָוקִים וּבְפוּתְיֵי קַרְתָּא, מִדְּחִילוּ דְּלָא יַבְאִישׁוּן לֵיהּ.</p>"],[9514013443,"<p>אַיָּילָתִי חֲבֵירָתִי חֲמִי, הָא חַבְרַיָיא כָּלְהוֹ דִּתְרֵי מְתִיבְתֵּי הָכָא. חֲבֵרִים דְּאִינוּן מְתִיבְתֵּי, מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִּי, דְּתֵיאוּבְתִּי לְמִשְׁמַע לְקָלָךְ.</p>"],[9514013444,"<p>כַמָּה זִמְנִין אִיהוּ דְּלָא שְׁמַעְנָא לְקָלָךְ, וְלָא יְדַעְנָא לָךְ. כְּדֵין כָּל עַלְמָא בְּעִרְבּוּבְיָיא, עַמִּין בְּעַמִּין אוּמִּין בְּאוּמִּין. וּמַאן דְּלָא אִתְחֲזֵי לְמַלְכָּא, יֵיתוּן לֵיהּ לְמִישְׁלַט. וְיֵיתוּן עִמֵּיהּ עַמִּין נוּכְרָאִין, וְלִישָׁנִין אוֹחֲרָנִין, דְּלָא יִשְׁתְּמוֹדְעִין דִּינָא, וְלָא נִימוּסֵי מַלְכוּתָא. וְכַמָּה קְרָבִין יַחְשְׁבוּן לְמֶעְבַּד.</p>"],[9514013445,"<p>וּבְגוֹ שָׂפָה רַפְיָיא, וּמַמְלַל רָכִּיךְ, יַעֲבֵיד כִּרְעוּתֵיהּ, וְיִשְׁלוֹט. וְיַחְשֵׁיב כַּמָּה מַחְשְׁבִין לְאַבְאָשָׁא. וְעַל עַמָּא יְחִידָאָה יַעֲבֵיד נִימּוּסִין בִּישִׁין. כְּדֵין יְהֵא עָאקוּ עַל עָאקוּ, עַל הַהוּא עַמָּא יְחִידָאָה. בֵּיהּ זִימְנָא יִתְתַּקַּף קוּדְשָׁא בְּרִיךְ הוּא, וִיפַיֵּיס לְאַיַּילְתֵּיהּ בְּכַמָּה פִּיּוּסִין, וְיַתְקֵיף בָּהּ, וִיקִים לָהּ מֵעַפְרָא, אִיהוּ וְלָא אָחֳרָא. וּתְרֵי מְתִיבְתֵּי יִשְׁתָּאֲרוּן בַּהֲדָהּ.</p>"],[9514013446,"<p>תְּלַת מַלְכִין יִשְׁתָּאֲרוּן, וְיִתְעָרוֹן בִּתְלַת סִטְרִין דְּעָלְמָא, עַל עַמָּא דָא. וְהַהוּא מַלְכָּא דְּהֲוָה שָׁלֵיט בְּפוּם רַכִּיךְ, יִשְׁלוֹט בִּרְגַז סַגְיָא, וְנֵס וְתוֹקְפָא עַל עַמָּא קַדִּישָׁא.</p>"],[9514013447,"<p>וּבְיַרְחָא תְּלִיתָאֵי, בְּד' לְיַרְחָא, בְּתֵשַׁע שַׁעֲתֵי וּפַלְגָא, יֵהֲכוּן כָּל בְּנֵי מְתִיבְתֵּי בַּהֲדָה דְּאַיַּילְתָּא, לְגוֹ קִבְרֵיהּ דְּרַעֲיָא, מְהֵימְנָא דְבֵיתָא, וְתֵיהַב תְּלַת קָלִין עֲלֵיהּ. בְּשַׁעֲתָא דְשִׁמְשָׁא יִתְכְּנֵישׁ מֵעָלְמָא, וְקִבְרֵיהּ יִתְפַּתַּח, וְיִבְעוּן בְּנֵי מְתִיבְתֵּי לַעֲאָלָא לְתַמָּן, וְלָא יִתְיְיהֵיב לוֹן רְשׁוּתָא, וְיִסְתַּלְּקוּן כָּלְהוֹ לְאַתְרַיְיהוּ. וְהִיא תֵיעוֹל, וּמִגַּוֵּויהּ יִפּוֹק מַה דְּיִפּוֹק. וְתִשְׁכַּח לְמשֶׁה יָתֵיב וְלָעֵי, וּבוּצִינָא דָּלֵיק קַמֵּיהּ, וְכַמָּה רֵיחִין וּבוּסְמִין סַחֲרָנֵיהּ.</p>"],[9514013448,"<p>כֵיוָן דְּחָאמֵי לָהּ דְּעָאלַת, יָקוּם, וְיִתְחַבְּרוּן כַּחֲדָא דָּא עִם דָּא, וְקָלְיָא יִתְעֲרוּן בְּרוּם רוּמֵי רְקִיעִין, וְקוּדְשָׁא בְּרִיךְ הוּא יִשְׁמַע, וְיֵיעוֹל לְגוֹ הֵיכָלָא דְּאַהֲבָה, וְיִטוֹל מִתַּמָּן תְּלַת רְחִימִין, וְיִפְתַּח לוֹן מְעַרְתֵּיהּ. כְּדֵין יִתְעַר מָשִׁיחַ בְּהַהוּא לֵילְיָא, וְיִשְׁתַּכַּח תַּמָּן בַּהֲדַיְיהוּ, וִיהַדְּרוּן רָזִין דְּאוֹרַיְיתָא, בְּכָל הַהוּא לֵילְיָיא, בִּמְעַרְתָּא דְמשֶׁה.</p>"],[9514013449,"<p>וְכַד סָלֵיק עַמּוּדָא דְצַפְרָא, יִתְגְּנֵיז מָשִׁיחַ וְיִשְׁתָּאֲרוּן משֶׁה וּשְׁכִינְתָּא בְּהַהוּא יוֹמָא, כְּיוֹמָא דְּשָׁבוּעוֹת. וְסַלְקָא שְׁכִינְתָּא עַל הַהוּא טוּרָא, וְתִשְׁתְּמַע תְּלַת קָלִין, חַד לָקֳבֵיל אַבְרָהָם, וְחַד לָקֳבֵיל יִצְחָק, וְחַד לָקֳבֵיל משֶׁה וְיַעֲקֹב. הֲדָא הוּא דִכְתִיב, (ישעיהו מ׳:ט׳) עַל הַר גָּבֹהַּ עֲלִי לָךְ מְבַשֶּׂרֶת צִיּוֹן הָרִימִי בַכֹּחַ קוֹלֵךְ וְגו' הָרִימִי אַל תִּירָאִי אִמְרִי כו'.</p>"],[9514013450,"<p>הָרִימִי, הָרִימִי, אִמְרִי. דָּא הָרִימִי בַכֹּחַ, תְּרוּעָה. הָרִימִי אַל תִּירָאִי, תְּקִיעָה. אִמְרִי, הָא תְּרוּעָה תְּקִיעָה וּתְרוּעָה כַּחֲדָא. וְדָא אִיקְרָא שׁוֹפָר תְּרוּעָה. שׁוֹפָר מֵהַהוּא תְּרוּעָה דִּלְעֵילָא.</p>"],[9514013451,"<p>שׁוֹפָר זְעֵירָא, בְּגִין דְּאִית אָחֳרָא דְּאִקְרֵי שׁוֹפָר גָּדוֹל. שׁוֹפָר זְעֵירָא דָּא, אִקְּרֵי שׁוֹפָר הוֹלֵךְ גּוֹ תְּנוּעָה דְּבוּצִינָא, הֲדָא הוּא דִכְתִיב, (שמות י״ט:י״ט) וַיְהִי קוֹל הַשּׁוֹפָר הוֹלֵךְ. בְּגִין דְּאָחֳרָא אִיהוּ שׁוֹפָר גָּנִיז וְטָמִיר, וְלָא הוֹלֵךְ. אֲבָל דָּא זְעֵירָא, אִיהוּ הָכָא בְּיוֹמָא דְּשָׁבוּעוֹת, וְהַאי אִיהוּ דְּאִיתְעַר בְּיוֹמָא דְאוֹרַיְיתָא, בְּיוֹמָא דְשָׁבוּעוֹת.</p>"],[9514013452,"<p>בְּאִתְעָרוּ דְּהַאי שׁוֹפָר, דְּאִיתְעַר בִּתְרוּעָה וּתְקִיעָה וּתְרוּעָה, יִתְעָרוּן אֲבָהָן מִגּוֹ מְעַרְתָּא, וְיִסְתַּלְּקוּן בְּרוּחָא, וְיֵיתוּן לְגַבָּהּ. וּמֵהַהוּא קָלָא, כַּמָּה חַיָּיבִין בְּאַרְעָא קַדִּישָׁא יְמוּתוּן, וְיִסְתַּלְּקִין מֵעָלְמָא. בְּהַהוּא יוֹמָא, סָלְקִין צְלוֹתִין דְּיִשְׂרָאֵל בְּכָל אֲתַר, דְּאִינוּן קַמֵּי מַלְכָּא קַדִּישָׁא. וַאֲבָהָן יֵיתוּן כַּחֲדָא, וִיהוֹן בְּהַהוּא טוּרָא. וּמשֶׁה סָלֵיק בַּהֲדַיְּיהוּ. וְתַמָּן יִסְתַּכֵּל בַּאֲבָהָן, וְאִינוּן בֵּיהּ. וְיֵיעֲלוּן כָּלְהוֹ גּוֹ מְעַרְתָּא דְמשֶׁה. וּמָשִׁיחַ יִתְעַר לְגַבַּיְיהוּ, וְיִתְחַבְּרוּן כָּלְהוֹן בְּהַאי יוֹמָא.</p>"],[9514013453,"<p>וּבְהַאי יוֹמָא, יִתְעָרוּן עֶשֶׂר שִׁבְטִין, לַאֲגָחָא קְרָבִין לְאַרְבַּע סִטְרִין דְּעָלְמָא, בַּהֲדֵי מְשִׁיחָא דְּאִתְמְשַׁח עֲלַיְיהוּ, וִיקַבֵּל מְשִׁיחוֹ עַל יְדָא דְּחַד כֹּהֵן צֶדֶק, וְשִׁבְעָה רוֹעִים מְהֵימְנָן עִמֵּיהּ.</p>"],[9514013454,"<p>וּמְשִׁיחָא דָא מִשִּׁבְטָא דְאֶפְרַיִם הוּא, וּמִזַּרְעָא דְּיָרָבְעָם בֶּן נְבָט הֲוֵי בְּרֵיהּ דַּאֲבִיָּה, דִּבְעוּלֵימוֹי מֵת, וְהַהוּא יוֹמָא דְמֵת, אִתְיְילֵיד לֵיהּ בַּר, וְאִתְנְטֵיל מִבֵּי יָרָבְעָם לְמַדְבְּרָא. וּלְתַמָּן נְטָלוּ מְאָה וְשִׁבְעִין גִּבָּרִין, כָּלְהוֹ זַכָּאִין מִשִּׁבְטָא דְאֶפְרָיִם, דְּלָא אִשְׁתַּכְּחוֹ בְּחוֹבָא דְיָרָבְעָם.</p>"],[9514013455,"<p>וּמֵהַאי בְּרֵיהּ דַּאֲבִיָּה, נְפֵיק הַאי מְשִׁיחָא. וְעַל דָּא כְּתִיב, (מלכים א י״ד:י״ג) וְסָפְדוּ לוֹ כָל יִשְׂרָאֵל וְקָבְרוּ אֹתוֹ. סְתִים הַאי נְבוּאָה לְשַׁעֲתָא, וּנְבוּאָה לֶעָתִיד, כִּי זֶה לְבַדּוֹ יָבֹא לְיָרָבְעָם אֶל קָבֶר יַעַן נִמְצָא בוֹ דָּבָר טוֹב אֶל ה' אֱלֹהֵי יִשְׂרָאֵל בְּבֵית יָרָבְעָם. דָּא הַאי מְשִׁיחָא, דְּאִיהוּ דָּבָר טוֹב אֶל ה'.</p>"],[9514013456,"<p>כֵיוָן דְּיִנְדְּעוּן אֲבָהָן, דְּפַקֵּיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַיַּילְתֵּיהּ וּלְעַמֵּיהּ, כַּמָּה חֵידוּ עַל חֵידוּ בְּהַאי יוֹמָא. בְּאַרְעָא דְּצָפוֹן מַלְכוּתָא דְתֵימָן, כַּמָּה עָאקוֹ עַל עָאקוֹ יִתְעָרוּן בְּהַאי יוֹמָא עַל עַמָּא דְיִשְׂרָאֵל, וְתִתְקַבֵּל צְלוֹתְהוֹן בְּרַעֲוָוא. וּבְפַנְיָיא דְּהַאי יוֹמָא, תֶּהֱדַר שְׁכִינְתָּא לְגוֹ בֵיתָא, וּמָשִׁיחַ לְאַתְרֵיהּ, וַאֲבָהָן לְגוֹ מְעַרְתָּא דִּילְהוֹן.</p>"],[9514013457,"<p>שְׁכִינְתָּא תְּהַךְ וְתֶהֱדַר לְגַבֵּי משֶׁה, שִׁבְעִין יוֹמִין. לְסוֹף שִׁבְעִין יוֹמִין, סָלֵיק נְאָקוֹ דְּיִשְׂרָאֵל לְקַמֵּי מַלְכָּא קַדִּישָׁא, דִּיהוֹן מְעִיקִין לוֹן בְּכָל סִטְרִין דְּעָלְמָא. וּכְנִישְׁתָּא חָדָא לְצַד דָּרוֹמָא יִתְאֲבֵיד וְיִתְחֲרֵיב. וַחֲמִשָּׁה זַכָּאֵי קְשׁוֹט יִתְקַטְלוּן בֵּינַיְיהוּ.</p>"],[9514013458,"<p>כְדֵין לְסוֹף תְּלָתִין וּתְּרֵין יוֹמִין דְּיִקְטְלוּן לִכְנִישְׁתָּא הַהִיא, יִלְבַּשׁ קוּדְשָׁא בְּרִיךְ הוּא קִנְאָה לְהַהוּא שׁוֹפָר זְעֵירָא. וְהַהוּא מָשִׁיחַ בְּרֵיהּ דְּאֶפְרַיִם יִפְרוֹשׂ פְּרִישָׂא כְּחַד תּוֹר דְּקַרְנוֹי סָלְקִין כְּקַרְנוֹי דִּרְאֵם.</p>"],[9514013459,"<p>וְהַהוּא שׁוֹפָר זְעֵירָא, יִתְקַע תְּרוּעָה תְּקִיעָה וּתְרוּעָה, תְּלַת זִמְנִין בְּרֵישׁ טוּרָא כְּמִלְּקַדְּמִין, כְּדֵין נָטְלִין דִּגְלִין דְּהַהוּא מָשִׁיחַ, וְיִפּוֹל רַעֲשָׁא עַל עָלְמָא, בְּאִינוּן קָלִין דְּשׁוֹפָרָא. וְכָל אִינוּן בְּנֵי עָלְמָא יִשְׁמְעוּן וְיֶחֱמוּן. כְּמדָּבָר אַחֵר, (ישעיהו י״ח:ג׳) כָּל ישְׁבֵי תֵבֵל וְשֹׁכְנֵי אָרֶץ כִּנְשׂא נֵס הָרִים תִּרְאוּ וְכִתְקֹעַ שׁוֹפָר תִּשְׁמָעוּ.</p>"],[9514013460,"<p>וּכְדֵין יִתְבַּעֲרוּן גִּלּוּלִין מִן אַרְעָא קַדִּישָׁא. וּתְלַת קְרָבִין יַעַבְדוּן בְּנֵי יִשְׁמָעֵאל בַּהֲדֵי מָשִׁיחַ דָּא. וְאִינוּן יֵיתִין וְיִסְגְּדוּן לְמָארֵי עָלְמָא בְּטוּרָא דְקוּדְּשָׁא בִּירוּשָׁלַיִם. וְאִילֵין קְרָבִין יְהוֹן בְּאֶלֶף שְׁתִיתָאָה.</p>"],[9514013461,"<p>וּבְיַרְחָא דְבוּל, יִפּוֹלוּ שַׂנְאֵיהוֹן, וְיִתְעַבְרוּן כָּל אִינוּן גִּילוּלִין דְּיִשְׁתָּאֲרוּן בְּאַרְעָא קַדִּישָׁא. וּמִתַּמָּן יַהֲכוּן וְיִתְעָרוּן קְרָבִין עַל עָלְמָא. וּבְעוֹד דְּאִינוּן יַגִּיחוּן קְרָבִין עִם כָּל בְּנֵי עָלְמָא, יִתְכַּנְּשׁוּן בְּנוֹי דֶּאֱדוֹם עַל אַרְעָא קַדִּישָׁא, וְיִתְפְּסוּן לָהּ, וְיִשְׁלְטוּן עֲלָהּ תְּרֵיסַר יַרְחֵי.</p>"],[9514013462,"<p>לְסוֹף תְּרֵיסַר יַרְחִין, יִתְגַּעַשׁ וְיִרְעַשׁ כָּל עָלְמָא. וּבֵין זִמְנִין אִלֵּין, דִּשְׁכִינְתָּא תֵּהַךְ וְתֶהֱדַר לְגַבֵּי מְעַרְתָּא דְמשֶׁה, יַתְטַמַּר מַלְכָּא מְשִׁיחָא ט' יַרְחִין, כְּיַרְחִין דְּיוֹלֵדָה, וְאִינוּן ט' יַרְחִין, כַּמָּה צִירִין וַחֲבָלִים יִטוֹל עַל גַּרְמֵיהּ.</p>"],[9514013463,"<p>וּבֵין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא יַסְגֵּי צַעֲרֵיהּ, וְיֵעוֹל לְגוֹ שְׁבִילִין דְּאִילָנָא חָדָא, דְּאִית לֵיהּ אִילָנָא קַדִּישָׁא רַבְרְבָא וְתַקִּיף. וְתַמָּן בְּשִׁבְעִין עַנְפִין, יִטוֹל מְכִילָן דַּאֲלַכְסוֹנִין, וְיִטוֹל לְשִׁבְעִין מְמַנָּן, דְּסַחֲרָאן לְשִׁבְעִין עַנְפִין דְּאִילָנָא, גּוֹ אִינוּן מְכִילָן אֲלַכְסוֹנִין, וְיִשְׁתַּכְּחוּן אֲסוּרִין חַד תַּקְלָא דִּמְכִילָא וּפַלְגּוּ. כְּדֵין יָחֵית לוֹן מִכָּל עֲנָפָא וַעֲנָפָא.</p>"],[9514013464,"<p>וְכַמָּה עַנְפִין זְעִירִין וּדְלָא זְעִירִין יִתָּבְרוּן בְּמֵיחַתְהוֹן מִתַּמָּן, בְּגִין דְּאִתְאַחֲדָאן גּוֹ עַנְפִין, וּבְמֵיחַתְהוֹן יִתָּבְרוּ. כְּדֵין כַּמָּה סַגִּיאִין מֵעַמָּא קַדִּישָׁא יִתָּבְרוּן בֵּין רַגְלִין דִּשְּׁאָר עַמִּין. וְכָל אִינוּן מְמַנָּן, יַעַבְרוּן לוֹן גּוֹ נְהַר דִּינוּר, וְיִתְעַבְרוּן מִשּׁוּלְטָנֵיהוֹן.</p>"],[9514013465,"<p>וּבֵין כָּךְ מָשִׁיחַ צִירִין וַחֲבָלִין יְהוֹן לֵיהּ כְּיוֹלֵדָה. וְעַל הַהוּא זִמְנָא כְּתִיב, (תהילים כ׳:ב׳) יַעַנְךָ ה' בְּיוֹם צָרָה. דְּאִינוּן תֵּשַׁע פְּסוּקִים כְּיַרְחִין דְיוֹלֵדָה. וְשִׁבְעִין תֵּיבִין, דְּהָא לְשִׁבְעִין שְׁנִין בְּאֶלֶף שְׁתִיתָאָה, יוֹלִיד וְיִשְׁלוֹט עַל כָּל עָלְמָא. וּבְגִין כָּךְ בְּאִינוּן תִּשְׁעָה יַרְחִין, יִתְחֲזוּן בְּכָל לֵילְיָא, מִפַּלְגוּ וָאֵילָךְ, רֶכֶב אֵשׁ וְסוּסֵי אֵשׁ לְבַר מֵרְקִיעָא, מְגִיחָן קְרָבִין אִלֵּין בְּאִלֵּין, עַד דְּיִנְהַר צַפְרָא.</p>"],[9514013466,"<p>לְבָתַר דְּאִינוּן תִּשְׁעָה יַרְחִין יַעַבְרוּן, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא יִתְעַר לְמָשִׁיחַ דָּא, וְיַפֵּיק לֵיהּ מִגִּנְתָּא דְעֵדֶן. וְהַהוּא יוֹמָא דְּיִפּוֹק, יִזְדַּעְזַע כָּל עָלְמָא, דְּיַחְשְׁבוּ כָּל בְּנֵי עָלְמָא דִּימוּתוּן.</p>"],[9514013467,"<p>וְעַל הַהוּא יוֹמָא כְּתִיב, (ישעיהו ב׳:י״ט) וּבָאוּ בִּמְעָרוֹת צוּרִים וּבִמְחִילוֹת עָפָר מִפְּנֵי פַּחַד ה'. דָּא שְׁכִינְתָּא, דְּתֵירוֹם מֵהַהוּא זִימְנָא וָאֵילָךְ, וּמָשִׁיחַ בַּהֲדָהּ. וּמֵהֲדַר גְּאוֹנוֹ, דָּא מָשִׁיחַ. בְּקוּמוֹ לַעֲרֹץ הָאָרֶץ. כְּדֵין (שם יא) וְאָסַף נִדְחֵי יִשְׂרָאֵל וּנְפֻצוֹת יְהוּדָה יְקַבֵּץ וְגו'. דָּא בְּשִׁתִּין שְׁנִין דְּאֶלֶף שְׁתִיתָאָה, וְיֵהֲכוּן לְבָתַר דְּיַעֲבֵיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא כַּמָּה נִסִּין.</p>"],[9514013468,"<p>(במדבר ל״א:י״ח) וְכֹל הַטַף בַּנָּשִׁים אֲשֶׁר לֹא יָדְעוּ מִשְׁכַּב זָכָר. תַּמָּן תָּנִינָן, אָמַר רִבִּי יְהוּדָה, אֵין הָעוֹלָם מִתְנַהֵג אֶלָּא בִּתְרֵין גְּוָונִין, דְּאָתוֹ מִסְטַר אִתְּתָא, דְּאִשְׁתַּכְּחַת חַכִּימַת לִבָּא. הֲדָא הוּא דִכְתִיב, (שמות ל״ה:כ״ה) וְכָל אִשָּׁה חָכְמַת לֵב בְּיָדֶיהָ טָווּ וַיָּבִיאוּ מַטְוֶה אֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן. וּמַאי מַתְיָין. אֶת הַתְּכֵלֶת וְאֶת הָאַרְגָּמָן, גְּוָונִין דִּכְלִילָן בְּגוֹ גְּוָונֵי.</p>"],[9514013469,"<p>הֲדָא הוּא דִכְתִיב, (משלי ל״א:י״ג-י״ד) דָּרְשָׁה צֶמֶר וּפִשְׁתִּים וַתַּעַשׂ בְּחֵפֶץ כַּפֶּיהָ. וּכְתִיב בְּיָדֶיהָ טָווּ. מַאי טָווּ. אָמַר רִבִּי יְהוּדָה, טָווּ בְּדִינָא, טָווּ בְּרַחֲמֵי, אָמַר רִבִּי יִצְחָק, אַמַּאי אִתְקַרְיָא אִשָּׁה. אָמַר לֵיהּ, דִּכְלִילָא בְּדִינָא, וּכְלִילָא בְּרַחֲמֵי. תָּא חֲזֵי, דְּאָמַר רִבִּי אֶלְעָזָר, כָּל אִתְּתָא בְּדִינָא אִתְקְרִיאַת, עַד דְּאַטְעֵמַת טַעֲמָא דְּרַחֲמֵי. דְּתַנְיָא, מִסִּטְרָא דְּבַר נָשׁ אָתֵי חִוָּורָא, וּמִסִּטְרָא דְאִתְּתָא אָתֵי סוּמְקָא, טַעֲמָא אִתְּתָא מֵחִוָּורָא, חִוָּורָא עָדִיף.</p>"],[9514013470,"<p>וְתָּא חֲזֵי, אַמַּאי אֲסִירָן נְשָׁא שְׁאָר עַמִּין דְּיָדְעֵי מִשְׁכְּבֵי דְכוּרָא. מִשּׁוּם דְּתָנִינָן, אִית יָמִינָא, וְאִית שְׂמָאלָא. יִשְׂרָאֵל, וּשְׁאָר עַמִּין. גַּן עֵדֶן, וְגֵיהִנֹּם. עָלְמָא דָא, וְעָלְמָא דְאָתֵי. יִשְׂרָאֵל לְקִבְלֵי דְּרַחֲמֵי, וּשְׁאָר עַמִּין לְקִבְלֵי דְדִינָא. וּתְנַן, אִתְּתָא דְּאַטְעֵמַת טַעֲמָא דְּרַחֲמֵי, רַחֲמִין נָצְחָא. אִתְּתָא דְּטָעֲמָא טַעֲמָא דְדִינָא, דִּינָא בְּדִינָא אִתְדַּבְּקַת. וַעֲלַיְיהוּ אִתְקְרֵי, (ישעיהו נ״ו:י״א) וְהַכְּלָבִים עַזִּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה.</p>"],[9514013471,"<p>וְעַל דָּא תָּנִינָן, הַנִּבְעֶלֶת לְגוֹי, קְשׁוּרָה בוֹ כְּכֶלֶב. מַה כַּלְבָּא תַּקִּיפָא בְּרוּחֵיהּ, חֲצִיפָא. אוּף הָכֵי דִינָא בְּדִינָא תַּקִּיפָא, חֲצִיפָא בְּכוֹלָא.</p>"],[9514013472,"<p>הַנִּבְעֶלֶת לְיִשְׂרָאֵל, תָּנִינָן, כְּתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. מַאי טַעְמָא, מִשּׁוּם דְּנִשְׁמָתָא דְיִשְׂרָאֵל, אַתְיָיא מֵרוּחָא דֵאלֹהִים חַיִּים. דִּכְתִיב, (ישעיהו נ״ז:ט״ז) כִּי רוּחַ מִלְּפָנַי יַעֲטוֹף. מַשְׁמַע דִּכְתִיב מִלְּפָנַי. וּבְגִין כָּךְ אִתְּתָא דְּהִיא בְּתוּלְתָּא, דְּלָא אִתְדַּבְּקַת בְּדִינָא קַשְׁיָא דִשְׁאָר עַמִּין, וְאִתְדַּבְּקַת בְּיִשְׂרָאֵל, רַחֲמִין נָצְחָא וְאִתְכַּשְׁרַת.</p>"],[9514013473,"<p>וְתָּא חֲזֵי, כְּתִיב (תהילים פ״ט:ג׳) כִּי אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. מַאי חֶסֶד. הוּא חַד מִכִּתְרֵי עִילָּאִי דְמַלְכָּא. דְּנִשְׁמָתָא דְיִשְׂרָאֵל קָרָא לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא חֶסֶד, עַל תְּנַאי דְּיִתְבְּנֵי, וְלָא יִשְׁתֵּיצֵי חֶסֶד מֵעָלְמָא, מַשְׁמַע דִּכְתִיב יִבָּנֶה.</p>"],[9514013474,"<p>בְּגִין כַּךְ תָּנִינָן, מַאן דְּשֵׁצֵי חֶסֶד מֵעָלְמָא, אִשְׁתֵּיצֵי הוּא לְעָלְמָא דְאָתֵי. וְעַל דָּא כְּתִיב, (דברים כ״ה:ה׳) לֹא תִהְיֶה אֵשֶׁת הַמֵּת הַחוּצָה, בְּגִין לְמֵיעְבַּד חֶסֶד עִם מִיתָא, וְאִתְעֲבֵיד בִּנְיָנָא, דִּכְתִיב עוֹלָם חֶסֶד יִבָּנֶה.</p>"],[9514013475,"<p>מַאֲמָר קַו הַמִּדָּה. אָמַר רִבִּי שִׁמְעוֹן, עַד הָכָא לָא הֲווֹ חַבְרַיָיא יָדְעֵי רָזָא דְּגוֹ יִחוּדָא. אָמַר רִבִּי אֶלְעָזָר, כָּל קְרָאִין דְּאוֹרַיְיתָא רָזִין סְתִימִין עִילָּאִין אִינוּן, וְהַאי קְרָא מַאן אִיהוּ.</p>"],[9514013476,"<p>פְּתַח וַאֲמַר, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. הַאי קְרָא, אַף עַל גַּב דְּכַמָּה סִטְרִין דָּרִישְׁנָא בֵּיהּ, רָזָא דְּיִיחוּדָא דְּבֵיהּ סְתִימָא מַעְיָינִין, לִבָּא אָטֵים הוּא מִנֵּיהּ, דְּכַמָּה חַכִּימִין טְרִישִׁין דְּלִבָּא לָעָאן, וְלָא יָדְעֵי, וְלָא אִדְבָּקִין. סְתִים מֵחֵיזוּ עֵינֵיהוֹן, וּמְסוּכְלְתָנוֹ לִבֵּיהוֹן. תָּא חֲזֵי, בְּרָזָא דְּיִיחוּדָא אַתְוָון טְמִירִין, שׁוּרִין וְתֵיבִין גְּלִיפִין בְּקִיּוּמַיְיהוּ.</p>"],[9514013477,"<p>שְׁמַע, שְׁמָא דְרָזָא דְיִיחוּדָא, גּוֹ טְמִירָא עִילָּאָה סְתִים, וְגַלְיָא גוֹ גְּלִיפֵי טְמִירִין, לְסַלְקָא בְדַרְגּוֹי לְאִשְׁתַּלָּמָא לְעֵילָא. שְׁמַע, בֵּיהּ תַּלְיָיא שֵׁ\"ם, בֵּיהּ תַּלְיָיא שְׁמִיעָה. שֵׁם, כְּמָה דְאַתְּ אָמֵר (שמואל ב ו) אֲשֶׁר נִקְרָא שֵׁם. ע', אַשְׁגָּחוּתָא דְּרֵישׁ שַׁתָּא וְעַד סְיָיפָא שַׁתָּא.</p>"],[9514013478,"<p>ע' טוֹבָה לְאִסְתַּכָּלָא בֵּיהּ. בְּגִין דְּאִית עַיִן טוֹבָה וְעַיִן רָעָה. עַיִן טוֹבָה, מִסִּטְרָא דְּיָמִינָא. עַיִן רָעָה מִסִּטְרָא דִשְׂמָאלָא. עַיִן טוֹבָה, הַיְינוּ רָזָא דִּרְשִׁים בֵּיהּ יִשְׂרָאֵל, דִּכְתִיב שְׁמַע יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. וְאוֹקְמוּהָ, דְּהָכָא יִשְׂרָאֵל סָבָא.</p>"],[9514013479,"<p>וּמַאן דַּאֲמַר יִשְׂרָאֵל זוּטָא, כֹּלָּא חַד. יִשְׂרָאֵל זוּטָא שַׁפִּיר, דְּעַיִן סְמִיךְ בֵּיהּ. וּמַאן אִיהוּ. דִּכְתִיב (איוב ל״ו:ז׳) לֹא יִגְרַע מִצַּדִּיק עֵינָיו. וְדָא ו' זְעֵירָא. ו' עִילָּאָה, ו' זְעֵירָא כֹּלָּא חַד. ו' זְעֵירָא, מַבּוּעָא דְבֵירָא דְּלָא אַפְסֵיק מִנֵּיהּ לְעָלְמִין.</p>"],[9514013480,"<p>עַד הָכָא אִתְפָּרְשׁוּ אוֹרְחִין גְּלִיפִין בְּרָזָא דָא. מִכָּאן וּלְהָלְאָה, רָזֵי דְרָזִין דְּיִיחוּדָא שְׁלִים, כִּדְקָא חָזֵי שִׁיעוּרָא דְּלֵיהּ שִׁיעוּרָא לְמֶיעְבַּד מְדִידִין וְשִׁיעוּרִין לְסִטְרִין כָּלְהוֹ.</p>"],[9514013481,"<p>יהוה אֱלֹהֵינוּ יהוה. רָזָא דְּאַרְבֵּיסַר אַתְוָון. תְּלַת שְׁמָהָן פְּנִימָאִין, כְּלָלָא דְּכֹלָּא. רָזָא חָדָא, עֵילָא וְאֶמְצָעִיתָא וְתַתָּא. הָכָא כְּלָלָא דְּכָל סִטְרִין, מֵאֲתַר דְּלֵית בֵּיהּ שִׁיעוּרָא דְּאִקְרֵי אֵין סוֹף, עַד סְיָיפֵי סִטְרָא בַּתְרָאָה תַּתָּאָה לְכָל דַּרְגִּין.</p>"],[9514013482,"<p>חַה לְעֵילָא, אֲתַר דְּשֵׁירוּתָא, דְּמִתַּמָּן נָפְקִין שְׁבִילִין לְכָל סִטְרִין. חַד בְּאֶמְצָעִיתָא רָזָא דְמשֶׁה אַכְלֵיל גַּרְמֵיהּ בֵּיהּ בְּגוֹ אַבְרָהָם וְיִצְחָק. חַד כְּלָלָא דְּדָוִד מַלְכָּא. תִּיקּוּנָא וְסַמְכָא חַד לְכָלְהוֹ.</p>"],[9514013483,"<p>וְכַד מִתְחַבְּרָן אַתְוָון דִּמְהֵימְנוּתָא, אִתְגַּלְּיָין בְּחִבּוּרָא וְקִישּׁוּרָא דְּכֹלָּא. תְּרֵין עָלְמִין, עִילָּאָה וְתַתָּאָה. עִילָּאָה סָלְקָא עַד דְּלֵית שִׁיעוּרָא וְאֵין סוֹף. תַּתָּאָה נָחֲתָא. בְּשִׁעוּרָא עַד סוֹף דְּכָל דַּרְגִּין.</p>"],[9514013484,"<p>עָלְמָא עִילָּאָה דְּמִתְקַשְּׁרָא וְסָלְקָא עַד אֵין סוֹף, פָּלֵיג אַתְוֵוי בְּדַרְגּוֹי, שֶׁבַע אַתְוָון, יהו\"ה אל\"ה. עֲל כָּל רָזָא דְעָלְמָא עִילָּאָה, דְּמִתְקַשְּׁרָא וְסָלְקָא עַד אֵין סוֹף, וְּאִתְפְּלֵיג בְּאַתְוֵוי שִׁבְעָה. עַלְמָא תַּתָּאָה, דְּמִתְקַשְּׁרָא בֵּיהּ, וְנָחֲתָא עַד סוֹף דְּכָל דַּרְגִּין, פָּלֵיג אַתְוֵוי בְּדַרְגּוֹי שֶׁבַע אַתְוָון, ינ\"ו יהו\"ה. תְּלַת אַתְוָון עִילָּאִין, בְּד' אִלֵּין, רָזָא חָדָא, חִבּוּרָא וְקִשּׁוּרָא חָדָא, דְּלֵית בְּהוּ פֵּירוּדָא. וּבְגִין כָּךְ לְאַרְבֵּיסַר אַתְוָון ז' וְז', וְכֹלָּא חָד.</p>"],[9514013485,"<p>אֶחָה, וְאוֹקְמוּהָ דלי\"ת עִילָּאָה וְרַב עַל שְׁאָר אַתְוָון. וְכֵן רֵי\"ש דְּאֵל אַחֵר. לְאִשְׁתְּמוֹדְעָא, דְּלָא לְאַחְלָפָא רָזָא קַדִישָׁא עִילָּאָה, וּלְאַכְלָלָא סִטְרָא אֲחֳרָא בַּהֲדֵיהּ.</p>"],[9514013486,"<p>סִימָן עי\"ן דל\"ת דְּאִינוּן רַבְרְבִין, עַל דָּא, לְאַסְהָדָא סַהֲדוּתָא דְּרָזֵי דְרָזִין, לַאֲפָקָא מִשְׁחֲתָא חָדָא, לִמְשִׁיחוֹ דְּרָזָא דִמְהֵימְנוּתָא. וּמַאן דְּיָדַע רָזָא דָא, יָדַע רָזָא דְמָארֵיהּ וְאַחְסֵין תְּרֵין עָלְמִין, עַלְמָא דָא וְעַלְמָא דְאָתֵי. וּמִשְׁחֲתָא אִקְרֵי קַו הַמִּדָּה.</p>"],[9514013487,"<p>וְהָא אִתְיְיהֵיב לְחַכִּימֵי עֶלְיוֹנִים קַדִּישִׁין, דְּיָדְעִין רָזָא דְמָארֵיהוֹן וּמִשְׁתַּדְּלֵי בִּיקָרֵיהּ. וְלָא אִתְיְיהֵיב לְחַיָּיבֵי עָלְמָא, דְּלָא יָדְעֵי וְלָא חַיְישֵׁי לִיקָרָא דְמָארֵיהוֹן. וְאִינוּן זַכָּאֵי קְשׁוֹט דִּי בְהוֹ רָזָא דִמְהֵימְנוּתָא עִילָּאָה, לְהוֹ אִתְיְהֵיב לְמִנְדַע וּלְאִסְתַּכָּלָא, בְּגִין דְּלָא סָטָאן יָמִינָא וּשְׂמָאלָא.</p>"],[9514013488,"<p>קַו הַמִּדָּה, אוֹרֶךְ וְרוֹחַב. קַו הַמִּדָּה, עוֹמְקָא וְרוֹמָא. קַו הַמִּדָּה, עִיגּוּלָא וְרִיבּוּעָא. בִּתְלֵיסַר תַּרְעִין קָיְימָא לְמִנְדַע. וְאִינוּן שִׁיתָּא וְעֶשְׂרִין לִתְרֵין סִטְרִין, כַּד מִתְגַּלְּפֵי בְּגִילוּפַיְיהוּ. כֹּלָּא חַד בְּמִשְׁחֲתָא דָא. קַו הַמִּדָּה סָלְקָא וְנָחֲתָא, אִתְגְּלֵיף בִּגְלִיפוֹי לְכָל סִטְרִין.</p>"],[9514013489,"<p>נְהוֹרָא דְלָא קָיְימָא בִּנְהוֹרָא, גָּלֵיף, וּנְפֵיק נְצִיצוּ דְכָל נִצּוֹצִין, וּבָטַשׁ גּוֹ רַעֲוָא דְּרַעֲוָון, וְאִתְטַמַּר בֵּיהּ, וְלָא יְדִיעַ.</p>"],[9514013490,"<p>בְּזִמְנָא דְרַעֲוָא דָא בָּעָא לְאִתְפַּשְּׁטָא, נְפֵיק הַאי נְצִיצוּ דְּטָמִיר גּוֹ הַאי רְעוּתָא, בְּגִין דְּאִתְחֲזֵי, וְלָא אִתְחֲזֵי לְאִתְקַיְימָא כְּגַוְונָא דָא.</p>"],[9514013491,"<p>כַד אִתְפַּשַּׁט רְעוּתָא דָא, בָּטַשׁ הַאי נְצִיצוּ, דְּאַחֲזֵי גַוָּון וְלָא גַוָון, וְעָאל בְּהַהוּא אִתְפַּשְׁטוּתָא, וּנְפַק בִּגְוָונוֹי, וְסָלְקָא, וְקָיְימָא בִּסְלִיקוּ גוֹ רְעוּתָא וְאִתְפַּשְׁטוּתָא.</p>"],[9514013492,"<p>בָּטַשׁ רַעֲוָא אִתְפַּשְׁטוּתָא דִילֵיהּ, בִּסְתִימוּ דְּלָא אִתְיְידַע, וְאַפֵּיק נְהוֹרִין דַּקִּיקִין צְלִילִין כְּלִילִין כַּחֲדָא. כַּד בָּעָאן לְנָפְקָא הַאי נְצִיצוּ, דְּבֵיהּ גְּוָונִין. בָּטַשׁ בְּהַהוּא אִתְפַּשְׁטוּתָא, וְאִתְדְּחֵיק. וּמִגּוֹ דְּחִיקוּ, נָפְקִין אִינוּן נְהוֹרִין דַּקִּיקִין, וְאִשְׁתַּמְּעוּ כַּחֲדָא. כְּדֵין הַאי נְצִיצוּ אַחֲזֵי בְּהוּ גַּוְונֵי, וְאִצְטַבַּע כָּלְהוֹ כַּחֲדָא, חִיוַּר וְסוּמָק וְיָרוֹק וְאוּכָם. וְאִתְעַכַּב בֵּיהּ תְּרֵיסַר יַרְחִין. וּלְבָתַר אִתְעַקְּרוּ מִתַּמָּן, וְאִשְׁתִּילוּ בַּאֲתַר אָחֳרָא.</p>"],[9514013493,"<p>וְהַאי נְצִיצוּ, סָלְקָא וְנָחֲתָא. וְהַאי אִיקְרֵי בּוּצִינָא דְּקַרְדִּינוּתָא. הַאי אַתְקֵין וּבָטַשׁ בְּכָל נְטִיעָן נְהוֹרִין, וְאוֹמֵר לוֹ גְּדַל. כְּדֵין אַפֵּיק מַבּוּעִין הַהוּא אִתְפַּשְּׁטוּתָא עִילָּאָה קַדְמָאָה, וְאַשְׁקֵי וְנָהֵיר לְכָלְהוֹ, וְאִתְרַבִּיאוּ.</p>"],[9514013494,"<p>בְּהַאי בּוּצִינָא דְּקַרְדִּינוּתָא, נָהֵיר מַאן דְּנָהֵיר, וְסָלְקָא וְנָחֲתָא, וְאִתְפְּשַׁט לְכָל סִטְרִין, וּכְדֵין אִיקְרֵי קַו הַמִּדָּה. וְקָיְימָא מִשְׁחֲתָא לְעֵילָא וְתַתָּא. קַו הַמִּדָּה בּוּצִינָא דְּקַרְדִּינוּתָא סְתִימָא דְּכָל סְתִימָן, מִשְׁחֲתָא נְהִירָא דְּאַתְקִין שַׁפִּירוּ לְכֹלָּא. הַהוּא שַׁפִּירוּ דִּנְפֵיק מִפְּשִׁיטוּ קַדְמָאָה, אִיהוּ אַתְקֵין לוֹן. בֵּיהּ קָיְימִין לְמִשְׁחֲתָא לְעֵילָא וְתַתָּא. מַאן דְּזָכֵי בְּהַאי, וְיָדַע בֵּיהּ, זָכָה לְמִנְדַע בְּחָכְמְתָא דְמָארֵיהּ, זַכָּאָה חוּלָקֵיהּ בְּהַאי עָלְמָא וּבְעָלְמָא דְאָתֵי.</p>"],[9514013495,"<p>דָּא מִשְׁחֲתָא לְרָזָא דִמְהֵימְנותָא, קַו הַמִּדָּה אוֹרְכָא וּפוּתְיָא בְּשִׁיעוּרָא. עוֹמְקָא וְרוֹמָא בְּשִׁיעוּרָא. עִיגּוּלָא וְרִבּוּעָא בְּשִׁיעוּרָא. כֹּלָּא סַחֲרָא מִשְׁחֲתָא חָדָא. כָּל נְהוֹרִין, וְכָל רָזִין, לָא סָלְקִין, וְלָא נָחֲתִין, וְלָא מִתְפַּשְּׁטִין, אֶלָּא בְּמִשְׁחֲתָא דָא. בַּר לְעֵילָא לְעֵילָא, דְּלֵית שִׁיעוּרָא, וְלָא קָיְימָא בְּהַאי לְאִסְתַּכָּלָא וּלְמִנְדַע.</p>"],[9514013496,"<p>כָל שִׁיעוּרִין וְכָל מִשְׁחָתִין הוּא כָּלֵיל לוֹן, וְכוֹלָּא אִתְכְּלֵיל בֵּיהּ. קַו הַמִּדָּה, אִינוּן גְּוָונִין דְּאִצְטַבְּעוּ בֵּיהּ, וְקָיְימִין בֵּיהּ, אִתְפַּשְּׁטוּ. וְכַד אִתְרַבִּיאוּ, סָלְקָן וּמִתְפַּשְׁטָן לְאוֹרְכָּא וּלְפוּתְיָא וְעוֹמְקָא וְרוֹמָא. וְאִיהוּ סָלְקָא וּמַדֵּיד לְכֹלָּא בְּמִשְׁחֲתָא חָדָא. שָׁארֵי מִלְּעֵילָא מֵאֲתַר דְּשָׁארֵי שִׁיעוּרָא, עַד סוֹף דַּרְגֵּי מְהֵימְנוּתָא.</p>"],[9514013497,"<p>תַּרְעָא קַדְמָאָה, שֵׁירוּתָא דְּשָׁארֵי טְמִירָא דִּטְמִירוּ, וְהַאי נְצִיצוּ אִתְרַבֵּי וְנָצֵיץ, דְּלָא אִתְגַּלְיָיא וְלָא אִתְיְדַע, עַד דְּמָטֵי לְרַעֲוָא דְרַעֲוִין, וּמִתַּמָּן אִתְגַּלְּיָיא וְלָא אִתְגַּלְּיָיא, עַד דְּקָשֵׁיר קִשְׁרִין לְמִשְׁחֲתָא, כְּגַוְונָא דְאִיהוּ מָדֵיד, הָכֵי אִתְרַבִּיאוּ וְסָלְקָן לְכָל סְטַר, קִשְׁרָא דְּנָעֵיץ מִתַּמָּן, וְשָׁרָאן קִשְׁרִין.</p>"],[9514013498,"<p>הַהוּא קִשְׁרָא קַדְמָאָה, תְּלָתָא אַלְפֵי עָלְמִין קְשִׁירִין בֵּיהּ. חַד עַלְמָא סַלְקָא לְעֵילָא, וְחַד נַחֲתָא לְגַבֵּיהּ, וְחַד נַחֲתָא לְתַתָּא מִנֵּיהּ, דְּאִיהוּ דַקִּיקָא מִכָּלְהוֹ. בֵּין עָלְמָא וְעָלְמָא אֶלֶף עָלְמִין. עָלְמָא תַּתָּאָה מִכָּלְהוֹ, אָרְכֵּיהּ אֶלֶף אַמִּין.</p>"],[9514013499,"<p>וַחֲמֵשׁ זַרְתִּין אִתְכְּלִילוּ בְּהַאי קִשְׁרָא. וְהַאי קִשְׁרָא, אוּרְכֵּיהּ תְּלָתָא אַלְפֵי עָלְמִין וַחֲמֲשׁ אֶצְבְּעָאן. פּוּתְיֵהּ, תְּלַת אַלְפֵי עָלְמִין.</p>"],[9514013500,"<p>וְכֹלָּא אִתְקַּשַּׁר בְּעִיגּוּלָא. עִיגּוּלָא דְסָלְקָא וְנָחֲתָא. בְּעִיגּוּלָא חָדָא שִׁית אַלְפִין עָלְמִין לְגוֹ מֵעִיגּוּלָא חַד. וְהַאי קִשְּׁרָא כָּלֵיל כֹּלָּא. הַאי קִשְּׁרָא קַדְמָאָה, קִיּוּמָא נָעִיץ מֵהָכָא, וְאִתְפַּשְּׁטוּ קְשָׁרִין וּמְדִידִין.</p>"],[9514013501,"<p>מֵהַאי קִשְּׁרָא, שָׁארֵי קַו הַמִּדָּה לְאִתְפַּשְׁטָא, מָדֵיד אֶלֶף דְּאִיהוּ עִיזְקָא חָדָא, וְאֶלֶף דְּאִיהוּ עִיזְקָא חָדָא, לְאִתְאַחֲדָא דָּא בְּדָא. וְאִלֵּין עִיזְקָן אִינוּן מָאתָן אֶלֶף עָלְמִין, דִּכְסִיף בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. וְאִלֵּין עִיזְקָן אִתְאַחֲדָן דָּא בְּדָא.</p>"],[9514013502,"<p>בֵּין עִיזְקָא וְעִיזְקָא, ת\"ק אֶלֶף עָלְמִין. וְאִלֵּין דְּפָתְחֵי תַּרְעִין לְכָל סְטַר. בֵּין עָלְמָא וְעָלְמָא טֶפַח. עִיזְקָא תִּנְיָינָא, רַב מֵחֲבֵירְתָּהּ בְּמִשְׁחֲתָא קַדְמָאָה דְּכֹלָּא.</p>"],[9514013503,"<p>מֵהָכָא אִתְפַּשַּׁט לְתַתָּא, וּמָדֵיד קַו הַמִּדָּה תְּלַת זַרְתִּין פְּשִׁיטִין בְּלָא קִשְׁרָא. אָרְכָּא דְּהַהוּא זֶרֶת שִׁתִּין רִבּוֹא עָלְמִין.</p>"],[9514013504,"<p>בְּהַאי זֶרֶת אִתְתַּקְּנוּ שָׁמַיִם, בְּרָזָא דְשִׁתִּין רִבּוֹא עָלְמִין. וְכָל עָלְמָא וְעָלְמָא כְּלִילָא בְּאַרְבַּע אַלְפִין עַלְמִין אָחֳרָנִין. הֲדָא הוּא דִכְתִיב, (ישעיהו מ׳:י״ב) וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן. אִתְפַּשַּׁט קַ\"ו הַמִּדָּ\"ה, וְאִתְתַּקַּן בִּמְדִידוּ תְּרֵין זַרְתִּין, וּפַלְגָּא, וּפְלַג פַּלְגָא, בְּלָא קִשְּׁרָא.</p>"],[9514013505,"<p>כָל מִשְׁחֲתִין אִלֵּין דְּהַאי סִטְרָא, דְּקָיְימָא בְּקַו הַמִּדָּה, מִשְׁחֲתָא חָדָא לְרִיבּוּעָא כֹּלָּא, וְלָאו הָכָא לְעִיגּוּלָא. וּמִשְׁחֲתָא דְּקָיְימָא בְּקַ\"ו הַמִּדָּ\"ה, אִיקְרֵי מִשְׁחֲתָא דְרִיבּוּעָא. בְּהַאי מִשְׁחֲתָא קָיְימָא כֹּלָּא וְאִתְקַיָּים.</p>"],[9514013506,"<p>עוֹמְקָא דְּרִיבּוּעָא דָא, חַמְשִׁין זַרְתִּין, לְאִתְפַּתְּחָא לַחֲמֵשׁ סִטְרִין. רוֹמָא חָמֵשׁ. וְעַד הָכָא קָיְימָא מִשְׁחֲתָא דְרִיבּוּעָא. וְהָכָא קָיְימָא קִשְׁרָא לְקִיּוּמָא, קִשְׁרָא קַדְמָאָה, דְּאִיהוּ שֵׁירוּתָא דְהַאי, אִיהוּ קִיּוּמָא. קַיְימָא קַו הַמִּדָּה בִּמְדִידוּ דְּמִשְׁחֲתָא, וְעַד הָכָא תַּרְעָא קַדְמָאָה לְקִיּוּמָא.</p>"],[9514013507,"<p>אִשְׁתַּכַח קַו הַמִּדָּה, בְּמִשְׁחֲתָא דָא דְּרִיבּוּעָא בְּכָל סִטְרוֹי, שֶׁבַע מְאָה אֶלֶף עָלְמִין, וְשִׁבְעָה טְפָחִים, וַחֲמֵשׁ זַרְתִּים, וּפַלְגָא, וּפְלַג פַּלְגָא. עוֹמְקָא וְרוֹמָא חַמְשִׁין וַחֲמֵשׁ זַרְתִּין.</p>"],[9514013508,"<p>הָכָא אִשְׁתַּכְלְלוּ קַו הַמִּדָּה בְּמִשְׁחֲתָא חָדָא. מִשֵּׁירוּתָא דְּקִשְׁרָא קַדְמָאָה, עַד סִיּוּמָא דְּמִשְׁחֲתָא דְנָא דְרִיבּוּעָא. הָכָא מִשְׁחֲתָא חָדָא לְקִיּוּמָא חַד. וְהַאי אִיקְרֵי מִשְׁחֲתָא עִילָּאָה, קִיּוּמָא סְתִימָאָה, קִשְׁרָא קַדְמָאָה, וְרִיבּוּעָא דָא קִיּוּמָא דְרָזָא ידו\"ד, שְׁמָא קַדִּישָׁא עִילָּאָה, כְּלָלָא דְקִשְׁרָא קַדְמָאָה, וּמִשְׁחֲתָא דְרִיבּוּעָא דְסָלְקֵי גוֹ מִשְׁחֲתָא, בִּרְעוּתָא דִסְתִימוּ עַד אֵין סוֹף.</p>"],[9514013509,"<p>וְעַד הָכָא קִיּוּמָא חָדָא עִילָּאָה סְתִימָאָה. מֵהָכָא אִתְפַּשַּׁט קַו הַמִּדָּה, וּמָדֵיד גּוֹ גְוָונִין דְּקָיְימִין בְּקִישׁוּרָא חָדָא, כְּלִילָא חָדָא. קַו הַמִּדָּה אִתְגַּלְיָיא, וְקָיְימָא בִּנְצִיצוּ דְּנָהֵיר, וְכָל גְּוָונֵי קָיְימִין בֵּיהּ.</p>"],[9514013510,"<p>קִשְׁרָא תִּנְיָינָא. קַו הַמִּדָּה שָׁארֵי, וְאִתְגַּלְיָיא בְּי\"ב קִשְׁרִין עִילָּאִין, וּמָאתָן וּתְלָתִין וְשִׁית קִשְׁרִין אָחֳרָנִין דַּקִּיקִין. אִלֵּין י\"ב קִשְׁרִין עִילָּאִין, קָיְימִין גּוֹ קִשְׁרָא קַדְמָאָה סְתִימָא וְרִבּוּעָא, וּמִתְקַשְׁרָאן וְאִתְאַחְדָאן בְּהוּ. וּמִתְאַחְדָאן וּמִתְקַשְׁרִין בְּאִלֵּין אָחֳרָנִין. וְכַד מִסְתַּכְּלִין מִלִּין, כּוֹלָּא אִיהוּ מִשְׁחֲתָא חָדָא.</p>"],[9514013511,"<p>וְקִשְׁרָא קַדְמָאָה מֵאִינוּן י\"ב, אִלֵּין אִינוּן דְּקָיְימִין בְּמִשְׁחֲתָא, בְּגִין דְּמִתְפַּשְׁטֵי יַתִּיר. וְכָל אִינוּן אָחֳרָנִין, מִתְפַּשְׁטִין הָכֵי, אֶלָּא אִילֵּין דָּבְקִין דָּא עִם דָּא, וּכְלִילָן דָּא עִם דָּא. וּבְקַו הַמִּדָּה, קָיְימֵי כָּלְהוֹ כַּחֲדָא, כְּלָלָא חָדָא, לִמְשִׁיחָא חָדָא.</p>"],[9514013512,"<p>הַאי קִשְׁרָא, כְּגַוְונָא דְקִשְׁרָא קַדְמָאָה אִיהוּ, וְשִׁיעוּרָא דִילֵיהּ, וְאוֹרְכֵּיהּ וּפוּתְיֵיהּ, כְּהַהוּא גַוְונָא מַמָּשׁ, בַּר דְּהַאי בְּאִתְגַּלְּיָיא, וְהַהוּא קַדְמָאָה נָעִיץ דְּלָא אִתְגַּלְיָיא.</p>"],[9514013513,"<p>קִשְׁרָא תְּלִיתָאָה, קִשְׁרָא דָא אִיהוּ קַדְמָאָה, וְדָא מְשַׁנְיָיא מִכָּל אִינוּן גְּוָונִין, וְדָא אִיהוּ קִשְׁרָא וְגַוָּון יַתִּיר, וְאִיהוּ קָאִים לְמִשְׁחֲתָא לְאִתְפַּשְּׁטָא.</p>"],[9514013514,"<p>שָׁארֵי קַו הַמִּדָה, וּמָדֵיד בְּאִלֵּין תְּרֵיסַר קִשְׁרִין. תְּלַת קִשְׁרִין מִינַיְיהוּ עִילָּאִין, דְּקָיְימִין לְמִשְׁחֲתָא בְּהַהוּא מְדִידוּ דְּמָדֵיד, וְאַסְגֵּי אָרְכָּאן דְּיוֹמִין בְּכוֹלָּא. וְסִימָן דָּא חוֹ\"ל. וְיֵשׁ לוֹ רָזָא דִּכְתִיב, (איוב כ״ט:י״ח) וְכַחוֹל אַרְבֶּה יָמִים. וְהָא אוֹקִימְנָא.</p>"],[9514013515,"<p>מָהֵיה אֶלֶף, וְשָׁארֵי מֵרֵישָׁא דְּעִזְקָא דִלְעֵילָּא, דִּיוּקְנָא רָזָא דְאָדָם. מָדֵיד בְּרֵישָׁא, לְאִתְפַּשְׁטָא לְתַתָּא בְּאוּרְכָּא.</p>"],[9514013516,"<p>הַהוּא רֵישָׁא שָׁארֵי מִלְּעֵילָא, וּמָדֵיד בְּעִיגּוּלָא, לִתְרֵין סִטְרִין. סִטְרָא חָדָא תְּלַת מְאָה זַרְתִּין, וּפַלְגָּא, וְחַד שְׁלִישׁ. סִטְרָא דָא קָיְימָא בַּחֲמֵשׁ מַזְלְגִין, דְּעַיְילֵי לְסִטְרָא תִּנְיָינָא, וּמִתְדַּבְּקָן אִלֵּין בְּאִלֵּין. וּמִשְׁחֲתָא דְּאִלֵּין מַזְלְגִין דְּעַיְילֵי דָא בְּדָא, תְּלַת מְאָה טְפָחִים, וְחַד זַרְתָּא וּפַלְגָא. מִתְדַּבְּקָן אִלֵּין בְּאִלֵּין, לְקָשְׁרָא סִטְרָא דָא בְּסִטְרָא תִּנְיָינָא.</p>"],[9514013517,"<p>סִטְרָא תִּנְיָינָא, מָדֵיד בּוּצִינָא בְּאִתְפַּשְׁטוּת, וְאִתְעֲבֵיד מִשְׁחֲתָא תְּלַת מְאָה זַרְתִּין, וּפַלְגָּא, וְחַד שְׁלִישׁ, כְּהַהוּא סִטְרָא קַדְמָאָה. אִשְׁתַּכַּח עִיגּוּלָא דְרֵישָׁא דָא, שִׁית מְאָה וְחַד זַרְתִּין, וּתְרֵין שְׁלִישִׁים. מִשְׁחֲתָא דְאִינוּן מַזְלְגִין, שִׁית מְאָה טְפָחִים וּתְלַת זַרְתִּין.</p>"],[9514013518,"<p>דְּהָא הוּא עִיגּוּלָא דְרֵישָׁא, דְּאִיתְפַּשַּׁט בּוּצִינָא וּמָדֵיד לְתַתָּא, לְאוֹרְכָּא אִשְׁתַּכַּח בְּהַהוּא בּוּצִינָא בִּמְדִינוּ, שִׁית מְאָה אַלְפִין עָלְמִין, וְשִׁתִּין רִבּוֹא אָחֳרָנִין. דָּא אִיהוּ אִתְפַּשְׁטוּתָא דְּבוּצִינָא, לְמֶיעֱבַד מִשְׁחָתִין לְעִיגּוּלָא וְאוּרְכָּא. וְהָכָא אִיהוּ קִשְׁרָא חָדָא לְתַתָּא, וְקִשְׁרָא לְעֵילָא.</p>"],[9514013519,"<p>קַו הַמִּדָּה, מָדֵיד אֶלֶף. וְשָׁארֵי מֵעוֹמְקָא דְגוּפָא לְגוֹ, וְאִתְפַּשַּׁט בּוּצִינָא, וּמָדֵיד לְאוֹרְכָּא בְּעוֹמְקָא. וּקְשַׁר חֲמֵשׁ מְאָה אַלְפִין עָלְמִין בִּמְעוֹי לְגוֹ. כְּמָה דְאַתְּ אָמֵר, (שיר השירים ה׳:י״ד) מֵעָיו עֶשֶׁת שֵׁן מְעֻלֶּפֶת סַפִּירִים.</p>"],[9514013520,"<p>מְעֻלֶּפֶת, דָּא הִיא בּוּצִינָא, עַד דְּלָא אִתְפַּשְׁטַת, דְּאִיהִי מְעֻלֶּפֶת לְאִתְפַּשְׁטָא, וּלְמֶיעֱבַד מְדִידוּ, וְדָא אִיהו מְדִידוּ דְּבוּצִינָא בְּהַאי סִטְרָא, רוּמָא וּפוּתְיָיא. בְּרָזָא דִּנְפֵיק מִבּוּצִינָא אִתְפַּשְׁטוּתָא חָדָא, דְּאִיהוּ רוּמָא וּפוּתְיָיא, תְּלַת מְאָה אַלְפִין זַרְתִּין, לְאִתְפַּשְׁטָא בִּתְלַת מְאָה עָלְמִין. וּבֵין עָלְמָא וְעָלְמָא, תְּלַת מְאָה אֶלֶף טְפָחִים. וְכָלְהוֹ קָיְימֵי בְּרוֹמָא וּפוּתְיָיא, בְּרָזָא דְּבוּצִינָא דְקַרְדִינוּתָא. וְקָיְימָא הַאי בְּשִׁית סִטְרִין, אִלֵּין שִׁית סִטְרִין דְּעָלְמָא, דְּכָלְהוֹ קָיְימִין בְּהַאי בּוּצִינָא, בְּאִתְפַּשְׁטוּתָא דָא.</p>"],[9514013521,"<p>וְהָכָא אִתְקַשַּׁר קִשְׁרָא חָדָא לְתַתָּא, וְקִשְׁרָא חָדָא בְּאֶמְצָעִיתָא, וְקִשְׁרָא חָדָא לְעֵילָא. אִתְקַשְּׁרוּ אִלֵּין תְּלָתָא קִשְׁרִין, בַּאֲתַר דָּא בְּבוּצִינָא. אִשְׁתַּכַּח בּוּצִינָא דָא, בְּרָזָא דִּלְעֵילָא וְאֶמְצָעִיתָא וְתַתָּא, לְמֶיעְבַּד מִשְׁחֲתָא.</p>"],[9514013522,"<p>תְּלַת קְשִׁירִין אִלֵּין אִתְקַשְּׁרִין בְּבוּצִינָא, וְקָיְימָא אִלֵּין תְּלָתָא בְּסִטְרָא דְּאוֹרְכָּא, וְאִלֵּין עָבְדִין תְּלָתָא אָחֳרָנִין, בְּסִטְרָא דְאוֹרְכָּא.</p>"],[9514013523,"<p>אִלֵּין תְּלַת קַדְמָאי, קָיְימֵי גוֹ מִשְׁחֲתָא, כָּל קִשְׁרָא וְקִשְׁרָא, קָאִים בְּמִשְׁחֲתָא, שִׁית מְאָה אֶלֶף עָלְמִין, וְשִׁית זַרְתִּין, וְשִׁית טְפָחִים. וְכָלְהוֹ קָיְימִין בְּקִיּוּמָא.</p>"],[9514013524,"<p>אִשְׁתַּכָחוֹ תְּלַת קִשְׁרִין קַדְמָאי, דְּאִינוּן תְּמַנֵּי סְרֵי מְאָה אַלְפֵי עָלְמִין, וּתְמַנֵּי סְרֵי זַרְתִּין, וּתְמַנֵּי סְרֵי טְפָחִים. וְדָא אִיהוּ רָזָא דְבוּצִינָא בְּסִטְרָא דָא. וְכֵן כְּגַוְונָא דָא קָיְימִין תְּלַת קִשְׁרִין אָחֳרָנִין.</p>"],[9514013525,"<p>וְכֹלָּא קָיְימָא בִּרְעותָא דְּמִשְׁחֲתָא דְּבוּצִינָא, דְּסָלְקָא עַד אֵין סוֹף. מִשְׁחֲתָא דְּבוּצִינָא אִתְפַּשְׁטַת מִקִּשְׁרִין אִלֵּין, וְסָלֵיק וְקָשֵׁיר כֹּלָּא בְּקִישׁוּרָא חָדָא גּוֹ מִשְׁחֲתָא בִּשְׁלִימוּ חָדָא. אִתְהַדְּרַת אִתְפַּשְׁטוּתָא, וְקַיָּים גּוֹ רוֹמָא וְעִיגוּלָא וְרִבּוּעָא, וְסָלֵיק וְקָשֵׁיר לְעֵילָא חַד קִשְׁרָא. לְבָתַר נָחֵית וְקָשֵׁיר לְתַתָּא קִשְׁרָא חָדָא, וְקַיָּים כֹּלָּא.</p>"],[9514013526,"<p>אִשְׁתַּכַח רָזָא דְבוּצִינָא, בְּכָל הַנֵּי קִשְׁרִין, וּבְכָל הַנֵּי מְדִידִין, מִשְׁחֲתָא חָדָא, וְקִשְׁרָא חָדָא. וְהַהוּא קִשְׁרָא כַּד סָלְקָא וְקָשֵׁיר חַד קִשְׁרָא, עָבִיד מִשְׁחֲתָא, וְקָאִים בְּקִיּוּמָא, וְנָעֵיץ נְעִיצוּ דִּמְהֵימְנוּתָא. כַּד נָחֵית וְקָשֵׁיר חַד קִשְׁרָא עָבִיד מִשְׁחָתָא וְקָאִים בְּקִיּוּמָא וְנָעֵיץ נְעִיצוּ דִּמְהֵימְנוּתָא.</p>"],[9514013527,"<p>רִבּוּעָא קָיְימָא עַל עִיגּוּלָא, וְעִיגּוּלָא עַל אוֹרְכָּא, וְאוֹרְכָּא עַל עוֹמְקָא, וְעוֹמְקָא עַל רוֹמָא, וְרוֹמָא עַל פּוּתְיָא. וְכֹלָּא בְּרָזָא דְּבוּצִינָא, לְמֶיעְבַּד מְדִידוּ.</p>"],[9514013528,"<p>קָיְימָא בּוּצִינָא, וְאַהֲדַר לְאִתְפַּשְׁטָא כְּמִלְּקַדְּמִין, כַּד קָשֵׁיר קִיּוּמָא זִמְנָא חָדָא אִיהוּ מְעוּלֶפֶת, בִּזְמַן דְּאִיהִי מְעוּלֶפֶת, כְּדֵין רָשִׁים כָּל גְּוָונִין בְּאִינוּן אַתְרִין דְּאִתְחַזְּיָין, חִיוַּר וְסוּמַק וְיָרוֹק וְאוּכָם. וְאִלֵּין אִינוּן אַרְבַּע גְּוָונִין, דְּאַתְקֵינַת בּוּצִינָא, וְאַנְהֵירַת בִּנְהִירָא דְּנָעֵיץ וְנָפְקָא, וְדָא הוּא מְעוּלֶפֶת סַפִּירִים, סַפִּירִים דִּנְהִירִין.</p>"],[9514013529,"<p>אֲהַדְּרַת בּוּצִינָא וְאִתְפַּשְׁטַת כְּמִלְקַדְּמִין, וְנָטָה קָו וְעָבִיד מִדָּה. וּמָדֵיד אֶלֶף לִסְטַר דָּא, וְאֶלֶף לִסְטַר דָּא, וְכֵן לְאַרְבַּע סִטְרִין. לָקֳבֵל קִיּוּמָא דְאַתְוָון יהו\"ה, דְּאִינוּן ד' אַתְוָון. אִתְפַּשְׁטַת בּוּצִינָא, וּמָדֵיד גּוֹ גְּוָונִין לְקִיּוּמָא, בִּנְצִיצוּ, לְאוֹרְכָּא וּלְרוֹמָא וּלְעוֹמְקָא וּלְפוּתְיָיא. נְצִיצוּ דְּיָמִינָא בְּגַוָּון חִיוַּר, בְּרָזָא דְּבוּצִינָא בְּמִשְׁחֲתָא.</p>"],[9514013530,"<p>כְהַהוּא פְּשִׁיטוּ דִּגְוָונִין, קָיְימָאן בִּמְדִידוּ לְאוֹרְכָּא, לְעֵילָא, וְתַתָּא, שֶׁבַע מְאָה אֶלֶף עָלְמִין, וְשִׁית מְאָה וּתְלֵיסַר זַרְתִּין. וְכֵן בְּכָל אִינוּן סִטְרִין, בְּכָל אִינוּן גְּוָונִין.</p>"],[9514013531,"<p>כַד מְדִידוּ דְּהַהוּא גַּוָון אוּכָם, דְּקָיְימָא בִּגְרִיעוּתָא, לְאִתְחַבְּרָא בְּגַוָּון חִיוַּר, וְכַד מִתְחַבְּרָן אִלֵּין תְּרֵין גְּוָונִין כַּחֲדָא, כְּדֵין אִינוּן מִשְׁחֲתָא חָדָא. אִשְׁתַּכְּחוֹ אִלֵּין גְּוָונִין בִּמְדִידוּ דְּמִשְׁחֲתָא, לְאַרְבָּעָה סִטְרִין דִּגְוָונִין, תְּמַנְיָא וְעֶשְׂרִין אֶלֶף עָלְמִין, וְאֶלֶף וּמָאתָן וְאֶלֶף וּמָאתָן, מֵהַאי סִטְרָא וּמֵהַאי סִטְרָא, וּתְרֵיסַר זַרְתִּין.</p>"],[9514013532,"<p>עַד הָכָא פְּשִׁיטוּ דְרָזָא דְּבוּצִינָא לְעֵילָא, בִּמְדִידוּ בְּכָל סִטְרִין, לְאוֹרְכָּא וּפוּתְיָיא, לְעוֹמְקָא וְרוֹמָא. בְּהַנֵּי אַרְבַּע, קָיְימִין כָּל מִשְׁחֲתִין, בְּרָזָא דְּבוּצִינָא, וְאִתַּקְנָא לְקָיְימָא תָּדִיר בְּקִיּוּמָא, גּוֹ רְעוּתָא, וְאִתְפַּשְׁטוּתָא דְּלִבָּא, וּמוֹחָא, וְרוּחָא. מַאן דְּבָעֵי לְמֶיעְבַּד מְדִידוּ בְּשִׁיעוּרָא דָא, וּלְנַטְלָא בּוּצִינָא דְּקַרְדִּינוּתָא בִּידֵיהּ, וּלְאִתְפַּשְׁטָא בֵּיהּ בְּכָל הַנֵּי סִטְרִין, וְעָבִיד מִשְׁחֲתָא דָא. זַכָּאָה חוּלָקֵיהּ, דְּכָל רָז לָא אָנֵיס לֵיהּ, וְכָל מִלָּה דְחָכְמְתָא עִילָּאָה לָא יִסְתַּלַּק מִנֵּיהּ. עַד הָכָא קָיְימָא בּוּצִינָא בְּרָזָא דְּחָכְמָתָא עִילָּאָה.</p>"],[9514013533,"<p>אִלֵּין דְּקָיְימִין בְּבוּצִינָא דְּקַרְדִינוּתָא, אִינוּן שֶׁבַע עֶשְׂרֵה קִשְׁרִין. בְּאִלֵּין י\"ז קִשְׁרִין, קָיְימָא רָזָא דְּמִשְׁחֲתָא, וּלְנַטְלָא מַטְלָנִין, וְאִתְפַּשְׁטוּתָא דְּבוּצִינָא, בֵּין קִשְׁרָא וְקִשְׁרָא, לְסִטְרָא דָא וּלְסִטְרָא דָא. וְכָלְהוֹ שִׁבְסְרֵי קִשְׁרֵי, כָּלְהוֹ קָיְימִין בְּכָל מִשְׁחֲתִין, דְּאוֹרְכָּא וּפוּתְיָיא וְעוֹמְקָא וְרוֹמָא. מֵקִשְׁרָא דָא לְקִשְׁרָא דָא, קָיְימִין כָּלְהוֹ רָזִין בְּכָל מִשְׁחֲתִין.</p>"],[9514013534,"<p>וְאִינוּן קִשְׁרִין תְּלֵיסַר, וְכָל אִינוּן אָחֳרָנִין, כָּלְהוֹ קָיְימִין בִּכְלָלָא חָדָא, וְכָלְהוֹ בְּרָזָא חָדָא, לָקֳבֵיל אַרְבַּע אִלֵּין דְּקָאַמְרִין, וְלָקֳבֵיל אַרְבַּע גְּוָונִין, וְלָקֳבֵיל רָזָא דְאַרְבַּע אַתְוָון.</p>"],[9514013535,"<p>מִכָאן וּלְהָלְאָה אִתְפַּשַׁט בּוּצִינָא, וְקָיְימִין קִשְׁרִין אַחֲרָנִין בְּבוּצִינָא, לְמֶיעְבַּד מִשְׁחֲתִין אָחֳרָנִין, בְּרָזָא דִּתְלַת שְׁמָהָן. וּמִנַּיְיהוּ קָיְימִין ב' שְׁמָהָן לְבוּצִינָא גּוֹ מִשְׁחֲתָא. וְאִינוּן תְּלַת שְׁמָהָן דְּקָאֲמָרָן, אִינוּן יהו\"ה אֱלֹהֵינוּ יהו\"ה. אִשְׁתָּאֲרוּ תְּרֵין שְׁמָהָן לְבוּצִינָא, וְאִינוּן יהו\"ה אֱלֹהֵינוּ.</p>"],[9514013536,"<p>הַשְׁתָּא בְּבוּצִינָא דָא, אִיהוּ מִשְׁחֲתָא דְּלָא עָמִיק גּוֹ עוֹמְקָא, וְקָיְימָא רָז דָּא בְּאֶמְצָעִיתָא. הַשְׁתָּא בּוּצִינָא דְּהַהִיא מְעוּלֶפֶת, אִתְפַּשְׁטַת בִּתְלַת סִטְרֵי דְרָזָא, לְמֶעְבַּד מִשְׁחֲתָא. הָכָא קָיְימָא בּוּצִינָא וְאִתְתַּקְּנַת. בְּגִין דְּהָכָא אִיהוּ מִשְׁחֲתָא אָחֳרָא, בַּר מֵאִינוּן מִשְׁחֲתִין.</p>"],[9514013537,"<p>תִּיקּוּנָא דְּבוּצִינָא דְּאִתְתַּקְנַת, עַד לָא אִתְפַּשְׁטַת, אִתְתַּקְנַת מִגּוֹ טְמִירוּ דְּאֵין סוֹף, סַלְקָא וְנַחֲתָא, וְאִתְגְּנֵיז בֵּיהּ מַה דְּאִתְגְּנֵיז, וּפַשֵׁיט לָהּ, תְּלַת אַרְגְּוָונִין בֵּיהּ אִתְחַזְּיָין, וְאִינוּן הֲווֹ תִּיקּוּנָא לְאִתְפַּשְּׁטָא, וּלְמֶיעְבַּד מִשְׁחֲתָא.</p>"],[9514013538,"<p>אִתְתַּקָּנַת בִּגְנִיזוּ דְּגָנֵיז, בְּגַוָּון אָחֳרָא. לְמֶיעְבַּד שַׁפִּירוּ וְתִיקּוּנָא דְּאָדָם. לְאַתְקָנָא גּוֹ מִשְׁחֲתָא, בְּשַׁפִּירוּ, בְּתִיקּוּנָא, לְאִתְחַפְיָיא מַה דְּטָמִיר לְגוֹ.</p>"],[9514013539,"<p>שָׁארֵי בּוּצִינָא לְאִתְפַּשְׁטָא, וְאִתְעֲבֵיד חַד קִשְׁרָא לְעֵילָא, הַהוּא קִשְׁרָא אִסְתַּלַּק גּוֹ הַהִיא אִתְפַּשְׁטוּתָא, מִגּוֹ דְּהַהוּא מְעוּלֶפֶת. כַּד שָׁארֵי וְאִתְפַּשְׁטַת, קָשֵׁיר קִשְׁרָא חָדָא, וְהַהוּא קִשְׁרָא אֶלֶף אַמִּין בֵּיהּ. מֵהַהוּא קִשְׁרָא אִתְפַּשְׁטַת בּוּצִינָא חַד זַרְתָּא וּפַלְגָא, וּמָדֵיד מְדִידוּ לְאוֹרְכָּא, אֶלֶף וְשִׁית מְאָה עָלְמִין.</p>"],[9514013540,"<p>הַהוּא אוֹרְכָּא, קִשְׁרָא מִכָּאן, וְקִשְׁרָא מִכָּאן. וּנְטֵיל הַהוּא אוֹרְכָּא, גּוֹ הַהוּא טְמִירוּ דְּאֵין סוֹף, עַד דְּמָטוֹ לְחַד מִגְדְּלָא דְּפָרְחָא בַּאֲוִירָא. כֵּיוָן דְּמָטָא הָתָם, אִתְפַּשְׁטַת בּוּצִינָא, וְקָיְימָא לַאֲנָחָא הַהוּא מִשְׁחֲתָא, בִּקְשִׁירוּ דָא, וְאִתְעֲבִידַת בּוּצִינָא דְּלָא אִתְיְדַע, עַד דְּאִתְמְשַׁח הַאי מִשְׁחֲתָא, דְּהַאי אִתְגְּנֵיז בְּגוֹ הַהוּא גְנִיזוּ. לְבָתַר בָּטַשׁ לֵיהּ לְבַר, כַּד נַפְקָא, אִשְׁתַּכַּח בֵּיהּ אֶלֶף אַלְפִין, וְאַרְבַּע מֵאוֹת רִבּוֹא עָלְמִין, וְכַמָּה רָזִין אָחֳרָנִין, כָּלְהוֹ קָיְימִין בְּהַאי מִשְׁחֲתָא.</p>"],[9514013541,"<p>לְבָתַר אִתְפַּשְׁטַת מֵהַאי אֲתַר, וּמָדֵיד בְּרִיבּוּעָא חָמֵשׁ קִשְׁרִין. וְכָל קִשְׁרָא וְקִשְׁרָא, אִית בֵּיהּ חֲמֵשׁ מְאָה אֶלֶף עָלְמִין. כָּל קִשְׁרָא וְקִשְׁרָא קָיְימָא, בְּרָזָא דְּהַהוּא גְנִיזוּ. קִשְׁרָא קַדְמָאָה שָׁארֵי, וְאִתְפְּשַׁט בּוּצִינָא עַד קִשְׁרָא תִּנְיָינָא, בְּגוֹ רִיבּוּעָא אֶלֶף אַמִּין. מֵהַאי קִשְׁרָא אִתְפַּשְׁטַת בּוּצִינָא עַד קִשְׁרָא תְּלִיתָאָה, אֶלֶף אַמִּין אָחֳרָנִין. מֵהַאי קִשְׁרָא עַד קִשְׁרָא רְבִיעָאָה לְעוֹמְקָא, אֶלֶף אַמִּין. מֵהַאי קִשְׁרָא לְעוֹמְקָא דִלְתַתָּא, אֶלֶף אַמִּין. אִשְׁתַּכָּחוֹ אִלֵּין קִשְׁרִין בְּאִלֵּין מִשְׁחֲתִין תְּמַנְיָא אֶלֶף עָלְמִין.</p>"],[9514013542,"<p>וְהָכָא בְּמִשְׁחֲתָא דָא, אִתְעֲבֵיד דָּא כּוּרְסְיָיא לְמִשְׁחֲתָא עִילָּאָה קַדְמִיתָא דְּקָאֲמָרָן. וְהָכָא קָיְימָא וְאִתְיַישְׁבָא מִשְׁחֲתָא קַדְמָאָה, דְּאִתְעֲבֵיד בְּבוּצִינָא לְקִיּוּמָא לְאַשְׁרָאָה בָהּ. דָּא מִשְׁחֲתָא דְּאֶמְצָעִיתָא, דְּלָאו אִיהוּ גְנִיזָא כְּקַדְמָאָה.</p>"],[9514013543,"<p>בְּהַאי מִשְׁחֲתָא דְרָזָא דְּאָדָם דְּקָאֲמָרָן, בּוּצִינָא קָיְימָא וַעֲבֵיד מִשְׁחֲתָא בְּגוֹ אִתְפַּשְׁטוּתָא דָא, וַעֲבֵיד מְדִידוּ דְּקִשְׁרָא דְּקַיָּימָא, דְּלָא נָטֵיל לְעָלְמִין. וְקִשְׁרָא דָא קַיְימָא לְתַתָּא, וַעֲבֵיד בְּהַאי קִשְׁרָא מִשְׁחֲתָא, לְהַהוּא מְדִידוּ דְּקָיְימָא בְּשַׁפִּירוּ, וְאַתְקֵין וּמָדֵיד מִשְׁחֲתִין, מִגּוֹ רְעוּ דְּגָנֵיז. וּמָשֵׁיךְ הַהוּא מְדִידוּ לְתַתָּא.</p>"],[9514013544,"<p>וְעַל דָּא אַחְסֵין משֶׁה יְרוּתָא דְּאִתְכְּלֵיל בְּגוֹ רָזָא דְאִתְמַשְׁכוּתָא דָא, דְּאִתְמְשַׁךְ לְתַתָּא. וְעַל דָּא אַכְלֵיל גַּרְמֵיהּ בְּמִשְׁחֲתָא דָא, דְּהִיא קַיְימָא בִּמְשִׁיכוּ דְּאֶמְצָעִיתָא. מִשְׁחֲתָא דָא קָיְימָא בְּקִיּוּמָא, עַד קְיָימָא קַדִּישָׁא דְּקָאֲמָרָן, וְתַמָּן אִשְׁתַּכָּחוֹ מִשְׁחֲתִין בְּרָזָא דְּבוּצִינָא, כְּמִשְׁחֲתָא דִלְעֵילָא.</p>"],[9514013545,"<p>מִכָאן וּלְהָלְאָה אִתְפַּשְׁטוּ בְּרָזָא דִּמְהֵימְנוּתָא, לְאִשְׁתַּכָּחָא וּלְמֶהֱוֵי קִיּוּמָא דְּכֹלָּא, לְכָל אִינוּן רְתִיכִין עִילָּאִין וְתַתָּאִין.</p>"],[9514013546,"<p>עַד כָּאן רָזָא דְּבוּצִינָא, קַו הַמִּדָּה, גּוֹ רָזָא דְעָלְמָא עִילָּאָה, לְאִשְׁתַּכָּחָא קִיּוּמָא בְּכָל אִינוּן קִיּוּמִין וְרָזִין עִילָּאִין. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּא בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי, דְּאִינוּן יָכְלֵי לְאִתְדַּבְּקָא בְּרָזָא דְמָארֵיהוֹן כִּדְקָא חָזֵי.</p>"],[9514013547,"<p>מִכָאן וּלְהָלְאָה, שָׁארֵי בּוּצִינָא לְאִתְפַּשְׁטָא גּוֹ רָזָא דִּמְהֵימְנוּתָא. וְהַהוּא פְּשִׁיטוּ קַדְמָאָה דְּמִשְׁחֲתָא, אִגְנִיז וְאִסְתַּלַּק. אִתְנְהֵיר וְאִתְנְצֵיץ.</p>"],[9514013548,"<p>כֹלָּא מִגּוֹ רָזָא דְּבוּצִינָא, מֵהַהוּא מִשְׁחֲתָא. אֲוִירָא חָדָא נָפְקָא מִגּוֹ בּוּצִינָא. וְהַהוּא אֲוִירָא סָלְקָא וְנָחֲתָא, וַעֲבֵיד חַד פְּשִׁיטוּ אָחֳרָא, מְשַׁנְיָיא מִקַּדְמָאָה, וְהַהוּא פְּשִׁיטוּ אִיהוּ דְּנָפְקָא מִגּוֹ הַהוּא אֲוִירָא.</p>"],[9514013549,"<p>בְּרָזָא דְּבוּצִינָא דְּקָיְימָא וְלָא קָיְימָא, נָפְקָא חַד פְּשִׁיטוּ דְּהַהוּא בּוּצִינָא, דְּנָפְקָא, וּמָשֵׁיךְ לְאִתְעַטְרָא לְתַתָּא הַהוּא מִשְׁחֲתָא. בְּגִין דְּהָכָא לְתַתָּא, קָיְימָא מִשְׁחֲתָא לְאִתְעַטְרָא וּלְאִתְקַיְּימָא.</p>"],[9514013550,"<p>בּוּצִינָא נָפְקָא וְאִתְפַּשְּׁטַת, בְּרָזָא דְהַהוּא אֲוִירָא דְּנָפְקָא, וּמָדֵיד מִגּוֹ תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ גְּוָונִין, בְּסוּסְפִיתָא דְדַהֲבָא כַּסְפָּא נְחָשָׁא וּפַרְזְלָא. וְנָפְקָא מִגּוֹ קִשְׁרָא חָדָא, דְּקָיְימָא לְחַבְּרָא בֵּין עֵילָא וְתַתָּא. וְהַהוּא קִשְׁרָא אַפֵּיק כָּל גְּוָונִין. בְּרָזָא דְמִשְׁחֲתָא דְשַׁרְבִיטָא.</p>"],[9514013551,"<p>מֵהַאי קִשְׁרָא וּלְתַתָּא, אִתְפָּרְשָׁן מִשְׁחֲתִין לְכַמָּה סִטְרִין. וְהַהוּא פְּשִׁיטוּ דִּנְפַק מִגּוֹ הַהוּא קִשְׁרָא, מְחַבֵּר לוֹן כַּחֲדָא.</p>"],[9514013552,"<p>קִשְׁרָא דָא אִתְקַשַּׁר לְעֵילָא, בְּהַהוּא פְּשִׁיטוּ דְּמִשְׁחֲתָא עִילָּאָה דְּטָמִיר וְגָנֵיז, וְאִתְקַיַּים בְּקִיּוּמֵיהּ דְּבוּצִינָא דְּנָהֵיר וְקַיָּים. כּוֹלָא אִתְקַשַּׁר לְתַתָּא, בְּהַהוּא נְהוֹרָא דְּלָא נָהֵיר, דְּקָיְימָא לְאַנְהָרָא בְּרָזָא דִּמְהֵימְנוּתָא, לְאִתְחַבְּרָא דָא בְּדָא. הַאי קִשְׁרָא קָאֵי בֵּין עֵילָא וְתַתָּא.</p>"],[9514013553,"<p>שֶׁבַע אַלְפֵי עָלְמִין, קָיְימִין בִּנְהִירוּ דְּמִשְׁחֲתָא, בְּהַהוּא קִשְׁרָא. הַאי קִשְׁרָא נָהֵיר בְּאִינוּן גְּוָונִין, לְתַתָּא, כְּגַוְונָא דִלְעֵילָא. אִינוּן גְּוָונִין נָהֲרִין מִגּוֹ הַהוּא קִשְׁרָא, וְקָיְימִין כָּלְהוֹ בִּמְדִידוּ דְּמִשְׁחֲתָא, בְּהַהוּא פְּשִׁיטוּ דְּאִתְפְּשַׁט, וְאִתְקָיְימִן כָּלְהוֹ בְּקִיּוּמָא בִּשְׁלִימוּ לְאִתְעַטְרָא. הַאי פְּשִׁיטוּ כַּד אִתְפְּשַׁט וּמָדֵיד, כּוֹלָּא אִתְתַּקַּן לְאִתְחַבְּרָא דָּא בְּדָא.</p>"],[9514013554,"<p>אִתְפְּשַׁט פְּשִׁיטוּ דְּנָפְקָא מִגּוֹ בּוּצִינָא, וַעֲבֵיד מִשְׁחֲתָא, לְיָמִינָא וּשְׂמָאלָא, לְעוֹמְקָא וְרוֹמָא, לְאוֹרְכָּא וּפוּתְיָיא. מִשְׁחֲתָא קַדְמָאָה לְיָמִינָא בְּהַהוּא פְּשִׁיטוּ. הַהוּא דְּנָפְקָא מִגּוֹ קִשְׁרָא הַהוּא דְּקָאֲמָרָן. וְהַהוּא פְּשִׁיטוּ אִיקְרֵי בּוּצִינָא זְעֵירָא, וְקָיְימָא לְמִשְׁחֲתָא דְּכַמָּה שַׁיְיפִין, לְחַבְּרָא לוֹן כַּחֲדָא, וּלְקָשְׁרָא לוֹן בְּקִישׁוּרָא חָדָא בְּהַהִיא מִשְׁחֲתָא דִּלְעֵילָא, לְמֶהֱוֵי כֹּלָּא בְּרָזָא דְמִשְׁחֲתָא חָדָא.</p>"],[9514013555,"<p>אִתְפְּשַׁט הַהוּא פְּשִׁיטוּ לְיָמִינָא, וַעֲבֵיד מִשְׁחֲתָא. שָׁארֵי גוֹ עִיגּוּלָא, מָדֵיד אֶלֶף בְּהַהוּא פְּשִׁיטוּ. הַהוּא פְּשִׁיטוּ מָדֵיד בְּעִיגּוּלָא, וַעֲבֵיד קִשְׁרָא מֵהַהוּא קִשְׁרָא דִלְעֵילָא, עַד הַאי פְּשִׁיטוּ, תְּרֵי אַלְפֵי אַמִּין לִסְטַר יָמִינָא, וּתְרֵי אַלְפֵי אַמִּין לִסְטַר שְׂמָאלָא, וּתְרֵי אַלְפֵי אַמִּין לְכָל סְטַר.</p>"],[9514013556,"<p>עִיגּוּלָא דְּשָׁארֵי מָדֵיד, וַעֲבֵיד קִשְׁרָא כִּדְקָאֲמָרָן, בִּתְחוּם תְּרֵי אַלְפֵי אַמִּין, גּוֹ מִשְׁחֲתָא, מִתְפַּשֵּׁט מִגּוֹ נְקוּדָה דְּקָיְימָא בֵּין שְׁאָר חַיָּילִין, וּמָדֵיד תְּרֵי אַלְפֵי מִילִין לְכָל סְטַר. שָׁארֵי בְּהַהוּא עִיגּוּלָא, אֶלֶף וּתְשַׁע מְאָה זַרְתִּין וּפַלְגָא.</p>"],[9514013557,"<p>בְּהַהוּא פְּשִׁיטוּ, שָׁארֵי וּמָדֵיד בְּעִיגּוּלָא, וַעֲבֵיד תְּרֵין קִשְׁרִין, מִשֵּׁירוּתָא דָא, עַד סוֹפָא דְהַאי מְדִידוּ. בְּגִין דַּאֲתַר דָּא לָא קָיְימָא בְּרִבּוּעָא, יהו\"ה, דָּא מִשְׁחֲתָא דִּפְשִׁיטוּ דְּנָפְקָא מִגוֹ קִשְׁרָא עִילָּאָה, בְּרָזָא דְבוּצִינָא. שָׁארֵי בְּעִיגּוּלָא, וּמָשֵׁיךְ וְנָטֵי לְתַתָּא, עַד סִטְרָא דְקִשְׁרָא לְתַתָּא.</p>"],[9514013558,"<p>אַהֲהַר וּמָדֵיד מִסִּטְרָא דָא לְסִטְרָא דָא, בְּגוֹ עוֹמְקָא דְהַהוּא עִיגּוּלָא, וְלֹא קָשֵׁיר קִשְׁרָא. וּמָדֵיד בִּמְשִׁיחוּ לְתַתָּא, מִשְׁחֲתָא דְהַאי מֵשֵׁירוּתָא דְעִיגּוּלָא, אֶלֶף אַמִּין וּתְרֵיסַר אַלְפִין זַרְתִּין.</p>"],[9514013559,"<p>שָׁארֵי וּמָדֵיד, מִגּוֹ רוֹמָא וְעוֹמְקָא וְאוֹרְכָּא וּפוּתְיָיא, בְּרָזָא דִדְיוֹקְנָא דְּאָדָם, בְּשַׁפִּירוּ חֵיזוּ דְנוּקְבָא, וּמָדֵיד בְּעִיגּוּלָא דְרֵישָׁא, בְּסִטְרָא חָדָא בְּהַהוּא פְּשִׁיטוּ. הַהוּא פְּשִׁיטוּ אִתְפַּשַּׁט וּמָדֵיד בְּעִיגּוּלָא דְרֵישָׁא, בְּלָא פַּלְגוּ כְּלָל.</p>"],[9514013560,"<p>וּמָהֵיה בְּסִטְרָא דְּרוּמָא בְּעִיגּוּלָא. וְאִתְפַּשַּׁט וּמָשֵׁיךְ לְתַתָּא, וְקָשֵׁיר קִשְׁרָא. מָדֵיד מֵרֵישָׁא בְּעִיגּוּלָא, בְּשִׁיעוּרָא דִּתְלַת אֶלֶף, אַמִּין כְּלִילָן כַּחֲדָא. וְאִתְמְשַׁךְ וְאִתְפַּשַּׁט לְתַתָּא, בְּלָא קְשִׁירוּ. וְהַהוּא שִׁיעוּרָא, שִׁית אֶלֶף סִטְרִין דְּעָלְמִין, וְשִׁית אֶלֶף טְפָחִים, בְּעִיגּוּלָא.</p>"],[9514013561,"<p>גּוֹ פְּשִׁיטוּ דְּבוּצִינָא דְּנָפְקָא, אִתְפַּשְׁטַת הַאי דְּנָפַק מִגּוֹ הַאי קִשְׁרָא עִילָּאָה, דְּרָזָא דְּבוּצִינָא, וּמָדֵיד בְּעִיגּוּלָא לְסִטְרָא רְבִיעָאָה, וַעֲבֵיד מִשְׁחֲתָא, וּמָדֵיד אֶלֶף לְסִטְרָא יָמִינָא. מִשְׁחֲתָא דְּהַאי סִטְרָא דְּיָמִינָא, לִתְרַע דָּרוֹמָא, מָדֵיד אֶלֶף וְאֶלֶף וְאֶלֶף וְאֶלֶף, בְּהַהוּא סִטְרָא, דְּד' סִטְרִין דְּעָלְמָא, אִשְׁתַּכָּחוֹ אַרְבַּע אֶלֶף. וְכֵן אִתְפַּשַּׁט הַאי פְּשִׁיטוּ לְכָל סִטְרִין.</p>"],[9514013562,"<p>בִּתְרַע מִזְרָח, קָיְימָא פְּשִׁיטוּ אָחֳרָא, דְּנָפְקָא מֵהַאי פְּשִׁיטוּ דְּמָדֵיד מִשְׁחֲתָא, וְקָיְימָא הַהוּא פְּשִׁיטוּ אָחֳרָא בְּאֶמְצָעִיתָא, וּמָדֵיד אֶלֶף, בְּהַהוּא סִטְרָא בְּאֶמְצָעִיתָא.</p>"],[9514013563,"<p>וְעָמֵיק בְּעוֹמְקָא, וּמָדֵיד מְדִידוּ בְּרָזָא דִמְהֵימְנוּתָא, בְּרָזָא דְּשִׁית סִדְרֵי מִשְׁנָה. וְאִלֵּין שִׁית סִדְרִין, קָיְימִין בְּהַהוּא עוֹמְקָא דְרָזָא דְבוּצִינָא, דְּהַהוּא פְּשִׁיטוּ. אִלֵּין שִׁית סִדְרִין, קָיְימִין גּוֹ מְדִידוּ דְּשָׁנָה. שָׁנָ\"ה, אִיהוּ סִימָן, בְּרָזָא דְּאִינוּן שִׁית סִדְרִין דְּמִשְׁנָה, דְּקָאֲמָרָן.</p>"],[9514013564,"<p>הַאי פְּשִׁיטוּ קַדְמָאָה, דְּנָחֲתָא וּנְפֵיק מִגּוֹ הַהוּא קִשְׁרָא דְּקָאֲמָרָן, אוֹרְכָּא דִילֵיהּ לְמֶיעְבַּד מִשְׁחֲתָא. בּיהּ, אִיהוּ אַלְפֵי אַלְפִין רִבְוָון עָלְמִין, עַד הַהוּא נְצִיצוּ בַּתְרָאָה, דְּלֵית בֵּיהּ נְהוֹרָא כְּלָל. וְרָזָא דָא לִבְנֵי מְהֵימְנוּתָא לְמֶיעְבַּד מִשְׁחֲתָא. אִיהוּ רָזָא דִכְתִיב, (דניאל ז׳:י׳) אֶלֶף אַלְפִין יְשַׁמְשׁוּנֵיהּ וְרִבּוֹ רִבְוָון קֳדָמוֹהִי יְקוּמוּן. בְּהַאי אִיהוּ רָזָא לְמִשְׁחֲתָא, כִּדְקָאֲמָרָן.</p>"],[9514013565,"<p>פְּשִׁיטוּ תִּנְיָינָא דְּקָאֲמָרָן, דְּנַחֲתָא וּנְפֵיק מִגּוֹ הַאי פְּשִׁיטוּ קַדְמָאָה, וְאִיהוּ קָיְימָא בְּאֶמְצָעִיתָא, אוֹרְכָּא דִילֵיהּ, לְמֶיעְבַּד בֵּיהּ מִשְׁחֲתָא בְּהַהוּא סִטְרָא, אֶלֶף רִבּוֹא עָלְמִין, וּשְׁבַע מְאָה אֶלֶף וַחֲמִשָּׁה וְשִׁבְעִין. וְסִימָנָךְ, (שמות ל״ח:כ״ח) וְאֶת הָאֶלֶף וּשְׁבַע הַמֵּאוֹת וַחֲמִשָּׁה וְשִׁבְעִים עָשָׂה וָוִים לָעַמּוּדִים.</p>"],[9514013566,"<p>זַכָאִין אִינוּן דְּיָדְעִין לַאֲפָקָא רָזִין עִילָּאִין גּוֹ מְהֵימְנוּתָא, וְיָדְעֵי לְמֵיעַל לְיָמִינָא וְלִשְׂמָאלָא כִּדְקָא יָאוֹת בְּלָא כִסּוּפָא. וְעַל דָּא כְּתִיב (דניאל י״ב:ג׳) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ.</p>"],[9514013567,"<p>בּוּצִינָא דְקַרְדִינוּתָא, כַּד עָבִיד מִשְׁחֲתָא, אִתְכְּנַשׁ לְגַוֵּיהּ, וְקָיְימָא בְּכָל דַּרְגָּא וְדַרְגָּא, בְּהַהוּא כְּנִישׁוּ וְקַיָּים לוֹן. לְבָתַר, קָיְימָא וְסָלְקָא מְעוּלֶפֶת, עַד דְּסָלְקִין וְאִתְגְּנֵיז, וְאִתְטַמַּר וְלָא אִתְיְידַע. וְכֹלָּא אִשְׁתָּאַר בְּקִיּוּמָא, כְּדֵין נָהֵיר מַה דְּנָהֵיר, וְאַפֵּיק נַחֲלִין וּמַיִּין, לְרַוָּואָה כּוֹלָא. עַד הָכָא רָזָא דְּבוּצִינָא דְּקַרְדִינוּתָא, לְאַחְדָא בָהּ בְּכָל סִטְרֵי מְהֵימְנוּתָא.</p>"],[9514013568,"<p>בּוּצִינָא דְקַרְדִינוּתָא, קָיְימָא גּוֹ טְמִירִין, וְסָלְקָא וְנָחֲתָא. מַאן דְּיָדַע רָזָא דְּחָכְמְתָא, יָכֵיל לְאַדְבְּקָא וּלְמֶיעְבַּד מִשְׁחֲתֲין בְּכָלְהוֹ סִטְרִין, עַד דְּיָדַע בְּרָזִין עִילָּאִין, בְּרָזִין דְּמָארֵיהּ, בְּרָזִין דְּחָכְמְתָא, בְּגִין לְמִנְדַע וּלְאַדְבְּקָא. מַאן דְּיָדַע וְאִסְתַּכַּל, זַכָּאָה חוּלָקֵיהּ בְּהַאי עָלְמָא וּבְעָלְמָא דְאָתֵי. בְּגִין דְּהָא כְּלָלָא דָא, יְתַקֵּן רַגְלוֹי דְּבַר נָשׁ, לְעָאלָא בְּפַרְגּוֹדָא, וּלְמֵיהַךְ בְּאוֹרַח מֵישַׁר, זַכָּאָה אִיהוּ בְּעָלְמָא דֵין, וְזַכָּאָה אִיהוּ בְּעָלְמָא דְאָתֵי. עֲד כָּאן קַו הַמִּדָּה.</p>"],[9514013569,"<p>(דברים כ״א:י׳) כִּי תֵצֵא לַמִּלְחָמָה עַל אֹיְבֶיךָ. רַבִּי שִׁמְעוֹן פְּתַח, (הושע ח׳:ג׳) זָנַח יִשְׂרָאֵל טוֹב אוֹיֵב יִרְדְּפוֹ. מַאי זָנַח יִשְׂרָאֵל טוֹב, דָּא יֵצֶר הַטוֹב, דִּשְׁלֹמֹה מַלְכָּא קְרָיֵיהּ טוֹב. דִּכְתִיב, (קהלת ד׳:י״ג) טוֹב יֶלֶד מִסְכֵּן וְחָכָם. אוֹיֵב יִרְדְּפוֹ, דָּא יֵצֶר הָרָע, דְּאִיהוּ שַׂנְאֵיהּ דְּבַּר נָשׁ, דִּשְׁלֹמֹה מַלְכָּא קְרָיֵיהּ שׂוֹנֵא. דְּסַגִּיאִין שְׁמָהָן אִית לֵיהּ, דִּכְתִיב, (משלי כ״ה:כ״א) אִם רָעֵב שׂנַאֲךָ הַאֲכִילֵהוּ לָחֶם. וְדָא הִיא אוֹרַיְיתָא קַדִּישָׁא. כְּמָה דְאַתְּ אָמֵר, (שם ט) לְכוּ לַחֲמוּ בְלַחְמִי.</p>"],[9514013570,"<p>וְעַל דָּא בָּעֵי בַּר נָשׁ לְשַׁוָּואָה מִלִּין דְּאוֹרַיְיתָא עֲלֵיהּ, בְּגִין דִּיהֵא תְּבִירָא בֵּיהּ, דְּלֵית לֵיהּ קִטְרוּגָא לְיֵצֶר הָרָע, בַּר מִלִּין דְּאוֹרַיְיתָא. וְעַל דָּא כְּתִיב, (דברים ו) וְהָיוּ הַדְּבָרִים הָאֵלֶּה אֲשֶׁר אָנֹכִי מְצַוְּךָ הַיּוֹם עַל לְבָבֶךָ. עַל תְּרֵי יְצָרֶיךָ.</p>"],[9514013571,"<p>אָמַר לֵיהּ רַבִּי יְהוּדָה, יֵצֶר הַטוֹב מַאי בָּעֵי מִלִּין דְּאוֹרַיְיתָא. אָמַר לֵיהּ, יֵצֶר הַטוֹב אִתְעַטַר בְּהוּ, וְיֵצֶר הָרָע אִתְכְּנַע בְּהוּ.</p>"],[9514013572,"<p>וְעַל דָּא כִּי תֵצֵא לַמִּלְחָמָה עַל אֹיְבֶיךָ דָּא אִיהוּ יֵצֶר הָרָע. דַּאֲנַן צְרִיכִין לְמֵיפַּק לְקִבְלֵיהּ בְּמִלִּין דְּאוֹרַיְיתָא, וּלְקַטְרְגָא לֵיהּ, וּכְדֵין יִתְמְסַר בִּידָא דְּבַּר נָשׁ. כְּמָה דְאִתְּמָר, וּנְתָנוֹ ה' אֱלֹהֶיךָ בְּיָדֶךָ וְשָׁבִיתָ שִׁבְיוֹ.</p>"],[9514013573,"<p>אָמַר רִבִּי שִׁמְעוֹן, וַוי עַל דָּא, וַוי עַל דָּא, (משלי ל׳:כ״ב) תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְנָבָל כִּי יִשְׂבַּע לָחֶם. דְּהָא יֵצֶר הַטוֹב אִשְׁתַּבָּאי בִּידֵיהּ, וְאִיהוּ מֶלֶךְ עֲלֵיהּ.</p>"],[9514013574,"<p>אֵשֶׁת יְפַת תֹּאַר, דָּא הִיא נִשְׁמָתָא. כְּמָה דְאַתְּ אָמֵר, (שם לא) אִשָּׁה יִרְאַת ה' הִיא תִתְהַלָּל. דְּהָא בְּכָל יוֹמָא וְיוֹמָא, אִינוּן סִיעָן וּמַנְהִיגִין דְּנִשְׁמָתִין, וְאִינוּן סִיעָן וּמַנְהִיגִין דְּיֵצֶר הָרָע, אִינוּן בְּקִטְרוּגָא תְּדִירָא, מְקַטְרְגִין אִלֵּין בְּאִלֵּין, וְכָל שַׁיְיפִין דְּגוּפָּא בְּצַעֲרָא בֵּינַיְיהוּ, בֵּין נִשְׁמָתָא וּבֵין יֵצֶר הָרָע.</p>"],[9514013575,"<p>וַהֲבֵאתָהּ אֶל תּוֹךְ בֵּיתֶךָ, דְּאִתְתַּרְכַת מִתַּמָּן. (שם ל) וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. וּכְבָר אוֹקִימְנָא מִלִּין. וְגִלְחָה אֶת רֹאשָׁהּ וְעָשְׂתָה אֶת צִפָּרְנֶיהָ, וְתִדְכֵּי מֵהַהוּא זוּהֲמָא דְּאַטֵיל בָּהּ נָחָשׁ.</p>"],[9514013576,"<p>וְהֵסִירָה אֶת שִׂמְלַת שִׁבְיָהּ, מֵאִינוּן כְּסוֹ דִּמְסָאֲבָא וְזִינִין בִּישִׁין מֵחוֹבָא דְּעֶגְלָא. דְּהָא בְּקַדְמִיתָא הַוְיָא לְהוֹ לְבוּשֵׁי קוּדְשָׁא, דְּקַבִּילוּ בְּטוּרָא דְסִינַי. וְכַד עֲבָדוּ יַת עֶגְלָא, אַעֲדוּ מִנַּיְיהוּ אִינוּן לְבוּשֵׁי יְקָר, דִּכְתִיב (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב.</p>"],[9514013577,"<p>וּבָכְתָה אֶת אָבִיהָ וְאֶת אִמָּהּ יֶרַח יָמִים, דָּא הִיא יַרְחָא דֶּאֱלוּל, דְּבֵיהּ סָלֵיק משֶׁה לְטוּרָא, לְמִבְעֵי רַחֲמִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּיִשְׁתְּבֵיק לְיִשְׂרָאֵל עַל חוֹבָא דְּעֶגְלָא. וּבְגִין דָּא וּבָכְתָה אֶת אָבִיהָ וְאֶת אִמָּהּ יֶרַח יָמִים, בְּגִין דְּגַלֵּי עֶרְיָיתָא דְּקוּדְשָׁא בְּרִיךְ הוּא וְעֶרְיָיתָא דְאוֹרַיְיתָא. כְּמָה דְאַתְּ אָמֵר, (ויקרא י״ח:ז׳) עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה. וְעַל דָּא אֲמַר, (תהילים קי״ט:קל״ו) פַּלְגֵי מַיִם יָרְדוּ עֵינָי עַל לֹא שָׁמְרוּ תוֹרָתֶךָ.</p>"],[9514013578,"<p>וַהֲווּ יִשְׂרָאֵל רְחִיקִין מִמַּלְכָּא כָּל הַהוּא זִמְנָא, עַד יוֹמָא דְּכִפּוּרֵי, דְּנָחֵית משֶׁה מִן טוּרָא, וַהֲווּ יִשְׂרָאֵל בְּתַעֲנִיתָא כָּל הַהוּא יוֹמָא. וּכְדֵין אִתְדַּבַּק מַלְכָּא בְּמַטְרוֹנִיתָא. כְּמָה דְאַתְּ אָמֵר, (דברים כ״א:י״ג) וְאַחַר כֵּן תָּבוֹא אֵלֶיהָ וּבְעַלְתָּהּ וְהָיְתָה לְךָ לְאִשָּׁה.</p>"],[9514013579,"<p>וְגָזְרוּ קְיָימָא עִם קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יִפְלְחוּן עוֹד פּוּלְחַן נוּכְרָאָה. כְּמָה דְאַתְּ אָמֵר (שמות ל״ד:י׳) הִנֵּה אָנֹכִי כּוֹרֵת בְּרִית נֶגֶד כָּל עַמְּךָ וְגו'. וּכְתִיב תַּמָּן, (שם) אֱלֹהֵי מַסֵּכָה לֹא תַעֲשֶׂה לָּךְ. וְעַל דָּא וּמָכֹר לֹא תִמְכְּרֶנָּה בַּכָּסֶף, לָא תְשַׁקֵּר בְּנִשְׁמָתְךָ, בְּגִין דַּחֲלָן דִּכְסַף. כְּמָה דְאַתְּ אָמֵר, (שמות כ׳:כ׳) לֹא תַעֲשׂוּן אִתִּי אֱלֹהֵי כֶסֶף וֵאלֹהֵי זָהָב לֹא תַעֲשׂוּ לָכֶם.</p>"],[9514013580,"<p>זַכָאִין אִינוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא גְּזַר עֲלֵיהוֹן תַּעֲנִיתָא בְּיוֹמָא דֵין. דִּכְתִיב, (ויקרא כ״ג:כ״ט) כִּי כָל הַנֶּפֶשׁ אֲשֶׁר לֹא תְעֻנֶּה בְּעֶצֶם הַיּוֹם הַזֶּה וְנִכְרְתָה מֵעַמֶּיהָ. בְּגִין דְּיִתְכַּפֵּר לְהוֹן כָּל חוֹבֵיהוֹן. דִּכְתִיב, (שם טז) כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם מִכֹּל חַטֹאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ. עַד כָּאן.</p>"],[9514013581,"<p><Noneb>מדרש הנעלם </b></p>"],[9514013582,"<p>רַבִּי שִׁמְעוֹן אֲמַר, נַפְשָׁא, דְּהִיא מִשִּׁפְעָא דִּיסוֹדָא עִילָּאָה, כַּד אִיהִי חָבַת, אֶשָׁא דִּלְעֵילָא שָׁלְטָא עֲלֵיהּ. זִינָא בְּזִינֵיהּ. וּבְגוּפָא שָׁלְטָא אֶשָׁא דִלְרַע. וּשְׁלָמָא עַל כָּל יִשְׂרָאֵל.</p>"],[9514013583,"<p>וּמַאן דַּאֲמַר, דְּמַאן דְּאָזֵיל מֵהַאי עָלְמָא בְּלָא בְנִין, דְּאָתֵי זִימְנָא אַחֲרִיתֵּי לְעָלְמָא הָדֵין, אֲמַר קְשׁוֹט.</p>"],[9514013584,"<p>וְעוֹד. אִינוּן חַיָּיבַיָא דְּשָׁאטִין בַּאֲוִירָא, עַד דִּמְרַצוּ חוֹבַיְיהוּ, וּבָתַר נִכְנָסִין פַּעַם שְׁנִיָּה בַּגּוּף, כְּדֵי לְצָרֵף אוֹתוֹ, וְאִם יִצְדַּק, שׁוּב אֵינוֹ נִכְנַס פַּעַם אַחֶרֶת. וְאִם לָאו, פַּעַם שְׁלִישִׁית. שֶׁנֶּאֱמַר, (איוב ל״ג:כ״ט) הֶן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר. וְאִם חַס וְשָׁלוֹם לֹא יִצְדַק בְּאֵלּוּ הַשְּׁלשָׁה פְּעָמִים, שׁוּב אֵין לוֹ תַּקָּנָה, וְזֶהוּ הִכָּרֵת תִּכָּרֵת. וְעַל דָּא בָּעֵי בַּר נָשׁ לְאִזְדַּהֲרָא בְּנַפְשֵׁיהּ, דִּילְמָא אָתָא זִימְנָא אָחֳרָא.</p>"],[9514013585,"<p>וְאִית לָנָא רְאָיָה מִנָּדָב וַאֲבִיהוּא, כִּדְכָתִיבְנָא, דְּמִיתוּ פַּלְגֵי גוּפָא הֲווֹ בְּגִין דְּלָא אִנְסִיבוּ. וְעוֹד אִית לָנָא סֶמֶךְ, מֵעִנְיַן יְבָמָהּ יָבֹא עָלֶיהָ. בְּגִין דְּלָא יִשְׁתַּרֵשׁ זַרְעֵיהּ, וְלָא יִצְטְרִיךְ לְמֵיתֵי זִימְנָא אָחֳרָא בַּגּוּף. וְתוּ אוֹלִיפְנָא מֵאוֹנָן, דַּאֲמַר הַכָּתוּב בֵּיהּ, (בראשית ל״ח:ט׳) לְבִלְתִּי נְתָן זֶרַע לְאָחִיו.</p>"],[9514013586,"<p>וְעוֹד רְאָיָה אָחֳרָא, (רות ד׳:י״ז) יֻלַּד בֵּן לְנָעֳמִי. וְכִי לְנָעֳמִי יֻלַּד, וַהֲלֹא רוּת יְלָדַתּוּ. אֶלָּא לְלַמֵּד, שֶׁזֶּה עוֹבֵד הוּא הָיָה מַחְלוֹן, וּמִית בְּלָא בְּנִין.</p>"],[9514013587,"<p>וּבְגִין כָּךְ תֶּחֱמֵי, בַּר נָשׁ צַדִּיק וְרַע לוֹ. דִּילְמָא זִימְנָא אַחֲרִיתֵּי אָתָא לְעָלְמָא, וְלָא הֲוָה זַכָּאי כָּל כָּךְ, וּמֵת בְּעִנְיַן זֶה, וּכְדוֹ הַשְׁתָּא כַּד עָאל לְהַאי עָלְמָא, מְנֻכֶּה חוֹבֵיהּ, וְהָדֵין הוּא צַדִּיק וְרַע לוֹ.</p>"],[9514013588,"<p>וּכְמוֹ כֵן רָשָׁע וְטוֹב לוֹ. דִּילְמָא אֲתָא זִימְנָא אָחֳרָא, וּמִת בְּלָא בְנִין, וַהֲוָה זַכַּאי וְלָא גָּמוּר, וְהַשְׁתָּא מְשֻׁלָּם לֵיהּ מִזְכוּתֵיהּ בְּעָלְמָא דֵין. וְדָא הוּא (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּיקִים יֵלְכוּ בָם.</p>"],[9514013589,"<p>וְהָא דַּאֲמָרָן (דברים כ״ה:ה׳) כִּי יֵשְׁבוּ אַחִים יַחְדָּו. רַבִּי יִצְחָק אֲמַר, כִּי יֵשְׁבוּ אַחִים, שֶׁיַּכִּירוּ בְּלִבָּם שֶׁהֵם אַחִים. כְּמדָּבָר אַחֵר, (תהילים כ״ט:י׳) וַיֵּשֶׁב ה' מֶלֶךְ לְעוֹלָם. בַּמֶּה דְּאִשְׁתְּמוֹדְעִין דְּהוּא מַלְכָּא עַל כּוֹלָּא.</p>"],[9514013590,"<p>וּמֵת אֶחָד מֵהֶם וּבֵן אֵין לוֹ, הָא אִם הֲווֹ לֵיהּ בְּנִין, לָא אִצְטְרִיךְ. רַבִּי תַּנְחוּם אֲמַר רַבִּי יוֹסֵי, יְבָמָהּ יָבֹא עָלֶיהָ, לְמַאי אִצְטְרִיךְ. דְּלָא לְאַמְעוּטֵי מִדִּמְיוֹנָא דְּכָלֵיל כָּל דִּמְיוֹנִין.</p>"],[9514013591,"<p>רַבִּי יִצְחָק פְּתַח, (קהלת ד׳:ח׳) יֵשׁ אֶחָד וְאֵין שֵׁנִי גַּם בֵּן וְאָח אֵין לוֹ. יֵשׁ אֶחָד, דֵּין הוּא בַּר נָשׁ דְּיִתְפַּטַר מֵעַלְמָא הָדֵין חֲסַר מִן טַבְתָּא, דְּהוּא חַד, וְלֵית לֵיהּ זְכוּתָא לְמֶעְבַּד תִּנְיָין. דְּתַנְיָא, אָמַר רִבִּי יִצְחָק, הַאי מַאן דְּאִתְפַּטַר מִן עַלְמָא הָדֵין יָחִיד בְּלָא תִּנְיָין, אִיתְמְעֵיט וְיִשְׁתֵּיצֵי מִדִּמְיוֹנָא דְּכָלֵיל כָּל דִּמְיוֹנִין.</p>"],[9514013592,"<p>טוֹבִים הַשְּׁנַיִם מִן הָאֶחָד. מַאי טַעְמָא, מִשּׁוּם דִּכְתִיב אֲשֶׁר יֵשׁ לָהֶם שָׂכָר טוֹב בַּעֲמָלָם. אָמַר רִבִּי יִצְחָק, תָּא חֲזֵי, דִּכְתִיב קְרָא, (שם) כִּי אִם יִפֹּלוּ הָאֶחָד יָקִים אֶת חֲבֵרוֹ, בְּהַהוּא דִמְיוֹנָא. וְאִילּוּ הָאֶחָד שֶׁיִּפּוֹל, וְאֵין שֵׁנִי לַהֲקִימוֹ.</p>"],[9514013593,"<p>רַבִּי יְהוּדָה שְׁלַח לֵיהּ לְר' אַבָּא, אֲמַר, אַתּוּן דְּקַיִּימְתּוּן קַמֵּי מָארֵיהוֹן דְּמַתְנִיתִין, מַאי טַעְמָא יְבָמָהּ יָבֹא עָלֶיהָ לְהָקִים שֵׁם הַמֵּת, וְלֹא בְּאִשָּׁה אַחֶרֶת.</p>"],[9514013594,"<p>שְׁלַח לֵיהּ, (ירמיהו ב׳:כ״ד) פֶּרֶ\"ה לִמֻּד מִדְבָּר בְּאַוַּת נַפְשָׁהּ שָׁאֲפָה רוּחַ. אִיתְרְגֵישׁ רַבִּי יְהוּדָה, וַאֲמַר, וַדַּאי דָא הִיא רָזָא דְחָכְמְתָא, מַשְׁמַע דַּאֲמַר שָׁאֲפָה רוּחַ, רוּחַ מַמָּשׁ.</p>"],[9514013595,"<p>וְאָזְלָא הָא כְּהַאי דְּאָמַר רִבִּי יוֹסֵי דִּכְתִיב, (קהלת ח׳:י׳) וּבְכֵן רָאִיתִי רְשָׁעִים קְבֻרִים וָבָאוּ. וָבָאוּ מַמָּשׁ. אָמַר רִבִּי יִצְחָק, וּמִתְפַּרֵשׁ מִלָּה, בְּמַאי דִכְתִיב בְּאַוַּת נַפְשָׁהּ דְּמַשְׁמַע דְּאֲפִילּוּ אֲרוּסָה, וַאֲפִילּוּ בְּעוּלָה אַתְיָין בְּתוֹעַלְתָּא דְהַאי מִלָּה.</p>"],[9514013596,"<p>(דברים כ״ה:ו׳) וְהָיָה הַבְּכוֹר אֲשֶׁר תֵּלֵד יָקוּם וכו'. וּמַאי טַעְמָא הַבְּכוֹר, וְלֹא הַשֵּׁנִי וְלֹא הַשְּׁלִישִׁי. אָמַר רִבִּי יוּדָן, הַבְּכוֹר וְהָרִאשׁוֹן עַל כָּל פָּנִים שֶׁל מֵת הוּא, וְדַעְתַּיְיהוּ דְּתַרְוֵיהוֹן בְּזִוּוּגָא קַדְמָאָה בְּמִיתָא.</p>"],[9514013597,"<p>תַּנְיָא, אָמַר רִבִּי יוֹסֵי, וְעָלְתָה יְבִמְתּוֹ הַשָּׁעֲרָה אֶל הַזְּקֵנִים, הַאי מִלָּה חוּצְפָּא אִתְחֲזֵי. אָמַר רִבִּי יְהוּדָה, חַס וְשָׁלוֹם דְּחוּצְפָּא הוּא, אֶלָּא לְאִתְחֲזָאָה טִיבוּ דְּבָעְיָיא לְמֶעְבַּד עִם מִיתָא, וְאִיהוּ לָא בָעֵי, וּלְפִיכָךְ עָבְדֵית לֵיהּ קְלָנָא קַמֵּי כּוֹלָּא.</p>"],[9514013598,"<p>מַאי קְלָנָא עָבְדֵית לֵיהּ. דִּכְתִיב, וְיָרְקָה בְּפָנָיו, לְהִכָּלֵם בִּפְנֵי הַכֹּל, אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו. וּקְרָא כְתִיב, וְיָרְקָה וְאָמְרָה כָּכָה כו'. כְּמָה דְאַתְּ אָמֵר, (במדבר יב) וְאָבִיהָ יָרֹק יָרַק בְּפָנֶיהָ הֲלֹא תִכָּלֵם.</p>"],[9514013599,"<p>רַבִּי אַבָּהוּ אֲמַר ר' יוֹחָנָן, צָהֲבָה וְיָרְקָה רוֹקָא, דְּמִתְחֲזֵי לְכוֹלָּא דְּאִיהוּ רוֹקָא, וְלָא מַיִם, וְלָא דְּאִתְכַּסֵּי בְּעַפְרָא.</p>"],[9514013600,"<p>הַהִיא אִיתְּתָא, דְּאָתַת לְקַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, וְרָמַת רוֹקָא, וַחֲזֵי בָהּ דְּאָכְלַת בְּהַהוּא שַׁעֲתָא, וְלָא הֲוֵי מִתְחֲזֵי רוֹקָא, וְלָא אִתְעֲבֵידַת הַהוּא יוֹמָא, וּלְבָתַר אִמְלְכוּ וְאִזְדַּוְּוגוּ דָּא עִם דָּא.</p>"],[9514013601,"<p>וּמִי עֲבֵיד ר' שִׁמְעוֹן הָכֵי, וְהָתְנַן אִי אִמְלְכוּ קוֹדֶם דְּתִסְתַּלֵּק קַמֵּי דַּיָּינָא יָאוֹת, וּמִדְּתִשְׁרֵי סִינֵיהּ קַמֵּי דַיָּינָא לָא.</p>"],[9514013602,"<p>אָמַר רִבִּי יְהוּדָה, שָׁאנֵי הַהִיא אִיתְּתָא, דְּעַד לָא עֲבָדוּ דָּא עִם דָּא, אֶלָּא דְּאַרְמֵית רוֹקָא לְמֶחֱזֵי, וְלָא הֲוָה כַשְׁרָא וַאֲזָלוּ וְאִזְדַּוְּוגוּ דָּא עִם דָּא לְבָתַר.</p>"],[9514013603,"<p>וְחָלְצָה נַעֲלוֹ, כְּמָה דְאַתְּ אָמֵר (הושע ה) חָלַץ מֵהֶם. רַבִּי יְהוּדָה אֲמַר רַבִּי חִיָּיא, כְּתִיב, (שמות ג) אַל תִּקְרַב הֲלֹם שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ, וְכִי מִנְעָל מְטַהֵר אֶת הַמָּקוֹם, אוֹ מְטַמֵּא אֶת הַמָּקוֹם. אֶלָּא אָמַר רִבִּי אַבָּא, מְלַמֵּד שֶׁצִּוָּה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדֶרֶךְ כָּבוֹד לְהִתְפָּרֵשׁ מֵאִשְׁתּוֹ מִכֹּל וָכֹל. בְּמשֶׁה כְּתִיב נְעָלֶיךָ, וּבִיהוֹשֻׁעַ כְּתִיב נַעַלְךָ, שֶׁלֹּא יִתְפָּרֵשׁ מֵאִשְׁתּוֹ מִכֹּל וָכֹל, אֶלָּא לְעִתִּים מְזוּמָנִים.</p>"],[9514013604,"<p>כִי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו. מָקוֹם יֵשׁ לְךָ בְּמַעֲלָה גְדוֹלָה מִשְּׁאָר בְּנֵי אָדָם, מַדְרֵגָה הַנִּקְרֵאת קוֹדֶשׁ. וְעַל כֵּן נִצְטַוָּה לְהִתְפָּרֵשׁ מֵאִשְׁתּוֹ בְּדֶרֶךְ נַעַל. אַף כָּאן נָמֵי הַאי נַעַל פְּרִישׁוּת אִשָּׁה.</p>"],[9514013605,"<p>אָמַר רִבִּי יוֹחָנָן, צָרִיךְ הָאָדָם לִבְטוֹחַ בְּקוֹנוֹ, וְלִיקַּח אִשָּׁה, וּלְהוֹלִיד בָּנִים, שֶׁלֹּא יֵלֵךְ עֲרִירִי לָעוֹלָם הַבָּא. דִּתְנַן, מַאי דִכְתִיב, (ויקרא כ) עֲרִירִים יָמוּתוּ, דְּכָל מִי שֶׁאֵין לוֹ בָּנִים בָּעוֹלָם הַזֶּה, הוּא כְּאִלּוּ לֹא נִבְרָא וְלֹא הָיָה, וְנִקְרָא עֲרִירִי מִן הָעוֹלָם הַזֶּה, וּמִן הָעוֹלָם הַבָּא.</p>"],[9514013606,"<p>הְאָמַר רִבִּי יוֹחָנָן, מֵאַחַר שֶׁהָאָדָם נוֹשֵׂא אִשָּׁה, וּמוֹלִיד בָּנִים. נִקְרָא עֶבֶד ה', וְנוֹחֵל הָעוֹלָם הַזֶּה, וְהָעוֹלָם הַבָּא. דִּכְתִיב, (יחזקאל מד) לְהָנִיחַ בְּרָכָה אֶל בֵּיתֶךָ.</p>"],[9514013607,"<p>מָשָׁל לְמָה הַדָּבָר דּוֹמֶה. לְמֶלֶךְ שֶׁנָּתַן פִּקָּדוֹן לִשְׁלשָׁה בְּנֵי אָדָם, הָאֶחָד שָׁמַר אֶת הַפִּקָּדוֹן. הַשֵּׁנִי אָבַד אֶת הַפִּקָּדוֹן לְגַמְרֵי. הַשְּׁלִישִׁי טִנֵּף אֶת הַפִּקָּדוֹן, וְנָתַן מִמֶּנּוּ לְאַחֵר לְשָׁמְרוֹ. לְיָמִים, בָּא הַמֶּלֶךְ לִתְבּוֹעַ פִּקְדּוֹנוֹ. אוֹתוֹ שֶׁשָּׁמַר הַפִּקָּדוֹן, שִׁבְּחוֹ הַמֶּלֶךְ וַעֲשָׂאוֹ נֶאֱמַן בֵּיתוֹ. הַשֵּׁנִי שֶׁאָבַד אֶת הַפִּקָּדוֹן, הֶאֱבִידוֹ מִן הָעוֹלָם, וְצִוָּה שֶׁלֹּא יִהְיֶה לוֹ שֵׁם וּשְׁאֵרִית. הַשְּׁלִישִׁי שֶׁטִנֵּף אֶת הַפִּקָּדוֹן, וְהִנִּיחַ מִמֶּנּוּ לְאַחֵר, אָמַר הַמֶּלֶךְ, הַנִּיחוּ לָזֶה עַד שֶׁנִּרְאֶה הָאַחֵר, הֵיאַךְ יַעֲשֶׂה מִמַה שֶּׁהִנִּיחַ זֶה בְּיָדוֹ, וּבֵין כָּךְ לֹא יֵצֵא מִבֵּית הַמֶּלֶךְ.</p>"],[9514013608,"<p>זָכָה הָאַחֵר, יֵצֵא זֶה לַחֵירוּת. לֹא זָכָה, אָמַר הַמֶּלֶךְ, תְּנוּ לָזֶה עוֹנֶשׁ עַל שֶׁטִנֵּף אֶת הַפִּקָּדוֹן, וְיִשָּׁאֵר הַפִּקָּדוֹן שֶׁלּוֹ. רַב הוּנָא אֲמַר, כֵּיוָן דְּעָאל עָאל.</p>"],[9514013609,"<p>וְאִי טִנֵּף אֶת הַפִּקָּדוֹן וְלֹא הִנִּיחַ בְּיַד אַחֵר לְשָׁמְרוֹ, מוֹצִיאִין אוֹתוֹ מִבֵּית הַמֶּלֶךְ, עַד שֶׁיָּבֹא אַחֵר וִיתַקֵּן מַה שֶּׁטִנֵּף זֶה, וְהַפִּקָּדוֹן מוֹצִיאִין אוֹתוֹ מִיָּדוֹ שֶׁל זֶה, וְנוֹתְנִין אוֹתוֹ לָזֶה שֶׁתִּיקְּנוֹ.</p>"],[9514013610,"<p>רַבִּי חִיָּיא אֲמַר, כְּתִיב (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה. כֵּיוָן דַּאֲמַר נִשְׁמַת חַיִּים, אַמַּאי וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה. אֶלָּא, עַל מְנָת כֵּן נָתַן הַקָדוֹשׁ בָּרוּךְ הוּא נְשָׁמָה בָּאָדָם, שֶׁיִּהְיֶה לְנֶפֶשׁ חַיָּה. בְּמַעֲרָבָא קוֹרִין לְיוֹלֶדֶת, חַיָּה.</p>"],[9514013611,"<p>וְתוּ, אֱלֹהִים אַפֵּיק זִינִין לְזִינֵיהּ, וְהִיא הַנְּשָׁמָה. וְהַנְּשָׁמָה מִתְחַלֶּקֶת וּמִתְרַבָּה בַּגּוּף, בְּעוֹד שֶׁהִיא בַּגּוּף, וְכֵיוָן שֶׁיּוֹצְאָה מֵהַגּוּף, מִתְרַבָּה בְּיוֹתֵר, וּמַשֶּׂגֶת מַה שֶּׁלֹּא תוּכַל לְהַשִּׂיג בְּעוֹדָהּ בַּגּוּף.</p>"],[9514013612,"<p>וְתֵיכֶף שֶׁנִּפְרֶדֶת מֵהַגּוּף, רוֹצָה לְהִדָּבֵק בֵּאלֹהִים, וּבְגִין דְּלָא אֲפֵיקַת גּוּפָא, דְּהוּא זִינֵיהּ, כְּמָה דַּאֲפֵיק אֱלֹהִים נִשְׁמָתָא דְּהוּא זִינֵיהּ, לא מִתְקַבְּלַת, וְחוֹזֶרֶת וְשׁוֹאֶפֶת עַד שֶׁתִּכָּנֵס בְּגוּף אַחֵר, כְּדֵי לְקַיֵּים זֶרַע וְלָשׁוּב לְהִדָּבֵק בַּגּוּף הַטָהוֹר וְהַזַּךְ וְהַנָּקִי. וּמִי שֶׁלֹּא הִנִּיחַ בָּנִים, לָא מִזְדַּקֵּק לֵיהּ. הֲדָא הוּא דִכְתִיב, (ירמיהו ב׳:כ״ד) בְּאַוַּת נַפְשָׁהּ שָׁאֲפָה רוּחַ.</p>"],[9514013613,"<p>רַבִּי שִׁמְעוֹן אֲמַר, הַאי מַאן דְּלָא אִשְׁתָּאַר בַּתְרֵיהּ גִּזְעִין לְשָׁרְשָׁא, נִשְׁמָתֵיהּ אִשְׁתֵּיצֵי מִן הַהוּא דִמְיוֹנָא דְּכָלֵיל כָּל דִּמְיוֹנִין, עַד דְּמִתְגַּלְגְּלָא, וְאִיתּוֹרָקַת מִמָּאנָא לְמָאנָא. כְּמָה דְאַתְּ אָמֵר, (שם מה) וְלֹא הוּרַק מִכְּלִי אֶל כֶּלִי. מַאי תַּקְנְתֵּיהּ. כְּתִיב, (ויקרא כ״ה:כ״ה) וּבָא גֹאֲלוֹ הַקָּרֹב אֵלָיו וְגָאַל אֵת מִמְכַּר אָחִיו.</p>"],[9514013614,"<p>רַבִּי יְהוּדָה אֲמַר, מִתְגַּלְגֶּלֶת עַד דִּי תִשְׁכַּח מָאנָא דְּכַשְׁרָא לְאִתְתַּקָּנָא. וְאִי הַהוּא פָּרוֹקָא לָא הֲוֵי, קוּזְטִיפָא דְּבוּדִיטָא אִתְּבַר. וְעַל הַאי אִתְקְרֵי, (דברים ז׳:י׳) וּמְשַׁלֵּם לְשׂוֹנְאָיו אֶל פָּנָיו לְהַאֲבִידוֹ. וּכְתִיב (שם ה) וְעֹשֶׂה חֶסֶד לַאֲלָפִים לְאֹהֲבַי וּלְשֹׁמְרֵי מִצְוֹתָי.</p>"],[9514013615,"<p>הִילְכָךָ אָמַר רִבִּי אַבָּא, כְּתִיב (בראשית ט׳:ו׳) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. מַה שְּׁמָא דָא אַפֵּיק זִינִין לְזִינֵיהּ. כָּךְ בָּעֵי בַּר נָשׁ לַאֲפָקָא זִינִין לְזִינֵיהּ.</p>"],[9514013616,"<p>רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, אֲזַל לֵיהּ וַעֲרַק לְמַדְבְּרָא דְלוּד, וְאִתְגְּנֵיז בְּחַד מְעַרְתָּא, הוּא וְרַבִּי אֶלְעָזָר בְּרֵיהּ. אִתְרְחֵישׁ לוֹן נִיסָּא, וּנְפַק לְהוֹ חַד חֲרוּבָא, וְחַד מַעֲיָינָא דְמַיָּיא. אָכְלֵי מֵהַהוּא חֲרוּבָא, וְשָׁתָאן מֵאִינוּן מַיִין. הֲוָה אֵלִיָּהוּ זָכוּר לַטוֹב, אָתֵי לוֹן בְּכָל יוֹמָא תְּרֵי זִמְנֵי, וְאוֹלִיף לוֹן. וְלָא יָדַע אֵינַשׁ בְּהוּ.</p>"],[9514013617,"<p>יוֹמָא חַד הֲווֹ חַכִּימַיָיא בְּבֵי מִדְרְשָׁא שׁוֹאֲלִין, וְאָמְרִין, קְלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים, אִינוּן כְּנֶגֶד בַּיִת רִאשׁוֹן. קְלָלוֹת שֶׁבְּמִשְׁנֵה תוֹרָה כְּנֶגֶד בַּיִת שֵׁנִי וְגָלוּת אַחֲרוֹן. בַּקְּלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים, אִית בְּהוּ הַבְטָחוֹת, וַחֲבִיבוּ דְּקוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, דִּכְתִיב, (ויקרא כ״ו:מ״ד) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְגו'. וּכְתִיב וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם. קְלָלוֹת שֶׁבְּמִשְׁנֵה תוֹרָה, לֵית בְּהוּ הַבְטָחוֹת, וְלֵית בְּהוּ נֶחָמָה כְּלָל, כְּמָא דִכְתִיב בַּקְּלָלוֹת קַדְמָאִין. וְלָא הֲווֹ יָדְעֵי.</p>"],[9514013618,"<p>קָם רַבִּי יְהוּדָה בַּר אִלְעָאי וַאֲמַר, חֲבָל עַל גְּרִיעוּתָא דְּבַר יוֹחָאי, וְלֵית מַאן דְּיָדַע מִנֵּיהּ. וְאִלּוּ יָדְעֵי, לֵית רְשׁוּ לְגַלָּאָה לֵיהּ.</p>"],[9514013619,"<p>ר' יוֹסֵי בֶּן רִבִּי יְהוּדָה, קָם יוֹמָא חַד בְּצַפְרָא, חָמֵי כָּל אִינוּן עוֹפִין דְּאִינוּן הֲווֹ טָאסָן, וְשַׁפְנִינָא חָדָא אָזְלָא בַּתְרַיְיהוּ. קָם עַל רַגְלוֹי וַאֲמַר, שַׁפְנִינָא, שַׁפְנִינָא מְהֵימְנָא, מִיּוֹמָא טוֹפָנָא דִּיוּקְנָא דְּעַמָּא קַדִּישָׁא, לְךָ יָאוֹת וּלְךָ נָאֶה, זִיל וַעֲבֵיד לִי שְׁלִיחוּתָא חָדָא לְבַר יוֹחָאי, בַּאֲתַר דְּאִיהוּ תַּמָּן.</p>"],[9514013620,"<p>אִסְתַּחֲרָא הַהוּא שַׁפְנִינָא וְקָמַת קַמֵּיהּ. כְּתַב פִּתְקָא חָדָא, וַאֲמַר מָה דַאֲמַר. וְקָמַת שַׁפְנִינָא וּנְטָלַת בְּפוּמָהּ, וַאֲזָלַת לְגַבֵּיהּ דְּרַבִּי שִׁמְעוֹן, וְשַׁוִּיאַת לֵיהּ בִּכְנָפָא. אִסְתַּכַּל בְּהַהוּא פִּתְקָא, וּבְכָה, הוּא וְרַבִּי אֶלְעָזָר בְּרֵיהּ. וַאֲמַר, בָּכֵינָא עַל פְּרִישׁוּתָנָא מִן חַבְרַיָא, וּבָכֵינָא עַל מִלִּין אִלֵּין, דְּלָא אִתְגַּלְּיָין לְהוֹ, מַה יַּעַבְדּוּן דָּרֵי בַּתְרָאי, אִי יַשְׁגִּיחוּן בְּהַאי.</p>"],[9514013621,"<p>אַדְהָכֵי, אֲתָא אֵלִיָּהוּ זָכוּר לַטוֹב, חֲמֵי דִּבְכֵי, אֲמַר בִּשְׁלִיחוּתָא אָחֳרָא הֲוֵינָא זַמִּין, הַשְׁתָּא, וְשַׁדְּרַנִי קוּדְשָׁא בְּרִיךְ הוּא לְשַׁכְּכָא דְּמָעִיךְ. אִי רַבִּי, אִי רַבִּי, לָא הֲוָה אִצְטְרִיךְ הַשְׁתָּא לְגַלָּאָה לְצַדִּיקַיָיא מִלִּין אִלֵּין.</p>"],[9514013622,"<p>אֲבָל כָּךְ אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, בִּקְלָלוֹת קַדְמָאִין אִית ל\"ב קְרָאֵי, וְכָלְהוֹ לָקֳבֵיל שְׁבִילֵי דְאוֹרַיְיתָא. בִּקְלָלוֹת בַּתְרָאי אִית בְּהוּ נ\"ג קְרָאֵי, לָקֳבֵיל פָּרְשִׁיָּין וְאוֹרְחִין דְּאוֹרַיְיתָא.</p>"],[9514013623,"<p>בְּגָלוּת קַדְמָאָה דְבַיִת רִאשׁוֹן, עָבְרוּ יִשְׂרָאֵל אִינוּן שְׁבִילִין סְתִימִין דְּסִתְרָא, אִתְגְּלֵי חוֹבַיְיהוּ, וְאִתְגְּלֵי קִיצָא דִילְהוֹן, וְנֶחָמָתָא וְאַבְטָחוּתָא דִילְהוֹן. בְּגָלוּת בַּתְרָאָה דְּבַיִת שֵׁנִי, עָבְרוּ יִשְׂרָאֵל ג\"ן פָּרָשִׁיּוֹת אוֹרְחִין דְּאִתְגַּלְּיָין, אִסְתִּים חוֹבַיְיהוּ, וְאִסְתִּים קִיצַיְיהוּ, וְלָא כְתִיב בְּהוּ הַבְטָחוֹת וְנֶחָמוֹת.</p>"],[9514013624,"<p>אַדְּהָכֵי, עֲבַר חַד רוּחָא, וְאַפְרֵישׁ לוֹן, וְסָלֵיק אֵלִיָּהוּ גּוֹ גַּלְגַּלָּא דְנוּרָא, וְאִשְׁתָּאַר רַבִּי שִׁמְעוֹן, וּבְכֵי, וְאַדְמוּךְ אַפִּיתְחָא דִמְעַרְתָּא. אַדְּהָכֵי, אֲתָא אֵלִיָּהוּ זָכוּר לַטוֹב, אֲמַר, קוּם רַבִּי שִׁמְעוֹן אִתְעַר מִשְׁנָתָךְ, זַכָּאָה חוּלָקָךְ, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרָךְ. כָּל הַבְטָחוֹת וְנֶחָמוֹת דְּיִשְׂרָאֵל, בְּהַנֵּי קְלָלוֹת כְּתִיבֵי.</p>"],[9514013625,"<p>פּוֹק וַחֲזֵי, מַלְכָּא דִּרְחֵים לִבְרֵיהּ, וְאַף עַל גַּב דְּלַטְיֵיהּ וְאַלְקְיִיהּ, רְחִימוּ דִמְעוֹי עֲלֵיהּ. כַּד אַחֲזֵי רוּגְזָא תַּקִּיף, כְּדֵין רַחְמָנוּתָא עֲלֵיהּ. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא, אַף עַל גַּב דְּלַיֵּיט, מִלּוֹי בִּרְחִימוּ. אִתְחַזְיָין בְּאִתְגַּלְיָיא לְוָוטִין, וְאִינוּן טַבְוָון סַגִּיאָן, בְּגִין דְּאִלֵּין קְלָלוֹת בִּרְחִימוּ הֲווֹ. מַה דְּלָא הֲוָה כֵּן בְּאִינוּן קַדְמָאִין, דְּכָלְהוֹ הֲווֹ בְּדִינָא תַּקִּיף.</p>"],[9514013626,"<p>בְּאִלֵּין אִית דִּינָא וּרְחִימוּ, כְּאַבָּא דִּרְחֵים עַל בְּרֵיהּ, וּרְצוּעָה דְּמַלְקִיּוּתָא נָקִיט בִּידֵיהּ, עֲבֵיד נְהִימוּ סַגְיָא, וְקָלִין רַבְרְבִין. וּמַלְקְיוּתָא כְּלִילִין בְּרַחֲמֵי.</p>"],[9514013627,"<p>וְקַשְׁיָא מִכָּל אִינוּן קְלָלוֹת, דָּא הוּא דִכְתִיב, (דברים כ״ח:ס״א) גַּם כָּל חֳלִי וְכָל מַכָּה אֲשֶׁר לֹא כָתוּב בְּסֵפֶר הַתּוֹרָה יַעְלֵם ה' עָלֶיךָ עַד הִשָּׁמְדָךְ. הָכָא אִינוּן הַבְטָחוֹת דְּאַבָּא עַל בְּרֵיהּ, בִּרְחִימוּ סַגֵּי. יַעֲלֶה לָא כְתִיב, אֶלָּא יַעְלֵם, יַכְבֵּשׁ לוֹן, וִיכַסֵּי לוֹן בְּנוּקְבָא דְדוּכְתַּיְיהוּ, דְּלָא יִפְקוּן לְבַר, וִיהוֹן כְּבוּשִׁין וּמְכוּסִין בְּנוּקְבַיְיהוּ.</p>"],[9514013628,"<p>עַד הִשָּׁמְדָךְ, מַה דְּלָא יְהֵי לְעָלַם וּלְעָלְמֵי עָלְמַיָיא, דְּהָא אוֹמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יְשֵׁיצֵי יַת יִשְׂרָאֵל לְעָלַם וּלְעָלְמֵי עָלְמִין, וְדוּכְרָנֵיהוֹן יְהֵי קַיָּים תְּדִירָא. דִּכְתִיב, (ישעיהו ס״ו:כ״ב-כ״ג) כֵּן יַעֲמֹד זַרְעֲכֶם וְשִׁמְכֶם. וּכְתִיב, (ירמיהו ל״א:ל״ז) כֹּה אָמַר ה' אִם יִמַּדּוּ שָׁמַיִם מִלְּמַעְלָה כו'.</p>"],[9514013629,"<p>וְהוֹאִיל וּבְאוֹמָאָה אִיהוּ דְּלָא יִשְׁתֵּיצוּן יִשְׂרָאֵל, זְמִינָא דִּיהוֹן כָּל מַכְתְּשִׁין וּמַרְעִין טְמִירִין וּמְכוּסִין, דְּלָא יִפְקוּן לְבַר לְאַבְאָשָׁא לוֹן, עַד זִימְנָא דְּיִשְׁתֵּיצוּן מִן עָלְמָא, מַה דְּלָא יְהֵא לְעָלַם וּלְעָלְמֵי עָלְמִין.</p>"],[9514013630,"<p>סוֹפָא דְכוּלְהוֹן וְסִיּוּמָא דִילְהוֹן, (דברים כ״ח:ס״ח) וֶהֱשִׁיבְךָ ה' מִצְרַיִם בָּאֳנִיּוֹת בַּדֶּרֶךְ אֲשֶׁר אָמַרְתִּי לְךָ לֹא תֹסִיף עוֹד לִרְאֹתָהּ וְהִתְמַכַּרְתֶּם שָׁם לְאֹיְבֶיךָ לַעֲבָדִים וְלִשְׁפָחוֹת וְאֵין קֹנֶה. הָכָא הַבְטָחוֹת וְנֶחָמוֹת, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לְיִשְׂרָאֵל בְּסוֹף יוֹמַיָא. וֶהֱשִׁיבְךָ ה' מִצְרַיִם בָּאֳנִיּוֹת, אַבְטָחוּתָא לַאֲתָבָא וּלְמֶיעְבַּד נִסִּין וְאָתִין דַּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, בְּיוֹמִין קַדְמָאִין. כְּמָה דְאַתְּ אָמֵר (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>"],[9514013631,"<p>בָּאֳנִיּוֹת, הָכָא אִיהוּ, כְּמָה דַּאֲמַרְתְּ, דְּאַתְּ דָּרֵישׁ בַּעֲנִיּוּת, שֶׁתִּכְלֶה פְּרוּטָה מִן הַכִּיס. אֲבָל, זְמִינִין כָּל בְּנֵי עָלְמָא לְמֵיתֵי עֲלַיְיהוּ דְיִשְׂרָאֵל עַל סְפִינָן דְּיַמָּא, וְיַחְשְׁבוּן לְשֵׁיצָאָה לוֹן מִן עָלְמָא, וְכָלְהוֹ טְבִיעִין גּוֹ יַמָּא, כְּמָה דַּעֲבַד בְּיוֹמִין קַדְמָאִין.</p>"],[9514013632,"<p>וְתַמָּן אִיהוּ חֶדְוָה סַגִּיאָה. כְּתִיב הָכָא בָּאֳנִיּוֹת, וּכְתִיב הָתָם (ישעיהו מ״ג:י״ד) בָּאֳנִיּוֹת רִנָּתָם. מַה לְּהַלָּן רִנָּה אַף כָּאן רִנָּה.</p>"],[9514013633,"<p>בַּדֶּרֶךָ אֲשֶׁר אָמַרְתִּי לְךָ. מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא, לָא גַּלֵּי גְּבוּרְתֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאִתְחֲזָאָה בְּעָלְמָא, וְשַׁעֲתָא דִרְעוּתָא, אֶלָּא בְּהַהוּא דֶּרֶךְ. כִּי כַּאֲשֶׁר רְאִיתֶם אֶת מִצְרַיִם, בְּאוֹתוֹ דֶּרֶךְ, וּבְהַהוּא גַּוְונָא יַעֲבֵיד לָךְ.</p>"],[9514013634,"<p>דְּהָא לְבָתַר מִכָּל שְׁאָר סִטְרִין יִתְכַּנְּשׁוּן עֲלַיְיהוּ דְיִשְׂרָאֵל, וְיַחְשְׁבוּן יִשְׂרָאֵל, דִּבְזִמְנָא דָא יִתְאַבְדוּן, וְאִינוּן זְבִינִין לְבַעֲלֵי דְבָבֵיהוֹן, הֲדָא הוּא דִכְתִיב, (דברים כח) וְהִתְמַכַּרְתֶּם שָׁם, וְנִמְכַּרְתֶּם לָא כְתִיב, אֶלָּא וְהִתְמַכַּרְתֶּם, בִּלְבַבְכוֹן תַּחְשְׁבוּן דְּאַתּוּן זְבִינִין, וְלָאו הָכֵי, דְּהָא וְאֵין קוֹנֶה כְּתִיב, וְלֵית מַאן דְּיָכֵיל לְשַׁלְטָאָה עֲלַיְיהוּ.</p>"],[9514013635,"<p>וְכָל דָּא, לְסוֹף יוֹמַיָּא. וְתַלְיָיא כּוֹלָּא בִּתְיוּבְתָּא. וְכוֹלָּא סְתִים. כְּמָא דִּכְתִיב, (שם כט) לְמַעַן תַּשְׂכִּילוּ אֶת כָּל אֲשֶׁר תַּעֲשׂוּן. מַאן דְּאִית לֵיהּ לִבָּא, יִסְתַּכֵּל וִידַע לַאֲתָבָא לְמָארֵיהּ.</p>"],[9514013636,"<p>אֲמַר לֵיהּ ר' שִׁמְעוֹן, בְּאָן אֲתַר אִתְגַּלְּיָיא פִּירְקָנָא דְיִשְׂרָאֵל בְּהַנֵּי קְלָלוֹת. אֲמַר, אַשְׁגַּח וְדַיֵּיק, דּוּכְתָּא בִּישָׁא מִכָּלְהוֹ, תַּמָּן הֲוֵי.</p>"],[9514013637,"<p>אַשְׁגַּח וְדַיֵּיק וְאַשְׁכַּח, דִּכְתִיב, (שם כח) וְהָיוּ חַיֶּיךָ תְּלֻאִים לְךָ מִנֶּגֶד וּפָחַדְתָּ לַיְלָה וְיוֹמָם וְלֹא תַאֲמִין בְּחַיֶּיךָ. וְאַף עַל גַּב דְּיָדְעֵי חַבְרַיָא זְמַן, אִינוּן חַיִּים, תְּלוּיִן קַמָּן וּסְפֵיקָן. וְעִיקָרָא אִיהוּ וְיַצִּיבָן מִלִּין.</p>"],[9514013638,"<p>כְתַב פִּתְקָא לְעִידָן רַמְשָׁא, וְשַׁוֵּיהּ בְּפוּם שַׁפְנִינָא, וַאֲזָלַת לְגַבֵּיהּ דְּרַבִּי יוֹסֵי, דְּהֲוָה בְּדוּכְתֵּיהּ, וְעֵינוֹי מְחַכָּאן. כֵּיוָן דַּחֲמָא לָהּ, אֲמַר, שַׁפְנִינָא. כַּמָּא אַתְּ מְהֵימְנָא מִכָּל עוֹפָא דִשְׁמַיָא, קָרָא עֲלֵיהּ, (בראשית ח׳:י׳-י״א) וַתָּבֹא אֵלָיו הַיּוֹנָה לְעֵת עֶרֶב וְהִנֵּה עֲלֵה זַיִת טָרָף בְּפִיהָ.</p>"],[9514013639,"<p>נְטַל פִּתְקָא, וְעָאל לְגַבֵּי חַבְרַיָיא, וְאַחְמֵי לוֹן. וְסָחֵי לוֹן עוֹבָדָא, תְּוַוהוּ. בְּכָה רַבִּי יְהוּדָה וַאֲמַר, וַוי, אַף עַל גַּב דְּלָא יַדְעִינָן לֵיהּ, (קהלת י״א:ג׳) מְקוֹם שֶׁיִּפּוֹל הָעֵץ שָׁם יְהוּא. אֲתַר דְּבַר יוֹחָאי תַּמָּן, חַבְרַיָּיא בַּהֲדֵיהּ, וּמִתְעָרִין מִנֵּיהּ וְאוֹלְפִין מִנֵּיהּ.</p>"],[9514013640,"<p>זַכָאָה נַפְשֵׁיהּ דְּבַר יוֹחָאי, דְּקוּדְשָׁא בְּרִיךְ הוּא עֲבֵיד עִמֵּיהּ נִסִּין, וְאִיהוּ גָּזֵיר, וְקוּדְשָׁא בְּרִיךְ הוּא מְקַיִּים. וַעֲתֵיד לְמֶהֱוֵי רֵישָׁא לְצַדִּיקַיָיא, דְּיַתְבֵי בְּגִנְתָּא דְעֵדֶן. וִיקַבֵּל אַפֵּי שְׁכִינְתָּא, וְיֶחֱמֵי לְקוּדְשָׁא בְּרִיךְ הוּא, וְיִשְׁתַּעְשַׁע עִם צַדִּיקַיָּיא, וְיֵימָא לְהוֹ, בֹּאוּ נִשְׁתַּחֲוֶה וְנִכְרָעָה נִבְרָכָה לִפְנֵי ה' עוֹשֵׂנוּ.</p>"],[9514013641,"<p>מ (שמות כ״א:כ״ב) כִּי יִנָּצוּ אֲנָשִׁים, אִלֵּין מִיכָאֵל וְסמאל. וְנָגְפוּ אִשָּׁה הָרָה, דָּא כְּנֶסֶת יִשְׂרָאֵל וְיָצְאוּ יְלָדֶיהָ בַּגָּלוּת. עָנוֹשׁ יֵעָנֵשׁ, דָּא סמאל. כַּאֲשֶׁר יָשִׁית עָלָיו בַּעַל הָאִשָּׁה, דָּא קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514013642,"<p>יוֹסֵף, מִדִּילֵיהּ יַהֲבוּ לֵיהּ. פּוּמָא דְלָא נְשַׁק לַעֲבֵרָה, (בראשית מ״א:מ׳) וְעַל פִּיךָ יִשַּׁק כָּל עַמִּי. וְרָזָא דְמִלָּה, מִנֵּיהּ אִתְּזַן כָּל עָלְמָא, וּמִנֵּיהּ פָּרְחִין נִשְׁמָתִין לְכוֹלָּא.</p>"],[9514013643,"<p>הַצַּוָּאר שֶׁלֹּא הִרְכִּין לַעֲבֵירָה, וַיָּשֶׂם רְבִד הַזָּהָב עַל צַוָּארוֹ. וְרָזָא דְמִלָּה, ו' דַּרְגִּין דְּאִינוּן לְעֵילָּא מִנֵּיהּ, וְכוּלְהוֹ נָגְדִין לֵיהּ נְגִידוּ טָבָא מֵעַתִּיקָא קַדִּישָׁא.</p>"],[9514013644,"<p>וְהָא הוּא רָזָא דְּזָהָ\"ב דְּאִיהוּ אַרְבֵּיסַר דְּכָל חָדָא וְחָדָא, מֵאִינוּן ז' דַּרְגִּין, כְּלִילָא מֵרַחֲמָא וְדִינָא. וְדָא הוּא רָזָא, דַּאֲמָרוּ מָארֵי מַתְנִיתִין, סוּכָּה שֶׁהִיא גְּבוֹהָה לְמַעְלָה מֵעֶשְׂרִים אַמָּה פְּסוּלָה. בְּגִין דְּכָל חָדָא וְחָדָא, כְּלִילָא מֵרַחֲמֵי וְדִינָא, וְאִם הִיא לְתַתָּא מִי' פְּסוּלָה, בְּגִין דְּלָאו אִיהִי כְּלִילָא מֵרַחֲמֵי וְדִינָא.</p>"],[9514013645,"<p>הַגּוּף שֶׁלֹּא הִרְכִּין לַעֲבֵירָה, (שם) וַיַּלְבֵּשׁ אֹתוֹ בִּגְדֵי שֵׁשׁ. הַיְינוּ רָזָא דְּו\"ו דִּשְׁמָא קַדִּישָׁא. הָרַגְלַיִם שֶׁלֹּא הָלְכוּ לִדְבַר עֲבֵירָה, וַיַּרְכֵּב אֹתוֹ בְּמִרְכֶּבֶת הַמִּשְׁנֶה. בְּגִין דְּאִית רְתִיכָא עִילָּאָה, וּרְתִיכָא תַּתָּאָה, וְיוֹסֵף זְכֵי לְתַרְוַויְיהוּ, בְּגִין דְּנָטַר בְּרִית קַיָּימָא קַדִּישָׁא.</p>"],[9514013646,"<p>שַׁבָּת, ש' בַּת. בִּזְמַן שֶׁיִּתְחַבְּרוּ ג' אָבוֹת עִם הַמַּלְכוּת, שֶׁהִיא בַּ\"ת, תִּקָּרֵא שַׁבָּת.</p>"],[9514013647,"<p>וַיִּטַע אֵשֶׁל בִּבְאֵר שָׁבַע, הַקִּיצוּץ שֶׁקָּצַץ אָדָם הָרִאשׁוֹן, תִּקְּנוֹ אַבְרָהָם, וְהוּא בִּבְאֵר שָׁבַע, שֶׁהִיא הַמַּלְכוּת. דָּ\"א אֵשֶׁ\"ל, גְּוָונֵי מִדּוֹת, שֶׁהֵם חג\"ת \"אָדוֹם \"שָׁחוֹר \"לָבָן הִמְשִׁיךְ לָהּ מֵהֶם, בְּסוֹד (בראשית כ״ט:ב׳) ג' עֶדְרֵי צֹאן רוֹבְצִים עָלֶיהָ.</p>"],[9514013648,"<p>יַעֲקֹב שִׁמֵּשׁ בְּבֵית שֵׁם וְעֵבֶר, י\"ד שָׁנָה. לְתִקּוּן יוֹבֵל וּשְׁמִטָה, שֶׁהֵם לֵאָה וְרָחֵל.</p>"],[9514013649,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דַּאֲפֵיק קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם, אֲפֵיק לוֹן בְּרָזָא דִּשְׁמָא דְּמ\"ב אַתְוָון, כְּגַוְונָא דִּבְרָא בֵיהּ שְׁמַיָא וְאַרְעָא.</p>"],[9514013650,"<p>וּבְגִין דָּא, כַּד נָפְקוּ יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם, נְטָלוּ תְּרֵיסַר מַטְלָנִין, עַד דְּמָטוֹ לְטוּרָא דְסִינַי. הֲדָא הוּא דִכְתִיב, בַּיּוֹם הַזֶּה בָּאוּ מִדְבַּר סִינַי. וּבְעָא קוּדְשָׁא בְּרִיךְ הוּא, דִּתְלָתִין מַטְלָנִין אוֹחֲרָנִין, דִּלְהֱווּ אָזְלִין יַתְהוֹן בִּתְלָתָא יוֹמִין. הֲדָא הוּא דִכְתִיב, (במדבר י׳:ל״ג) וַיִּסְעוּ מֵהַר ה' דֶּרֶךְ שְׁלשֶׁת יָמִים. עֲשָׂרָה מַטְלָנִין בְּכָל יוֹמָא.</p>"],[9514013651,"<p>וּבְגִין דְּחָבוֹ, גָּרְמוּ דִּלְהֱווֹ נָטְלִין יַתְהוֹן בִּתְלֵיסַר קַדְמָאִין. וּבְגִין דָּא לָא עָלוּ לְאַרְעָא, עַד דְנָטְלוּ תְּלָתִין מַטְלָנִין אוֹחֲרָנִין, וְאִשְׁתְּלֵים רָזָא דִשְׁמָא דְמ\"ב אַתְוָון, כְּגַוְונָא דְּעוֹבָדָא דִבְרֵאשִׁית.</p>"],[9514013652,"<p>(בראשית ג׳:ג׳) וּמִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן, דָּא הוּא אֲתַר דְּרוּחֵיהוֹן דִּבְנֵי נָשָׁא גְּנִיזִין. וְדָא הוּא אֲתַר דְּאִיקְרֵי אוֹצַר הַנְּשָׁמוֹת. וְהוּא גַּבֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וַאֲמַר לוֹן, לָא תִשְׁתַּדְּלוּן לְמִנְדַע, הָאֵיךְ רוּחֵיהוֹן מִתְפָּרְשִׁין מִזִּוּוּגָא דִּיְקָרָא דִילִי.</p>"],[9514013653,"<p>וְעַל דָּא תָּנִינָן (ויקרא י״ב:ב׳) אִשָּׁה כִּי תַזְרִיעַ וְיָלְדָה זָכָר כְּתִיב, וְלָא כָּלֵיל דְּכַר וְנוּקְבָא כְּפוּם אוֹרְחוֹי דְּעָלְמָא, דְּלָא מִתְחַבְּרָאן כְּמָה דִּנְפָקוּ מִלְּעֵילָא זוּגוֹת זוּגוֹת.</p>"],[9514013654,"<p>בְּגִין, דְּאָדָם קַדְמָאָה וְזוּגָא דִילֵיהּ, חָבוּ קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא, מִתְפָּרְשִׁין כַּד נָפְקִין מִלְּעֵילָא. עַד דִּיהֵא רַעֲוָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. אִי זָכָה בַּר נָשׁ, יַהֲבִין לֵיהּ זוּגֵיהּ, וְאִי לָא, מַפְרְשִׁין לָהּ מִנֵּיהּ, וְיַהֲבִין לָהּ אוֹחֲרָא, וּמוֹלִידִין בְּנִין דְּלָא כִּדְקָא יָאוֹת.</p>"],[9514013655,"<p>וְעַל דָּא כְּתִיב, (בראשית ו׳:ג׳) לֹא יָדוֹן רוּחִי בָאָדָם לְעוֹלָם. מַאי רוּחִי, רוּחוֹ מִבָּעֵי לֵיהּ. אֶלָּא אִינוּן תְּרֵין רוּחִי, דְּנָפְקֵי זוּגוֹת, לָא יִדּוֹנִין כַּחֲדָא. וְעַל דָּא כְתִיב, וְיָלְדָה זָכָר וְלָא כָלֵיל דְּכַר ונְוּקְבָא, כְּפוּם אוֹרְחוֹי דְּעָלְמָא. דְּאִינוּן גָּרְמוֹ.</p>"],[9514013656,"<p>רַבִּי רְחוּמָאי פָּתַח, (ישעיה יא ב) וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת ה', הָא הָכָא אַרְבַּע רוּחוֹת, וְלֹא זָכָה בָּהֶם אָדָם, זוּלָתִי מֶלֶךְ הַמָּשִׁיחַ בִּלְבָד.</p>"],[9514013657,"<p>וְהָכְתִיב (יחזקאל לז ט) מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ. אַרְבַּע לָא כְתִיב, אֶלָּא מֵאַרְבַּע רוּחוֹת. זֶהוּ רוּחַ שָׁלֵם.</p>"],[9514013658,"<p>אָמַר לֵיהּ הֵיאַךְ. אָמַר לֵיהּ, זֶה הַבָּא מִתּוֹךְ אַהֲבַת נְשִׁיקָה. הֵיאַךְ נְשִׁיקָה מֵאַהֲבָה אֵינוֹ אֶלָּא בַּפֶּה, וּמִתְחַבְּרָן רוּחַ בְּרוּחַ, וְכָל אֶחָד מֵהֶם כָּלוּל מִשְׁתֵּי רוּחוֹת, רוּחוֹ וְרוּחַ חֲבֵירוֹ, נִמְצְאוּ שְׁנֵיהֶם בְּאַרְבַּע רוּחוֹת. וְכָּל שֶׁכֵּן הַזָּכָר וְהַנְּקֵבָה בְּהִתְחַבְּרָם, שָׁם אַרְבַּע רוּחוֹת יַחַד. וְהַבֵּן הַבָּא מֵהֶם, זֶהוּ רוּחַ הַבָּא מֵאַרְבַּע רוּחוֹת. כְּמָא דְאַתְּ אָמֵר, מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, וְזֶהוּ רוּחַ שָׁלֵם.</p>"],[9514013659,"<p>רַבִּי בֶּרֶכְיָה אֲמַר, יְתֵיב הֲוֵינָא עַל פִּילֵי דְרוֹמִי רַבָּתָא, וַחֲמֵינָא חַד בַּר נָשׁ דְּהֲוָה אָתֵי. נְפַקְנָא לְגַבֵּיהּ, אָעֵילְנָא לֵיהּ בְּגוֹ בֵּיתָאי. בָּדִיקְנָא לֵיהּ, בְּמִקְרָא בְּמִשְׁנָה בְּתוֹסֶפְתָּא וּבְהַגָּדָה, וְלָא אַשְׁכַּחְנָא בֵּיהּ. נָזִיפְנָא בֵּיהּ, וְלָא אֲתֵיב לִי מִידֵי. אַפֵּיל גַּרְמֵיהּ אֲחוֹרֵי דַשָּׁא, וּדְמָךְ. אֲמֵינָא, הוּא וְכַלְבָּא יֵיכְלוּן כַּחֲדָא.</p>"],[9514013660,"<p>דְּהָכֵי אָמַר רִבִּי מִנְיוֹמֵי סָבָא דְגוּשׁ חַלְבָא, מַהוּ (ישעיה נו יא) וְהַכְּלָבִים עַזִּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה וְהֵמָּה רֹעִים וְגו'. לֹא יָדְעוּ שָׂבְעָה, אֵלּוּ עַמֵּי הָאָרֶץ, שֶׁהֵם עַזִּי פָנִים כַּכֶּלֶב, עַזִּי נֶפֶשׁ בְּכֹלָּא. מַאי טַעְמָא. מִפְּנֵי (שם) שֶׁלֹּא יָדְעוּ הָבִין. דְּקוּדְשָׁא בְּרִיךְ הוּא לָא אַשְׁרֵי קְדוּשָׁתֵיהּ בְּגַוַּויְיהוּ, וְעַל דָּא אִינוּן עַזִּי נֶפֶשׁ. וּבְגִין כָּךְ הוּא וְכַלְבָּא יֵיכְלוּן כַּחֲדָא.</p>"],[9514013661,"<p>כַד אִיתְעַר, קָם וּקְרֵיב לְגַבֵּי פָּתוֹרָא, מָאִיךְ רֵישׁוֹי וְלָא אֲמַר מִידֵי. חָמֵינָא וְאִסְתַּכַּלְנָא בְּעֵינוֹי, דְּחַיְיכָן. אֲמַר לִי, וַדַּאי מֵאוֹרְחוֹי דְּמָרָךְ אִתְרַחַקְתְּ, דְּהוּא תַּקֵּין פָּתוֹרָא עַד דְּלָא יֵיתֵי אָדָם, וְעַד דְּלָא יִפְקוֹד לֵיהּ, וְיִבְדּוֹק לֵיהּ. אִי תוֹסִיף לְמֵהַךְ בְּאוֹרְחָא דָא, לָא יִתְקַיְימוּן לָךְ בְּנִין. מִיַּד אַהֲדַר וַאֲמַר, יֵיחוֹן לָךְ, וְיִתְקַיְּימוּן לָךְ.</p>"],[9514013662,"<p>אֲמֵינָא לֵיהּ אַמַּאי אֲהַדְּרַת מִלָּה וְאִתְנֶחַמְתְּ. אֲמַר לִי, אָסוּר לֵיהּ לְבַר נָשׁ לְמֵילֵיט גַּרְמֵיהּ וְכָל שֶׁכֵּן אָחֳרָא, בְּגִין דְּקִלְּלַת חָכָם אֲפִילּוּ עַל תְּנַאי יִתְקַיֵּים. אֲמֵינָא, הָכֵי הוּא וַדַּאי, דִּכְתִיב (בראשית לא לב) עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךָ לֹא יִחְיֶה, וְאִתְקַיִּים. וְאַנְתְּ בָּדִיקְנָא בָּךְ, וּלְוָוטָךְ לָאו כְּלוּם.</p>"],[9514013663,"<p>פָּתַח וְאָמַר, (שמות לב לב) וְעַתָּה אִם תִּשָּׂא חַטָאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ. קְלָלָא דָא עַל תְּנַאי, וְקוּדְשָׁא בְּרִיךְ הוּא מָחִיל לְחוֹבֵיהוֹן בְּגִינֵיהּ דְּמשֶׁה, וְאַף עַל פִּי כֵּן אִתְמְחֵי מִפָּרְשָׁתָא מַעַלְיָיתָא בְּאוֹרַיְיתָא, בְּפִיקּוּדָא דְּעוֹבָדָא דְמַשְׁכְּנָא, וְאִיהִי פָּרָשַׁת וְאַתָּה תְּצַוֶּה. דְּהֲוָה לֵיהּ לְמִיכְתַּב שְׁמֵיהּ דְּמשֶׁה בְּכָל מִלָּה וּמִלָּה, וּבְכָל פִּיקּוּדָא וּפִיקּוּדָא דְּתַמָּן, וְאִתְמְחֵי מִכָּל הַהִיא פָּרְשָׁתָא, דְּלָא אִדְכַּר תַּמָּן. הֱוֵי קִלְּלַת חָכָם אֲפִילּוּ עַל תְּנַאי, אִתְקַיַּים.</p>"],[9514013664,"<p>כֵיוָן דְּאַרְגֵישְׁנָא בֵּיהּ, קַמְנָא וְאוֹתִיבְנָא לֵיהּ בְּרֵישָׁא דְּפָתוֹרָא. אֲמֵינָא, וְהָא לְבָתַר וְאַתָּה תְּצַוֶּה אֲמַר משֶׁה הַאי מִלָּה. אָמַר לֵיהּ, אֵין מוּקְדָם וּמְאוּחָר בַּתּוֹרָה.</p>"],[9514013665,"<p>שָׁאֵילְנָא לֵיהּ בְּמִקְרָא בְּמִשְׁנָה וּבְתוֹסֶפְתָּא וּבְהַגָּדָה, וַהֲוָה בָּקִי בְּכוֹלָּא. אֲמֵינָא אַמַּאי בְּקַדְמִיתָא לָא אֲתֵיבַת לִי, כַּד בָּדִיקְנָא בָּךְ. אֲמַר, שֵׁינְתָא אָנֵיס לִי. תְּרֵין יוֹמִין הֲווֹ דְּלָא דָּמִיכְנָא. וְהַשְׁתָּא דְּשֵׁינְתָא אֲתָא לְעֵינַי, לָא אָתֵיבְנָא לָךְ.</p>"],[9514013666,"<p>לְבָתַר דְּאָכַל וְשָׁתָה, פָּתַח וְאָמַר, (שה\"ש א א) שִׁיר הַשִּׁירִים. ש רַבְרְבָא, וְהִיא תִּנְיָינָא מִסּוֹפָא דְּאַתְוָוֵי דְּאַלְפָא בֵּיתָא. ב דִּבְרֵאשִׁית רַבְרְבָא, וְהִיא תִּנְיָינָא מִשֵּׁירוּתָא דְּאַלְפָא בֵּיתָא, מַאי טַעְמָא.</p>"],[9514013667,"<p>בְּגִין דְּשי\"ן רָזָא דִּרְתִיכָא עִילָּאָה, וְעַל דָּא אִיהִי בִּתְלַת סַמְכִין, דְּהָא אֲבָהָן אִינוּן רְתִיכָא. וְכָל שִׁיר הַשִּׁירִים רָזָא דִּרְתִיכָא עִילָּאָה אִיהִי, וּבְגִין כָּךְ שֵׁירוּתָא דִילֵיהּ בְּשי\"ן. ב, אִיהִי בֵּיתָא דְּעָלְמָא, דְּעוֹבָדָא דְעָלְמָא אִיהִי.</p>"],[9514013668,"<p>וְעַל דָּא אַתְוָון דְּקָיְימִין בְּשֵׁירוּתָא דְּסִפְרִין ד' אִינוּן. דְּהָא כְּגַוְונָא דְּאִיתְעֲבִידוּ, וּכְהַהוּא רָזָא דִּילְהוֹן, הָכֵי אַתְוָון רְשִׁימִין בְּרֵישָׁא. וְאִינוּן אַתְוָון רַבְרְבָן, דְּסָלְקָן עַל כָּל שְׁאָר אַתְוָון. וְהַהוּא אָת רָזָא וְסִתְרָא דְּכָל סִפְרָא.</p>"],[9514013669,"<p>וְאִלֵּין אִינוּן: א דְּהִבְרֵי הַיָּמִים. ב דִּבְרֵאשִׁית. מ דְּמִשְׁלֵי. ש דְּשִׁיר הַשִּׁירִים. אִלֵּין ד' אַתְוָון בְּרֵישׁ סִפְרִין, אִינּוּן אַתְוָון רַבְרְבָן. וּמַאן דְּיָדַע בְּהוּ, יוֹדֵעַ רָזָא דְּכָל סִפְרָא. וְהַהוּא אָת אוֹלִיף רָזָא דְּכָל סִפְרָא.</p>"],[9514013670,"<p>תִּיקּוּנָא דִילֵיהּ, דִּיוּקְנָא וְסִתְרָא דְּאָדָם בִּתְרֵין גְּוָונִין. רֵישָׁא דִלְעֵילָא, אִיהוּ נְקוּדָה קַדְמָאָה דְּשָׁלְטָא עַל כֹּלָּא, בִּגְלִיפוּ, דְּאִתְעַטַר לְאִתְפַּשְׁטָא תְּחוֹתֵיהּ. וא\"ו דְּאִיהוּ רָזָא וּדְיוֹקְנָא דְאָדָם. הוּא, וּבַת זוּגֵיהּ דלת דִּלְתַתָּא, דְּאִתְאַחֲהַת מִסִּטְרוֹי. וְדָא אִיהוּ שְׁלִימוּ דְּאָדָם.</p>"],[9514013671,"<p>בְּגַוְונָא אָחֳרָא, בְּאֶמְצָעִיתָא דִּיוּקְנָא דְּאָדָם, וְאִתְאַחִידָא בֵּיהּ מִתְּרֵין סִטְרִין, כְּגַוְונָא דִדְרוֹעִין, מִסִּטְרָא דָא וּמִסִּטְרָא דָא. וְדָא א, דִּיוּקְנָא וְרָזָא דִילֵיהּ, אָדָם אִיהוּ. וְעַל דָּא רְשִׁימָא אל\"ף, בְּרֵישׁ סִפְרָא דְדִבְרֵי הַיָּמִים, דְּהָא לָא אָתָא הַהוּא סִפְרָא אֶלָּא לְאַשְׁלָמָא אָדָם בְּסִתְרוֹי וְדַרְגּוֹי, בְּאִינוּן תּוֹלָדִין דִּילֵיהּ, לְמֶהֱוֵי כּוֹלָּא חַד אָדָם שְׁלִים.</p>"],[9514013672,"<p>אִיהִי בֵּיתָא דְּכָל עָלְמָא, מְסַחֲרָא לִתְלַת סִטְרִין, עֵילָא וְתַתָּא וְכָל עוֹבָדִין כְּלִילָן בְּגַוָּוהּ, סַחֲרָא תְּלַת סִטְרִין דְּכָל עָלְמָא, וְאִשְׁתָּאַר סִטְרָא דְצָפוֹן דְּלָא אִתְבְּנֵי, דְּאִיהוּ מָדוֹרָא בִּישָׁא, דְּתַמָּן שָׁרַת רָעָה דְּכָל עָלְמָא. כְּמָה דְאַתְּ אָמֵר, (ירמיה א יד) מִצָּפוֹן תִּפָּתַח הָרָעָה.</p>"],[9514013673,"<p>וְעַל דָּא, ב' אִיהִי בֵּיתָא וּבִנְיָינָא דְּכָל עָלְמָא, אִיהִי בְּרֵישׁ אוֹרַיְיתָא, רַבְרְבָא רְשִׁימָא, לְאַחֲזָאָה עַל כָּל סִפְרָא.</p>"],[9514013674,"<p>וְסִפְרָא דָא כְּעוֹבָדָא דִבְרֵאשִׁית, אִתְעֲבֵיד, בְּרָזָא דִשְׁמָא דְּאַרְבְּעִין וּתְרֵין, כָּלֵיל בְּעוֹבָדָא דִבְרֵאשִׁית. וְעַל דָּא רָזָא דְסִפְרָא בְּרֵישָׁא ב. סִיּוּמָא דְסִפְרָא ם. בְּרָזָא דְּאַרְבָּעִין וּתְרֵין אַתְוָון אִסְתַּלַּק.</p>"],[9514013675,"<p>מ' פְּתִיחָא, רָזָא דְנוּקְבָא שְׁלֵימָתָא, אֵשֶׁת חַיִל מִתְעַטְרָא בְּעִטְרָהָא. וְעַל דָּא, כָּל סִפְרָא דְמִשְׁלֵי, לָאו אִיהִי אֶלָּא תּוּשְׁבַּחְתָּא דְּהַאי אֵשֶׁת חַיִל, וּלְמֵיתַב דַּעְתָּא דִבְנֵי נָשָׁא, לְאִסְתַּמְּרָא מֵאִשָּׁה רָעָה. כְּמָא דְאַתְּ אָמֵר, לִשְׁמָרְךָ מֵאִשָּׁה רָעָה, וּלְאִתְקָרְבָא לְהַאי אֵשֶׁת חַיִל, בְּפוּלְחָנָא עִילָּאָה. וְעַל דָּא מ רַבְרְבָא בְּרֵישׁ סִפְרָא, עַל הַהוּא רָזָא אָזְלָא.</p>"],[9514013676,"<p>ש, דָּא אִיהִי מִתְיַיחֲדָא בְּרָזָא דִרְתִיכָא עִילָּאָה. דַּאֲבָהָן אִינוּן רְתִיכָא עִילָּאָה. וְאַבְרָהָם וְיִצְחָק אֲחִידָן דָּא בְּדָא, וּכְלִילָן דָּא בְּדָא. וְיַעֲקֹב עָאל בְּאֶמְצָעִיתָא, וְאַסְכִּים לִתְרֵין סִטְרִין. וְעַל דָּא מִתְיַיחֲדָאן כּוּלְהוֹ, בְּרָזָא דְּעַלְּמָא עִילָּאָה.</p>"],[9514013677,"<p>וּבְגִין כָּךְ, תּוּשְׁבַּחְתָּא דָּא, בְּרָזָא דִּרְתִיכָא עִילָּאָה אִיהִי, דְּאִתְיַחֲדָא בְּמַלְכָּא דִּשְׁלָמָא כּוֹלָּא דִּילֵיהּ, וּבְגִין כָּךְ אִיהִי רַבְרְבָא. וּבְגִין כָּךְ אִתְיַיחֲדַת בְּרֵישׁ סִפְרָא, לְאַחֲזָאָה, דְּכָל סִפְרָא עַל רָזָא דָא אָזְלָא וְאִתְתַּקַּן. וְעַל דָּא, אָת דָּא אִתְחֲזִיאַת שִׁבְחָא דְּכָל סִפְרָא. בְּהַהִיא שַׁעֲתָא קַמְנָא וְנָשִׁיקְנָא לֵיהּ, וְתָבַעְנָא מִנֵּיהּ דְּיִמְחוֹל לִי, וּמָחַל לִי.</p>"],[9514013678,"<p>פָּתַח וְאָמַר, (קהלת ה ה) אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ וְאַל תֹּאמַר לִפְנֵי הַמַּלְאָךְ כִּי שְׁגָגָה הִיא לָמָּה יִקְצֹף הָאֱלהִים עַל קוֹלֶךָ וְחִבֵּל אֶת מַעֲשֵׂה יָדֶיךָ. כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא בְּהַאי עָלְמָא. הַאי קְרָא אֵתִיבוֹן לְחַבְרַיָּיא, דְּהָכֵי אִצְטְרִיךְ לְמִיכְתַּב, אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת נַפְשֶׁךָ, כְּמָה דְאַתְּ אָמֵר, (ויקרא ד ב) נֶפֶשׁ כִּי תֶחֱטָא, וְלָא אַשְׁכְּחָן קְרָא דִּכְתִיב וּבָשָׂר כִּי יֶחֱטָא, וְיָאוֹת הוּא.</p>"],[9514013679,"<p>אֶלָּא הָכֵי מַסְקָנָא, דְּאָסוּר לֵיהּ לְבַר נַשׁ לְמִשְׁתָּעֵי מִלֵּי דִזְנוּתָא אֲפִילּוּ בְּאִיתְּתֵיהּ, בְּגִין דְּיִתְקַשֵּׁי, וְיֵיתֵי לְהִרְהוּרִין בִּישִׁין אָחֳרָנִין, וִיהֵא דָּשׁ בְּאִידְרֵיהּ, וְיִזְרַע חִטִין אָחֳרָנִין.</p>"],[9514013680,"<p>הֲדָא הוּא דִכְתִיב, אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ. דָּא בְּשַׂר קֹדֶשׁ דִּכְתִיב (בראשית יז יג) וְהָיְתָה בְרִיתִי בִּבְשַׂרְכֶם. וְאַל תֹּאמַר לִפְנֵי הַמַּלְאָךְ, הַהוֹלֵךְ לִימִינוֹ שֶׁל אָדָם, אַל תֹּאמַר דְּבָרִים שֶׁאֵינָן כְּהוֹגֶן, אֶלָּא כָּל דְּבָרֶיךָ בְּנַחַת וּבְמִשְׁקָל. מַאי טַעְמָא. מִפְּנֵי כִּי שְׁגָגָה הִיא. וְחַיָּיב עַל זֶה קָרְבַּן שְׁגָגָה.</p>"],[9514013681,"<p>וְעוֹד. שֶׁעַל זֶה, לָמָּה יִקְצֹף הָאֱלֹהִים עַל קוֹלֶךָ. מִפְּנֵי שֶׁהַקּוֹל יוֹלִיךְ אוֹתוֹ עוֹף הַשָּׁמַיִם, וּמַעֲמִיד אוֹתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514013682,"<p>וְחִבֵּל אֶת מַעֲשֵׂה יָדֶיךָ, עַל חֵטְא הַבָּשָׂר. מַאי טַעְמָא. מִפְּנֵי שֶׁכָּל אָדָם שֶׁיֵּשׁ לוֹ בְּרִית קֹדֶשׁ, אֵין יְכוֹלִים אוֹתָם הַשּׁוֹלְטִים בַּגֵּיהִנֹּם לְהַכְנִיסוֹ שָׁם. וּבִלְבָד שֶׁיִּשְׁמוֹר אוֹתוֹ. וְאִם לֹא שָׁמַר אוֹתוֹ, מַעֲבִירִים מִמֶּנּוּ, וּמַשְׁחִיתִים וּמְחַבְּלִים אוֹתוֹ. שֶׁזֶּהוּ מַעֲשֵׂה יָדָיו שֶׁל אָדָם. וְאַחַר כָּךְ מַכְנִיסִים אוֹתוֹ בַּגֵּיהִנֹּם, וְאֵין לָהֶם עַל מַה שֶׁיִּסְמוֹכוּ. הַשְׁתָּא בְּרִי, הֱוֵי זָהִיר בִּכְבוֹד חֲבֵירְךָ יוֹתֵר מִגּוּפְךָ.</p>"],[9514013683,"<p>פָּתַח רַבִּי יְהוֹשֻׁעַ וְאָמַר, (תהלים פד ד) גַּם צִפּוֹר מָצְאָה בַיִת וּדְרוֹר קֵן לָהּ אֲשֶׁר שָׁתָה אֶפְרֹחֶיהָ אֶת מִזְבְּחוֹתֶיךָ ה' צְבָאוֹת מַלְכִּי וֵאלֹהָי. גַּם צִפּוֹר, תַּמָּן תָּנִינָן, עָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא, אַתְרִין וְדוּכְתִּין קַדִּישִׁין, עִילָּאִין יַתִּיר מִשְּׁאָר דּוּכְתֵּי יִשּׁוּבָא.</p>"],[9514013684,"<p>וְכֹלָּא כְּגַוְונָא דִּיצִירָה דְּבַר נָשׁ. דְּקוּדְשָׁא בְּרִיךְ הוּא בָּרֵיר הַהוּא זַרְעָא, וּמְנַפְּצֵיהּ, כְּהַאי דִּמְבָרֵיר וּמְנַפֵּץ חִטִין, תַּבְנָא לְחוּד, וְקַשׁ לְחוּד, עַד דְּבָרֵיר חִטִין עַל דּוּכְתַּיְיהוּ.</p>"],[9514013685,"<p>כָךָ נְטַל קוּדְשָׁא בְּרִיךְ הוּא תַּלְגָא מִתְּחוֹת כּוּרְסֵי יְקָרֵיהּ, וְהַהוּא תַּלְגָא מִתְחַמְּמָא בְּכַמָּה גְּוָונִין, וְאַטֵיל לָהּ בְּגוֹ מַיָיא דְאִיתְתָא. מֵהָכָא, דְּאִתְּתָא לָא מִתְעַבְּרָא עַד דְּתוֹשִׁיד מַיָיא, וּבְאִינוּן מַיִין אַטֵיל דְּכוּרָא תַּלְגָא, דָּא הוּא זַרְעָא דְּאִיהוּ מְחוּבָּר כַּחֲדָא, יַתִּיר מֵהַהוּא דְאִתְתָא, כְּגַוְּונָא דְּתַלְגָא לָקֳבֵיל מַיָיא.</p>"],[9514013686,"<p>לְבָתַר דְּאַטֵיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא גּוֹ מַיָיא, בָּרֵיר לֵיהּ וְנָפֵיץ לֵיהּ, וַעֲבַד בְּקַדְמִיתָא טִיבּוּרָא, דְּאִיהוּ נְקוּדָה חָדָא מִגּוֹ בְּרִירוּ דְּתַלְגָא, וְהַהוּא טִיבּוּרָא, אִיהוּ נְקוּדָא דְצִיּוֹן.</p>"],[9514013687,"<p>וּמִתַּמָּן אִתְפַּשְּׁטוּ אַרְבַּע חוּטִין, לְאַרְבַּע סִטְרִין דְּעָלְמָא, מִזְרָח וּמַעֲרָב צָפוֹן וְדָרוֹם. מֵהַהוּא חוּטָא דְּאִתְמְשַׁךְ מִסִּטְרָא דְמִזְרָח, אִתְעֲבֵיד מִנֵּיהּ גּוּפָא. שָׁארֵי בְּמִזְרָח, וְסַיֵּים בְּמַעֲרָב. גּוּפָא אִיהוּ אַרְעָא דְיִשְׂרָאֵל. אִתְרְשֵׁים בְּאַתְוֵוי אדנ\"י. אָדוֹן וְרִבּוֹן כָּל עָלְמָא.</p>"],[9514013688,"<p>מֵהַהוּא חוּטָא דְּאִתְמְשַׁךְ מִסִּטְרָא דְדָרוֹם, דְּאִיהוּ בְּרִירוּ דְּכָל תַּלְגָא וְתוּקְפֵּיהּ, אִתְעֲבֵיד מִנֵּיהּ דְּרוֹעָא יָמִינָא, וְאִיהוּ בְּרִירוּ דְּעִינּוּגָא. וְדָא גַּן עֵדֶן, דְּעָאל בֵּיהּ אָדָם הָרִאשׁוֹן, וְאִיהוּ לְעִינּוּגָא דְּנִשְׁמָתִין, וְדָא טָמִיר וְגָנִיז, יָמִינָא דְּכָל עָלְמָא.</p>"],[9514013689,"<p>מֵהַהוּא חוּטָא דְּאִתְמְשַׁךְ מִסִּטְרָא דְצָפוֹן, אִתְעֲבֵיד מִנֵּיהּ וְאִתְבְּרֵי דְרוֹעָא שְׂמָאלָא. וְדָא גֵּיהִנֹּם. מֵהַהוּא פְּסוֹלֶת דְּתַלְגָא. וְאִיהוּ לְעוֹנָשָׁא דְּנִשְׁמָתִין דְּחַיָּיבַיָּא.</p>"],[9514013690,"<p>רֵישָׁא אִיהוּ בִשְׁמַיָיא אִתְתַּקַּן. וַהֲוָה עָלְמָא בְּלָא רֵישָׁא, עַד דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא. כַּד אִיתָּקַם מַשְׁכְּנָא, אִיתָּקַם רֵישָׁא.</p>"],[9514013691,"<p>פּוּמָא דְכָל עָלְמָא דְּאִתְתַּקַּן בְּרֵישָׁא, סִינַי. וְהוּא רְשִׁים הַאי פּוּמָא גּוֹ מַיָיא, מִבְּרִירוּ דְּתַלְגָא. יַרְכִין וְכָל שְׁאָר אֵיבָרִים, בְּכָל שְׁאָר אַרְעָא.</p>"],[9514013692,"<p>וּכְשֵׁם שֶׁהָאִשָּׁה יֵשׁ לָהּ צִירִים וַחֲבָלִים בִּשְׁעַת הַלֵּידָה. כֵּן כְּשֶׁבִּקֵּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא הָאָרֶץ לְאוֹר הָעוֹלָם, הָיוּ הַמַּיִם עוֹלִים וְיוֹרְדִים, יַעֲלוּ הָרִים יֵרְדוּ בְקָעוֹת. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא. הוֹצִיא מִן הַקַּרְקַע רְעָמִים וּזְוָעוֹת, וְנָסוּ הַמַּיִם. הֲדָא הוּא דִכְתִיב, (תהלים קד ז) מִן גַּעֲרָתְךָ יְנוּסוּן מִן קוֹל רַעַמְךָ יֵחָפֵזוּן. וְיָצְאָה הָאָרֶץ. וְנִשְׁאֲרָה נְמוּכָה מְלוּכְלֶכֶת, כַּוְּלַד הַזֶּה, שֶׁיּוֹצֵא, נָמוּךְ כַּמֵּת, וּמְלוּכְלָךְ מֵהַלֵּידָה.</p>"],[9514013693,"<p>וּכְשֵׁם שֶׁמְפַעְפְּעִין אֶת הַוְּלַד עַד שֶׁיִּתְעוֹרֵר, וְנוֹתְנִים אֵשׁ וְנֵר לְגַבּוֹ, לְחַמְּמוֹ, וּמַרְאָה לְהָאִיר. כָּךְ עָשָׂה הַקָדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ, כְּשֶׁיָּצְאָה מִתּוֹךְ הַמַּיִם. וְכוֹלָא בְּחַד קְרָא, הֲדָא הוּא דִכְתִיב, (תהלים עז יט) קוֹל רַעַמְךָ בַּגַּלְגַּל הֵאִירוּ בְרָקִים תֵּבֵל מִיָּד רָגְזָה וַתִּרְעַשׁ הָאָרֶץ.</p>"],[9514013694,"<p>עַל כֵּן נִסְתַּם הַפֶּה, עַד שֶׁבָּאוּ יִשְׂרָאֵל, וְהַפֶּה נִפְתַּח בְּרֹאשׁוֹ בַּשָּׁמַיִם, וְזֶה סִינַי שֶׁנִּתְּנָה בּוֹ הַתּוֹרָה, וְשָׁם נִתְתַּקֵּן הַדִּבּוּר.</p>"],[9514013695,"<p>וּכְשֶׁנִּכְנְסוּ יִשְׂרָאֵל לָאָרֶץ, נִסְתַּם הַפָּתוּחַ. וְנִפְתַּח הַסָּתוּם. נִסְתַּם הַפֶּה, שֶׁלֹּא הָיָה בּוֹ הַדִּיבּוּר, מִשֶּׁנִּסְתַּלֵּק משֶׁה. הֵפֶךְ מִן הָאָדָם. נִפְתַּח הַטַבּוּר, בֵּית הַמִּקְדָּשׁ. וּמִשָׁם אוֹכֵל מַה שֶּׁאִמּוֹ אוֹכֶלֶת, וְשׁוֹתֶה מִמַּה שֶּׁאִמּוֹ שׁוֹתָה. וְכָל הָעוֹלָם נִזּוֹן מִתַּמְצִית אֶרֶץ יִשְׂרָאֵל.</p>"],[9514013696,"<p>וּבְגִין כָּךְ, דּוּכְתִּין וְאַתְרִין אִינוּן בְּעָלְמָא, בְּשִׁבְחָא אִלֵּין עַל אִלֵּין. גַּן עֵדֶן דְּאִיהוּ דְּרוֹעָא יָמִינָא דְכָל עָלְמָא, אִית בֵּיהּ דּוּכְתִּין וְאַתְרִין, לְשִׁבְחָא אִלֵּין עַל אִלֵּין, וְתַמָּן הוּא עֵץ הַחַיִּים וְעֵץ הַדַּעַת טוֹב וָרָע.</p>"],[9514013697,"<p>וּבְחַה הֵיכָלָא מִינַיְיהוּ, אִית אֲתַר טָמִיר וְגָנִיז מִכּוֹלָא, וְלֵית מַאן דְּיָדַע בְּהַהוּא אֲתַר, בַּר חַד צִפּוֹר, דְּאָתֵי בְּכָל יוֹמָא תְּלַת זִמְנִין, וּמְצַפְצְפָא בְּגוֹ אִילָנֵי דְגִנְתָא, וַאֲמַר גַּם צִפּוֹר וְגו'.</p>"],[9514013698,"<p>וּבְהַהוּא צִפּוֹר יָדְעִין נִשְׁמָתִין סִימָנַיְיהוּ, בְּזִימְנָא דְאוֹדָן וּמְשַׁבְּחָן, וּבְזִמְנָא דְמִשְׁתַּדְּלָן בְּחָכְמְתָא לְמִנְדַע, וְהַהוּא צִפּוֹר עָאל בְּהַהוּא הֵיכָלָא, וְאִיטָמַר וְאִגְנֵיז וְלָא יְדִיעַ. וּדְרוֹר, דָּא הִיא נִשְׁמָתָא קַדִּישָׁא, דְּסָלְקָא לְעֵילָא וְהִיא בַּת חוֹרִין.</p>"],[9514013699,"<p>דָּבָר אַחֵר (תהלים פד ד) וּדְרוֹר קֵן לָהּ, דָּא יוֹבְלָא, דִּכְתִיב וּקְרָאתֶם דְּרוֹר. קֵן לָהּ בְּחָכְמְתָא עִילָּאָה. צִפּוֹר וּדְרוֹר, דָּא לְעֵילָא, וְדָא לְתַתָּא. אֲשֶׁר שָׁתָה אֶפְרוֹחֶיהָ, מַאן. הַאי דְרוֹר, שְׁנַת הַחֲמִישִּׁים, דַּאֲפֵיקַת מִינָהּ שִׁית אֶפְרוֹחִין, וְהַאי צִפּוֹר.</p>"],[9514013700,"<p>אִינוּן אֶפְרוֹחִין, תֵּיאוּבְתָּא דִילְהוֹן, לְגוֹ תְּרֵי מַדְבְּחָן, מִזְבֵּחַ הַפְּנִימִי, וּמִזְבֵּחַ הַחִיצוֹן. נְטָלוּ מִמִּזְבֵּחַ הַפְּנִימִי, וְיַהֲבוּ לְמִזְבֵּחַ הַחִיצוֹן. מַלְכִּי וֵאלֹהָי, מַלְכִּי: דָּא מִזְבֵּחַ הַחִיצוֹן. וֵאלֹהָי: דָּא מִזְבֵּחַ הַפְּנִימִי.</p>"],[9514013701,"<p>מִזְבֵּחַ הַחִיצוֹן, תֵּיאוּבְתֵּיהּ תָּדִיר לְגַבֵּי מִזְבֵּחַ הַפְּנִימִי, וּלְעוֹלָם לָא שָׁכֵיךְ מִלְּזַמְּרָא בְּשִׁירִין וְתוּשְׁבְּחִין, הֲדָא הוּא דִכְתִיב, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה.</p>"],[9514013702,"<p>כָל זְמַן שֶׁהַנֵּר דּוֹלֵק עַל הַפְּתִילָה, וְהַפְּתִילָה כְּתִיקּוּנָהּ, הָאוֹר מֵאִיר וְצַח, וְהַכֹּל נֶהֱנִין מִמֶּנּוּ. וְכָל זְמַן שֶׁהַפְּתִילָה נֶעְדֶּרֶת, וְהַשֶּׁמֶן חָסֵר מִן הַפְּתִילָה, הָאוֹר נִסְתַּלֵּק, וְאֵין מִי שֶׁיּוֹדֵעַ בְּאוֹתוֹ אוֹר כְּלוּם.</p>"],[9514013703,"<p>כָךָ, כָּל זְמַן שֶׁיִּשְׂרָאֵל הָיוּ מְתוּקָנִים וּמְסוּרְגָּלִים כִּפְתִילָה זוֹ, אוֹר שֶׁל מַעְלָה הָיְתָה דוֹלֶקֶת עֲלֵיהֶם, וְאוֹמֶרֶת שִׁירָה, וְאֵינוֹ מִשְׁתַּכֵּךְ לְעוֹלָם. כְּדוּגְמַת הָאוֹר עַל הַפְּתִילָה, שֶׁאֵינוֹ מִשְׁתַּכֵּךְ לְעוֹלָם, לְנֶגֶד מַעְלָה. וְאוֹתוֹ הַשִּׁיר הוּא הַמְעוּלֶּה שֶׁבַּשִּׁירִים, קֹדֶשׁ קֳדָשִׁים. נֶעְדַּר הַפְּתִילָה, כִּבְיָכוֹל נֶעְדַּר הָאוֹר, וְנִסְתַּלֵּק, וְאֵין מִי שֶׁיּוֹדֵעַ בּוֹ.</p>"],[9514013704,"<p>וּשְׁלֹמֹה צווֵֹחַ וְאוֹמֵר, וּזְכֹר אֶת בּוֹרְאֶךָ בִּימֵי בְחוּרֹתֶיךָ. הֱיֵה מִתְתַּקֵּן וּמְסַרְגֵּל עַצְמְךָ בְּמִצְוֹת וּבְמַעֲשִׂים טוֹבִים, בִּימֵי בְחוּרוֹתֶיךָ, בִּזְמַן שֶׁהַמָּאוֹר הַהוּא לוֹהֵב בַּפְּתִילָה.</p>"],[9514013705,"<p>דָּבָר אַחֵר עַל הָאוֹר הַהוּא בִּזְּמַן שֶׁהַפְּתִילָה מְתוּקֶנֶת אָמַר לְנֶגֶד אוֹתוֹ הָאוֹר, וּזְכֹר אֶת בּוֹרְאֶיךָ. הִתְעוֹרֵר לְנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשִׁיר וּתְעוֹרֵר הָאַהֲבָה.</p>"],[9514013706,"<p>(קהלת י״ב:א׳) עַד אֲשֶׁר לֹא יָבוֹאוּ יְמֵי הָרָעָה, בִּזְּמַן שֶׁהַלְּבָנָה מִתְמַעֶטֶת, וְתִשְׁלוֹט הָרָעָה, וְהַיָּמִים שֶׁלָּהּ הֵם יָמִים שֶׁאֵין בָּהֶם חֵפֶץ. עַד אֲשֶׁר לֹא תֶחְשַׁךְ הַשֶּׁמֶשׁ, זֶה נָהָר הַיּוֹצֵא מֵעֵדֶן, דִּכְתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. דִּכְתִיב בּוֹ, (איוב י״ד:י״א) וְנָהָר יֶחֱרַב וְיָבֵשׁ. וְהָאוֹר, זֶה הָאוֹר שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִתְעַטֵף בּוֹ, וְהוּא יְמִינוֹ. הֲדָא הוּא דִכְתִיב (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ.</p>"],[9514013707,"<p>וְהַיָּרֵחַ, הוּא הַיָּם הַמִּתְמַלֵּא מֵאוֹתוֹ נָהָר. הֲדָא הוּא דִכְתִיב, (איוב י״ד:י״א) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחֱרַב וְיָבֵשׁ. וְהַכּוֹכָבִים, אֵלּוּ שְׁנֵים עָשָׂר מַזָּלוֹת הַיְדוּעִים לָהּ. וְשָׁבוּ הֶעָבִים, אֵלּוּ שָׂרֵי אוּמּוֹת הָעוֹלָם. אַחַר הַגָּשֶׁם, אַחַר בְּכִיָּיתָן שֶׁל מַלְאֲכֵי הַשָּׁרֵת. דִּכְתִיב, (לא ידוע) מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן.</p>"],[9514013708,"<p>(קהלת י״ב:ג׳) בַּיּוֹם שֶׁיָּזְעוּ שֹׁמְרֵי הַבַּיִת, אֵלּוּ שׁוֹמְרֵי הַחוֹמוֹת. דִּכְתִיב (ישעיהו ס״ב:ו׳) עַל חוֹמוֹתַיִךְ יְרוּשָׁלַיִם הִפְקַדְתִּי שׁוֹמְרִים. וְהִתְעַוְּתוּ אַנְשֵׁי הֶחָיִל, אֵלּוּ הֵם שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. וּבָטְלוּ הַטֹחֲנוֹת, אֵלּוּ הֵם אוֹכְלֵי הַקָּרְבָּנוֹת. כִּי מִעֵטוּ כַּנְפֵי הַחַיּוֹת. וְחָשְׁכוּ הָרֹאוֹת בָּאֲרֻבּוֹת, אֵלּוּ הֵם (זכריה ד׳:י׳) עֵינֵי ה' הַמְשׁוֹטְטוֹת בְּכָל הָאָרֶץ, וְהֵם שִׁבְעָה עֵינֵי ה'.</p>"],[9514013709,"<p>וְסֻגְּרוּ דְלָתַיִם בַּשּׁוּק, אֵלּוּ הֵם הַשְּׁעָרִים שֶׁכּוּלָּם נִנְעֲלוּ, זוּלָתִי שַׁעֲרֵי דְמָעוֹת שֶׁלֹּא נִנְעֲלוּ. בִּשְׁפַל קוֹל הַטַחֲנָה, סוּכַּת דָּוִד, שֶׁנָּפְלָה וְנִשְׁפְּלָה לֶעָפָר, וְקוֹלָהּ שֶׁהָיְתָה מְשׁוֹרְרָה תָּמִיד בְּשִׁיר הָאַהֲבָה שָׁפַל. וְיִשַּׁחוּ כָּל בְּנוֹת הַשִּׁיר, הֵם הַמַּלְאָכִים הַנֶּחֱלָקִים בְּמִשְׁמְרוֹתָם עַל הַשִּׁיר, מֵהֶם, מְשׁוֹרְרִים בַּיּוֹם, וּמֵהֶם מִשְׁמָרוֹת מְשׁוֹרְרִים בַּלַּיְלָה.</p>"],[9514013710,"<p>(קהלת י״ב:ה׳) גַּם מִגָּבֹהַּ יִירָאוּ, כִּי גָּבוֹהַּ מֵעַל גָּבוֹהַּ שׁוֹמֵר. וְשׁוֹמֵר זֶה מִזֶּה, וּמְקַבֵּל זֶה מִזֶּה, בִּנְעִימָה וּבִקְדוּשָּׁה. וּבְחֻרְבַּן בֵּית הַמִּקְדָּשׁ, יָצְתָה מְאֵרָה, וְדִין חָזָק מָצוּי לְפָנָיו. וְגָבוֹהַּ יִירָא מִגָּבוֹהַּ וּמִדִּינוֹ.</p>"],[9514013711,"<p>וְחַתְחַתִּים בַּדֶּרֶךְ, כְּתִיב (ישעיהו מ״ג:ט״ז) הַנּוֹתֵן בַּיָּם דֶּרֶךְ וּבְמַיִם עַזִּים נְתִיבָה. וּבְאוֹתוֹ דֶּרֶךְ, הָיָה יוֹרֵד וּבָא הַטַל מֵרֹאשׁוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל שִׂמְחָה, וְכָל טוּב, וְכָל רָצוֹן, בְּאוֹתוֹ הַדֶּרֶךְ הָיָה בָּא. וּבְחֻרְבַּן בֵּית הַמִּקְדָּשׁ, תְּבִירוּ עַל תְּבִירוּ בְּאוֹתוֹ הַדֶּרֶךְ נִמְצָא, וְכָל רוּגְזָא וְאֵימְתָנֵי וְתַקִּיפָא וְדִינָא, בְּהַהוּא דֶרֶךְ הֲווֹ.</p>"],[9514013712,"<p>וְיָנֵאץ הַשָּׁקֵד, כְּמָא דְאַתְּ אָמֵר, וַיִּשְׁקֹד ה' עַל הָרָעָה. וּכְתִיב (ירמיהו א׳:י״א) מַקֵּל שָׁקֵד אֲנִי רוֹאֶה. וּצְמִיחַת הַשָּׁקֵד אֶחָד וְעֶשְׂרִים יוֹם. כָּךְ מִי\"ז בְּתַמּוּז, עַד תִּשְׁעָה בְּאָב. וּמִיּוֹם שֶׁהַשָּׁקֵד מֵצִיץ, הַפֶּרַח אֵין מוֹצִיא פְּרִי, עַד כ\"א יוֹם.</p>"],[9514013713,"<p>וְיִסְתַּבֵּל הֶחָגָב, יוּתַּן הַסֵּבֶל עַל שִׁכְמוֹ שֶׁל בֵּית דָּוִד. וְתָפֵר הָאֲבִיּוֹנָה, זוֹ עֲבוֹדַת בֵּית הַמִּקְדָּשׁ לְמַטָה. וּצְוָוחִין בְּנֵי נָשָׁא, וְלָא מִתְעַנּוּן. מַאי טַעְמָא, כִּי הוֹלֵךְ הָאָדָם אֶל בֵּית עוֹלָמוֹ, מִסְתַּלֵּק הַכָּבוֹד לְמַעְלָה לְמַעְלָה, וְאִינוּן צְוָוחִין וְלֵית מַאן דְּיַשְׁגַּח בְּהוּ. בְּגִין דְּאִיהוּ אִסְתַּלַּק לְבֵית עוֹלָמוֹ דִּנְפַק מִינֵיהּ. וְעַל דָּא אִשְׁתַּכַּח מְאֵרָה, וּבִישׁ, וּמָוֶת, וּמְאוֹרָעוֹת רָעוֹת בָּעוֹלָם. וְסָפְדִין וּצְוָוחִין בְּכָל יוֹמָא. דִּכְתִיב, כִּי עָלָה מָוֶת בַּחֲלוֹנֵינוּ.</p>"],[9514013714,"<p>(קהלת י״ב:ו׳) עַד אֲשֶׁר לֹא יֵרָתֵק חֶבֶל הַכֶּסֶף, חוּט שֶׁל חֶסֶד שֶׁנִּמְשַׁךְ מִלְּמַעְלָה לְמַטָה. וְתָרֻץ גֻּלַּת הַזָּהָב, דְּאִיהִי נַחֲתָא בְּהַהוּא חוּט. נִשְׁבַּר הַחוּט, נָפַל הַגּוּלָה. וְתִשָּׁבֶר כַּד עַל הַמַּבּוּעַ, שֶׁהַתּוֹרָה נִשְׁתַּכְּחָה בְּגָלוּתָא, וְאוֹתוֹ הַמַּשְׁאֵב, יופיאָמַר לֵיהּ הַשַּׂר, לֹא שָׁאַב מִמַּעְיַן הַתּוֹרָה, וּבְנֵי אָדָם נְבוֹכִים בָּהּ.</p>"],[9514013715,"<p>וְנָרֹץ הַגַּלְגַּל אֶל הַבּוֹר, וּמַלְאָךְ הַמַּשְׁחִית נִיתַּן לוֹ רְשׁוּת לְחַבֵּל בְּכָל יוֹם. וְיָשֹׁב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה, וְיִכְלוּ כָּל הַנְּשָׁמוֹת, וְהָעוֹלָם יִכְלֶה, וְהֶעָפָר שֶׁהַכֹּל נִהְיָה מִמֶּנּוּ, יָשׁוּב כְּבַתְּחִלָּה, וְיִהְיֶה הָעוֹלָם חָרֵב כְּשֶׁהָיָה. וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ, וְיִתְחַדֵּשׁ הָעוֹלָם כְּבַתְּחִלָּה. וּבְאוֹתוֹ זְמַן כְּתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ. אֲתָא ר' עֲזַרְיָה וְרַבִּי מְרוֹנוֹס, וּנְשָׁקוּהוּ בְּרֵישֵׁיהּ. קָרָא עֲלֵיהּ, (משלי י״ח:ט״ו) לֵב נָבוֹן יִקְנֶה דָּעַת וְאֹזֶן חֲכָמִים תְּבַקֶּשׁ דָּעַת.</p>"],[9514013716,"<p>פָּתַח וְאָמַר (שיר השירים א׳:א׳) שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, זַכָּאָה דָרָא דִי חָכְמְתָא דִלְעֵילָא שַׁרְיָא בְּגַוֵּיהּ. בְּשַׁעֲתָא דְקוּדְשָׁא בְּרִיךְ הוּא הֲוֵי בָּעֵי לְגַלָּאָה בְּאַרְעָא, מַה דְּלָא אִתְגְּלֵי לְמַלְאֲכֵי עִילָּאֵי. וּמַאי אִיהוּ, רָזִין דְּחָכְמְתָא דִשְׁמָא גְלִיפָא עִילָּאָה. דִּשְׁמָהָן קַדִּישִׁין לָא אִתְמַסְּרוּ לוֹן, וְאִתְמַסְּרוּ לְחַכִּימִין בְּאַרְעָא. בְּהַהִיא שַׁעֲתָא, מְשַׁבְּחָן וְאָמְרִין, (תהילים ח׳:ב׳) ה' אֲדוֹנֵינוּ מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ אֲשֶׁר תְּנָה הוֹדְךָ עַל הַשָּׁמָיִם.</p>"],[9514013717,"<p>מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ, אִילֵּין רָזִין גְּלִיפִין דִּשְׁמָהָן קַדִּישִׁין, דְּאִתְגַּלְּיָין בְּאַרְעָא, וְתוּשְׁבַּחְתָּא דְהַאי, עַל הַשָּׁמָיִם. דְּכָל אִינוּן אוֹכְלוּסִין אוֹדָן וּמְשַׁבְּחָן עוֹבָדָא דָא, דְּאִתְגְּלֵי בְּאַרְעָא מַה דְּלָא אִתְגְּלֵי לוֹן.</p>"],[9514013718,"<p>הָא הָכָא רָזִין דִּרְתִיכָא קַדִּישָׁא עִילָּאָה, דְּאַרְבַּע שְׁמָהָן גְּלִיפָן, וְהָא אִיהוּ רָזָא דְרָזִין רְתִיכָא עִילָּאָה דִשְׁמָהָן: אדנ\"י. צְבָאוֹ\"ת. יהו\"ה. אהי\"ה. רָזָא דְּאַרְבָּע שְׁמָהָן גְּלִיפָן, דְּאַרְבַּע זְהוֹרִין. וְכָל זָהֲרָא וְזָהֲרָא אִתְכְּלֵיל חַד בְּחַבְרֵיהּ, וְתֵיאוּבְתָּא דְהַאי לְעָאֳלָא בְּהַאי, וּלְאִתְכְּלָלָא הַאי בְּהַאי.</p>"],[9514013719,"<p>וְאִלֵּין אַרְבַּע זְהוֹרִין, אִתְפָּרְשָׁן בִּשְׁמָהָן יְדִיעָן: חַד אִקְרֵי זוֹהַ\"ר חָשׁוּךְ וְלָא חָשׁוּךְ. בְּאִסְתַּכְּלוּתָא דִילֵיהּ, מִיָּד אָרֵים חָשׁוּךְ. מִסְתַּכְּלָאן בֵּיהּ יַתִּיר, נָצֵיץ וְלָהֵיט בִּנְהִירוּ, וְשַׁפִּירוּ עִילָּאָה. וּנְהוֹרֵיהּ קָמִיט בְּגַוֵּיהּ, עַד דְּבָטַשׁ בֵּיהּ נְהוֹרָא אָחֳרָא, דְּכָרֵי בְּהַאי נְהוֹרָא, וְאַנְקֵיב לָהּ, כְּדֵין אִתְמַלְיָא מֵהַהוּא זָהֳרָא, וְנָצֵיץ לְכָל סְטַר.</p>"],[9514013720,"<p>זָהֳרָא דָא, אִתְגְּלֵיף בְּשִׁבְעִין וּתְרֵין נְצִיצִין, דְּאִינוּן שִׁבְעִין וּתְרֵין שְׁמָהָן גְּלִיפָן, דְּשִׁבְעִין סַנְהֶדְּרִין וּתְרֵין סַהֲדִין. כְּדֵין הַאי זוֹהֲרָא כְּלִילָא בִּשְׁתֵּי שְׁמָהָן, וּמִתְעַטְרָא בִּשְׁמָא דָא אדנ\"י.</p>"],[9514013721,"<p>כְדֵין אִיהוּ שַׂר דְּכָל עָלְמִין, וְכָל חֵילִין וְכָל מַשִּׁרְיָין דְּעִלָּאִין וְתַתָּאִין, כָּלְהוֹ אָמְרֵי תּוּשְׁבַּחְתָּא דְּהַאי קְרָא דְקָא מְשַׁבְּחָן לֵיהּ, וְאָמְרִין תּוּשְׁבַּחְתָּא, וּמְשַׁבְּחִים לְעֵילָא. וְדָא זָהֲרָא כַּד אִשְׁתְּלֵים, אִיהוּ שי\"ר. אָדוֹן, שַׂר, רִבּוֹן. י שְׁלִימוּ [ח ס ר כ א ן] מִכּוֹלָא, שִׁי\"ר הַמַּעֲלוֹת, רִבּוֹן מְמַנָּא עַל כָּל חֵילִין וּמַשִּׁרְיָין דַּרְגִּין דִּלְתַתָּא.</p>"],[9514013722,"<p>זָהֳרָא תִּנְיָינָא, הוּא זוֹהַר דְּכָל עַיְינִין עִילָּאִין סְתִימִין, כָּנֵישׁ לְגַבֵּיהּ. וְהוּא זוֹהַר נָצֵיץ לְעַיְינִין, דְלָא יָכִילוּ לְאִסְתַּכָּלָא בֵּיהּ, וְהַאי אִיקְרֵי חַי. וּבְגִין דְּאִיהוּ חַי, נָטֵיל כָּל זְהִירִין עִלָּאִין סְתִימִין, וְזָרֵיק זְהִירִין נְצִיצִין לְתַתָּא, וַעֲבֵיד פֵּירִין וְאִיבִּין לִזְנֵיהּ.</p>"],[9514013723,"<p>וְדָא זוֹהַר חַי, אִיקְרֵי חַי הָעוֹלָמִים. וְדָא אִיהוּ כְּלָלָא דְּעִילָּאֵי וְתַתָּאֵי, וְעַל דַּאֲפֵיק זָהֳרִין נְצִיצִין, וַעֲבֵיד אִיבִּין לִזְנֵיהּ, אִיקְרֵי הַאי זוֹהַר צְבָאוֹ\"ת. וְדָא אִיהוּ דְּתֵיאוּבְתֵּיהּ תָּדִיר, לְשַׁבָּחָא תְּדִירָא, בְּהַאי זוֹהַר קַדְמָאָה דְּאִקְרֵי שִׁיר. וְכַד כְּלִילָן כַּחֲדָא בְּחִבּוּרָא חָדָא בְּלָא פֵּירוּדָא, גּוֹ תֵּיאוּבְתָּא שְׁלֵימָא, כְּדֵין אִיקְרֵי כֹּלָּא שִׁיר הַשִּׁירִים.</p>"],[9514013724,"<p>וַאֲפִילּוּ אִיהוּ בִּלְחוֹדוֹהִי, דְּאִיהוּ כְּלָלָא דְּכֹלָּא, אִיקְּרֵי כְּלָלָא דְסַגִּיאִין, כְּלָלָא דְּכָל זָהֳרִין עִילָּאִין וְתַתָּאִין. כָּל קָרִינָן לֵיהּ, כְּלָלָא דְכוֹלָּא. חַיִּי\"ם אִיהוּ. עֲלֵיהּ כְתִיב (בראשית ב׳:ט׳) וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן. כָּל חַיִּים בֵּיהּ תַּלְיָין. מִינֵיהּ פָּרְחִין חַיִּין וּזְהוֹרִין לְכָל סְטַר.</p>"],[9514013725,"<p>הַאי שִׁיר דְּקָאֲמָרָן, אִיקְּרֵי בְּאֵ\"ר, וְאִינוּן חַיִּים עִילָּאִין עָאלִין בְּגַוֵּיהּ. וְהַהוּא זָהֳרָא דְּאִקְרֵי חַיִּים, נָבְעִין בֵּיהּ. וְעַל דָּא כְּתִיב, בְּאֵר מַיִם חַיִּים. וּכְתִיב בְּאֵר חֲפָרוּהָ שָׂרִים. עַל שְׁמָא דְאִינוּן רַבְרְבִין עִילָּאִין, זָהֳרִין טְמִירִין, דְּאִתְכַּנְשׁוּ בְּהַאי זָהֳרָא. וְאִינוּן לָא חֲפָרוּהָ, אֶלָּא עַל יְדָא דְדָא.</p>"],[9514013726,"<p>זָהֳרִבִּי אֶלְעָזָר תְּלִיתָאָה, הַאי אִיהוּ זָהֳרָא כְּלָלָא דִּתְלַת זָהֳרִין, רָזָא דִתְלַת אַתְוָון. בְּהַאי זָהֳרָא אֲבָהָן אִתְדַּבָּקוּ.</p>"],[9514013727,"<p>הַאי אִיהוּ רָצוֹא וָשׁוֹב, לֵית מַאן דְּיָכִיל לְאִתְיַשְּׁבָא בִּנְצִיצוּ דִילֵיהּ. עַל הַאי כְּתִיב, (יחזקאל א׳:י״ד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב. דָּא יָרֵית אַחְסַנְתָּא יְרוּתָא דְּזָהֳרִין טְמִירִין, דְּלָא אִתְגַּלְּיָין. וְרָזָא דִשְׁמָא קַדִּישָׁא דִּתְלַת אַתְוָון תַּלְיָין בְּהוּ, יה\"ו. מִכָּאן, אָת ה' רְבִיעָאָה לָקֵיט וְנָקֵיט. וְהָכֵי אִתְסַדַּר בְּסִידוּרָא שְׁלִים.</p>"],[9514013728,"<p>דָּא זִיהֲרִבִּי אֶלְעָזָר אִיהוּ רָצוֹא וָשׁוֹב, בְּרָזָא דְאָת ו', וְאִיהוּ קָאִים בְּאֶמְצָעִיתָא, בֵּין עֵילָא וְתַתָּא. אָת ה' מִסִּטְרָא דָא לְעֵילָא. וְאָת ה' מִסִּטְרָא דָא לְתַתָּא. וְהַחַיּוֹת דְּאִינוּן ו' בְּאֶמְצָעִיתָא. וְעַל דָּא רָצוֹא וָשׁוֹב, רָצוֹא לְגַבֵּי ה' עִילָּאָה, לְאִסְתַּלָּקָא לְגַבָּהּ בְּתֵאוֹבְתָּא שְׁלִים. וְשׁוּב לְגַבֵּי ה' תַּתָּאָה, לְמֵיהַב לָהּ, כְּמָא דְּלָקֵיט מִלְּעֵילָא.</p>"],[9514013729,"<p>זָהֳרָא דָא אִיהוּ כְּגַלְגַּלָּא דְעֵינָא, בְּאוֹרַח סָתִים, דְּזָהֳרָא דִילֵיהּ רָצוֹא וָשׁוֹב, תֵּיאוֹבְתֵּיהּ לְאִסְתַּלָּקָא לְעֵילָא, וּמִיָּד אַהֲדַר. וְרָזָא דָא אֲשֶׁר, קָאִים הָכָא וְהָכָא.</p>"],[9514013730,"<p>זָהֳרִבִּי אֶלְעָזָר רְבִיעָאָה אהי\"ה. הַאי אִיהוּ זָהֳרָא סָתִים, דְּלָא אִתְחֲזֵי כְּלָל. דְּהָא מֵהַאי זָהֳרָא סְתִימָא נָפְקוֹ שְׁאָר זְהִירִין, וְאִתְפַּשְׁטָן וְאִתְכְּלִילָן חַד בְּחַבְרֵיהּ. הַאי זָהֳרָא לָא אִתְגְּלֵי כְּלַל, אֲבָל קָאִים בְּסוּכְלְתָנוּ דְּלִבָּא. דְּלִבָּא יְדַע וְאִסְתַּכַּל בֵּיהּ, אַף עַל גַּב דְּלָא אִתְחֲזֵי כְּלָל.</p>"],[9514013731,"<p>וְהָא, בְּגִין דְּכָל אִינוּן זָהֳרִין, נָפְקָא מִנֵּיהּ תֵּיאוֹבְתָּא דְזָהֳרָא תַּתָּאָה, לְשַׁבָּחָא שִׁבְחָא, לְאִסְתַּכָּלָא בְּגוֹ אִינוּן זְהִירִין, לְאִתְכְּלָלָא בְּגַוַּיְיהוּ, לְאִסְתַּלָּקָא לְמֶחֱמֵי בְּהַהוּא נוֹעַם עִילָּאָה. וְעַל דָּא אֲמַר דָּוִד מַלְכָּא, אַחַת שָׁאַלְתִּי מֵאֵת ה' אוֹתָהּ אֲבַקֵּשׁ שִׁבְתִּי בְּבֵית ה' כָּל יְמֵי חַיַּי לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. וְרָזָא דָא לִשְׁלֹמֹה, לְמַלְכָּא דִּשְׁלָמָא כֹּלָּא דִילֵיהּ.</p>"],[9514013732,"<p>כְתִּיב (זכריה ד׳:ב׳) רָאִיתִי וְהִנֵּה מְנוֹרַת זָהָב כֻּלָּהּ וְגֻלָּהּ עַל רֹאשָׁהּ וְשִׁבְעָה נֵרֹתֶיהָ עָלֶיהָ שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת לַנֵּרוֹת אֲשֶׁר עַל רֹאשָׁהּ. זְכַרְיָה אִתְגְּלֵי לֵיהּ רָזָא דִּמְנַרְתֵּי דַכְיָין. חַד מִתְסַדְּרָא. וְחַד דְּנָהֳרָא.</p>"],[9514013733,"<p>רָאִיתִי וְהִנֵּה מְנוֹרַת, דָּא מְנַרְתָּא מִתְסַדְּרָא בְּשִׁבְחֵי דִגְוָונִין גְּלִיפָאן, בִּשְׁמָא אדנ\"י. בִּשְׁמָא דָא מְנַהֲרָא לְתַתָּאי, וְזָן וּמְפַרְנֵס לוֹן כִּדְקָא יָאוֹת.</p>"],[9514013734,"<p>זָהָב, רָזָא דְבֵי דִינָא בִּשְׁמָא אֱלֹהִי\"ם, לְמֵידַן כָּל עָלְמָא, דְּהָא בְדִינָא קָאי, וְעַל שְׁמָא דָא אִתְבְּרֵי. וְכֹלָּא בְּרָזָא דִשְׂמָאלָא.</p>"],[9514013735,"<p>כוּלָּהּ, כַּד אִשְׁתְּלֵים בְּסִטְרָא דְיָמִינָא, דְאַתְקֵיף בָּהּ בְּרָזָא דִשְׁמָא ידו\"ד, דְּהָא כְדֵין אִיהִי כַּלָּה בַּחוּפָּה, דְּעָלְמִין כּוּלְהוּ בִּרְחִימוּ בְּחִבּוּרָא חָדָא. דְּהָא כְדֵין וְגֻלָּהּ עַל רֹאשָׁהּ. כְּתִיב גֻּלָּהּ, דָּא אִיהוּ מְקוֹרָא דְצַדִּיק, דְּאִתְעֲבֵיד, נָהָר פְּלָגָיו דְּחָדָאן עִיר אֱלֹהִים, וַעֲבֵיד פֵּירִין וְאִיבִּין, בִּשְׁמָא דְאִתְקְרֵי צְבָאוֹ\"ת. מִתְתַּחֲמָא בִּתְרֵיסַר תְּחוּמִין, לְאַרְבַּע סִטְרֵי עָלְמָא.</p>"],[9514013736,"<p>וְשִׁבְעָה נֵרוֹתֶיהָ עָלֶיהָ, דָּא רָזָא דִשְׁמָא עִילָּאָה גְלִיפָא, בְּרָזָא דְּשִׁבְעִין שְׁמָהָן, דְּאִתְקְרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. וְאִינוּן שִׁבְעָה קַיָּימִין, דְּעַלְמָא קָאִים עֲלַיְיהוּ.</p>"],[9514013737,"<p>שִׁבְעָה וְשִׁבְעָה, אִלֵּין תַּתָּאֵי, דְּקָיְימִין לְקִבְלֵיהוֹן דְּעִלָּאֵי, וְכָלְהוֹ אָחֵיד לַנֵּרוֹת אֲשֶׁר עַל רֹאשָׁה. שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת, אִלֵּין שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים, אִלֵּין עִילָּאֵי וְאִלֵּין תַּתָּאֵי. דְּמִתְחַבְּרָאן כַּחֲדָא.</p>"],[9514013738,"<p>תּוּ. שִׁבְעָה וְשִׁבְעָה כּוּלְהוּ לְעֵילָא, בְּגִין דְּכָלֵיל כָּל חַד בְּחַבְרֵיהּ. וְאִי תֵימָא, שִׁיתָּא, אִיהוּ שַׁפִּיר דְּכָלֵיל חַד בְּחַבְרֵיהּ, חַד דְּאִשְׁתָּאַר בְּמַאן אִתְכְּלֵיל.</p>"],[9514013739,"<p>אֶלָּא כַּד סָלְקִין כָּלְהוֹ לִתְרֵיסַר, הַהוּא דְּקָאִים עֲלַיְיהוּ, דְּאַשְׁלֵים תְּלֵיסַר, אִתְכְּלֵיל בְּחַד דְּקָיְימָא עֲלֵיהּ, דְּאִיהוּ דַרְגָּא דְּכָלְהוֹ כְּלִילָן בֵּיהּ, וְדָא אִיהוּ נְקוּדָה עִילָּאָה, דְּכָלְהוֹ נָפְקוֹ מִינֵּיהּ.</p>"],[9514013740,"<p>תּוּ. תְּרֵין דַּרְגִּין אִינוּן, וְכָל חַד אִיקְרֵי שִׁבְעָה. חַד אִיהוּ עַלְמָא דְּאָתֵי, דְּאִיהוּ שִׁבְעָה, וְאִקְּרֵי שִׁבְעָה, דִּכְתִיב וַיִּבְנֵהוּ שֶׁבַע שָׁנִים. וְחַד אִיהוּ צַדִּיק, דְּאִקְּרֵי שִׁבְעָה, וְאִיהוּ שֶׁבַע דִּכְתִיב (משלי כ״ד:ט״ז) כִּי שֶׁבַע יִפּוֹל צַדִּיק וָקָם.</p>"],[9514013741,"<p>וְאִלֵּין תְּרֵין כְּתָרִין, מוּצָקוֹת לַנֵּרוֹת. חַד מִסִּטְרָא דָא, וְחַד מִסִּטְרָא דָא. וְאַף עַל גַּב דְּאִינוּן בְּמִנְיָינָא דְּאִינוּן נֵרוֹת, וְעִם כָּל דָּא, שִׁבְחָא מֵאִלֵּין, תְּרֵין, דְּאִינוּן שִׁבְעָה וְשִׁבְעָה, דְּמוּצָקוֹת לְגַבַּיְיהוּ. דְּאִינוּן נֵרוֹת דְּקָא נָהֲרִין עַל רֵישָׁא דְּהַהוּא מְנוֹרָה, וְהַהוּא מְנוֹרָא קָא מְנַהֲרָא מֵחֵילָא דִילְהוֹן, לְסַלְקָא לְגַבֵּיהּ עֵילָא. וְכַד סָלְקָא, סָלְקָא מִדַּרְגָּא לְדַרְגָּא, וּמִכִּתְרָא לְכִתְרָא, עַד דְּאִתְאַחֲדָא כֹּלָּא לְעֵילָא, וְרָזָא דָא, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה.</p>"],[9514013742,"<p>שִׁיר הַשִּׁירִים, עַל פּוּמָא דְאֵלִיָּהוּ אִתְגְּזַר, בִּרְשׁוּ עִילָּאָה. שִׁיר הַשִּׁירִים, שִׁבְחָא דְּשִׁבְחִין, לְמַלְכָּא דִּשְׁלָמָא דִילֵיהּ. בְּגִין דְּאִיהוּ אֲתַר דְּבָעֵי חֶדְוָה, דְּלָא אִית תַּמָּן רוּגְזָא וְדִינָא. דְּהָא עַלְמָא דְאָתֵי, כּוֹלָּא אִיהוּ חֶדְוָה, וְאִיהוּ חָדֵי לְכוֹלָּא. וּבְגִין כָּךְ מְשַׁדַּר חֵדוּ וְחֶדְוָה לְכָל דַּרְגִּין.</p>"],[9514013743,"<p>כְמָא דְאִצְטְרִיךְ אִתְעָרוֹ דְחֶדְוָה לְאִתְעָרָא מֵהַאי עַלְמָא לְעֵילָא. הָכֵי אִצְטְרִיךְ לְאִתְעָרָא חֶדְוָה וְחֵידוּ, מֵעַלְמָא דְסִיהֲרָא, לְגַבֵּי עַלְמָא עִילָּאָה. וּבְגִין כָּךְ עָלְמִין קָיְימִין בְּדוּגְמָא חָדָא, וְאִתְעָרוֹ לָא סַלְקָא אֶלָּא מִתַּתָּא לְעֵילָא.</p>"],[9514013744,"<p>שִׁיר תתר\"ו סִימָן, בְּאַתְוָון גְּלִיפָאן דִּשְׁמָא קַדִּישָׁא, זָעוֹ וְרֶתֶ\"ת דְּכָל עָלְמִין, וְכָל נוּקְבִין דִּתְהוֹמָא רַבָּא, עַד דְּהַאי פְּשִׁיטוּ דְרוּחָא, עָאל לְגַבֵּי תַּרְעָא קַדְמָאָה דְלִסְטַר מִזְרָח. הַהוּא מָארֵי דְעַיְינִין, בְּת\"ק מַפְתֵּחָאן דְּהֵיכָלִין, וְהָא אִיהוּ בִּגְלִיפוּ דִּשְׁמָא קַדִּישָׁא, דִּתְרֵיסַר אַתְוָון, דְּטָאסִין בֵּיהּ תְּשַׁע סְרֵי מַשִּׁרְיָין מְלַהֲטָן דְּנוּרָא.</p>"],[9514013745,"<p>וְהַהוּא מָארֵי דְעַיְינִין, לָקֵיט גּוּמְרִין דְּאֶשָׁא, שַׁיְיפֵי דְנוּרָא, וְעָאלִין גּוֹ הַהוּא הֵיכָלָא דְּאִתְקְרֵי זְבוּל, הֵיכָל דְּתַמָּן כָּל שְׁבָחִין אִתְסַדְּרָן לְסַלְקָא לְעֵילָא. וְעַל דָּא כְּתִיב (מלכים א ח׳:י״ג) בָּנֹה בָּנִיתִי בֵּית זְבוּל לָךְ. וְאִיהוּ הֵיכָלָא, דְּאִית בָּהּ תתר\"ו דַּרְגִּין, דְּסָלְקָן בְּשִׁבְחֵי דְּתוּשְׁבַּחְתָּא, וּבְגוֹ כּוּלְהוּ אִית חַד דַּרְגָּא פְּנִימָאָה מִכּוּלְהוּ, דְּתַמָּן אִתְבְּרֵיר רְחִימוּ דְהַאי תּוּשְׁבַּחְתָּא, בְּרִירוּ דִנְקוּדָא תַּתָּאָה. וְכַד אִתְבְּרֵיר מִגּוֹ כּוּלְהוּ, סָלְקָא לְעֵילָא בְּרָזָא דְּשִׁיר, וְאִיקְּרֵי שִׁיר הַשִּׁירִים, וְסָלְקָא מִכָּל אִינוּן שִׁבְחִין, וְאִתְבְּרֵיר מִכּוּלְהוּ.</p>"],[9514013746,"<p>כְתִיב (מלכים א ו׳:ו׳-ז׳) וְהַבַּיִת בְּהִבָּנֹתוֹ אֶבֶן שְׁלֵמָה וְגו', וְהַבַּיִת בְּהִבָּנוֹתוֹ, כַּד הֲווֹ דְּכַר וְנוּקְבָא כַּחֲדָא מִתְחַבְּרָא, כְּדֵין אֶבֶן שְׁלֵימָה, אִשְׁתְּלֵימַת כְּמָה דְאִצְטְרִיךְ. וְלָא אִשְׁתְּלֵימַת, עַד דַּהֲוַת מַסָּע, דְּנָסַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַתְקֵין לָהּ, וְקַשֵּׁיט לָהּ, וְאַיְיתֵי לָהּ לְגַבֵּי דְאָדָם, וּכְדֵין נִבְנָה, וְאִשְׁתְּלֵימַת מִכּוֹלָּא.</p>"],[9514013747,"<p>וְכַד אִתְחַבָּרוּ דָּא עִם דָּא, כָּל רוּחִין אוֹחֲרָנִין, וְכָל זִינִין בִּישִׁין, אִתְעֲבָרוֹ מִתַּמָּן, וְלָא אִתְקְרִיבוּ לְמַקְדְּשָׁא. הֲדָא הוּא דִכְתִיב, (שם) וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל לֹא נִשְׁמַע בַּבַּיִת בְּהִבָּנֹתוֹ. דְּהָא כּוּלְהוּ עָאלוּ גּוֹ נוּקְבָא דִתְהוֹמָא רַבָּא. כֵּיוָן דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא לְתַתָּא, וְאִתְתַּקַּן הֵיכָלָא עַל בּוּרְיֵיהּ, כְּדֵין אִתְגְּלֵי שִׁיר הַשִּׁירִים, דְּאִצְטְרִיךְ לְאִתְחַבָּרָא מַקְדְּשָׁא בְּמַקְדְּשָׁא.</p>"],[9514013748,"<p>כַד הֲוָה משֶׁה בְּמַדְבְּרָא, בְּגִין חוֹבֵיהוֹן דְּיִשְׂרָאֵל, זִוּוּגָא דְמשֶׁה הֲוַת מִתְחַבְּרָא בֵּיהּ, בַּאֲחוֹרָא הֲווֹ דְּכַר וְנוּקְבָא מִתְחַבְּרָאן כַּחֲדָא. כְּדֵין, וְהַבַּיִת בְּהִבָּנוֹתוֹ, זְעֵיר זְעֵיר.</p>"],[9514013749,"<p>כַד עֲבָרוּ יִשְׂרָאֵל יַת יַרְדְּנָא, וּמשֶׁה אִתְכְּנֵישׁ, נְסַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַתְקֵין לָהּ בְּמִשְׁכַּן שִׁילֹה, עַד דְּאִשְׁתְּלֵימַת בְּבֵי עָלְמִין, וְאִתְחַבָּרַת בַּמֶּלֶךְ שְׁלֹמֹה, וַהֲווּ עָלְמִין אַפִּין בְּאַפִּין. כְּדֵין, אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה. מַסָּע: דְּלָא הֲוַת בַּאֲתַר חָד קְבִיעַ, אֶלָּא אִתְעַקַּר וְאִשְׁתֵּיל, וּכְדֵין נִבְנָה כִּדְקָא יָאוֹת.</p>"],[9514013750,"<p>וְכָל זַיְינִין בִּישִׁין, וְכָל רוּחִין בִּישִׁין, כְּדֵין אִתְעֲבָרוֹ מֵעַלְמָא, וְלָא שַׁלִּיטוּ כְּלָל, הֲדָא הוּא דִכְתִיב, (מלכים א ו׳:ז׳) וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַרְזֶל לֹא נִשְׁמַע בַּבַּיִת בְּהִבָּנֹתוֹ.</p>"],[9514013751,"<p>בְּהַהִיא שַׁעֲתָא, כַּד אִתְעֲבָרוֹ כּוֹלָּא מֵעָלְמָא, וְאִשְׁתְּאָרַת אִתְּתָא בְּבַעֲלָהּ אַפִּין בְּאַפִּין, כְּדֵין אִתְגְּלֵי שִׁיר הַשִּׁירִים. וְדָא אִיהוּ שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, בְּלָא עִרְבּוּבְיָא כְּלָל. אֲשֶׁר לִשְׁלֹמֹה, אַפִּין בְּאַפִּין. אֲשֶׁר לִשְׁלֹמֹה, דְּאִתְעַקַּר וְאִשְׁתֵּיל בַּאֲתַר דִּשְׁלָמָא כּוֹלָּא דִילֵיהּ.</p>"],[9514013752,"<p>חֲדֵי ר' שִׁמְעוֹן. אֲמַר לֵיהּ אֵלִיָּהוּ, רַבִּי אֵימָא מִילָךְ, וַאֲנָא אֲבַתְרָךְ, דְּהָא מִינִי וּמִינָךְ תִּסְתַּיֵּים מִלְּתָא. וּרְשׁוּ אִתְיְהֵיב לָן מֵעִם עַתִּיקָא דְכוֹלָּא, דְּיִתְגַּלּוּ רָזִין אִלֵּין מִתַּתָּא וּמֵעֵילָא. אַנְתְּ לָקֳבֵיל תַּתָּאֵי. וַאֲנָא לָקֳבֵיל עִילָּאֵי.</p>"],[9514013753,"<p>וּבְחַיָּיךָ רַבִּי, רְבוּ יַתּיר אִית לָךְ, דְּכָל מִילָךְ יִכָּתְבוּן לְעֵילָא קַמֵּי עַתִּיק יוֹמִין, וּמִילַיי לָא יִכָּתְבוּן לְעֵילָא, אֶלָּא בְּהַאי עָלְמָא יִכָּתְבוּן מִילַיי, עַל יְדָךְ. מִילָךְ יְהוֹן כְּתִיבִין לְעֵילָא, וּמִילַיי כְּתִיבִין לְתַתָּא. זַכָּאִין אַתּוּן צַדִּיקַיָּיא בְּהַאי עָלְמָא, וְזַכָּאִין אַתּוּן בְּעַלְמָא דְאָתֵי.</p>"],[9514013754,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה. כְּתִיב (תהילים קכ״ו:ו׳) הָלוֹךְ יֵלֵךְ וּבָכֹה נֹשֵׂא מֶשֶׁךְ הַזָּרַע וְגו'. בְּכַמָּה זִמְנִין הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹכַח לוֹן לְיִשְׂרָאֵל, לְאַהֲדָרָא לוֹן בִּתְיוּבְתָּא לְגַבֵּיהּ, לְמֵהַךְ בְּאוֹרַח מֵישַׁר, בְּגִין לְאִסַלְּקָא בְּגַוַּוְיהוּ. דְּהָא כַּד יִשְׂרָאֵל זַכָּאִין, וְאָזְלִין בְּאוֹרַח מֵישַׁר, כִּבְיָכוֹל, סִילוּקָא אִיהוּ לְקוּדְשָׁא בְּרִיךְ הוּא עִמָּהוֹן, בְּכָל עַמִּין דְּעָלְמָא. כַּד יִשְׂרָאֵל זַכָּאִין, וְאָזְלִין בְּאוֹרַח מִישׁוֹר, סָלֵיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא עַל כָּל בְּנֵי עָלְמָא, וְכוּלְהוּ אוֹדָן וּמְשַׁבְּחָן לֵיהּ, וְלָאו אִינוּן בִּלְחוּדַיְיהוּ, אֶלָּא אֲפִילּוּ עִילָּאִין לְעֵילָא, כּוּלְהוּ אוֹדָן לֵיהּ בְּגִינַיְיהוּ דְיִשְׂרָאֵל. וְלָא דָא בִּלְחוֹדוֹי, אֶלָּא אִיהוּ אִסְתַּלֵּק בִּיקָרֵיהּ, בְּגִינַיְיהוּ דְיִשְׂרָאֵל מַמָּשׁ. וְלָא דָא בִּלְחוֹדוֹי, אֶלָּא אֲפִילּוּ יִשְׂרָאֵל מַמָּשׁ, מִסְתַּלְּקֵי בִּיקָרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא וְתַתָּא.</p>"],[9514013755,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְיִשְׂרָאֵל זַכָּאִין, כּוּרְסָא יְקָרָא דִלְעֵילָא אִסְתְּלֵיק לְעֵילָא לְעֵילָא, בְּכַמָּה חֶדְוָון, בְּכַמָּה רְחִימוּ, וּמִתְחַבְּרָן עָלְמִין בְּחֶדְוָוא, וְכוּלְהוּ אִתְבָּרְכָן מֵעֲמִיקָא דְנַחֲלִין, וְעַלְמִין כּוּלְהוּ אִשְׁתַּקְיָין, וְאִתְבָּרְכָאן וְאִתְקַדְּשָׁאן בְּכַמָּה בִּרְכָאן, בְּכַמָּה קִדּוּשִׁין, וְקוּדְשָׁא בְּרִיךְ הוּא חָדֵי עִמְּהוֹן, בְּחֶדְוָא בִּשְׁלִימוּ.</p>"],[9514013756,"<p>וּבְשַׁעֲתָא דְיִשְׂרָאֵל לָאו אִינוּן זַכָּאִין, כּוֹלָא אִיהוּ בְּהִפּוּכָא. וְעִם כָּל דָּא רְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא לָא אִתְמְנַע מִנַּיְיהוּ, וְכוּרְסְיָיא דִילֵיהּ יָתְבָא עֲלַיְיהוּ, כְּאִמָּא עַל בְּנִין, וְלָא אִתְמְנָעַת מִלְּמִתְבַּע עֲלַיְיהוּ רַחֲמֵי.</p>"],[9514013757,"<p>וּבְהַאי קָלָא סָלְקָא לְעֵילָא, בְּגִין דִּרְעוּתָא דִילֵיהּ מַאן דְּאוֹלִיף סַנֵּיגוֹרְיָא עַל בְּנוֹי. מְנָא לָן, מִמּשֶׁה, דְּאִסְתַּלַּק בִּסְלִיקוּ עַל דְּאוֹלִיף זְכוּ עֲלַייהוּ דְיִשְׂרָאֵל. הֲדָא הוּא דִכְתִיב, (שמות ל״ד:כ״ט) וּמשֶׁה לֹא יָדַע כִּי קָרַן עוֹר פָּנָיו. אֵימָתַי אִסְתְּלֵיק לִיקָרָא דָא. כַּד חָאבוּ יִשְׂרָאֵל, וְאוֹלִיף עֲלַיְיהוּ זְכוּ.</p>"],[9514013758,"<p>כְגַוְונָא דָא כְּתִיב, הָלוֹךְ יֵלֵךְ וּבָכֹה, עַל חוֹבֵיהוֹן דְּיִשְׂרָאֵל. מַאי נוֹשֵׂא מֶשֶׁךְ הַזָּרַע. דָּא רָזָא דְּכוּרְסְיָיא דִּיְקָרָא, דְּאִיהוּ נָטֵיל מְשִׁיכוּ דְּזֶרַע קוּדְשָׁא עִילָּאָה, לְמֶיעְבַּד פֵּירִין וְאִיבִּין בְּהַאי עָלְמָא.</p>"],[9514013759,"<p>וְכַד אִסְתַּלִּיקַת בְּקָלָא דְיִשְׂרָאֵל, אַף עַל גַּב דְּלָאו אִינוּן זַכָּאִין, עִם כָּל דָּא, קוּדְשָׁא בְּרִיךְ הוּא אַעֲלֵי לָהּ, וְאַשְׁקֵי לָהּ, מִשַּׁקְיוּ דְּנַחֲלָא עֲמִיקָא, וְאִשְׁתְּלֵים מִכָּל סִטְרִין. כְּדֵין, בֹּא יָבֹא בְּרִנָּה, מִגּוֹ דְּהַהוּא שְׁלִימוּ וּבִרְכָאן וְקִדּוּשִׁין דְּאִשְׁתְּלֵימַת. בְּקַדְמִיתָא, הָלוֹךְ יֵלֵךְ וּבָכֹה, עַל חוֹבֵייהוֹן דְּיִשְׂרָאֵל. כַּד תָּבוּ, בֹּא יָבֹא בְּרִנָּה.</p>"],[9514013760,"<p>בְּשַׁעֲתָא דְּבָנָה שְׁלֹמֹה בֵּי מַקְדְּשָׁא, וְאִשְׁתְּלֵים עַלְמָא תַּתָּאָה כְּגַוְּונָא דְּעַלְמָא עִילָּאָה, יִשְׂרָאֵל כּוּלְהוֹן הֲווֹ זַכָּאִין, וְאִסְתַּלָּקוֹ בְּכַמָּה דַרְגִּין עִילָּאִין, וּכְדֵין אִסְתְּלַק כּוּרְסְיָיא דִּיְקָרָא בְּחֶדְוָה, בְּכַמָּה חֶדְוָון, בְּכַמָּה עִילוּיִין.</p>"],[9514013761,"<p>וּכְדֵין שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, סְלִיקוּ בְּחֶדְוָוא, וּנְחִיתוּ בְּחֶדְוָוא. עָלְמִין כּוּלְהוּ בְּחֶדְוָא. וְחִיבּוּרָא בְּחֶדְוָה. שִׁיר, לְקוּדְשָׁא בְּרִיךְ הוּא. הַשִּׁירִים, לְעִילָּאִין וְתַתָּאִין. אֲשֶׁר לִשְׁלֹמֹה, חִבּוּרָא דְּעָלְמִין כּוּלְהוּ בְּחֶדְוָא, לְמַלְכָּא דִשְׁלָמָא כֹּלָּא דִילֵיהּ. עַל פּוּמָא דְּאֵלִיָּהוּ אִתְגְּזַר.</p>"],[9514013762,"<p>שִׁיר הַשִּׁירִים, כְּתִיב (דברים כ״ח:י״ב) יִפְתַּח ה' לְךָ אֶת אוֹצָרוֹ הַטוֹב וְגו'. בְּשַׁעֲתָא דִּבְרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, בְּרָא בְּקַדְמִיתָא, שִׁיתִּין עִילָּאִין, דְּאִינוּן מְקוֹרֵי, לְנַחֲתָא בְּהוֹן גִּשְׁמַיָא דְּבִרְכָן, וְקִדּוּשִׁין עִילָּאִין דִּלְעֵילָא. וְאִינוּן נְטָלוֹ בְּקַדְמִיתָא מִמְּקוֹרָא דְחַיֵּי, מֵאֲתַר עִילָּאָה דִּנְפָקוֹ מִתַּמָּן.</p>"],[9514013763,"<p>הְהָא בְּקַדְמִיתָא עַד לָא אִיתְבְּרֵי עָלְמָא, סָלֵיק וְאִתְגְּלֵי חַד רְעוּתָא, דְּאִיקְרֵי מַחֲשָׁבָה סְתִימָא, וְשַׁוֵּי כּוֹלָּא בְּהַהִיא מַחֲשָׁבָה סְתִימָא, וְכָל מַאי דְּהֲוָה וִיהֱוֵי. וּמֵהַהוּא מַחֲשָׁבָה סָלֵיק רְעוּתָא לְמִבְרֵי עָלְמָא, וּנְפַק נְבִיעוּ דַּקִּיק, כָּלֵיל סְתִימוּ דְּמַחֲשָׁבָה, וְדָא לָא אִשְׁתְּמַע לְבַר, וְלָא אִתְגַּלְּיָא. וְאִית בֵּיהּ אִסְתַּכְּלוּתָא דְּחָכְמְתָא, לְחַכִּימֵי לִבָּא אִתְמְסַר, בְּגִין דְּלָא אִתְגַּלְּיָא לְבַר.</p>"],[9514013764,"<p>מֵהַאי נָפְקֵי חָמֵשׁ מְקוֹרִין, וְחַד סְתִימָא, וְחַד דְּכָנֵישׁ כּוֹלָּא. וְאִינוּן מְקוֹרִין הֲווֹ, כַּד אִתְבְּרֵי עָלְמָא. כְּמָה דְאַתְּ אָמֵר (בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים. בְּרֵאשִׁית: בָּרִבִּי אֶלְעָזָר שִׁי\"ת. דָּא שִׁית, מְקוֹרָא דְּכָנֵישׁ כָּל מְקוֹרִין, לְמֵיזַן עָלְמִין.</p>"],[9514013765,"<p>אֶת הַשָּׁמַיִם, אִלֵּין אִינוּן ו' מְקוֹרִין עִילָּאִין דִּלְעֵילָא, לְמֵיהַב לְהַאי שִׁית. מִיּוֹמָא דְאִתְבְּרֵי עָלְמָא, עַד דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא, הֲווֹ סְתִימִין, וָלֹא אִתְפַּתְּחוּ כְּלָל.</p>"],[9514013766,"<p>וְאִיתֵימָא אַבְרָהָם הֲוָה בְּעָלְמָא. הָא כְתִיב (שם יב) וַיְהִי רָעָב בָּאָרֶץ. יִצְחָק, וַיְהִי רָעָב בָּאָרֶץ מִלְּבַד הָרָעָב וְגו'. וְיַעֲקֹב, הָא כְתִיב (שם מא) וַיְהִי רָעָב בְּכָל הָאֲרָצוֹת. משֶׁה, הָא בְּכַמָּה דוּכְתִּין כְּתִיב (במדבר יא) מִי יַאֲכִילֵנוּ. פ (שמות טז) לְהָמִית אֶת כָּל הַקָּהָל הַזֶּה בָּרָעָב. צ (שם יז) וַיִּצְמָא שָׁם הָעָם לַמָּיִם. (במדבר כ) וְלֹא הָיָה מַיִם לָעֵדָה.</p>"],[9514013767,"<p>יְהוֹשֻׁעַ, אַף עַל גַּב דְּעָאלוּ לְאַרְעָא, כְּתִיב (יהושע ה) וַיִּשְׁבֹּת הַמָּן מִמָּחֳרָת בְּאָכְלָם מֵעֲבוּר הָאָרֶץ. בִּימֵי שׁוֹפְטִים כְּתִיב, (רות א) וַיְהִי בִּימֵי שְׁפֹט הַשֹׁפְטִים וַיְהִי רָעָב בָּאָרֶץ. בְּדָוִד כְּתִיב (שמואל ב כא) וַיְהִי רָעָב בִּימֵי דָוִד.</p>"],[9514013768,"<p>מַאי טַעְמָא כָּל דָּא. בְּגִין דְּאִינוּן שִׁיתִּין לָא אִתְפַּתְּחוּ, וְעַלְמָא אִתְּזַן מִתַּמְצִיתָא דָּחֵיק, בְּלָא פְּתִיחָא כְּלַל, אֶלָּא כְּזִיעַ דְּזִיעַ מִגּוֹ אִילָנָא, וְנָחֵית לְתַתָּא, אוֹ מִגּוֹ אַבְנָא.</p>"],[9514013769,"<p>בְּשַׁעֲתָא דַּאֲתָא שְׁלֹמֹה מַלְכָּא, וְאִתְבְּנֵי בֵּי מַקְדְּשָׁא, וַהֲווּ עַלְמִין כּוּלְהוּ בְּשִׁיקּוּלָא חָדָא עֵילָא וְתַתָּא. כְּדֵין, הַהוּא שִׁית דִּמְקַבֵּל וְכָנֵישׁ לְכָל אִינוּן שִׁיתִּין עִילָּאִין, אִתְפַּתַּח.</p>"],[9514013770,"<p>אֵימָתַי אִתְפַּתַּח, בְּשַׁעֲתָא דְּאִינוּן שִׁיתִּין עִילָּאִין אִתְפַּתְּחוּ. כֵּיוָן דְּאִתְפַּתַּח הַאי שִׁית, נְפָקוֹ בִּרְכָאן לְעָלְמָא. אֵימָתַי אִתְפַּתַּח, כַּד אַעֲדִיאוּ מִנֵּיהּ, חַד עֲקִימָא דִּיתֵיב לְרַגְלֵיהּ. וְכֵיוָן דְּהַהוּא אִתְעֲבַר, שִׁית אִתְעֲבֵיד שִׁיר, וְאִתְפַּתַּח אוֹצָר הַטוֹב. בְּחֵילָא דְמַאן, אֶת הַשָּׁמַיִם, אִינוּן שְׁאָר שִׁיתִּין, וְהַיְינוּ הַשִּׁירִים, דְּכוּלְהוּ אִתְפַּתְּחוּ, וְאַתְקִינוּ לְמֵיהַב מְזוֹנָא לְכָל עָלְמִין.</p>"],[9514013771,"<p>כְדֵין כְּתִיב (מלכים א ה) וַיֵּשֶׁב יְהוּדָה וְיִשְׂרָאֵל לָבֶטַח אִישׁ תַּחַת גַּפְנוֹ וְתַחַת תְאֵנָתוֹ. וּכְתִיב (שם ד) אוֹכְלִים וְשׁוֹתִים וּשְׂמֵחִים. דְּהָא שִׁית וְשִׁיתִין אִתְפַּתָּחוּ. וְכָל עִידוּנִין עִילָּאִין הֲווֹ נַחֲתִין לְעָלְמִין כּוּלְהוּ. וְכָלְהוֹ הֲווֹ חָדָאן לְסָלְקָא לְגַבֵּי עָלְמָא עִילָּאָה, לְמִלְקַט בִּרְכָאן וְעִדּוּנִין לְעָלְמִין. כְּדֵין, חֲבִיבוּ אִתְעַר מִנַּיְיהוּ לְגַבֵּי מַלְכָּא עִילָּאָה, לְמֶהֱוֵי כּוֹלָּא חַד בְּלָא פֵּירוּדָא. כְּדֵין שִׁבְחָא דְּסָלְקָא עַל כָּל שְׁבָחִין, לְמַלְכָּא דִּשְׁלָמָא כֹּלָּא דִּילֵיהּ, לְמֶהֱוֵי כּוֹלָא בְּחֶדְוָה עֵילָא וְתַתָּא.</p>"],[9514013772,"<p>כְתִיב (תהלים סה) שִׁיר, וּכְתִיב (שם) לְךָ דֻמִיָּה תְהִלָּה וְגו'. דָּוִד מַלְכָּא הֲוָה יָדַע בְּרוּחַ קוּדְשָׁא, דְּאִזְדַּמַּן שִׁיר דָּא, לְאִתְגַּלְּיָא בְּעָלְמָא. וַאֲמַר, שִׁיר דְּאִזְדַּמָּן לְאִתְגְּלֵי, לְךָ דוּמִיָּה. אִיהוּ בַּחֲשַׁאי, דְּלֵית רְשׁוּ לְאִתְגַּלְּיָיא תּוּשְׁבַּחְתָּא דָא, אֶלָּא תּוּשְׁבַּחְתָּא וּתְהִלָּה דָא אֱלֹהִים בְּצִיּוֹן, כַּד אִתְבְּנֵי בֵּי מַקְדְּשָׁא, דְּאִיהוּ לָקֳבֵיל מַקְדְּשָׁא עִילָּאָה, כְּדֵין לְךָ יְשׁוּלַּם נֶדֶר.</p>"],[9514013773,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (במדבר כ״א:י״ז) אָז יָשִׁיר יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת. (שמות ט״ו:א׳) אָז יָשִׁיר משֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת. הָתָם תּוּשְׁבַּחְתָּא דְנוּקְבָא. הָכָא תּוּשְׁבַּחְתָּא דְּסָלֵיק לְעַלְמָא דִדְכוּרָא אִיהוּ.</p>"],[9514013774,"<p>הָכָא אִיהוּ רָזָא, דְּגוּפָא וְרוּחָא מִתְחַבְּרָאן כַּחֲדָא, גּוּפָא בְּגוּפָא, וְרוּחָא בְּרוּחָא. שִׁיר הַשִּׁירִים, אִתְדַּבְּקוּתָא דְּגוּפָּא בְּגוּפָא. (שה\"ש א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ, אִתְדַּבְּקוּתָא דְּרוּחָא בְּרוּחָא. וְכֹלָּא אִיהוּ בְּרָזָא דִּרְחִימוּ עִילָּאָה, לְמֶהֱוֵי כּוֹלָא חַד, בְּיִיחוּדָא חָדָא.</p>"],[9514013775,"<p>וְרָזָא דְיִיחוּדָא הָכָא. שִׁיר דָּא אִיהוּ יִשְׂרָאֵל, דִּמְמַנָּא בְּסַהֲדוּתָא דְּיִיחוּדָא. הַשִּׁירִים, ה' אֱלֹהֵינו ה'. וְכוֹלָּא חָד, בְּיִיחוּדָא חָד. וְאוֹקִימְנָא יִיחוּדָא דָא, וְהָכָא יִיחוּדָא דְּעַלְמִין כָּלְהוֹ. אֲשֶׁר לִשְׁלֹמֹה, רָזָא דְּאֶחָד.</p>"],[9514013776,"<p>וְהָא אִיהוּ דְּאִצְטְרִיךְ שְׁלֹמֹה מַלְכָּא לְיַיחֲדָא, בְּרָזָא דְרוּחַ קוּדְשָׁא. לְאִתְחַבְּרָא כּוֹלָא בְּיִיחוּדָא חָדָא, בִּרְעוּתָא, לְאִתְדַּבְּקָא דָּא בְּדָא, לְמֶהֱוֵי כּוֹלָּא חַד. דְּהָא שְׁלֹמֹה אִיהוּ מַלְכָּא דִּשְׁלָמָא כּוֹלָּא דִּילֵיהּ.</p>"],[9514013777,"<p>מַאי כּוֹלָּא דִּילֵיהּ הָכָא, וְכִי סַגִּיאִין שְׁלָמִין נִינְהוּ. אֶלָּא חַד שְׁלָמָא אִיהוּ, וּתְרֵין נִינְהוּ. חַד שְׁלָמָא אִיהוּ, דְּאִיהוּ שְׁלָמָה דְבֵיתָא, דִּבְגִינֵיהּ אִשְׁתְּמוֹדַע דְּכוּרָא דְּכַר. וְחַד שְׁלָמָא אָחֳרָא, דְּאִיהוּ שְׁלָמָא דִּתְרֵין סִטְרִין, חַד דְּעָאל בְּאֶמְצָעִיתָא בְּאִינוּן תְּרֵין סִטְרִין, וַעֲבֵיד שְׁלָמָא בֵּינַיְיהוּ, אִיהוּ שָׁלוֹם אָחֳרָא.</p>"],[9514013778,"<p>אֲבָל שָׁלוֹם דִּדְכוּרָא אִשְׁתְּמוֹדַע דָּכָר בְּגִינֵיהּ, אִיהוּ צַדִּיק. וְאִקְּרֵי מַלְכָּא עִילָּאָה בְּגִינֵיהּ, מֶלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. וּבְגִין כָּךְ, כָּל תּוּשְׁבַּחְתָּא דְּשִׁיר הַשִּׁירִים, לְמַלְכָּא דִּשְׁלָמָא כּוֹלָּא דִּילֵיהּ, וְיִיחוּדָא דְקָא מִתְיַיחֵד כּוֹלָּא, בַּאֲתַר דָּא אִיהוּ. בְּגִין דְּאִיהוּ נָטֵיל כָּל תֵּיאוּבְתָּא דְּכָל שַׁיְיפִין, וְכָל עִינּוּגִין, וְכָל כִּיסּוּפִין עִילָּאִין, וְכָנֵישׁ כּוֹלָא לְגַוֵּיהּ.</p>"],[9514013779,"<p>וְעַל דָּא אִיקְּרֵי אִיהוּ אֶחָד, שְׁלֹמֹה מַלְכָּא בְּרָזָא דְּרוּחַ קוּדְשָׁא. כַּד שְׁרָא עֲלֵיהּ הַהוּא רוּחַ קוּדְשָׁא, בָּעָא לְחַבְּרָא כּוֹלָה בִּרְעוּתָא שְׁלִים כִּדְקָא יָאוֹת, וּלְיַיחֲדָא כּוֹלָא בַּחֲבִיבוּ בִּרְעוּתָא, לְמֶהֱוֵי חַד עֵילָא וְתַתָּא. וְעַל דָּא אֲמַר קְרָא, (זכריה יד) יִהְיֶה ה' אֶחָ\"ד וּשְׁמ\"וֹ אֶחָ\"ד.</p>"],[9514013780,"<p>(שה\"ש א) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ וְגו'. כְּתִיב (יחזקאל א) וָאֵרֶא הַחַיּוֹת וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ אֵצֶל הַחַיּוֹת לְאַרְבַּעַת פָּנָיו. הַאי קְרָא בְּקִיטוּרָא דְּרַבִּי אֶלְעָזָר אִתְּמַר. וָאֵרֶא הַחַיּוֹת, רָזָא דְיִשְׂרָאֵל סָבָא, קַפְּטִירָא בִּגְלִיפוֹי בְּיָמִינָא וּבִשְׂמָאלָא.</p>"],[9514013781,"<p>תְּלַת רְשִׁימִין קְטוּרִין דָּא עִם דָּא, דָּרוֹם מִזְרָח וְצָפוֹן, יה\"ו, אַפִּין סְתִימִין, לָא שָׁלֵיט עֵינָא לְמֶחֱמֵי, וְהָכָא אָמַר וָאֵרֶא.</p>"],[9514013782,"<p>אֶלָּא, הֲוָה מִסְתַּכֵּל מִגּוֹ נְהוֹרָא דְּלָא נָהֲרָא, כְּמַאן דְּחָמֵי בַּעֲשָׁשִׁיתָא, גּוֹ עַיְינִין סְתִימִין, כַּד מְנַצְּצָן גּוֹ הַהוּא עֲשָׁשִׁיתָא. לָהֵיט לְהִיטוּ לְפוּם שַׁעֲתָא, וְלָא קָאִים בְּקִיּוּמָא.</p>"],[9514013783,"<p>מִתְגַּלְגְּלִין נָצְצִין לְפוּם הַאי שַׁעֲתָא, וְעָאל נְצִיצוּ דָּא בְּדָא. חַד סָלֵיק וְנָחֵית, וְאִתְתַּקַּף בִּסְטַר דָּרוֹם, בְּרָזָא דְאָת יו\"ד. אִתְתַּקַּף וְעָאל בְּסִטְרָא דְצָפוֹן, וּמִתְגַּלְגֵּל בְּקוֹטְרוֹי, וְעָאל וְסָלֵיק בְּרָזָא דְאָת ט', וְאִתְגְּנֵיז. הֲדָא הוּא דִכְתִיב, (בראשית א) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. דְּנָצֵיץ וְלָהֵיט בִּגְלִיפִין בְּאָת ט', וְגָנֵיז לֵיהּ.</p>"],[9514013784,"<p>רָזָא דְאָת דָא סְתִימָא בִּסְתִימוּ, נָפֵיק מִינֵּיהּ כָּל נְצִיצוּת וְזָהֳרָא, דְּנָהֵיר וְנָצֵיץ. זַכָּאָה אִיהוּ מַאן דְּחָמֵי לָהּ בְּחֶלְמֵיהּ, דָּא אַכְּסַדְרָה דְּמִינָהּ נָצְצִין נְצִיצִין, פָּשֵׁיט וְכָנֵישׁ.</p>"],[9514013785,"<p>וְחַד סָלֵיק וְנָחֵית, וְאִתְתַּקַּף בִּסְטַר מִזְרָח, בְּרָזָא דְאָת ט' וְאָת יו\"ד. אִתְפַּשֵּׁיט מִתְּרֵין סִטְרִין, וּמִתְגַּלְגְּלָא בְּאַרְבַּע, תְּרֵין לְעֵילָא, כִּירוּתָא דְאַבָּא וְאִימָּא. וְאִית תְּרֵין מִתְּרֵין סִיטְרִין, מִסְטַר דָּרוֹם וְצָפוֹן, מִתְיַישְׁבָא בְּכוּלְּהוּ. וְאִיהוּ רְתִיכָא עִילָּאָה, בְּאַרְבַּע סִטְרִין. אוֹפַן אֶחָד בָּאָרֶץ אֵצֶל הַחַיּוֹת, דָּא אִיהוּ רְתִיכָא תַּתָּאָה, כְּלִילָא בְּאַרְבַּע סִטְרִין.</p>"],[9514013786,"<p>רְתִיכָא עִילָּאָה, דְּאִיהוּ רָזָא דְּאַרְבַּע סִטְרִין, פָּשֵׁיט נְהִירוּ מִתְּלַת סִטְרִין, חַד דִּילֵיהּ דְּאִתְחַבָּרוּ בֵּיהּ יְרוּתָא דְּאַבָּא וְאִימָּא, דַּהֲווֹ תְּרֵין, וּמִתְחַבְּרָן לְחַד. וּתְרֵין מִתְּרֵין סִטְרִין.</p>"],[9514013787,"<p>פָּשֵׁיט נְהִירוּ דְּמִזְרָח, הַאי רְתִיכָא תַּתָּאָה גַּלֵּי פֶּן חַד, לְגַבֵּי דְהַהוּא נְהִירוּ, וּמְקַבְּלָא לֵיהּ, וְאִתְנְהֵיר מִינֵיהּ. וְכַד אִתְנְהֵיר הַהוּא פֶּן מֵהַהוּא נְהִירוּ, כְּדֵין הַהוּא פֶּן אִיקְּרֵי אדנ\"י. וְאִיהוּ שַׁלִּיט וְרִבּוֹן בְּשָׁלְטָנוֹ דִּנְהִירוּ רַב. וְהַהוּא פֶּן כֵּיוָן דִּמְקַבֵּל הַהוּא נְהִירוּ, אִתְעֲבֵיד לֵיהּ הֵיכָלָא, וְגָנֵיז לֵיהּ בְּגַוֵּיהּ, וּבְגִינֵיהּ אִתְעֲבֵיד אָדוֹן רִבּוֹן וְשַׁלִּיט.</p>"],[9514013788,"<p>פָּשֵׁיט זְהִירוּ דְּדָרוֹם, הַאי רְתִיכָא תַּתָּאָה גַּלֵּי פֶּן חַד לְגַבֵּי דְהַהוּא נְהִירוּ, וּמְקַבְּלָה לֵיהּ וְאִתְנְהֵיר מִנֵּיהּ. וְכַד אִתְנְהֵיר הַהוּא פֶּן מֵההוּא נְהִירוּ, כְּדֵין הַהִיא פֶּן אִקְרֵי אֵל. וְאִיהוּ שַׁלִּיט לְאוֹטָבָא לְעַלְמָא בְּרַחֲמֵי. וּלְמֵיהַב מְזוֹנָא לְכָל חַד וְחַד כִּדְקָא יָאוֹת.</p>"],[9514013789,"<p>פָּשֵׁיט נְהִירוּ דְצָפוֹן, הַאי רְתִיכָא תַּתָּאָה גַּלֵּי פֶּן חַד לְגַבֵּי דְּהַהוּא נְהִירוּ, וּמְקַבְּלָא לֵיהּ, וְאַנְהֵיר מִנֵּיהּ. וְכַד הַהוּא פֶּן אִתְנְהֵיר מִנֵּיהּ, כְּדֵין הַהוּא פֶּן אִיקְּרֵי אֱלֹהִים. וְאִיהוּ שַׁלִּיט, רִבּוֹן, לְמֵידַן עַלְמָא בְּדִינָא, וּלְמֵיהַב דִּינָא לְכָל מַאן דְּאִצְטְרִיךְ, וּלְאִתְנַהֲגָא כּוֹלָּא בְּדִינָא.</p>"],[9514013790,"<p>עַד הָכָא, אַנְפִּין עִילָּאִין וְאַנְפִּין תַּתָּאִין, בְּרָזָא דִּתְלַת בִּתְלַת מִתְחַבְּרָאן, וְאִתְכְּלִילוּ אִלֵּין בְּאִלֵּין. פֶּן חַד דְּאִשְׁתָּאַר מֵרְתִיכָא תַּתָּאָה, כּוֹלָּא שָׁאֲלִין עֲלֵיהּ אוֹפַן, אָן אִיהוּ פֶּן חַד דְּאִשְׁתָּאַר.</p>"],[9514013791,"<p>הָהַר וַאֲמַר בְּאָן אֲתַר הוּא, בָּאָרֶץ. בְּגִין דְּלָא יִשְׁתָּאֲרוּן תַּתָּאִין בְּלָא אַשְׁגָּחוּתָא אֲפִילּוּ רִגְעָא חָדָא. הַהוּא פֶּן, כַּד אִתְכְּלִילוּ כּוּלְהוּ תְּלָתָא אָחֳרָנִין, הַאי פֶּן נָטֵיל מִכּוּלְהוּ, וְאִתְכְּלִילוּ בְּכָלְהוֹ, וְאִיהוּ בְּלחוֹדוֹי בְּכָלְהוֹ, בְּגִין לְאַשְׁגָּחָא בְּטִיבוּ עַל כָּל בְּנֵי עָלְמָא.</p>"],[9514013792,"<p>וְהַאי פֶּן מְשַׁבֵּחַ תָּדִיר, וְאִתְעָרַת אִתְעָרוֹ לְגַבֵּי אִינוּן דִּלְעֵילָא דַּעֲלֵהּ. וְאִינוּן דִּלְעֵילָא דַּעֲלֵהּ, מִתְעָרֵי לְגַבֵּי אִינוּן עִילָּאִין דִּלְעֵילָא. וְאִינוּן עִילָּאִין דִּלְעֵילָא, מִתְעָרִין לְגַבֵּי עֵילָא, וְאִתְקַשְּׁרֵי דָּא בְּדָא עַד אֵין סוֹף.</p>"],[9514013793,"<p>וְהַאי כַּד אִתְעַר בְּאִתְעָרוּ דְּאִינוּן פָּנִים, בְּאִינוּן נְשִׁיקִין עִילָּאִין, לְמֶהֱוֵי דְּבִיקֵי בְּרָזָא עִילָּאָה, וּלְאַשְׁלָמָא וּלְמֵיזַן כָּל עָלְמִין, לְמֶהֱוֵי כָּל עָלְמִין כּוּלְהוּ בְּחֶדְוָא. כְּמָא דְאַתְּ אָמֵר, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ כִּי טוֹבִים דֹּדֶיךָ מִיָּיִן.</p>"],[9514013794,"<p>יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. עַל פּוּמָא דְאֵלִיָּהוּ אִתְגַּזַּר. כְּתִיב (בראשית ד) וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן וְגו'. וְהָאָדָם, דָּא אָדָם קַדְמָאָה, סְתִירָא, בִּגְלִיפוֹי דַּקִּיקִין עִילָּאִין. יָדַע, מַה דְּלָא אִשְׁתְּמוֹדַע בָּהּ מִקַּדְמַת דְּנָא. יָדַע לְמֶהֱוֵי אַנְפִּין בְּאַנְפִּין. כַּד אִסְתַּכְּלָן אַנְפִּין בְּאַנְפִּין לְשִׁימּוּשָׁא, כְּדֵין כְּתִיב יָדַע. יָדַע לְאַשְׁקָאָה לָהּ, לְמִיזְרַע בָּהּ זַרְעָא, לְמֶעְבַּד תּוֹלָדִין. הַאי לְטַב, בְּאִתְעָרוֹ דְאַשְׁגָּחוּתָא לְתַתָּא.</p>"],[9514013795,"<p>מִדַּאֲתָא נָחָשׁ עַל חַוָּה, אֲטֵיל בָּהּ זוּהֲמָא, וְקַיִן מֵהַהוּא זוּהֲמָא נָפֵיק. וְאִי תֵימָא אֵיךְ נָפֵיק מִתַּמָּן, וְהָא כְתִיב וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן, דְּמַשְׁמַע דְּמֵאָדָם הֲוָה, וְלָא מִסִּטְרָא אָחֳרָא, וְאַתְּ אֲמַרְתְּ דַּאֲטֵיל נָחָשׁ בָּהּ זוּהֲמָא וּנְפֵיק מִינֵּיהּ קַיִן.</p>"],[9514013796,"<p>אֶלָּא, וַדַּאי הַהוּא נָחָשׁ אֲטֵיל בָּהּ זוּהֲמָא, וּמֵהַהוּא זוּהֲמָא אִישָׁאֵיב בָּהּ הַהוּא רוּחַ בִּישָׁא, וְהַהוּא הֲוָה מְכַשְׁכְּשָׁא בִּמְעָהָא, וְלָא הֲוָה לֵיהּ גּוּפָא לְאִתְכְּלָלָא בֵּיהּ, וּלְמֵיפַק לְעָלְמָא. וְכֵיוָן דַּאֲתָא אָדָם, בְּאִתְעָרוֹ דְּהַהוּא זוּהֲמָא, וְאִתְחַבַּר בְּאִתְּתֵיהּ, עֲבַד לֵיהּ גּוּפָא לְהַהוּא רוּחָא בִּישָׁא דְּהֲוָה בִּמְעָהָא, וְאִתְכְּלֵיל בְּגַוֵּיהּ, וּנְפַק לְעָלְמָא בִּדְיוֹקְנָא מֵעֵילָא וְתַתָּא.</p>"],[9514013797,"<p>וְחַוָּה אַשְׁגָּחַת בְּהַאי, וַאֲמָרַת קָנִיתִי אִישׁ אֶת ה'. עִם ה'. וּבְגִין כָּךְ, כָּל עוֹבָדוֹי דְּקַיִן, הֲווֹ מֵהַהוּא סִטְרָא אָחֳרָא בִּישָׁא. וְכַד אַיְיתֵי קוּרְבָּנֵיהּ, מֵהַהוּא סִטְרָא בִּישָׁא אַיְיתֵי לֵיהּ. הֲדָא הוּא דִכְתִיב, (שם) וַיְהִי מִקֵּץ יָמִים, וְלָא כְתִיב וַיְהִי מִקֵּץ יָמִין.</p>"],[9514013798,"<p>(שם) וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הֶבֶל. דְּוַדַּאי הַהוּא רוּחָא בִּישָׁא אִתְתַּקַּף וְאִתְגַּבַּר בְּעוֹבָדָא דְקַיִן, וְאִתְבַּר חֵילָא וְתוּקְפָא בְּהֶבֶל, וְלָא הֲוָה לְגַבֵּיהּ כְּלוּם. עַד הָכָא הֲוָה בְּסִטְרָא דְּזוּהֲמָא כּוֹלָּא.</p>"],[9514013799,"<p>כֵיוָן דַּאֲתָא לְבָתַר וְאִתְיְילֵיד שֵׁת, אִתְבַּסֵּם עָלְמָא, בְּצַדִּיקֵי וַחֲסִידֵי דַּהֲווֹ לְבָתַר בְּעָלְמָא. שֵׁ\"ת: דָּא אִיהוּ סִיּוּמָא דְאַלְפָא בֵּיתָא. וְאַף עַל גַּב דְּאִתְבַּסַּם, לָא אַעֲדִיאוּ עֲקִימוּ בִּישָׁא מֵעָלְמָא, אֶלָּא אִתְכַּפְיָא מִקַּמֵּי סִטְרָא דִמְהֵימְנוּתָא, סִיּוּמָא דְּאַתְוָון.</p>"],[9514013800,"<p>דְּהָא עַד הָכָא אִתְבְּרֵי עַלְמָא בְּאַתְוָון דְּאוֹרַיְיתָא, וְלָא אִשְׁתַּלִּימוּ אַתְוָון, עַד דְּאִתְיְילֵיד שֵׁת. כֵּיוָן דְּאִתְיְילֵיד שֵׁת, אִשְׁתַּלִּימוּ כָּל עוֹבָדִין דִּלְעֵילָא וְתַתָּא, בְּרָזָא דְּאַתְוָון. כְּדֵין אִתְבַּסַּם עָלְמָא, דְּאִשְׁתְּלֵים תִּיקּוּנוֹי. מִכָּאן וּלְהָלְאָה, שָׁארֵי עָלְמָא לְאִתְנַהֲגָא כְּפוּם מֵישַׁר אוֹרְחוֹי.</p>"],[9514013801,"<p>שֵׁירוּתָא דְּקָא שָׁארֵי, מֵאִינוּן אַתְוָון דְּאִשְׁתְּבָקוֹ בְּקַדְמִיתָא. אָדָם, שָׁארֵי בְּאָלֶ\"ף, וְסַיֵּים בְּמֶ\"ם. וּלְבָתַר דְּסַיֵּים אַלְפָא בֵּיתָא בְּשֵׁת, אִתְהַדְּרוּ אַתְוָון אֱנוֹ\"שׁ, אָלֶ\"ף כְּמִלְּקַדְּמִין, נ' דְּאִיהוּ בָּתַר מ' דְּאִשְׁתְּבֵיק מֵאָדָם. ש', שֵׁירוּתָא דְּאַתְוָון דְּשֵׁ\"ת. נָטֵיל אַתְוָון מֵהַאי וּמֵהַאי. ו' דִּיוּקְנָא דְּאָדָם, לְאִתְחֲזָאָה, דְּהָא מִשֵּׁת אִתְיַחֲסוּ דָרִין בְּעָלְמָא בְּאוֹרַח מֵישַׁר, כִּדְקָא יָאוֹת.</p>"],[9514013802,"<p>וּבְרָזָא דְּאַתְוָון אִתְבְּנֵי כּוֹלָּא. וַאֲזָלוּ תְּלָתִין וּתְרֵין אַלְפָא בֵּיתוֹת, עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי. כֵּיוָן דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי, אִתְכְּנִישׁוּ אַתְוָון, וְאַסְתִּימוּ בְּהִפּוּכָּא דְּאַלְפָא בֵּיתוֹת, וּנְפָקַאת אוֹרַיְיתָא, כְּלִילָא בִּתְלָתִין וּתְרֵין שְׁבִילִין דְּרָזָא דְּחָכְמְתָא עִילָּאָה, וְאִתְרְשִׁימַת אַלְפָא בֵּיתָא, בִּתְרֵיסַר תְּחוּמִין, תְּרֵיסַר שְׁבָטִין. בַּר תְּרֵין דְּאִסְתַּלָּקוֹ מִנְהוֹן, וְאִינוּן ח\"ט, דְּלָא אִתְחֲזוֹ בְּהוּ כְּלָל.</p>"],[9514013803,"<p>עַד דְּאָעֳלוּ לְאַרְעָא בְּשֵׁירוּתָא, וַהֲוָה חֵרֶם בֵּינַיְיהוּ בְּחוֹבָא דְעָכָן, וּכְדֵין אִתְהַדְּרוּ אִינוּן תְּרֵין אַתְוָון, דַּהֲווֹ מִסְתַּלְּקֵי מִנַּיְיהוּ, וְאִינוּן מַכְרְזֵי וְאָמְרֵי חָטָא יִשְׂרָאֵל. וְאִלֵּין אַתְוָון לָא אִסְתַּלָּקוֹ מִנַיְיהוּ, אַף עַל גַּב דַּהֲווֹ בְּאַרְעָא קַדִּישָׁא, בְּכָל דָּרָא וְדָרָא</p>"],[9514013804,"<p>עַד דַּאֲתָא שְׁלמֹה, וּבָנָה בֵּי מַקְדְּשָׁא, וְאִתְיַישְׁבוּ עָלְמִין, עֵילָּא וְתַתָּא בִּדְיוֹקְנָא חָדָא. כְּדֵין אִתְיַישְׁרוּ אַתְוָון כּוּלְהוּ, וְאִינוּן תְּרֵין אַתְוָון דַּהֲווֹ רְשִׁימִין בֵּינַיְיהוּ לְבִישׁ, אִתְהַפִּיכוּ לְטַב, אִתְהַדְּרוּ טַח, דִּכְתִיב (מלכים א ה) וַיֵּשֶׁב יְהוּדָה וְיִשְׂרָאֵל לָבֶטַ\"ח.</p>"],[9514013805,"<p>כוּלְהוּ אַתְוָון הֲווֹ שְׁלָמִין בֵּינַיְיהוּ בְּלָא קִטְרוּגָא כְּלַל, וְאַתְוָון דְּאַלְפָא בֵּיתָא כּוּלְהוּ, הֲווֹ שְׁלֵימֵי עֵילָא וְתַתָּא. אַתְוָון עִילָּאִין הֲווֹ שְׁלֵימִין לְעֵילָא. אַתְוָון דַּקִּיקִין הֲווֹ שְׁלֵימִין לְתַתָּא.</p>"],[9514013806,"<p>בְּשַׁעֲתָא דִּכְרוּבִים הֲווֹ פַּרְסֵי גַדְפַיְיהוּ מִתַּתָּא לְעֵילָא, אַתְוָון פָּרְחִין מִתַּתָּא לְעֵילָא, וְאַתְוָון מֵעֵילָא לְתַתָּא, וְעָאלִין אִלֵּין בְּאִלֵּין, וְאִתְכְּלִילוּ אִלֵּין בְּאִלֵּין, בִּנְשִׁיקִין דִּרְחִימוּ.</p>"],[9514013807,"<p>כֵיוָן דְּאַתְוָון מִתְחַבְּרָן, כָּל דַּרְגִּין תַּתָּאִין, וְדַרְגִּין עִילָּאִין, וְעָלְמִין כּוּלְהוּ, מִתְחַבְּרָאן כַּחֲדָא, וְנַשְׁקֵי אִלֵּין בְּאִלֵּין, בִּנְשִׁיקוּ דִּרְחִימוּ, עַד דַּהֲווֹ כּוּלְהוּ חַד, וְקוּדְשָׁא בְּרִיךְ הוּא חַד, בְּלָא פֵּירוּדָא כְּלָל.</p>"],[9514013808,"<p>כָל נְשִׁיקִין דִּרְחִימוּ, לָאו אִינוּן אֶלָּא לְמֶהֱוֵי כְּלָלָא חָדָא, לְאִתְכְּלָלָא דָּא בְּדָא בְּלָא פֵּירוּדָא. וּבְגִין כָּךְ נְשִׁיקִין אִלֵּין בְּכוֹלָא, אִינוּן, לְמֶהֱוֵי כּוֹלָא חַד בִּכְלָלָא חָדָא, אַתְוָון בְּאַתְוָון, עָלְמִין בְּעָלְמִין, דַּרְגִּין בְּדַרְגִּין, אִתְּתָא בְּבַעֲלָהּ, לְמֶהֱוֵי כּוֹלָא חַד.</p>"],[9514013809,"<p>פִּיהוּ, אַמַּאי פִּיהוּ, פִּיו מִיבָּעֵי לֵיהּ. אֶלָּא לְאַכְלָלָא תַּרְוַיְיהוּ כַּחֲדָא. פִּיהוּ, לְאִתְחֲזָאָה דְּהָא אִיהִי זְמֵינִית לְגַבֵּיהּ, כְּאִתְּתָא דְּתַקֵּינַת פּוּמָהּ, לְקַבְּלָה נְשִׁיקוּ מִבַּעֲלָהּ. בְּגִין כָּךְ אִתְחֲזֵי זְמִינוּ דְּפוּמָהּ.</p>"],[9514013810,"<p>פִּיהוּ, הָכָא אִית לְאִסְתַּכָּלָא, אִי תֵימָא דִּנְשִׁיקִין אִינוּן לְעֵילָא לְעֵילָא בְּאֵין סוֹף, בְּגִין דַּאֲמַר בְּאוֹרַח סְתִים יִשָּׁקֵנִי פִּיהוּ. וּלְבָתַר אַהֲדַר בְּאִתְגַּלְּיָא דּוֹדֶיךָ. לָאו הָכֵי, דְּהָא נְשִׁיקִין לָא תַּלְיָין תַּמָּן לְעֵילָא, אֶלָּא אִתְּתָא בְּבַעֲלָהּ. אֶלָּא עַד לָא אִתְקְרִיבוּ דָּא בְּדָא, אֲמַר בְּאוֹרַח סְתִים. כֵּיוָן דְּאִתְקְרִיבוּ וְאִתְנְשִׁיקוּ בִּדְבֵיקוּ דִרְחִימוּ דָּא בְדָא, אִיהִי אָמְרָה בְּאִתְגַּלְּיָא, דּוֹדֶיךָ, וְלָא כְתִיב דּוֹדָיו, דְּהָא כְּלִילָן כַּחֲדָא בִּרְחִימוּ, בְּחִבּוּרָא חָדָא, בְּלָא פֵּירוּדָא כְּלָל.</p>"],[9514013811,"<p>כִי טוֹבִים דֹּדֶיךָ מִיָּיִן, טוֹב לָאו אִיהוּ, אֶלָּא מִסְּטַר דְּאוֹר קַדְמָאָה, דִּכְתִיב (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וְהַשְׁתָּא דְּאָת בִּשְׁלִימוּ, דְּאִתְכְּלֵיל יָמִינָא בִּשְׂמָאלָא. טוֹבִים דּוֹדֶיךָ מִיָּיִן, דָּא יֵינָא דְאוֹרַיְיתָא, דְּאִיהוּ חֶדְוָה, טוֹבִים מִסִּטְרָא דִשְׂמָאלָא.</p>"],[9514013812,"<p>חָדֵי רַבִּי שִׁמְעוֹן וַאֲמַר, וַדַּאי דָא אִיהוּ חֶדְוָא, דְּזָכֵינָא בְּכָל הַנֵּי מִלִּין עִילָּאִין. אָמַר לֵיהּ אֵלִיָּהוּ, רַבִּי, אַפְתַּח פּוּמָךְ, דְּמִילָךְ כְּתִיבִין לְעֵילָא, וּמִילַיי כְּתִיבִין לְתַתָּא. זַכָּאִין אַתּוּן צַדִּיקַיָא קַמֵּי עַתִּיק יוֹמִין, בְּהַאי עַלְמָא וּבְעַלְמָא דְּאָתֵי.</p>"],[9514013813,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ כִּי טוֹבִים דֹּדֶיךָ מִיָּיִן. אוֹרַיְיתָא דִּבְעַל פֶּה, הֲוָה אָמְרָה לְגַבֵּי אוֹרַיְיתָא דְּבִכְתַב, דְּאִיהִי אָזְלַת בָּתַר אִינוּן נְשִׁיקִין דְּתוֹרָה דְּבִכְתַב, בָּתַר מְתִיקוּ דִילָהּ, לְאִתְחַבָּרָא דָּא עִם דָּא בְּאִינוּן נְשִׁיקִין. וּכְדֵין אִיהִי בִּפְלוּגְתָּא בְּעוּלֵימְתָהָא, לְאִתְתַּקְנָא בַּהֲדָהּ, לְמֶהֱוֵי כּוּלְהוּ קְשִׁיטִין לְגַבֵּי תּוֹרָה שֶׁבִּכְתָב.</p>"],[9514013814,"<p>וְכַד אִתְחַבְּרַת וְאִתְכְּלִילַת בְּתוֹרָה שֶׁבִּכְתַב בְּחֶדְוָה, בְּחִבּוּרָא חָדָא, דְּנָשֵׁיק דָּא בְּדָא בִּרְחִימוּ, אַתְקָפַת בֵּיהּ, וַאֲמָרָה לֵיהּ בַּחֲבִיבוּ, כַּמָּה יַקִּירִין חֲבִיבוּתֵיךְ, מֵחַמְרָא דִילָךְ, דְּאַתְקֵיף בִּי רְחִימוּ דִילָךְ, עַד דְּרָוֵי לִי חֲמַר דִּרְחִימוּ, לְאִתְתַּקְפָא בָּךְ, קִישּׁוּטָא דְּאִתְקַשְׁטַת אוֹרַיְיתָא דְּעַל פֶּה בְּעוּלֵימְתָהָא, לְאִתְחַבְּרָא בְּאוֹרַיְיתָא דְּבִכְתָב.</p>"],[9514013815,"<p>מִשְּׁנָה אִיהִי שֵׁרוּתָא דְרֵישָׁא, בְּרָזָא דְּתִיקוּנָא דְּאִתְחֲזֵי לָהּ, בָּרַיְיתָא אִיהִי בְּרָזָא דְּתִיקּוּנָא יַרְכִין וְרַגְלִין. גּוּפָא בְּתִיקּוּנָא דְּאִתְחֲזֵי לָהּ.</p>"],[9514013816,"<p>אָתָאן עוּלֵימְתָהָא, מְקָרְבִין לָהּ, לְתַקָּנָא לָהּ. דָּא אֲמַר מוּתָּר, וְדָא אֲמַר אָסוּר, דְּדָא אִיהוּ קִישּׁוּטָא דְּכַלָּה, כַּד מְקַשְׁטֵי לָהּ. דָּא אֲמַר כַּד מְקַשְׁטֵי, הָכֵי אָזְלָא קִישׁוּטָא דָא. וְדָא אֲמַר לָאו הָכֵי. דָּא אֲמָרָה קִישּׁוּטָא דְרֵישָׁא הָכֵי אָסִיר וּמְהַדַּק. וְדָא אֲמָרָה כִּיפָה דְרֵישָׁא מוּתָּר בְּסִטְרָא דָא, וְאָסִיר וּמְהַדַּק בְּסִטְרָא דָא.</p>"],[9514013817,"<p>דָּא אֲמָרָה, קִישּׁוּטָא דְדַהֲבָא דָא, בִּלְבוּשָׁא דָא, אִיהוּ פָּסוּל לְמֶהֱוֵי קִישּׁוּטָא לְגַבֵּי דָא. וְדָא אֲמַר, כָּשֵׁר וְיָאוֹת הוּא לְאִתְחֲזָאָה דָּא בְּדָא. וְכָל דָּא אִיהוּ תִּיקּוּנָא וְקִישּׁוּטָא דְכַלָּה.</p>"],[9514013818,"<p>וְעִם כָּל דָּא, בְּעוֹד דְּאִינוּן מְקַשְׁטָן, וְרַמְיָא קִטְרוּגָא בְּקִישּׁוּטָא, הִיא אוֹסִיפַת חֵילָא וְנוֹי וְגַוָּון, וְתִיקּוּן בְּהוּ וְיַתְבָא בִּיקָרָא בֵּינַיְיהוּ, וְאִתְחַשְּׁבַת בְּנַפְשָׁהּ יַתִּיר מִכַּמָּה דַּהֲוַת מְאָה זִמְנִין.</p>"],[9514013819,"<p>כֵיוָן דְּאִתְקַשְׁטַת בְּהוּ, כּוּלְהוּ אַחֲדִין לָהּ בְּקִישּׁוּטָהָא, וּבְתִיקּוּנֵי שְׁפִּירָתָא, וְעָאלִין לָהּ לְגַבֵּי מַלְכָּא, אוֹרַיְיתָא דְבִכְתָב.</p>"],[9514013820,"<p>כַד יָתְבָא מַטְרוֹנִיתָא בְּמַלְכָּא, בְּתִיקּוּן שַׁפִּירָא, וּמַלְכָּא חָזֵי לָהּ מִתְקַשְׁטָא בְּשַׁפִּירוּ, הַהוּא קִישּׁוּטָא מַכְרִיז וַאֲמַר לְמַלְכָּא, לְנַשְׁקָא לָהּ, דְּדָא אִיהוּ דְּבֵקוּתָא דִּרְחִימוּ, לְאִתְכְּלָלָא דָּא בְּדָא. מַאן גָּרֵים בְּאִינוּן נְשִׁיקִין וּבְהַהוּא רְחִימוּ, אִינוּן עוּלֵמְתָאן דְּקַשִּׁיטוּ לָהּ.</p>"],[9514013821,"<p>כַד בָּעְיָא לְאוֹטָבָא לְעוּלֵימְתָהָא, הִיא וּמַלְכָּא לְמֵיהַב לוֹן נְבַזְבְּזָן, לְכוּלְהוּ יָהֵיב כַּחֲדָא. לְכוּלְהוּ דַּהֲווֹ מְקַטְרְגֵי דָּא בְּדָא עַל קִישּׁוּטָהָא, יַהֲבֵי מַלְכָּא וּמַטְרוֹנִיתָא נְבַזְבְּזָן וּמַתְּנָן בִּרְעוּ בַּחֲבִיבוּ, לְמֵיחְסַן לוֹן יְרוּתָא בְּאֶלֶף עָלְמִין דִּכְסִיפִין לְעַלְמָא דְאָתֵי. וְכָּל שֶׁכֵּן אִינוּן דְּיָדְעֵי בְּרָזִין דְּחָכְמְתָא, לְקַשְׁטָא קִישּׁוּטָהָא, דְּלֵית שִׁיעוּרָא לְאַחְסָנַת יְרוּתָא דִּלְּהוֹן בְּעַלְמָא דְאָתֵי. עֲלַיְיהוּ כְתִיב, (משלי כא) לְהַנְחִיל אֹהֲבַי יֵ\"שׁ וְגו'.</p>"],[9514013822,"<p>(שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ כִּי טוֹבִים דֹּדֶיךָ מִיָּיִן. הָא הָכָא שִׁבְעָה תֵּיבִין, לָקֳבֵיל ז' דַּרְגִּין דַּעֲלָהּ. וּלְקִבְלַיְיהוּ ז' הַנְּעָרוֹת הָרְאוּיוֹת לָתֶת לָהּ, דְּקָא מְקַשְׁטֵי לָהּ, לַאֲעָלָא לָהּ לְגַבֵּי מַלְכָּא.</p>"],[9514013823,"<p>יִשָּׁקֵנִי, לְגַבֵּי חַי הָעוֹלָמִים. מִנְּשִׁיקוֹת, לְגַבֵּי חַסְדֵּי דָּוִד. פִּיהוּ, לְגַבֵּי יִשְׂרָאֵל סָבָא. כִּי טוֹבִים, לְגַבֵּי אוֹר קַדְמָאָה. דּוֹדֶיךָ, לְגַבֵּי יִצְחָק יְדִיד מִבֶּטֶן. מִיָּין, לְגַבֵּי יַיִן עִילָּאָה דְּמִנְטְרָא תָּדִיר.</p>"],[9514013824,"<p>שֶׁבַע הַנְּעָרוֹת הָרְאוּיוֹת לָתֶת לָהּ מִבֵּית הַמֶּלֶךְ, אִינוּן: מִיכָאֵ\"ל. גַּבְרִיאֵ\"ל. רְפָאֵ\"ל. אוֹרִיאֵ\"ל. צִדְקִיאֵ\"ל. יוֹפִיאֵ\"ל. רָזִיאֵ\"ל. וְכַמָּה אֶלֶף וְרִבּוֹא מַשִּׁרְיָין עִמְהוֹן. כְּמָא דְאַתְּ אָמֵר, וַעֲלָמוֹת אֵין מִסְפָּר.</p>"],[9514013825,"<p>תְּלַת קְרָאֵי אִינוּן הָכָא, דְּכוּלְהוּ בְּחוּשְׁבְּנָא עַל רָזִין דִּלְהוֹן. חַד, שִׁיר הַשִּׁירִים, דְּאִיהוּ רָזָא דִרְתִיכָא, כְּמָא דְּאִתְּמָר. תְּרֵין, יִשָּׁקֵנִי, דְּאִיהוּ רָזָא דְשֶׁבַע תֵּיבִין, בְּז' דַרְגִּין, כְּמָא דְּאִתְּמָר. תְּלַת, לְרֵיחַ שְׁמָנֶיךָ טוֹבִים, דְּאִיהוּ רָזָא דְעֶשֶׂר תֵּיבִין, עֶשֶׂר אֲמִירָן. וְדָא אִיהוּ רָזָא דְתוּשְׁבַּחְתָּא דָא, לְכָלְלָא חָדָא קַדְמָאָה. וְעַל רָזָא דָא תּוּשְׁבַּחְתָּא דְשַׁבָּת מִתְיַיסְדָא. בַּר תְּרֵיסַר בַּתְרָאי, דְּאִינוּן בְּתוּשְׁבַּחְתָּא אָחֳרָא.</p>"],[9514013826,"<p>הָכָא, בְּשִׁיר הַשִּׁירִים, בִּקְרָא, (שיר השירים ד׳:י״ד) נֵרְ\"ד וְכַרְכֹּם וְגו'. ז' נְשִׁיקִין אִינוּן, בְּשֶׁבַע דַּרְגִּין דְּהַאי קְרָא. דִּנְשִׁיקִין שֶׁבַע אִינוּן, מִכָּל דַּרְגָּא חַד נְשִׁיקָה. וְכֵן נְשִׁיקִין דְּיַעֲקֹב, בְּז' תֵּיבִין כָּלֵיל נְשִׁיקוֹי, דִּכְתִיב, וַיִּשַּׁק יַעֲקֹב לְרָחֵל וַיִּשָּׂא אֶת קוֹלוֹ וַיֵּבְךִָּ. בְּכִיָה דְּחֶדְוָה דִּרְחִימוּ, לָקֳבֵל תֵּיבַת מִיָּיִן. דְּאִיהוּ רְחִימוּ דְחֶדְוָה.</p>"],[9514013827,"<p>לְאִתְחֲזָאָה, דִּנְשִׁיקִין בְּרָזָא דְשֶׁבַע אִינוּן. כְּמָא דְאִיהִי בַּת שֶׁבַע, הָכֵי כָּל מִילוֹי בְּשֶׁבַע. וְעַל דָּא (תהילים ט״ז:י״א) שׂוֹבַע שְׂמָחוֹת אֶת פָּנֶיךָ וְגו', אַל תִּקְרֵי שׂוֹבַע, אֶלָּא שֶׁבַע, שֶׁבַע שְׂמָחוֹת.</p>"],[9514013828,"<p>בְּכָל נְשִׁיקִין דִּרְחִימוּ, לֵית נְשִׁיקִין כְּאִינוּן דְּאִתְעָרָא הָכָא כְּנֶסֶת יִשְׂרָאֵל, יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ. אַף עַל גַּב דְּאִינוּן ז' נְשִׁיקִין כְּמָא דְאִתְּמָר, תְּלַת נְשִׁיקִין אִתְחֲזוֹן הָכָא, וְהַנֵּי תְּלַת נְשִׁיקֵי דְּאִתְחֲזוֹן בִּקְרָא. יִשָּׁקֵנִי חַד, מִנְּשִׁיקוֹת דְּאִינוּן תְּרֵין, הָא תְּלַת.</p>"],[9514013829,"<p>וְהַשְׁתָּא אִיהִי תְּבָעַת מֵאִינוּן נְשִׁיקוֹת, וּמַה דַּאֲמַרְתְּ מִנְּשִׁיקוֹת, דְּמַשְׁמַע חַד נְשִׁיקָא, דִּכְתִיב מִנְּשִׁיקוֹת, וְלָא כְתִיב נְשִׁיקוֹת, דְהָא נְשִׁיקוֹת דְּאִינוּן תְּרֵין, מֵאִינוּן נְשִׁיקוֹת לָאו אִיהוּ אֶלָּא חָדָא. וַדַּאי אִצְטְרִיךְ, מַאן דְּשָׁאֵיל, לָא אִצְטְרִיךְ לְשָׁאֲלָה סַגֵּי, אֶלָּא זְעֵיר, דְּהָא כֵּיוָן דְּשָׁארֵי, יִטוֹל מַאן דְּיִטוֹל. קוּדְשָׁא בְּרִיךְ הוּא, שָׁאֲלִין לֵיהּ זְעֵיר, וְהוּא יָהֵיב סַגֵּי. אַבְרָהָם שָׁאַל זְעֵיר, וְקוּדְשָׁא בְּרִיךְ הוּא יְהַב לֵיהּ סַגֵּי. הוּא שָׁאַל בְּרָא חֲדָא, מַה כְּתִיב, (בראשית כ״ב:י״ז) וְהַרְבָּה אַרְבֶּה אֶת זַרְעֲךָ כְּכוֹכְבֵי הַשָּׁמַיִם וְכַחוֹל אֲשֶׁר עַל שְׂפַת הַיָּם וְגו'. בְּגִין דְּכָךְ אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְעַל דָּא אֲמַרְתְּ מִנְּשִׁיקוֹת, וְלָא נְשִׁיקוֹת.</p>"],[9514013830,"<p>יִשָּׁקֵנִי, דְּבֵיקוּ דִּרְחִימוּ, רוּחַ בְּרוּחַ. דְּהָא ד' רוּחִין מִתְחַבְּרָן, וְאִתְעֲבִידוּ כַּחֲדָא. דָּא יָהֵיב רוּחָא לְחַבְרֵיהּ. וְנָטֵיל הַהוּא רוּחַ דְּחַבְרֵיהּ, דְּאִתְדַּבַּק בֵּיהּ. אִשְׁתַּכַּח, רוּחָא דִילֵיהּ וְרוּחָא דְחַבְרֵיהּ, הָא תְּרֵין. אוּף הָכֵי חַבְרֵיהּ. אִשְׁתַּכְּחֵי, ד' רוּחִין דְּמִתְחַבְּרָן כַּחֲדָא, בְּאִינוּן נְשִׁיקִין.</p>"],[9514013831,"<p>מִנְשִׁיקוֹת פִּיהוּ, מֵאִינוּן נְשִׁיקִין עִילָּאִין, דְּקָא הֲוָה נָשֵׁיק מִקַּדְמַת דְנָא. דְּהָא רְחִימוּ דְחֶדְוָא לָאו אִיהוּ, אֶלָּא מִגּוֹ נְשִׁיקִין דְּרוּחָא עִילָּאָה בְּתַתָּאָה.</p>"],[9514013832,"<p>פִּיהוּ, וְלָא כְתִיב פִּיו, מַאי פִּיהוּ. אֶלָא זְמִינוּ דְעָלְמָא דְאָתֵי, מֶלֶךְ דִּשְׁלָמָא כּוֹלָּא דִּילֵיהּ. וְדָא אִיהוּ תּוֹסֶפֶת ה', דְּאִתּוֹסַף עַל דָּא. בְּגִין דְּכָל רְחִימוּ דְעַלְמָא תַּתָּאָה, לָאו אִיהוּ אֶלָּא לְאִתְחַבְּרָא בְּעַלְמָא עִילָּאָה, עַלְמָא דְאָתֵי. וְעַל דָּא, כָּל תּוּשְׁבְּחָן אִתְעַר עַלְמָא תַּתָּאָה, לְגַבֵּי עַלְמָא עִילָּאָה.</p>"],[9514013833,"<p>כִי טוֹבִים, דְּלִיקוּ וּנְצִיצוּ דְּבוּצִינִין עִילָּאִין, וְכָל שְׁרַגִּין מִתְתַּקְנָן וְדָלְקִין וְנָהֲרִין כִּדְקָא יָאוֹת וְדָא אִיהוּ דּוֹדֶיךָ, אִינוּן בּוּצִינִין קַדִּישִׁין רְחִימִין עִילָּאִין, כּוּלְהוּ נָהֲרִין וְנָצְצִין בִּנְהִירוּ בִּנְצִיצוּ, כִּדְקָא יָאוֹת. מַיִין, מֵחֶדְוָה דְּחַמְרָא טָבָא עִילָּאָה, דְּנָהֵיר אַנְפִּין, וִיהֵיב חֶדְוָה לְלִבָּא, וְכָל עָלְמִין בְּחוּלָקֵיהוֹן, חָדָאן בְּהַהוּא חֶדְוָה.</p>"],[9514013834,"<p>תָּא חֲזֵי, יִשְׂרָאֵל נָטְלִין חוּלָקֵיהוֹן, וְחָדָאן בְּהַהוּא חֶדְוָה, מֵחֲמַר טַב דְּנָהֵיר, וְזַכֵּיךְ, וְשַׁכֵּיךְ, וְקָיְימָא עַל דּוּרְדַיָיה. שְׁאָר עַמִּין כּוּלְהוּ, לָא נָטְלֵי אֶלָּא מִגּוֹ אִינוּן שְׁמָרִים דִּתְחוֹת חַמְרָא.</p>"],[9514013835,"<p>וְעַל דָּא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לוֹן מִשְׁתֶּה שְׁמָרִים. דְּהָא אִינוּן שְׁמָרִים דּוּרְדַּיָין כּוּלְהוּ, חוּלָקָא דִּשְׁאָר עַמִּין. וְעַל דָּא יִשְׂרָאֵל חֶדְוָה דִילְהוֹן בְּהַהוּא יַיִן דְּמִנְטְרָא, וְנַפְקָא מֵעָלְמָא דְאָתֵי, וּמִנְטְרָא בְּעִנְבוֹי.</p>"],[9514013836,"<p>תְּנַן, מַאן דְּחָמֵי עִנְבִין בְּחֶלְמָא, אִי חִוָּורָאן אִינוּן, סִימָן טַב לֵיהּ. וְאִי אוּכְמֵי, בַּעְיָין רַחֲמֵי. דְּהָא וַדַּאי בְּדִינָא קָיְימָא. מַאי טַעְמָא, בְּגִין דְּאִינוּן עִנְבִין חִוָּורְאִין, אִינוּן עִנְבֵי דְּנַטְרֵי הַהוּא חַמְרָא עִילָּאָה, וְאִינוּן גַּוָּון חִיוַּור רַחֲמֵי. וְאִינוּן עִנְבִין סוּמְקִי\"ן, אִינוּן סְטַר דִּינָא גַּוָון סוּמָק.</p>"],[9514013837,"<p>אֲכָלָן, כְּדַאי אִיהוּ לְעַלְמָא דְאָתֵי. מַאי טַעְמָא, בְּגִין דַּעֲבַר עַל דִּינָא, וְיָכֵיל לְשֵׁצָאָה לֵיהּ. וְחַמְרָא טָבָא דְּעַלְמָא דְאָתֵי, אִית לֵיהּ בֵּיהּ חוּלָקָא. שָׁתֵי חַמְרָא חִיוָּרָא, סִימָן טַב לֵיהּ, וְחֶדְוָה. סוּמְקָא, אִיהוּ דִינָא דְּשַׁרְיָא עֲלֵיהּ.</p>"],[9514013838,"<p>יַעֲקֹב, כַּד קָרֵיב לְגַבֵּי יִצְחָק אֲבוּהִי, יְהַב לֵיהּ מֵהַהוּא חַמְרָא טָבָא דְּמִנְטַר מֵעַלְמָא דְאָתֵי, דְּחֶדְוָה וּרְחִימוּ לָאו אִיהוּ, אֶלָּא כַּד אִתְעַר מִגּוֹ חַמְרָא טָבָא.</p>"],[9514013839,"<p>וְעַל דָּא יִצְחָק, דְּהֲוָה מִסִּטְרָא דְדִינָא קַשְׁיָא, אִצְטְרִיךְ לְמֶחֱדֵי לֵיהּ בְּהַהוּא חַמְרָא טָבָא, דְּאָתֵי מֵרָחוֹק. הֲדָא הוּא דִכְתִיב, וַיָּבֵא ל\"וֹ יַיִן מֵרָחוֹק, מִדּוּכְתָּא עִילָּאָה, מָשֵׁיךְ עֲלֵיהּ מֵהַהוּא חֶדְוָה לְמֶחֱדֵי לֵיהּ, כְּדֵין אִתְבַּסַּם רוּגְזָא, וְדִינָא תַּקִּיפָא אִתְכְּלֵיל בְּרַחֲמֵי, לְמֶהֱוֵי כּוֹלָּא כִּדְקָא יָאוֹת.</p>"],[9514013840,"<p>וּבְגִין כָּךְ אִינוּן דּוֹדִים, רְחִימִין עִילָּאִין, בּוּצִינִין קַדִּישִׁין, לָא נָהֲרִין אֶלָּא מִגּוֹ הַהוּא יַיִ\"ן, וּמַאן אִיהוּ, דָּא שְׁמָא גְלִיפָא מְפָרַשׁ דְּשִׁבְעִין אַתְוָון. דְּאִינוּן בּוּצִינִין קַדִּישִׁין, שְׁמָא גְלִיפָא קַדִּישָׁא דְּשִׁבְעִין שְׁמָהָן, דָּא אִיהוּ בְּרָזָא דְּאִינוּן עִנְבִין, דְּנַטְרִין יַיִן עִילָּאָה, כְּלָלָא דְּאִינוּן שִׁבְעִין.</p>"],[9514013841,"<p>וּבְגִין כָּךְ, חֶדְוָה וּרְעוּ בְּאִינוּן נְשִׁיקִין, לְאַתְעָרָא רְחִימוּ, מִיַּיִן עִילָּאָה אִיהִי. וְעַל דָּא, בּוּצִינִין נָהֲרִין וְנָצְצִין מֵהַהוּא יַיִן, דִּכְתִיב כִּי טוֹבִים דֹּדֶיךָ מִיָּיִן.</p>"],[9514013842,"<p>(שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים אָמַר רַבִּי שִׁמְעוֹן, הַאי קְרָא אִסְתַּכַּלְנָא בֵּיהּ, וְאִיהוּ סָתִים בְּרָזָא עִילָּאָה. רֵיחַ, אִית רֵיחַ וְאִית רֵיחַ, וְכַמָּה רֵיחִין אִינוּן. אִית רֵיחַ דְּסָלֵיק מִתַּתָּא לְעֵילָא, כְּגוֹן רֵיחָא דְקוּרְבָּנָא, דְּהַאי אִיהוּ רֵיחָא, דְּסָלֵיק, וְקָשַׁר קִשְׁרִין דָּא בְּגוֹ דָּא, וּמִשְׁתַּלְשֵׁל דָּא בְּדָא, עַד דְּאִתְעֲבֵיד כּוֹלָּא קִשְׁרָא חָדָא, וּנְהִירוּ חַד.</p>"],[9514013843,"<p>אִית רֵיחַ אָחֳרָא וְדָא אִיהוּ מַלְכָּא מְשִׁיחָא, דְּאִקְרֵי רֵיחַ. דִּכְתִיב, (ישעיהו י״א:ג׳) וַהֲרִיחוֹ בְּיִרְאַת ד'. וְדָא אִקְּרֵי רֵיחַ. וּמִתְקַשְׁרָא בְּרָזָא דְּרֵיחַ קוּרְבָּנָא.</p>"],[9514013844,"<p>וְרָזָא דָא (ויקרא א׳:י״ג) אִשֶּׁה רֵיחַ נִיחֹחַ לַה', אִשֶּׁה לְבַר קִישּׁוּרָא, וּמְזוֹנָא וּנְהִירוּ דְּחִילִין וּמַשִּׁרְיָין דְּאֶשָׁא, בְּטַהֲרוֹנָא קְמִיטִין. רֵיחַ לְגוֹ מִינֵיהּ, וְדָא אִיהוּ דְּאִתְקַשַּׁר לְגוֹ, וְנָהֵיר בְּרָזָא דִּבְרִית קַדִּישָׁא. וְדָא אִתְקְרֵי מַלְכָּא מְשִׁיחָא, דְּאִיהוּ רֵיחַ מֵאִינוּן בּוּסְמִין עִילָּאִין, דִּכְתִיב כְּרֵיחַ בְּשָׂמִים.</p>"],[9514013845,"<p>נִיחוֹחַ, נְהִירוּ דְּכָל גְּוָונִין עִילָּאִין, תִּפְאֶרֶת יִשְׂרָאֵל, וְשַׁפִּירוּ דְּכֹלָּא. וְדָא אִיהוּ נַיְיחָא דְרוּחָא עִילָּאָה, דְּשַׁרְיָא עֲלֵיהּ, וְנָהֵיר לְגַבֵּיהּ. לַה', לְמַלְכָּא דְּכוֹלָּא, וְכוֹלָּא אִתְקַשַּׁר דָּא בְדָא, וְאַנְהֵיר דָּא בְדָא, לְמֶהֱוֵי חַד בְּחֶדְוָה דְּכוֹלָּא, בְּרָזָא דְּקוּרְבָּנָא.</p>"],[9514013846,"<p>וְאִי תֵימָא, הָא אֶשָׁא דְאִיהוּ לְבַר בִּקְמִיטוֹן, דָּא אִיהוּ אִשֶּׁה, דִּמְהַהוּא אֶשָׁא מִתְקַמְטָן כַּמָּה חַיָּילִין, וְכַמָּה מַשִּׁרְיָין, אִלֵּין בְּאִלֵּין מְלַהֲטָן, בְּכַמָּה זַיינִין, לְכַמָּה סִטְרִין. וְכוּלְהוּ בְּרָזָא דְּקוּרְבָּנָא אִתְקְמִיטוּ, וְתָאבוֹ וְעָאלוֹ בְּהַאי אֶשָׁא.</p>"],[9514013847,"<p>בְּגִין דְּכוּלְהוּ מָארֵי תְּרֵיסִין, מָארֵי דְדִינִין. וְכַד תָּבִין, כְּמָא דְתָב רוֹגְזָא דְּנָפֵיק מִנְחִירִין, כַּד הֲוֵי נַיְיחָא, לְדוּכְתֵּיהּ. כְּמָא דְּאִלֵין חַיָּילִין וּמַשִּׁרְיָין מְלַהֲטָן קְמָטִין בְּאַתְרַיְיהוּ, הָכֵי נָמֵי חַיָּילִין וּמַשִּׁרְיָין עִילָּאִין קַדִּישִׁין, מָארֵי דְּנַיְיחָא וּרְעוּ, נָהֲרִין וְתָבִין בִּנְהִירוּ לְאִתְקַשְּׁרָא, גּוֹ הַאי ה', וְכָלְהוֹ אִלֵּין בְּאִלֵּין, וְדָא בְּדָא בְּחִבּוּרָא חָדָא, אִקְרֵי אִשֶּׁה, רָזָא דְּנַיְיחָא, וּמְזוֹנָא, וּנְהִירוּ דְּכָל סִטְרִין.</p>"],[9514013848,"<p>רֵיחַ, נְקוּדָה דִּלְגוֹ. רָזָא דִּבְרִית קַדִּישָׁא. אַמַּאי אִקְרֵי רֵיחַ, בְּגִין דְּאִיהוּ רֵיחָא דְבוּסְמִין עִילָּאִין קַדִּישִׁין, טְמִירִין, דְּלָא אִתְגַּלְיָין. וְכַד שַׁרְיָין, אָרַח לוֹן, כְּהַאי מַאן דְּאָרַח רֵיחַ בַּהֲדַס, אִיהוּ רֵיחַ נָפֵיק מֵהֲדַס, וְדָא נְקוּדָה אִקְרֵי רֵיחַ דְּנָפֵיק מֵהֲדַס.</p>"],[9514013849,"<p>נִיחוֹחַ, אֲתַר דְּנָחַת רוּחַ עִילָּאָה, וְשָׁרַאת עֲלֵיהּ לְמֶהֱוֵי רְתִיכָא עִילָּאָה, בְּרָזָא דְּע\"ב שְׁמָהָן. וּרְתִיכָא עִילָּאָה כֹּלָּא קִישּׁוּרָא חָדָא. לַה', לְמֶהֱוֵי כּוֹלָּא בִּנְהִירוּ חָדָא. וְעַל דָּא אִקְּרֵי רֵיחַ נִיחוֹחַ.</p>"],[9514013850,"<p>וּבְכָל אֲתַר, רֵיחַ, מִסְלִיקוּ דְּקָאִים עַל דַּרְגָּא אָחֳרָא תַּתָּאָה מִנֵּיהּ, וְהַאי אִיהוּ רֵיחַ מֵהַהוּא עִילָּאָה. לְרֵיחַ, דָּא אִיהוּ נְקוּדָא עִילָּאָה, דְּקָיְימָא בִּסְתִימוּ, מִגּוֹ הַהוּא דְּסָתִים דְּכָל סְתִימִין, דְּלָא אִתְיְדַע כְּלָל. וְהַאי נְקוּדָה אִיהִי רֵיחַ מֵהַהוּא סְתִימָא דְכוֹלָּא. וּבְגִין הַאי רֵיחַ, כָּל אִינוּן שְׁמָנִין וּבוּסְמִין, כּוּלְהוּ נְהִירִין וְאִקְרוּן טוֹבִים, בְּגִין דְּהַאי קַיַּים לוֹן, לְמֶהֱוֵי כּוּלְהוּ חַד קִישּׁוּרָא, נָהֵיר כַּחֲדָא.</p>"],[9514013851,"<p>וְאִי לָאו, לָא אִקְרוּן טוֹבִים. בְּגִין דְּכַד הַאי רֵיחַ עִילָּאָה, עָאל בִּסְתִימוּ לְגוֹ נַחֲלָא עֲמִיקָא, וְאִמְלֵי לֵיהּ כִּדְקָא יָאוֹת, כּוּלְהוּ דַּרְגִּין אִקְרוּן טוֹבִים.</p>"],[9514013852,"<p>רַב הַמְנוּנָא סָבָא אֲמַר הָכֵי, אִלֵּין אִינוּן יָמִים דְּאִקְּרוּן טוֹבִים. וְאִינוּן תְּפִילִּין דְּרֵישָׁא, דְּאִינוּן תְּפִילִּין דְּקוּדְשָׁא בְּרִיךְ הוּא מַנַּח לוֹן, וְעַל דָּא אִקְּרוּן טוֹבִים, בְּגִין דְּאִינוּן נַהֲרִין בְּרֵישָׁא דְּקוּדְשָׁא עִילָּאָה.</p>"],[9514013853,"<p>וּבְכָל אֲתַר, יָמִים טוֹבִים אִינוּן תְּפִילִּין דְּרֵישָׁא, דְּקוּדְשָׁא בְּרִיךְ הוּא מַנַּח לוֹן. חוֹלוֹ שֶׁל מוֹעֵד, דְּלָא אִקְרֵי יוֹם טוֹב, אִלֵּין תְּפִילִּין דִּדְרוֹעָא, דְּהָא לֵית לָהּ לְסִיהֲרָא מִגַּרְמָהּ כְּלוּם, אֶלָּא מִנְּהִירוּ דְּיוֹם טוֹב.</p>"],[9514013854,"<p>תְּפִילִּין דִּדְרוֹעָא דְּאִיהִי תְּפִלָּה שֶׁל יַד, לָא נְהִירָא אֶלָּא מִגּוֹ נְהִירוּ דִּתְפִילִּין שֶׁל רֹאשׁ. תְּפִלָּה דְּרֵישָׁא, יָמִים טוֹבִים. תְּפִלָּה דִדְרוֹעָא, חוּלוֹ שֶׁל מוֹעֵד. וְשַׁפִּיר קָאֲמַר, וְהָכֵי הוּא.</p>"],[9514013855,"<p>וְעַל דָּא, חוּלוֹ שֶׁל מוֹעֵד אִיהוּ לְעִנְיַן עֲבִידְתָּא, כְּגַוְונָא דְּיוֹם טוֹב וְאִצְטְרִיךְ חֶדְוָה כְּגַוְונָא דִילֵיהּ. וּבְגִין כָּךְ, בְּאִלֵּין יוֹמִין דְּאִינוּן תְּפִילִּין דְּמָארֵי עָלְמָא, אָסוּר לַאֲנָחָא שְׁאָר תְּפִילִּין, דְּהָא אִלֵּין יוֹמִין, דְּאִינוּן תְּפִילִּין עִילָּאִין שַׁרְיָין עַל רֵישֵׁיהוֹן דְּיִשְׂרָאֵל קַדִּישִׁין.</p>"],[9514013856,"<p>רַבִּי אֶלְעָזָר שָׁאֵיל לְרַבִּי שִׁמְעוֹן אֲבוֹי, אָמַר לֵיהּ, תֵּינַח תְּפִילִּין דְּרֵישָׁא, דְּשָׁרְיָין עַל רֵישֵׁיהוֹן דְּעַמָּא קַדִּישָׁא בְּיוֹם טוֹב. תְּפִילִּין שֶׁל יַד, דְּאִיהִי חוּלוֹ שֶׁל מוֹעֵד, אֵיךְ אֲנַן אֲחָדִין לָהּ.</p>"],[9514013857,"<p>אָמַר לֵיהּ, בְּגִין דַּאֲנַן אֲחָדִין לָהּ, וְאִיהִי יַ\"ד כֵּהָה, אָסוּר לְמֶעְבַּד עֲבִידְתָּא בְּסִטְרָא דִילָהּ, וְאִצְטְרִיךְ לְמֶעְבַּד חֶדְוָה, בְּסִטְרָא דִתְפִילִּין דְּרֵישָׁא.</p>"],[9514013858,"<p>וְעַמָּא קַדִּישָׁא אַחֲדִין תְּפִילִּין דְּמָארֵי עַלְמָא וְשַׁרְיָין עֲלַיְיהוּ בְּיוֹם טוֹב וּבְחוּלוֹ שֶׁל מוֹעֵד, וְאָסוּר לְאַעֲבָרָא תְּפִילִּין דְּמָארֵי עַלְמָא מֵעַל רֵישֵׁיהוֹן, לַאֲנַחָא תְּפִילִּין אָחֳרָנִין, דְּאִינוּן דּוּגְמָא וּדְיוֹקְנָא לְתַתָּא.</p>"],[9514013859,"<p>לְמַלְכָא דְּבָעֵי לְנַטְרָא לֵיהּ לְעַבְדֵּיהּ, אָמַר לֵיהּ עֲבֵיד חוֹתָמָא כִּדְיוֹקְנָא דְּחוֹתָמָא דִילִי, כָּל זִמְנָא דְּהַהוּא דִּיוּקְנָא יִתְחֲזֵי עֲלָךְ, כֹּלָּא יְזוּעוּן וִידַחֲלוּן מִינָךְ. לְבָתַר מִגּוֹ רְחִימוּ עִילָּאָה, דְּקָא רָחֵים לֵיהּ מַלְכָּא, יְהַב בִּידֵיהּ חוֹתָמָא דְּגוּשְׁפַּנְקָא עִילָּאָה דִּילֵיהּ, כֵּיוָן דְּאָחֵיד חוֹתָמָא עִילָאָה דְּמַלְכָּא בִּידֵיהּ, שָׁבֵיק מִנֵּיהּ הַהוּא דִּיוּקְנָא דְּאִיהוּ עָבַד.</p>"],[9514013860,"<p>אִי הַהוּא עֶבֶד, דָּחֵי חוֹתָמָא עִילָּאָה דְמַלְכָּא, בְּגִין הַהוּא חוֹתָמָא דְּאִיהוּ עָבִיד, וַדַּאי בַּר קָטוֹלָא אִיהוּ הַהוּא עַבְדָא, בְּגִין דַּעֲבֵיד קְלָנָא בְּחוֹתָמָא דְמַלְכָּא, וְלָא חָיֵישׁ לִיקָרֵיהּ. וּבְגִין כָּךְ, אָסוּר לְעַמָּא קַדִּישָׁא לְדַחְיָא חוֹתָמָא דְמַלְכָּא עִילָּאָה דְּשָׁרֵי עֲלָן, בְּגִין דִּיוּקְנָא דָא דַּאֲנַן עָבְדִין.</p>"],[9514013861,"<p>הַאי בְּמוֹעֵד וּבְחוּלוֹ שֶׁל מוֹעֵד, וְכָּל שֶׁכֵּן בְּשַׁבָּת, דְּכֹלָּא שַׁרְיָא עֲלָן, שַׁבָּת דְּמַעֲלֵי שַׁבְּתָא, תְּפִלָּה שֶׁל יַד. שַׁבָּת דְּיוֹמָא, תְּפִילִּין דְּרֵישָׁא.</p>"],[9514013862,"<p>וְהָכֵי קָא מְסַדַּר קוּדְשָׁא בְּרִיךְ הוּא לְעַמָּא קַדִּישָׁא רְחִימָא דִילֵיהּ, בַּחוֹל אִינוּן תְּפִילִּין דְּעָבְדוּ דִּיוּקְנָא דְּחוֹתָמָא דְמַלְכָּא, לְמֶהֱוֵי נְטִירִין בְּכָל סִטְרִין. בְּשַׁבָּת וּמוֹעֵד דְּאִינוּן יוֹמִין טָבִין, וּתְפִילִּין דְּמָארֵי עַלְמָא מַמָּשׁ. מְעַבְרָן הַהִיא דְיוֹקְנָא, וּמַנְחֵי תְּפִילִּין דְּמָארֵי עָלְמָא. זַכָּאִין עַמָּא דָא, דִּבְיָדָן חוֹתָמָא עִילָּאָה דְמַלְכָּא.</p>"],[9514013863,"<p>מַאן דְּמַנַּח תְּפִילִּין, אִצְטְרִיךְ לְמֶחֱדֵי. וְעַל דָּא כְּתִיב, וְשָׂמַחְתָּ בְּחַגֶּךָ. בִּתְפִילִּין דְּמָארֵי עַלְמָא אִצְטְרִיךְ לְמֶחֱדֵי. וְחֶדְוָה דָא, בְּמוֹעֵד וּבְחוּלוֹ שֶׁל מוֹעֵד, בִּתְפִילִּין דְּרֵישָׁא, וּבִתְפִילִּין דִּדְרוֹעָא.</p>"],[9514013864,"<p>בְּיוֹם טוֹב מֵהַהוּא רֵיחָא עִילָּאָה, שְׁמָנֶיךָ טוֹבִים, תְּפִילִּין דְּרֵישָׁא. בְּחוּלוֹ שֶׁל מוֹעֵד, שֶׁמֶן תּוּרַק שְׁמֶךָ, תְּפִלָּה שֶׁל יַד, דְּקָא סַלְקָא לְאִתְאַחֲדָא בְּאוֹרַח סָתֵים בִּתְפִילִּין דְּרֵישָׁא.</p>"],[9514013865,"<p>עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ, בְּיוֹם טוֹב בַּתְרָאָה דְּחַג, דְּהָא תְּפִלָּה שֶׁל יַד אִשְׁתְּלֵים וְאִתְנְהֵיר בִּשְׁלִימוּ. וּלְפַלְגָא חוּלָקָא לְכוֹלָּא, לְכָל אִינוּן מַשִּׁרְיָין וְחֵילִין דִּלְעֵילָא, וּלְכָל אִינוּן מַשִּׁרְיָין וְחֵילִין דִּלְתַתָּא. וְעַל דָּא עֲלָמוֹת אֲהֵבוּךָ, אִינוּן מַשִּׁרְיָין וְחֵילִין דִּלְעֵילָא, עוֹלָמוֹת וּמַשִּׁרְיָין וְחַיָּילִין דִּלְתַתָּא.</p>"],[9514013866,"<p>פְּתַח רַבִּי שִׁמְעוֹן וַאֲמַר, כְּתִיב (בראשית כ״ז:כ״ז) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרַכֵהוּ וְגו', מַה חָמָא יִצְחָק, דְּאַף עַל גַּב דְּהַהוּא מֵיכְלָא וּמִשְׁתַּיָא קָא אַיְיתֵי לֵיהּ יַעֲקֹב, לָא בָרְכֵיהּ, עַד זִמְנָא דְאָרַח בְּאִינוּן לְבוּשִׁין.</p>"],[9514013867,"<p>הָכָא אִית לְאִסְתַּכָּלָא, דְּהָא אִינוּן לְבוּשִׁין לָא הֲווֹ דִידֵיהּ דְּיַעֲקֹב, דְּהָא אוֹרַיְיתָא אַסְהֵידַת, דִּכְתִיב (שם) אֶת בִּגְדֵי עֵשָׂו בְּנָהּ הַגָּדוֹל, וְהָכָא כְּתִיב אֶת רֵיחַ בְּגָדָיו, וְכִי בְּגָדָיו הֲווֹ, רֵיחַ הַבְּגָדִים מִיבָּעֵי לֵיהּ, מַאי בְּגָדָיו.</p>"],[9514013868,"<p>אֶלָּא, בְּגָדָיו וַדַּאי הֲווֹ אִינוּן לְבוּשִׁין מַמָּשׁ, וְלָאו דְּעֵשָׂו. וְאַף עַל גַּב דִּכְתִיב בִּגְדֵי עֵשָׂו, בְּטוֹפְסָא הֲווֹ גַּבֵּיהּ. כְּגַוְונָא דָא הַהוּא בְּאֵר דִּיתֵיב עֲלֵיהּ יַעֲקֹב, וִיתֵיב עֲלֵיהּ משֶׁה, בְּטוֹפְסָא הֲוָה לְגַבֵּי אָחֳרָנִין, כֵּיוָן דַּאֲתָא יַעֲקֹב אִשְׁתְּמוֹדַע בֵּירָא לְמָארֵיהּ, וּסְלִיקוּ מַיָא לְגַבֵּיהּ, וְכֵן לְגַבֵּי משֶׁה.</p>"],[9514013869,"<p>כְגַוְונָא דָא, אִינוּן לְבוּשִׁין, בְּטוֹפְסָא הֲווֹ לְגַבֵּי עֵשָׂו, כֵּיוָן דְּאַלְבֵּישׁ לוֹן יַעֲקֹב, אִשְׁתְּמוֹדְעוּ מָאנִין לְמָארֵיהוֹן. מִיּוֹמָא דַּעֲבֵיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, לָא סְלִיקוּ רֵיחִין דִּילְהוֹן, עַד זִמְנָא דָא דְּלָבֵישׁ לוֹן יַעֲקֹב, דְּהָא אֲהַדְּרוּ לְבוּשִׁין לִדְיוֹקְנַיְיהוּ. יַעֲקֹב דִּיוּקְנָא דְּאָדָם וַדַּאי הֲוָה, וְשַׁפִּירוּ דִּילֵיהּ, בְּשַׁעֲתָא דְּחָמוֹ לְבוּשִׁין דִּיוּקְנָא דְאָדָם, סְלִיקוּ רֵיחָא.</p>"],[9514013870,"<p>תְּלַת רֵיחִין אִסְתַּלָּקוֹ הָכָא, חַד, רֵיחַ בְּגָדָיו. ב', רֵיחַ בְּנִי. ג', רֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ ה'. וְכוּלְהוּ תְּלַת, סְלִיקוּ לְגַבֵּי דְיִצְחָק, בְּשַׁעֲתָא דְּעָאל יַעֲקֹב לְגַבֵּיהּ.</p>"],[9514013871,"<p>וְכוּלְהוּ כְּתִיב בְּהַאי קְרָא, רֵיחַ בְּגָדָיו, הַיְינוּ עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. רֵיחַ בְּנִי, הַיְינוּ שְׁמָנֶיךָ טוֹבִים. רֵיחַ שָׂדֶה, הַיְינוּ שֶׁמֶן תּוּרַק שְׁמֶךָ. וַדַּאי כּוֹלָּא קִישׁוּרָא חָדָא. וְרָזָא דְּקוּרְבָּנָא דְּקָא אַתְעַרְנָא בֵּיהּ, כְּמָא דְּאִתְּמָר אִשֶּׁה, דְּהַיְינוּ עֲלָמוֹת אֲהֵבוּךָ, וְכֹלָּא רָזָא חָדָא. רֵיחַ, שֶׁמֶן תּוּרַק שְׁמֶךָ. נִיחוֹחַ, שְׁמָנֶיךָ טוֹבִים, וְכוֹלָּא חַד. לַה', הַיְינוּ לְרֵיחַ. וְכוֹלָא מִלָּה חָדָא, וְרָזָא חָדָא, בְּקִישּׁוּרָא חָדָא, כְּמָא דְּאִתְּמָר.</p>"],[9514013872,"<p>(שיר השירים א׳:ד׳) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה. כְּתִיב, וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכְכֶם וְגו'. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא יְהַב שְׁכִינְתֵּיהּ בֵּינֵיהוֹן דְּיִשְׂרָאֵל, לְמֶהֱוֵי רְבִיעָא עֲלַיְיהוּ, כְּאִימָּא עַל בְּנִין, וְלַאֲגָנָא עֲלַיְיהוּ בְּכָל סִטְרִין.</p>"],[9514013873,"<p>וְכָל זִמְנָא דְּהַהִיא אִימָּא קַדִּישָׁא יָתְבָא עֲלַיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְדַיָּירָא עִמְּהוֹן. בְּגִין דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא שָׁבֵיק לָהּ לְעָלְמִין, וְכָל חֲבִיבוּ דִּלְעֵילָא עֲלָהּ אִיהוּ.</p>"],[9514013874,"<p>וּבְגִין כָּךְ, יְהַב לָהּ מַשְׁכּוֹנָא בְּגַוַיְיהוּ דְּיִשְׂרָאֵל, לְמִנְדַע דְּלָא יִנְשֵׁי לוֹן, וְלָא יִשְׁבּוֹק לוֹן לְעָלְמִין. מַאי טַעְמָא, בְּגִין דְּהַהוּא מַשְׁכּוֹנָא בְּגַוַיְיהוּ. וְהִיא אָמְרַת, מַשְׁכּוֹנָא הֲוֵיתִי בְּתַתָּאי, אֱהֵא מַשְׁכּוֹנָא לְגַבָּךְ, וּלְסָלְקָא לְקִבְלָךְ, וַאֲנָא וּבְנִי אַחֲרֶיךָ נָרוּצָה.</p>"],[9514013875,"<p>מָשְׁכֵנִי, אַהֲדַרְנָא לְקִישּׁוּרָא דְּמִילִין קַדְמָאִין, עַל הַהוּא רָזָא אִשֶּׁה רֵיחַ נִיחוֹחַ. דְּהָא בְּשַׁעֲתָא דִרְעוּתָא סָלֵיק מִתַּתָּא בְּרָזָא דְקוּרְבָּנָא, אִיהוּ סָלְקַת וְאָמְרָה לְגַבֵי רְחִימָא דִילָהּ, מָשְׁכֵנִי: אוֹשֵׁיט יְמִינָךְ לְגַבָּאי, לְקַבְּלָא לִי, וּלְסַלְקָא לִי, בְּסִטְרָא דְאִתְעֲרוּתָא דִּשְׂמָאלָא. וִימִינָא לְחַבְּקָא לִי, וְדָא אִיהִי מָשְׁכֵנִי.</p>"],[9514013876,"<p>וְהָא אִשֶּׁה אֲמָרָהּ לְגַבֵּי רֵיחַ, רֵיחַ לְגַבֵּי נִיחוֹחַ, נִיחוֹחַ לַה'. וּכְדֵין, אַחֲרֶיךָ נָרוּצָה. מַאי נָרוּצָה, נְהֵא בִּרְעוּתָא. כְּמָה דְאַתְּ אָמֵר, (ויקרא א׳:ד׳) וְנִרְצָה לוֹ לְכַפֵּר עָלָיו. וְדָא אִיהִי דִּכְתִיב, (בראשית מ״א:י״ד) וַיְרִיצוּהוּ מִן הַבּוֹר. מַאי וַיְרִיצוּהוּ. דְאַרְצוּ לֵיהּ בְּמִלִּין טָבִין, בְּמִלִּין דְּרַעֲוָא טָבָא, דְּהֲוָה עָצֵיב מֵהַהוּא בּוֹר. וְעַל דָּא נָרוּצָה: נְהֵא בְּרַעֲוָא, בִּרְעוּתָא שְׁלִים כִּדְקָא יָאוֹת.</p>"],[9514013877,"<p>אַחֲרֶיךָ נָרוּצָה, טוֹל אַתּ רַעֲוָא בְּקַדְמִיתָא, וּלְבָתַר דְּתִטוֹל אַנְתְּ, אֲנָא, וְכָל אִינוּן עוּלֵימְתָאי, נְהֵא בְּרַעֲוָא. וְעַל דָּא מָשְׁכֵנִי.</p>"],[9514013878,"<p>מִכָאן, דְּרַעֲוָאן וּבִרְכָאן לָא אִשְׁתַּכָּחוֹ אֶלָּא בַּאֲתַר דִּדְכַר וְנוּקְבָא אִתְחַבָּרוּ כַּחֲדָא. וּבְגִין כָּךְ, מָשְׁכֵנִי לְגַבָּךְ בְּקַדְמִיתָא, בְּגִין דַּאֲקַבֵּל רַעֲוָא, מֵאֲתַר דְּכָל רַעֲוִין אִשְׁתַּכָּחוֹ. וּלְבָתַר, אַחֲרֶיךָ נָרוּצָה, נְהֵא בְּרַעֲוָא. וְאִי לָא תִּמְשְׁכֵנִי לְגַבָּךְ, רְעותָא, וְרַעֲוָא עִילָּאָה לָא יִשְׁרוֹן עֲלָךְ, דְּהָא דְּכַר בְּלָא נוּקְבָא, לָא שַׁרְיָין בֵּיהּ בִּרְכָאן.</p>"],[9514013879,"<p>וְכָל דָּא, בִּדְיוֹקְנָא דְּקָא אִתְעַרְנָא בְּרָזָא דְאָלֶף. דְּהָא תַּמָּן אִשְׁתַּכָּחוֹ רָזִין אִלֵּין, אִשֶּׁה רֵיחַ נִיחוֹחַ לַה'. וְאִיהוּ רָזָא דִלְעֵילָא וְתַתָּא, וְכָל רָזָא דִמְהֵימְנוּתָא בֵּיהּ תַּלְיָא, וְעַל דָּא סָלְקָא בְּאֶחָד. וְכֹלָּא אִיהִי א.</p>"],[9514013880,"<p>בְּשַׁעֲתָא דְּאָת דָּא פָּרַח בַּאֲוִירָא, אִסְתַּלִּיקוּ אֶלֶף וּמְאָה עָלְמִין, וְאִתְכְּלִילוּ בְּגַוֵּיהּ. וְאִתְרְשִׁימוּ אַתְוָון אָחֳרָנִין, וְאִתְגְּלִיפוּ אֲבַתְרֵיהּ. וְאִיהוּ אִתְעַטַר בְּעִטוּרָא גְלִיפָא, דְּכָלֵיל כָּל עָלְמִין.</p>"],[9514013881,"<p>וְאִיהִי חַד א, אִשֶּׁה רֵיחַ נִיחוֹחַ לַה'. אִשֶּׁה, דָּא קוֹצָא דְתַלְיָא לְתַתָּא, רָזָא דְּכָל חַיָּילִין וּמַשִּׁירְיָין אִלֵּין וְאִלֵּין. רֵיחַ, רָזָא דְּעַל הַהוּא קוֹצָא דְּאִתְאַחֲדָא בְּאֶמְצָעִיתָא. נִיחוֹחַ, רְתִיכָא דִּפְשִׁיטוּ דְּאֶמְצָעִיתָא, דְּשַׁרְיָא עֲלֵיהּ רוּחַ עִילָּאָה. לַה', נְקוּדָה עִילָּאָה דְּעַל גַּבֵּי אֶמְצָעִיתָא, דְאִיהוּ מְקַיִּים כּוֹלָּא. וְכוֹלָּא קִישּׁוּרָא חָדָא.</p>"],[9514013882,"<p>וְהָא דַּאֲחוֹרֵי אֶמְצָעִיתָא, אֲמַר, מָשְׁכֵנִי אַחֲרֶיךָ, לְאִתְחַבְּרָא עִמָּךְ, לִיטוֹל בִּרְכָאן, מֵעִם נְקוּדָה עִילָּאָה דַּעֲלָךְ. וְכַד נְהֵא דְכַר וְנוּקְבָא כַּחֲדָא, כֵּיוָן דְּתִטוֹל בִּרְכָאן וְרַעֲוָא, אֲנָא וְקוֹצָא דְּתַלְיָא לְתַתָּא מִינִי, אַחֲרֶיךָ נָרוּצָה, נִתְרְעֵי אֲבַתְרָךְ, לְמֶהֱוֵי חַד שְׁלִימוּ עֵילָא וְתַתָּא. וּלְמֶהֱוֵי א כָּל אֶחָד בִּשְׁלִימוּ דִּילֵיהּ.</p>"],[9514013883,"<p>(שה\"ש א) הֱבִיאֲנִי הַמֶּלֶךְ חֲדָרָיו וְגו'. בְּכָה רַבִּי שִׁמְעוֹן כְּמִלְקַדְּמִין וַאֲמַר. הַלְּוַאי יְהֵא בְּיָדָן לְגַלָּאָה רָזִין עִילָּאִין, חֶדְוָא אִיהוּ, הוֹאִיל וּרְעוּתֵיהּ לְגַלָּאָה רָזִין עִילָּאִין בְּדָרָא דָא.</p>"],[9514013884,"<p>אִית לְמִנְדַע, דְּהָא קִישּׁוּרָא דְּמִלִּין לָא אִשְׁתַּכָּחוֹ בִּקְרָא, דְּכֵיוָן דַּאֲמַר מָשְׁכֵנִי, מַהוּ הֱבִיאֲנִי הַמֶּלֶךְ חֲדָרָיו, תְּבִיאֵנִי לַחֲדָרֶיךָ מִבָּעֵי לֵיהּ. וְעַל דָּא נָגִילָה וְנִשְׂמְחָה בָךְ.</p>"],[9514013885,"<p>אֶלָּא בְּרָזָא דְּאַתְוָון, תַּלְיָין עִילָּאִין וְתַתָּאִין, וְעָלְמִין כּוּלְהוּ. וְקִישּׁוּרָא דְּמִלִּין הָכֵי הוא, קִישּׁוּרָא דְּתוּשְׁבַּחְתָּא לְגַבֵּי נְהוֹרָא, דַּעֲלָה אָמְרָה לְגַבֵּי בַּעֲלָהּ, אֶמְצָעִיתָא דְאָלֶ\"ף, מָשְׁכֵנִי עִמָּךְ, כְּמָה דְאִתְּמָר, וְאַף עַל גַּב דַּאֲמַרְתּ דָּא, בָּעָאת לְאִשְׁתַּבָּחָא לְגַבֵּיהּ, דְּאַף עַל גַּב דְּאִיהִי תְּחוֹתוֹי בְּשַׁחוּתָא לְגַבֵּי אֶמְצָעִיתָא דְאָלֶ\"ף, וּשְׁכִיבַת תְּחוֹתֵיהּ, אֲמָרַת לָאו אֲנָא בְּכָךְ, וְאַף עַל גַּב דַּאֲנָא לְגַבָּךְ הָכֵי, הֱבִיאֲנִי הַמֶּלֶךְ חֲדָרָיו, אֲנָא בְּעִילוּיָא וַחֲבִיבוּ לְגַבֵּי מַלְכָּא עִילָּאָה, בְּלָא שַׁחוּתָא.</p>"],[9514013886,"<p>דְּהָא הֱבִיאֲנִי חֲדָרָיו. בְּאָן אֲתַר, בְּאָת ה', דְּהָא אִתְפַּשְׁטוּתָא דִּלְעֵילָא, רָזָא דְמַלְכָּא עִילָּאָה, אָת הֵ\"א אִיהוּ. וְהַהוּא דְּעָאל לְגַבֵּיהּ, אֲנָא אִיהִי. וּבְגִין כָּךְ, אֲנָא בְּתוּשְׁבַּחְתָּא סַגֵּי, וּבְעִילּוּיָא יַקִּירָא, אַף עַל גַּב דַּאֲנָא בְּשַׁחוּתָא לְגַבָּךְ.</p>"],[9514013887,"<p>וַאֲנָא לָא חַיַּישְׁנָא, אֶלָּא לְמֶהֱוֵי גַּבָּךְ בְּשַׁחוּתָא. וְאַתְּ דְּתִשְׁלוֹט עָלַי. וְעַל דָּא, אַף עַל גַּב דֶּאֱהֵא יַתִּיר בְּשַׁחוּתָא לְגַבָּךְ, אֲנָא וְחַיָּילַי נָגִילָה וְנִשְׂמְחָה בָךְ, חֶדְוָוא וְרַעֲוָא אִית לָן לְמֶהֱוֵי לְגַבָּךְ, וְלָא לְאִתְפָּרְשָׁא מִינָךְ, דְּהָא כָּל חֶדְוָא וְרַעֲוָא לָאו אִיהִי אֶלָּא בָּךְ, דְּהָא לֵית חֶדְוָא וּרְעוּ לְאִתְּתָא אֶלָּא בְּבַעֲלָהּ, וְלָא בְאִימָּא וַאֲבוּהָ. הֱבִיאֲנִי הַמֶּלֶךְ חֲדָרָיו, וְלָא קַבֵּילְנָא חֶדְוָא וּרְעוּ אֶלָּא בָּךְ.</p>"],[9514013888,"<p>הֱבִיאֲנִי הַמֶּלֶךְ חֲדָרָיו, אִלֵּין אִינוּן חַדְרֵי גַּן עֵדֶן. וְאִם תֹּאמַר חַדְרֵי גַּן עֵדֶן, אִיהִי גַּן עֵדֶן, וְאִיהִי אָמְרַת הָכֵי. אֶלָּא, אִינוּן חֲדָרִים דְּגַן עֵדֶן אִתְזָנַת מִנַּיְיהוּ, וְאִתְקְרֵי בְּהוּ.</p>"],[9514013889,"<p>חֲדָרָא קַדְמָאָה, י\"ה, דָּא חֲדָרָא, וְאִידְרָא עִילָּאָה דְּלֵית בֵּיהּ חֵיזוּ, וְלָא גַּוָון כְּלָל, אֶלָּא כְּמָא דְּאִצְטַבַּע לְפוּם שַׁעֲתָא בִּמְדִידוּ דְּבוּצִינָא דְּקַרְדִינוּתָא, וְהָדַר סַלְקָא לְאֵין סוֹף, בִּסְתִירוּ דְּגָנֵיז.</p>"],[9514013890,"<p>הַאי חֲדָרָא קַדְמָאָה כַּד סַלְקָא מִשְׁחֲתָא, אִתְעֲבָרָא צְבִיעוּ דְגַוְונָא וְאִתְטַמַּר, וְלָא אִתְחֲזֵי בֵּיהּ גַּוָּון כְּלָל. כְּדֵין בְּאַרְבַּע סִטְרִין, אִתְחַזְיָין בִּטְמִירוּ, וְאִתְכַּסְיָין בְּאִתְגַּלְיָא, אַרְבַּע אַתְוָון, אִינוּן: אֶהְיֶה אֲשֶׁר אֶהְיֶה.</p>"],[9514013891,"<p>עַל מָה אִתְקְרֵי הָכֵי דְּזַמִּין לְאִתְגַּלְיָיא מִגּוֹ רֵיחָא דַּעֲלָהּ. וּבְגִין דְּעַד לָא אִתְמְלִיאַת לְאַנְהָרָא לְתַתָּא, אִתְקְרֵי אֶהְיֶ\"ה.</p>"],[9514013892,"<p>וְסִימָנָא דָא שֵׁירוּתָא דִנְבוּאָה דְמשֶׁה, דְּעַד כָּאן לָא נָפְקַת סִיהֲרָא מִכִּסּוּיָה, לְאִתְנָהֲרָא מִגּוֹ שִׁמְשָׁא. וְכֵיוָן דְּסִיהֲרָא הֲוַת בַּחֲשׁוֹכָא, עַד כְּעָן שִׁמְשָׁא לָא נָהֵיר לְגַבָּהּ, וְאִידְרָא עִילָּאָה דָּא לָא אִתְגַּלְיָיא לְאַנְהָרָא, דְּהָא הַהוּא רֵיחָא עִילָּאָה, סָלְקָא לְגוֹ סְתִימָא דְּכָל סְתִימִין, דְּלָא אִתְיְדַע כְּלָל, וּכְדֵין אֶהְיֶ\"ה.</p>"],[9514013893,"<p>וְכַד תָּב לְאַתְרֵיהּ, כְּדֵין קָיְימָא וַדַּאי לְאַנְהָרָא לְכוֹלָּא, וּכְדֵין אֲשֶׁר, אֶהְיֶה, דְּהָא כְדֵין אִתְתַּקְנָן לְאִתְמַלְיָא, מִגּוֹ שְׁבִיל חַד דַקִּיק, דְּעַיִּיל בֵּיהּ בִּסְתִימוּ. וְעִם כָּל דָּא, בִּשְׁמָהָן אִלֵּין, עַד כְּעָן לָא אִתְגַּלְיָיא לְאַנְהָרָא בּוּסִינִין.</p>"],[9514013894,"<p>לְבָתַר אֶהְיֶה תְּלִיתָאָה, דְּהָא זְמִינַת לְאִתְגַּלְּיָא, וּלְאַפְשָׁטָא נְהוֹרִין לְכָל סְטַר, וְדָא אִיהוּ אֶהְיֶ\"ה, הָא אֲנָא זַמִּין לְאִתְגַּלְּיָיא.</p>"],[9514013895,"<p>וְהָא תְּלִיתָאָה, תִּיקּוּנָא דְשׁוֹפָר לַאֲפָקָא קָלָא. וְכֵיוָן דְּנָפַק הַהוּא קָלָא בִּתְקִיפוּ דְּשֵׁירוּתָא דְקָלָא, נְפֵיק בְּתוֹקְפָא דְּהַהוּא דְּתָקַע לֵיהּ, הַהוּא שֵׁירוּתָא דְּקָלָא אִיקְרֵי יהו\"ה. בְּגִין דְּהַהוּא תּוֹקְפָא דְּשֵׁירוּתָא תָּב לְאַתְרֵיהּ, וְלָא אִתְגַּלְּיָיא כִּשְׁאָר שְׁמָהָן. לְבָתַר כַּד אִתְפַּשַּׁט קָלָא בִּפְשִׁיטוּ דְּנַיְיחָא, כְּדֵין אִיקְּרֵי יהוֹ\"ה, שְׁמָא דְאִתְגַּלְּיָא.</p>"],[9514013896,"<p>הָכָא רָזָא דְרָזִין, לְיָדְעֵי חָכְמְתָא עִילָּאָה. וּזְעִירִין אִינוּן דְּיָדְעִין שְׁמָא דָא. וְאַף עַל גַּב דְּהָא אוֹקִימְנָא בְּרָזָא דְּאַתְוָון, וְהָכֵי אִיהוּ. אֲבָל נְקוּדֻי וְטַעֲמֵי, קַבָּלָה לְמשֶׁה מִסִּינַי, בְּאוֹרַח סָתִים, לְחַכִּימֵי לִבָּא.</p>"],[9514013897,"<p>וְרָזָא דָא, (שמות ל״א:ו׳) וּבְלֵב כָּל חֲכַם לֵב נָתַתִּי חָכְמָה. דְּהָא מֵרָזָא דִּנְקוּדֵי וּתְנוּעֵי דְטַעֲמֵי, הֲווֹ יָדְעִין לְאַנְהָרָא צִיּוּרִין דִּלְעֵילָא. דְּהָא נְקוּדֵי דְאַתְוָון מִתְנַהֲגָן בְּהוּ הֲווֹ יָדְעִין, וּבְרָזָא דִילְהוֹן הֲווֹ יָדְעִין וְאִשְׁתְּמוֹדְעָן לְקַיְימָא הַהוּא צִיּוּרָא בְּרָזָא עִילָּאָה.</p>"],[9514013898,"<p>בְּגִין דְּכַוָּונָה וּרְעוּתָא אִיצְטְרִיךְ לְכָל אִינוּן עוֹבָדִין וְצִיוּרִין עִילָּאִין דִּלְעֵילָא. וְאִינוּן הֲווֹ יָדְעֵי מִגּוֹ רָזָא דְצִיּוּרָא דִּנְקוּדֵי, לְשַׁוָּואָה רְעוּתָא וְלִבָּא בְּכָל עוֹבָדָא וְעוֹבָדָא.</p>"],[9514013899,"<p>כָל אִינוּן צִיּוּרִין דְּמַשְׁכְּנָא, לָא הַוְיָן אֶלָּא רָזָא דְּאַתְוָון דַּקִּיקִין. בְּגִין דְּאִית אַתְוָון עִילָּאִין רַבְרְבִין, וְאִית אַתְוָון זְעִירִין דַּקִּיקִין. אַתְוָון זְעִירִין דַּקִּיקִין, אִינוּן עוֹבָדָא דְמַשְׁכְּנָא. אַתְוָון עִילָּאִין רַבְרְבִין, עוֹבָדָא דְבֵי מַקְדְּשָׁא דְּבַיִת רִאשׁוֹן, וְהַנֵּי לָא אִתְעֲבִידוּ לְאִתְקַּדְּשָׁא לְעֵילָא, אֶלָּא בְּצִיּוּרָא דָא.</p>"],[9514013900,"<p>דְּרָזָא דִּנְקוּדֵי דְּאַתְוָון דַּקִּיקִין, אִינוּן מִסִּטְרָא דִשְׂמָאלָא. וּנְקוּדֵי דְּאַתְוָון עִילָּאִין רַבְרְבִין, אִינוּן מִסִּטְרָא דְיָמִינָא. וְאִלֵּין כְּגַוְונָא דְאִלֵּין אִתְנָשׁוֹ מֵעָלְמָא, בַּר דְּאָתוֹ חַכִּימֵי, דְּקַבִּילוּ נְהִירוּ דְּחָכְמְתָא מִקַּדְמָאי, וַאֲקִימוּ לוֹן עַל אַתְוָון, לְנַטְלָא אַתְוָון מַטְלָנוֹן בְּגִינַיְיהוּ. וְעַל דָּא עֲבִידְתָּא דְמַשְׁכְּנָא, וַעֲבִידְתָּא דְּבֵי מַקְדְּשָׁא, בְּצִיּוּרָא נְקוּדֵי הֲווֹ שְׁלֵמִין בִּרְעוּתָא וְכַוָּנָה.</p>"],[9514013901,"<p>תְּנוּעֵי דְּטַעֲמֵי קַיְימוֹ כּוֹלָא עַל יְדָא דְמשֶׁה. וְעַל דָּא, (שמות ל״ט:ל״ג) וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל משֶׁה, דְּאִיהוּ קַיַּים כּוֹלָא בְּרָזָא דִלְהוֹן.</p>"],[9514013902,"<p>בִּתְנוּעֵי דְטַעֲמֵי, אִית בְּהוּ תְּנוּעֵי בְּרָזָא דִלְתַתָּא, לְאַנְהָגָא וּלְקַיְימָא עוֹבָדָא דְמַשְׁכְּנָא. וְאִית בְּהוּ תְּנוּעֵי בְּרָזָא דִלְעֵילָא, לְאַנְהָגָא וּלְקַיְּימָא עוֹבָדָא דְבֵי מַקְדְּשָׁא.</p>"],[9514013903,"<p>שְׁלֹמֹה מַלְכָּא, לָא אִצְטְרִיךְ לִנְקוּדֵי וּלְטַעֲמֵי, אֶלָּא אִינוּן הֲווֹ אַתְיָין בִּסְתִימוּ וּלְחִישׁוּ, וּמִתְצַיְירִין בִּגְלִיפוּ צִיּוּרֵי מַקְדְּשָׁא. הֲדָא הוּא דִכְתִיב, וְהַבַּיִת בְּהִבָּנוֹתוֹ, וַדַּאי, (מלכים א ו׳:ז׳) אֶבֶן שְׁלֵמָה מַסָּע נִבְנֶה. אֶבֶן שְׁלֵמָה, וְלֹא חָסְרָה בְּאַתְוָון דַּקִּיקִין, כְּעוֹבָדָא דְּמַשְׁכְּנָא. וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלִי בַּרְזֶל לֹא נִשְׁמַע בַּבַּיִת בְּהִבָּנוֹתוֹ. לֹא נִשְׁמַע וַדַּאי, דְּהָא אַתְרֵיהּ גָּרַם דְּאִיהוּ בִּלְחִישׁוּ.</p>"],[9514013904,"<p>וְעַל דָּא, סֵפֶר תּוֹרָה דְּאִיהוּ דִּיוּקְנָא דְּבֵי מַקְדְּשָׁא, לֵית בֵּיהּ דִּיוּקְנָא דְּטַעֲמֵי וּנְקוּדֵי, דְּכוֹלָא סָתִים בְּגַוֵּיהּ, כְּגַוְונָא דִּדְיוֹקְנָא דְּרָזָא דְבֵי מַקְדְּשָׁא קַדְמָאָה, דְּטַעֲמֵי וּנְקוּדֵי הֲווֹ סְתִימִין בְּגַוֵּיהּ.</p>"],[9514013905,"<p>וּדְחִיקוּ דְּתוֹקְפָא דְּשֵׁירוּתָא דְקָלָא, אַהֲדַר לְאַתְרֵיהּ, וּנְקוּדֵי דִילֵיהּ בְּאַתְוָון יֶהוֹ\"ה אִינוּן, בְּרָזָא דִשְׁמָא אֱלֹהִים. ובְגִינַיְיהוּ אִיקְרֵי בִּשְׁמָא דָּא, לְאִתְגַּלְּיָא אֱלֹהִים חַיִּים. וְעַל דָּא נְקוּדֵי מֵעֵילָא לְתַתָּא כָּנֵישׁ וְנָטֵיל, וְאַהֲדַר לְאַתְרֵיהּ.</p>"],[9514013906,"<p>לְבָתַר אִתְפַּשֵּׁיט בִּפְשִׁיטוּ דְּנַיְיחָא, וְאִתְהַדְּרוּ נְקוּדֵי, כְּגַוְונָא דְרָזָא עִילָּאָה, לְמֶהֱוֵי כּוֹלָּא רָזָא חָדָא כִּדְקָא יָאוֹת. אַתְוָון וּנְקוּדֵי בְּגַוְונָא חָדָא.</p>"],[9514013907,"<p>נְקוּהֵי בִּתְלַת אַתְוָון קַדְמָאִין. ה בַּתְרָאָה, לֵית לָהּ נְהוֹרָא מִגַּרְמָהּ כְּלוּם. י אִיהוּ אִתְנְהֵיר בֵּיהּ נְהִירוּ דִּנְקוּדָה בְּהַהוּא גַוְונָא מַמָּשׁ, וְהַהוּא דִּיוּקְנָא מַמָּשׁ. ה, נְהִירוּ דִּנְקוּדָה בְּהַהוּא גַוְונָא, וְרָזָא חָדָא. ו דְּאִיהוּ אֶמְצָעִיתָא, בְּרָזָא דִילֵיהּ לְמֶהֱוֵי כּוֹלָּא גּוּפָא וְרוּחָא, בִּדְיוֹקְנָא וּנְהִירוּ שְׁלִים, כִּדְקָא יָאוֹת.</p>"],[9514013908,"<p>וְעַל דָּא, שְׁמָא דָא שְׁמָא דְרַחֲמֵי, דְּאַתְוָון וּנְקוּדֵי בִּדְיוֹקְנָא וְרָזָא חָדָא, בְּאוֹרַח מֵישַׁר. כַּד אַתְוָון וּנְקוּדֵי בַּעֲקִימוּ דָּא מִן דָּא, כְּדֵין לָאו אִיהוּ בְּאוֹרַח דְּרַחֲמֵי, דְּהָא בְּהִפּוּכָא קַיְימָא.</p>"],[9514013909,"<p>וְרָזָא דָא, (שמות י״ד:כ׳) וַיָּבֹא בֵּין מַחֲנֵה מִצְרַיִם כו', בְּרָזָא דְּאַתְוָון גְּלִיפִין דְּקוּדְשָׁא בְּרִיךְ הוּא, אִתְחֲזֵי בְּאִינוּן תְּלַת סִטְרִין. וְהַהוּא דְּהִפּוּכָא, לָאו אִיהוּ בְּאוֹרַח דְּרַחֲמֵי, בְּגִין דְּמִתְהַפְּכָן אַתְוָון. וְכָּל שֶׁכֵּן אַתְוָון דְּאִינוּן כְּגַוְונָא אָחֳרָא.</p>"],[9514013910,"<p>ה' בַּתְרָאָה, לֵית לָהּ מִגַּרְמָהּ כְּלוּם. וּבְגִין כָּךְ לֵית לָהּ נְקוּדָה מִגַּרְמָהּ, בַּר כַּד עָבְדָא שְׁלִיחוּתָא, דְּאוֹזְפִין לָהּ חַד נְקוּדָה, לְאָעֳלָא וּלְמֶעְבַּד חֵילִין וְתוֹקְפָא. כְּמָה דְאוֹזְפִין לָהּ נְקוּדָה לַאֲעָלָא, אוּף הָכֵי אוֹזְפִין לָהּ אַתְוָון, דְּאִינוּן רָזָא עִילָּאָה לְאַשְׁלָמָא בְּהַהוּא שְׁלִיחוּתָא.</p>"],[9514013911,"<p>חַדְּרָא תִּנְיָינָא, אֵל. דָּא חַדְּרָא וְאִדְּרָא דְּיָמִינָא, דְּאִית בֵּיהּ חֵיזוּ, דְּאִתְטַמַּר וְאִתְגְּנֵיז. כֵּיוָן דְּנָפֵיק וְנָהֵיר לְפוּם שַׁעֲתָא, מִיָּד אִתְגְּנֵיז.</p>"],[9514013912,"<p>אֵל, אַמַּאי אִיקְּרֵי הָכֵי. א, אִיהוּ רָזָא דִנְהוֹרָא קַדְמָאָה, דְּכָלֵיל בִּתְרֵין נְהוֹרִין, וְעַל דָּא א' אִיהוּ חַד. מִתַּמָּן שֵׁירוּתָא לְאִתְנַהֲרָא וּלְאִתְפַּשְּׁטָא נְהוֹרִין לְכָל סְטַר, וְעַל דָּא אִיהוּ קַדְמָאָה לְכָל אַתְוָון, שֵׁירוּתָא דְכָלְהוֹ.</p>"],[9514013913,"<p>כְלָלָא דִתְלַת, דְּאִינוּן חַד. תְּלַת נְהוֹרִין אִינוּן כְּלִילִין בְּאוֹת א'. בִּדְרוֹעָא חָדָא בְּחַד סִטְרָא. וּדְרוֹעָא חָדָא בְּחַד סִטְרָא. ו בְּאֶמְצָעִיתָא, דְּכָלֵיל תְּרֵין דְּרוֹעִין, דִּתְרֵין סִטְרִין.</p>"],[9514013914,"<p>וְאִצְטְרִיךָ שִׁיעוּרָא דְּאֶמְצָעִיתָא, בִּתְרֵין דְּרוֹעִין דִּתְרֵין סִטְרִין. בְּגִין דְּאִיהוּ נָטֵיל לוֹן, וְאִיהוּ בִּלְחוֹדוֹי בְּתַרְוַיְיהוּ. א, אֵשׁ מִסִּטְרָא דָא. מַיִם מִסִּטְרָא דָא. רוּחַ פָּסֵיק בְּאֶמְצָעִיתָא, וְנָטֵיל בִּתְרֵין סִטְרִין, וְכוֹלָּא אִינוּן חַד.</p>"],[9514013915,"<p>תּוּ, א' דָא, אִתְפַּשַּׁט וְאִתְכְּלֵיל בִּכְלָלָא דְּכָלְהוֹ, וְכֵיוָן דְּאִיהוּ כָּלֵיל בִּשְׁלִימוּ דִּתְרֵין סִטְרִין, דְּאִתְעָרוֹ דִּתְלָתָא, אִתְעַר לְגַבֵּי נוּקְבֵיהּ, וְאִתְהַפַּךְ א בְּרָזָא אָחֳרָא. וְנָטֵיל נוּקְבֵיהּ לְתַתָּא מִינֵּיהּ, וּמִתְחַבְּרָאן כַּחֲדָא, וּכְדֵין נְקוּדָה עִילָּאָה שַׁרְיָא עֲלֵיהּ, לְאַחֲזָאָה דִּנְהוֹרָא עִילָּאָה, נְקוּדָה קַמַּיְיתָא, בְּרָזָא דִשְׁכִינְתָּא עִילָּאָה, לָא שַׁרְיָא אֶלָּא בַּאֲתַר דְּאִיהוּ דְּכַר וְנוּקְבָא מִתְחַבְּרָן כַּחֲדָא.</p>"],[9514013916,"<p>(בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת, הָא הָכָא אַרְבַּע אַלְפִין, מִתְחַבְּרָן כַּחֲדָא דְּכַר וְנוּקְבָא, בְּאַרְבַּע תֵּיבִין, בְּכָל תֵּיבָה וְתֵיבָה א' דְּאִיהוּ דְכַר. וּבְכָל תֵּיבָה וְתֵיבָה, אָת חַד דְּאִיהוּ נוּקְבָא.</p>"],[9514013917,"<p>וּבְסִפְרָא דְרַב הַמְנוּנָא סָבָא, בְּרֵאשִׁית, אָדָם וְאִתְּתֵיהּ. בָּרָא, אַבְרָהָם וְנוּקְבֵיהּ. אֱלֹהִים, יִצְחָק וְנוּקְבֵיהּ. אֵת, יַעֲקֹב וְנוּקְבֵיהּ.</p>"],[9514013918,"<p>וְאִי תֵימָא אֶת נוּקְבָא בְּכָל אֲתַר. תָּא חֲזֵי, א דְּכַר, ת נוּקְבָא כְּלִילָן תַּרְוַיְיהוּ כַּחֲדָא, וְנוּקְבָא אִתְחֲזֵי בִּשְׁלִימוּ, כְּלִילָא בְּרָזָא דְּכָל אַתְוָון. וּבְגִין כָּךְ אֶת, אַף עַל גַּב דְּנוּקְבָא אִיהוּ, אֲבָל אִיהִי בְּרָזָא דִּכְלָלָא דִּדְכוּרָא.</p>"],[9514013919,"<p>וְעַל דָּא אַרְבָּעָא זִוּוּגִין אִינוּן הָכָא. וּבְכָל אֲתַר א דְּכַר, דְּמִתְחַבְּרָא בְּנוּקְבָא בְּאָת אָחֳרָא, קִרְיַת אַרְבַּע, עַל דְּאִתְחַבְּרוּ אַרְבַּע רַבְרְבָן מְמַנָּן דְּעָלְמָא תַּמָּן.</p>"],[9514013920,"<p>ל, דָּא מִגְדָּל דְּפָרַח בַּאֲוִירָא, דְּאִיהוּ מֶלֶךְ גָּדוֹל. וּבְגִין כָּךְ אִיקְרֵי אֵל עֵילָא וְאֶמְצָעִיתָא כַּחֲדָא. עֵילָא וְרֵישָׁא דְאַשְׁגָּחוּתָא, רֵישָׁא דְּכָל אַתְוָון, כַּחֲדָא. אֵל: נָטֵיל אָלֶ\"ף סִיּוּעָא דְּהַהוּא מִגְדְּלָא דְּפָרַח בַּאֲוִירָא לְגַבֵּיהּ, וַעֲלֵיהּ סָלֵיק בִּשְׁמָא.</p>"],[9514013921,"<p>תְּלָתִין וּתְרֵין שְׁבִילִין אִינוּן דְנָפְקֵי מֵאוֹרַיְיתָא, וְאִינוּן רָזָא דְעֶשֶׂר אֲמִירָן, וְעֶשְׂרִין וּתְרֵין אַתְוָון דְּאוֹרַיְיתָא. וְכָלְהוֹ נָפְקֵי מֵרָזָא דִּנְקוּדָה עִילָּאָה. עֶשֶׂר אֲמִירָן, כָּלְהוּ כְּלִילָן בְּרָזָא דְאוֹרַיְיתָא, דְּאִיהוּ מֶלֶךְ עִילָּאָה, רָזָא דְתוֹרָה שֶׁבִּכְתָב, עַלְמָא דְאָתֵי.</p>"],[9514013922,"<p>וְעֶשְׂרִין וּתְרֵין אַתְוָון, מִתְפַּשְּׁטִין, וְשָׁרְיָין לְאִתְנְהָרָא מֵרֵישָׁא דִנְהוֹרָא קַדְמָאָה, בְּרָזָא דְיִחוּדָא, דְּתַמָּן אַתְוָון לְאִתְגַּלְּיָא, וּמִתַּמָּן נָהֲרִין אַתְוָון וְסָלְקִין, א' רָזָא דְּכָל אַתְוָון בְּרָזָא דְאֶחָד.</p>"],[9514013923,"<p>חַדְּרָא תְּלִיתָאָה, אֱלֹהִים. דָּא אִיהוּ זָהֳרָא סוּמְקָא, נָצֵיץ כְּדַהֲבָא. זָהֳרָא, דִּלְזִמְנִין נָהֵיר וְטַב, וּלְזִמְנִין אִתְחַשַּׁךְ בַּחֲשׁוֹכָא, וְלֵית לֵיהּ נְצִיצוּ כְּמָה דַהֲבָא.</p>"],[9514013924,"<p>אֱלֹהִים, רָזָא דְאִתְעֲרוּתָא לְגַבֵּי נוּקְבָא, בְּהַהוּא סִטְרָא. דִּשְׁמָא דָא אִיהוּ בְּרָזָא דְרָזִין לְיָדְעֵי חָכְמְתָא, דִּשְׁמָא דָא אִיהוּ דְכַר, וְאִתְעָרוֹ לְגַבֵּי נוּקְבָא בִּשְׁמָא דָא, כֹּלָּא אִתְעַר.</p>"],[9514013925,"<p>וְאִלְמָלֵּא אִתְעָרוֹ דִּשְׁמָא דָא, צַדִּי\"ק לָא אִיתְעַר. וְאַף עַל גַּב דְּכוֹלָּא אִיהוּ דִינָא, וְצַדִּיק מִסִּטְרָא דְּיָמִינָא אִיהוּ, אֲבָל אִתְעָרוֹ דִילֵיהּ, לָאו אִיהוּ אֶלָּא מִסִּטְרָא דִשְׂמָאלָא.</p>"],[9514013926,"<p>אָדָם שָׁבַק סִטְרָא דָא, וְאִתְעַר בְּהַהוּא טוּפְסְרָא דְדַהֲבָא, דְּנָפֵיק מִלִּכְלוּכָא דְּהִתּוּכָא דִילֵיהּ.</p>"],[9514013927,"<p>אֱלֹהִים, א', דְּכַר. להי\"ם, אִתְעֲרוּתָא דְצַדִּי\"ק, וְאִיהוּ מִילָ\"ה בִּפְרִיעוּ, בְּלָא סְטַר עָרְלָה כְּלַל. וְדָא אִיהוּ כַּד אִדְכַּר שְׁמָא דָא לְטַב, כְּגוֹן וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ, דְּאִתְעַר בְּרִית. בְּרָזָא דָא, וֵאלֹהִים פָּקֹד יִפְקֹד.</p>"],[9514013928,"<p>בְּסִטְרָא אָחֳרָא, אוֹרַיְיתָא אַסְהֵידַת עַל דִּינוֹי, דְּהָא מִתַּמָּן עָרְלָה נָפְקַת. לְזִמְנִין שְׁמָע דָא נוּקְבָא יָרְתָא לֵיהּ, בְּגִין לְאִתְדָּנָא עָלְמָא בְּהַהוּא רָזָא דְעָרְלָה. כַּד אִתְתַּקַּף הַאי אֱלֹהִים לְעֵילָּא, וְאִתְקַשֵּׁי הַהוּא עָרְלָה, וּפְרִיעָה לָא אִשְׁתְּכַח.</p>"],[9514013929,"<p>וְעַל דָּא, לְטַב בִּפְרִיעוּ אִיהוּ, דְּהָא אִתְפְּרַע עָרְלָה וְאִתְעֲבַר, וְאִתְגַּלְּיָא רָזָא דִבְרִית קַדִּישָׁא. וְכוֹלָּא בְּרָזָא דֵאלֹהִים אִיהוּ. דְּהָא גַּוָּון דָּא אִתְהַפַּךְ לְכַמָּה גְּוָונִין, לְזִמְנִין הָכֵי, וּלְזִמְנִין הָכֵי, וְדָא אִיהוּ בְּרָזָא דֵּאלֹהִים.</p>"],[9514013930,"<p>אֱלֹהִים, תְּלַת שְׁמָהָן אִינוּן. חָדָא, אֱלֹהִים חַיִּים, דְּאִיהוּ אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם. אֱלֹהִים, דְּפַחַד יִצְחָק. אֱלֹהִים בַּתְרָאָה. וְתַמָּן מִתְפַּשְּׁטִין אֱלֹהִים דְּפַחַד יִצְחָק.</p>"],[9514013931,"<p>אַשְׁגָּחוּתָא דִילֵיהּ, (זכריה י״ד:ח׳) חֶצְיוֹ אֶל הַיָּם הַקַּדְמוֹנִי דַיְיקָא. וְחֶצְיוֹ אֶל הַיָּם הָאַחֲרוֹן. אֶל הַיָּם הָאַחֲרוֹן דַּיְיקָא. דְּאִתְקְרֵי בִּשְׁמָא דָא.</p>"],[9514013932,"<p>וּבְגִין דְּנָפֵיק מִלְּעֵילָא, אִית לֵיהּ רְשׁוּ לְאַכְלָלָא יָמִינָא בְּגַוֵּיהּ. וְכַד אִתְכְּלִילָא יָמִינָא בְּגַוֵּיהּ, כְּדֵין אִיהִי בְּחֶדְוָא, וְאָחֵיד בְּגוֹ יַמָּא תַּתָּאָה תְּחוֹת רֵישָׁא. דִּכְתִיב (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, כְּדֵין אִתְקְרֵי אֱלֹהִי\"ם, דְּהָא אָזֵיל אֶל הַיָּם הָאַחֲרוֹן. וְדָא אִיהוּ חַדְּרָא תְּלִיתָאָה, מֵהַהוּא מֶלֶךְ עִילָּאָה.</p>"],[9514013933,"<p>חַדְּרָא רְבִיעָאָה, דִּיוּקְנָא דְיַעֲקֹב סָבָא, בְּרָזָא יְהוּ, דְּנָטֵיל יְרוּתָא דְאַבָּא וְאִמָּא, וְאִיהוּ אִתְרַבֵּי בְּגַוַּיְיהוּ, וַאֲזֵל לְקַמַּיְיהוּ.</p>"],[9514013934,"<p>אוֹרַח דִּצְנִיעוּ דְּכָל עָלְמָא, הָכֵי אִתְחֲזֵי, כְּגַוְונָא דְסִידּוּרָא דְּאַתְוָון דְּמָארֵי כּוֹלָּא, כְּמָא דְאִינוּן מִסְתַּדְּרוֹן יהו\"ה. אוֹרְחֵיהּ דִּדְכוּרָא, לְשַׁוָּאָה תָּדִיר נוּקְבֵיהּ לְקַמֵּיהּ, לְאַשְׁגָּחָא בָהּ, וּלְאִסְתַּלָּקָא מִינָהּ חֲשָׁדָא וְקִנְאָה, וְלָא יְהֵיב עֵינוֹי בְּאִנְתּוּ אָחֳרָא. י' דְּכַר, ה' נוּקְבָא. י\"ה, הָא נוּקְבָא לְקַמֵּי דְכוּרָא, בְּגִין לְאִסְתַּכָּלָא בָּהּ תָּדִיר. בְּרָא אָזֵיל לְקַמֵּיהּ אִמֵּיהּ, לְחַפְיָא לָהּ מֵעֵינָא. בְּגִין יְקָרָא דִילֵיהּ וִיקָרָא דַּאֲבוֹי. וְסִימָנָךְ (בראשית מ״ט:כ״ב) בֶּן פּוֹרָת יוֹסֵף. דִּכְתִיב, (שם לג) וְאַחַר נִגַּשׁ יוֹסֵף וְרָחֵל, יוֹסֵף לְקַמֵּי אִמֵּיהּ.</p>"],[9514013935,"<p>יַעֲקֹב נָטֵיל נוּקְבֵיהּ, וְשַׁוֵּי לָהּ לְקַמֵּיהּ, לְאַשְׁגָּחָא בָהּ תָּדִיר וְלָא בְאָחֲרָא. הֲדָא הוּא דִכְתִיב, (דברים יא) תָּמִיד עֵינֵי ה' אֱלֹהֶיךָ בָהּ, דְּלָא תִסְתַּלֵּק מֵעֵינָא רִגְעָא חָדָא. וְדָא אִיהוּ סִדְרָא דְּאַתְוָון קַדִּישִׁין, לְמֶהֱוֵי סִידוּרָא דָא עֵילָא וְתַתָּא.</p>"],[9514013936,"<p>אַתְוָון אִלֵּין אִתְרְשִׁימוּ בִּרְשִׁימוּ דִלְהוֹן, כַּד נָפְקוּ לְבַר מֵחֵילָא וְתוֹקְפָא דְשׁוֹפָר. כְּדֵין בְּשַׁעֲתָא דְּנָפְקֵי מֵחֵילָא וְתוֹקְפָא דְשׁוֹפָר, מִגּוֹ דְחִיקוּ, דְּאִתְעֲבֵיד קָלָא כְּלִילָא מֵאֵשׁ וְרוּחַ וּמַיִם, אַתְוָון אִתְגְּלִימוּ, וְאִתְרְשִׁימוּ בְּפַרְצוּפִין דִּלְּהוֹן, כָּל חַד וְחַד כִּדְקָא חָזֵי לוֹן, וְאִתְיַישְׁרוּ בְּדוּכְתַּיְיהוּ.</p>"],[9514013937,"<p>גְּנִיזִין הֲווֹ אַתְוָון גּוֹ שׁוֹפָר, בְּלָא רְשִׁימוּ דְּאִתְחֲזֵי כְּלַל, כֵּיוָן דְּנָפְקֵי, אִתְגְּלִימוּ כּוּלְהוּ, וְאִתְרְשִׁימוּ בִּדְיוּקְנַיְיהוּ, כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ, כְּמָא דְּאִתְחֲזֵי גּוֹ רָזָא דִּנְקוּדִין.</p>"],[9514013938,"<p>חֲדָרָיו, חֲדָרִין טְמִירִין. הֱבִיאֲנִי, גּוֹ אִינוּן אַתְוָון, לְמֶהֱוֵי בֵּינַיְיהוּ גּוּפְטְרָא בְּחִבּוּרָא חָדָא. וְכָל דָּא לָמָּה. (שה\"ש א) נָגִילָה וְנִשְׂמְחָה בָךְ, בְּגִין דִּיְהֵא לָן חֶדְוָוא בָּךְ.</p>"],[9514013939,"<p>עַל פּוּמָא דְאֵלִיָּהוּ אִתְגְּזַר. (שם) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה. כְּתִיב (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ וכו'. כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם, כְּמָא דַאֲמָרוּ חַבְרַיָּיא זַכָּאִין אִינוּן, דּוּ פַּרְצוּפִין אִתְבְּרִיאוּ בְּאַתְוָון עִילָּאִין רַבְרְבִין. וּבְאַתְוָון זְעִירִין תַּתָּאִין.</p>"],[9514013940,"<p>אַתְוָון עִילָּאִין רַבְרְבִין, הֲווֹ בְּאוֹרַח מִישׁוֹר לְגַבֵּי דְכַר. אַתְוָון זְעִירִין תַּתָּאִין, הֲווֹ בְּהִיפּוּכָא לְגַבֵּי נוּקְבָא. אַתְוָון עִילָּאִין רַבְרְבִין, הֲווֹ בְּאוֹרַח מֵישַׁר לְגַבֵּי דָּכָר, אב גד, וְכֵן כּוּלְהוּ, כְּמָה דְאִתְחֲזֵי לְמֵיהַךְ אַתְוָון בְּאוֹרַח מֵישַׁר לְגַבֵּי דְכוּרָא. אַתְוָון זְעִירִין תַּתָּאִין, הֲווֹ בְּהִפּוּכָא לְמִפְרַע גּוֹ נוּקְבָא, תשרק, וְכֵן כּוּלְהוּ, כְּמָא דְאִתְחֲזֵי גַבֵּי נוּקְבָא, דַּהֲוַות מֵאֲחוֹרָא, קֶשֶׁר דִּתְפִילִּין דְּאִיקְּרֵי אָחוֹר.</p>"],[9514013941,"<p>כְּמָה דְאַתְּ אָמֵר אָחוֹר וָקֶדֶם צַרְתָּנִי, אָחוֹר, לְגַבֵּי נוּקְבָא. וָקֶדֶם, לְגַבֵּי דְכוּרָא. וְדָא אִיהוּ דִּכְתִיב, (שמות לג) וְרָאִיתָ אֶת אֲחוֹרָי, דָּא נוּקְבָא דַּהֲוַת מֵאֲחוֹרָא.</p>"],[9514013942,"<p>וְכַד אִתְקַשְּׁטַת נוּקְבָא, דְּקַשֵּׁיט לָהּ מַלְכָּא עִילָּאָה, לְאִתְיַישְׁבָא אַתְוָון בְּדוּכְתַּיְיהוּ כִּדְקָא חָזֵי, אָעֵיל לוֹן לְאִדְרוֹי לְאִתְתַּקְנָא, וְאִתְתַּקְּנוּ אַתְוָון.</p>"],[9514013943,"<p>וְכָל אָת דְּנוּקְבָא, קָרֵי לְכָל אָת דִּדְכוּרָא, וְאִתְתַּקְּנוּ כָּל אָת וְאָת דְּכַר וְנוּקְבָא. וְכָל אָת קָרֵי וַאֲמַר, (שה\"ש א) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה.</p>"],[9514013944,"<p>כַד אִתְתַּקְּנוּ לְאִתְחַבְּרָא, בְּרָזָא דְּא\"ת ב\"ש אִתְתַּקְּנוּ. וְאִתְיַישְׁבוּ אַנְפִּין בְּאַנְפִּין. וְנוּקְבָא כַּד בָּעָא לְאִתְחֲזָאָה לְגַבֵּיהּ, הִיא אוֹמֶרֶת, דְּהָא אִתְקַשְׁטָא בִּרְעוּ דְּאִימָּא, וְכָל אַתְוָון אִתְתַּקָּנוּ. וְעַל דָּא הֱבִיאֲנִי הַמֶּלֶךְ חֲדָרָיו, לְאִתְתַּקָּנָא וּלְאִתְקַשָּׁטָא כִּדְקָא יָאוֹת.</p>"],[9514013945,"<p>וְכָל דָּא בְּגִין דְּנָגִילָה וְנִשְׂמְחָה בָ\"ךְ. עֶשְׂרִין וּתְרֵין אַתְוָון רְשִׁימִין עִילָּאִין. וְדָא אִיהוּ בָ\"ךְ. וְרָזָא דָא אֲשֶׁר נִשְׁבַּעְתָּ לָהֶם בָּךְ.</p>"],[9514013946,"<p>נַזְכִירָה דוֹדֶיךָ מִיָּיִן, כֵּיוָן דְּנִתְחַבַּר כַּחֲדָא, בְּהַהוּא חֶדְוָא דִילָן, נֵיהַב חֶלְקָא לְכָל חַד וְחַד מֵהַהוּא חֶדְוָא דִילָן, וְנַרְוֵוי לוֹן. כְּמָה דְאַתְּ אָמֵר, יִזְכֹּר כָּל מִנְחֹתֶיךָ. מִיָּיִן: מֵחֶדְוָא דִילָן, מִסִּטְרָא דְּהַהוּא יַיִן דְּחָדִי כּוֹלָּא.</p>"],[9514013947,"<p>מֵישָׁרִים אֲהֵבוּךָ, מֵישָׁרִים: אִינוּן שְׁאָר אַתְוָון דְּאִשְׁתְּאָרוּ. וּמָאן אִינוּן. מנצפ\"ך. דְּלֵית בְּכָל אַתְוָון דְּאִיקְרוֹן מֵישָׁרִים, בַּר אִלֵּין. וְאִינוּן דְּאִתְכַּפְּלוּ מֵישָׁרִים אִלֵּין בְּאִלֵּין, מ' בְּם', נ' בְּן', צ' בְּץ', פ' בְּף', כ' בְּך'. אִלֵּין מֵישָׁרִים אִלֵּין בְּאִלֵּין, וְדָא בְּדָא.</p>"],[9514013948,"<p>דְּהָא עֶשְׂרִים וּתְרֵין אַתְוָון כְּלִילָן בָּ\"ךְ, אִינוּן דְּאִשְׁתָּאֲרוּ דְּאִינוּן מֵישָׁרִים, אַהֵבוּךָ לְאִתְכְּלָלָא עִמָּךְ, בְּאִינוּן עֶשְׂרִין וּתְרֵין אַתְוָון.</p>"],[9514013949,"<p>אִילֵּין מֵישָׁרִים, אִינוּן אַתְוָון טְמִירִין גְּנִיזִין גּוֹ עַלְמָא עִילָּאָה. וְכַד אִתְגְּנֵיז אוֹר קַדְמָאָה, אִתְגְּנִיזוּ אַתְוָון אִלֵּין. וַהֲוָה יָדַע לוֹן אָדָם. בָּתַר דְּחָטָא אָדָם, אִתְגְּנִיזוּ כְּמִלְּקַדְמִין. עַד דַּאֲתָא אַבְרָהָם וְיָדַע לוֹן בְּרוּחַ קוּדְשָׁא דְּשָׁרַאת עֲלֵיהּ.</p>"],[9514013950,"<p>לְבָתַר אוֹרִית לוֹן לְיִצְחָק, דִּכְתִיב, (בראשית כ״ה:ה׳) וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. יִצְחָק אוֹרִית לוֹן לְיַעֲקֹב. יַעֲקֹב אוֹרִית לוֹן לְיוֹסֵף. כֵּיוָן דְּמִית יוֹסֵף, וּבְנֵי יִשְׂרָאֵל הֲווֹ בְּגָלוּתָא, אִתְגְּנִיזוּ אַתְוָון, וְאִסְתַּלְּקוּ כְּמִלְּקַדְּמִין.</p>"],[9514013951,"<p>עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי, וְאִתְמָסְרַת אוֹרַיְיתָא לְיִשְׂרָאֵל, אִתְגַּלּוּ אַתְוָון, וַהֲווּ יִשְׂרָאֵל יָדְעִין לוֹ עַל בְּרִירוּ דִלְהוֹן, בְּרָזָא דִשְׁמָהָן גְּלִיפִין. עַד דְּחָטְאוּ. כֵּיוָן דְּחָטְאוּ, כְּתִיב (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם. וַהֲוָה יָדַע לוֹן משֶׁה וִיהוֹשֻׁעַ וְשִׁבְעִים זְקֵנִים, וּבְהוֹ עָאלוּ לְאַרְעָא.</p>"],[9514013952,"<p>כֵיוָן דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא, וְאִתְגְּלֵי שִׁיר דָּא, אִתְגְּלִיפוּ אִלֵּין אַתְוָון, בְּעֶשְׂרִין וּתְרֵין אַתְוָון, רָזָא בָּ\"ךְ, וְהַיְינוּ מֵישָׁרִים אֲהֵבוּךָ.</p>"],[9514013953,"<p>וּכְתִיב, (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. (שיר השירים ז׳:י׳) וְחִכֵּךְ כְּיֵין הַטוֹב הוֹלֵךְ לְדוֹדִי לְמֵישָׁרִים. כָּלְהוֹ בְּרָזָא דְּאִלֵּין אַתְוָון, אִינוּן דְּאִקְּרוּן מֵישָׁרִים. וְאִלֵּין אַתְוָון, כִּתְרִין גְּנִיזִין גּוֹ עַלְמָא דְאָתֵי אִינוּן. וְכוּלְהוּ נְבִיעוּ בָּתַר נְבִיעוּ גּוֹ מַחֲשָׁבָה, בִּגְלִיפוּ דְּרָזִין דִּשְׁמָהָן קַדִּישִׁין, בִּגְלִיפוּ דְּכַר וְנוּקְבָא, לְאִסְתַּכְּמָא כַּחֲדָא, דְּהָא לֵית בְּכָל אַתְוָון אַסְכָּמוּתָא אִלֵּין בְּאִלֵּין לְמֶהֱוֵי דָּא בְּדָא, בַּר אִלֵּין.</p>"],[9514013954,"<p>תּוּ. מֵישָׁרִים, אִלֵּין יה, דִּרְחִימוּ דִּלְהוֹן לְגַבֵּי ו', וְאִינוּן אַסְכָּמוּתָא דְּכֹלָּא, וּבִרְעוּתָא חָדָא לְגַבֵּי ו. וְעַל דָּא, מָשְׁכֵנִי לְגַבֶּיךָ, לְמֶהֱוֵי עִמָּךְ, דְּהָא אַתְוָון קַדִּישִׁין עִילָּאִין אִינוּן יָה, אִתְחַבַּר עִמָּהוֹן ו', וְאִיהוּ שְׁמָא קַדִּישָׁא עִילָּאָה. ה דְּיָתְבָא תְּחוֹתֵיהּ, וְלֵית לָהּ מִגַּרְמָהּ כְּלוּם, תֵּיאוּבְתָּה דִידָהּ לְסָלְקָא לְגַבֵּיהּ, לְאִתְחַבַּר בַּהֲדֵיהּ, וְלָא סָלְקָא אֶלָּא בִּרְשׁוּ, וְאִיהִי אוֹמֶרֶת מָשְׁכֵנִי, לְמֶהֱוֵי בַּהֲדָךְ בְּחִיבּוּרָא חָדָא.</p>"],[9514013955,"<p>הֱבִיאֲנִי הַמֶּלֶךְ חֲדָרָיו, וְאַתְקֵין לִי בְּכָל זִינֵי תִּיקּוּנִין, בְּשַׁפִּירוּ עִילָּאָה, בְּגִין לְמֶהֱוֵי לְגַבָּךְ. וְעַל דָּא נָגִילָה וְנִשְׂמְחָה בָךְ, אֲנָא וְכָל תִּיקּוּנַי, כַּד אֱהֵא לְגַבָּךְ בְּחִיבּוּרָא חָדָא.</p>"],[9514013956,"<p>(שם א) נַזְכִּירָה דוֹדֶיךָ, כְּמָה דְּאִיתְּמָר, נַרְוֵוי לְכָל חַד וְחַד, וְנַחְדֵי לוֹן מֵהַהוּא יַיִן דְּחָדֵי כּוֹלָּא, וְלָא נַפְסִיק מִלֶּמֶחֱדֵי לוֹן, דְּהָא מֵישָׁרִים אֲהֵבוּךָ. וְלָא יִפְסְקוּן לְמִיתַּן לָךְ, הוֹאִיל וְהֵם אֲהֵבוּךָ, לְמֵיתַּן לָךְ, וְלַאֲרָקָא בָּךְ, וּלְאַנְהָרָא לָךְ.</p>"],[9514013957,"<p>אָמַר רַבִּי שִׁמְעוֹן, אִי נִיחָא קַמֵּי דְמַר, הָא כְתִיב, (תהלים צט) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. אִי אִינוּן יה, מַאן יָכֵיל לְאִתְתַּקָּנָא לוֹן, בַּר עַתִּיקָא דְּכָל עַתִּיקִין, דְּלָא יְדִיעַ כְּלַל, וְהַהוּא דְּלָא אִתְיְידִיעַ, טָמִיר וְגָנִיז, לָא אִקְרֵי אַתָּה, וְהֵיכֵי קָאָמַר וּכְתִיב אַתָּה כּוֹנַנְתָּ מֵישָׁרִים.</p>"],[9514013958,"<p>אֲמַר לֵיהּ, הָא אִתְּמָר דְּלֵית דִּיוּקְנָא לְאַתְוָון בִּגְלִימוּ דִּלְּהוֹן, עַד דְּנָפְקֵי לְבַר, כֵּיוָן דְּנָפְקֵי, אִתְגְּלִימוּ וְאִתְתַּקָּנוּ, לְאִתְקְרֵי בְּהוּ בְּאִינוּן אַתְוָון קוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ, אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. כֵּיוָן דְּמָטוֹ לְהַהוּא אֲתַר דְּאִקְּרֵי אַתָּה, כְּדֵין אִתְתַּקָּנוּ מֵישָׁרִים.</p>"],[9514013959,"<p>וְעַל דָּא תֵּיאוֹבְתָּא לְאִתְחַבְּרָא בְּאִינוּן אַתְוָון, לְמֶהֱוֵי כּוֹלָא שְׁמָא שְׁלִים, וְעַד דְּאִתְתַּקְּנוּ אִינוּן סִטְרִין דִּילָהּ, לָא אִתְחַבָּרַת בְּאִינוּן אַתְוָון, לְמֶהֱוֵי כּוֹלָּא שְׁמָא שְׁלִים.</p>"],[9514013960,"<p>וְעַל דָּא אִיהִי אֲמָרַת בְּתִיקּוּנֵי שַׁפִּירָהָא, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה, הָא אִיהִי וְסִטְרָהָא. הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו נָגִילָה וְנִשְׂמְחָה, הָא הִיא וְסִטְרָהָא.</p>"],[9514013961,"<p>בְּגִין דְּאִיהִי אִתְתַּקָּנַת בְּשַׁפִּירוּ תִּיקוּנָהָא, לְאִתְחַבְּרָא, לְמֶהֱוֵי שְׁמָא שְׁלִים בְּחִיבּוּרָא חָדָא. דְּכַד סָלְקָא, כְּדֵין אִיהוּ שְׁמָא שְׁלִים, רָזָא דִשְׁמָא ידו\"ד אֱלֹהִים.</p>"]]});
